#region src/00-core/registry.ps1
# Registry value/key primitives, key creation plans and key-tree restore.
# Covered by: tests/RegistryPrimitives.Tests.ps1, tests/RegistryKeyUndo.Tests.ps1

function ConvertTo-WtRegistryHivePath {
    <#
    .SYNOPSIS
        PURE: a provider path ('HKLM:\...', 'HKCU:\...',
        'Registry::HKEY_LOCAL_MACHINE\...') as the .NET hive key plus the
        sub-key path under it: @{ Hive; SubKey }. $null when the prefix
        is not one of the six hives.
    #>
    param([Parameter(Mandatory)][string]$Path)
    $p = $Path.Trim()
    if ($p.StartsWith('Registry::', [System.StringComparison]::OrdinalIgnoreCase)) { $p = $p.Substring(10) }
    $cut = $p.IndexOfAny([char[]]@('\', '/'))
    $prefix = $(if ($cut -lt 0) { $p } else { $p.Substring(0, $cut) })
    $subKey = $(if ($cut -lt 0) { '' } else { $p.Substring($cut + 1).Trim([char[]]@('\', '/')) })
    $hive = switch ($prefix.TrimEnd(':').ToUpperInvariant()) {
        'HKLM'                { [Microsoft.Win32.Registry]::LocalMachine }
        'HKEY_LOCAL_MACHINE'  { [Microsoft.Win32.Registry]::LocalMachine }
        'HKCU'                { [Microsoft.Win32.Registry]::CurrentUser }
        'HKEY_CURRENT_USER'   { [Microsoft.Win32.Registry]::CurrentUser }
        'HKCR'                { [Microsoft.Win32.Registry]::ClassesRoot }
        'HKEY_CLASSES_ROOT'   { [Microsoft.Win32.Registry]::ClassesRoot }
        'HKU'                 { [Microsoft.Win32.Registry]::Users }
        'HKEY_USERS'          { [Microsoft.Win32.Registry]::Users }
        'HKCC'                { [Microsoft.Win32.Registry]::CurrentConfig }
        'HKEY_CURRENT_CONFIG' { [Microsoft.Win32.Registry]::CurrentConfig }
        default               { $null }
    }
    if ($null -eq $hive) { return $null }
    return @{ Hive = $hive; SubKey = $subKey }
}

function Get-WtRegistryProperty {
    <#
    .SYNOPSIS
        The real read behind every GetPropertyAction default: what
        Get-ItemProperty -Name would return, via the .NET registry API,
        because Get-ItemProperty -ErrorAction SilentlyContinue costs
        ~20ms per missing key, and an unapplied setting is a missing key.
    #>
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][AllowEmptyString()][string]$Name
    )
    $split = ConvertTo-WtRegistryHivePath -Path $Path
    if ($null -eq $split) { return (Get-ItemProperty -LiteralPath $Path -Name $Name -ErrorAction SilentlyContinue) }
    $valueName = $(if ($Name -eq '(default)') { '' } else { $Name })
    $key = $null
    try {
        $key = $split.Hive.OpenSubKey([string]$split.SubKey)
        if ($null -eq $key) { return $null }
        $value = $key.GetValue($valueName, $null)
        if ($null -eq $value) { return $null }
        return [PSCustomObject]@{ $Name = $value }
    }
    catch { return $null }
    finally { if ($null -ne $key) { $key.Close() } }
}

function Get-WtRegistryValue {
    <#
    .SYNOPSIS
        Reads one registry value, reporting Present=$false (not a throw)
        when the key or the value itself is missing. Runs entirely behind
        -GetPropertyAction because the Registry PSProvider does not exist
        on the macOS dev host.
    #>
    param(
        [Parameter(Mandatory)]
        [string]$Path,

        [Parameter(Mandatory)]
        [string]$Name,

        [scriptblock]$GetPropertyAction = {
            param($p, $n)
            Get-WtRegistryProperty -Path $p -Name $n
        }
    )

    $result = & $GetPropertyAction $Path $Name

    if ($null -eq $result -or $result.PSObject.Properties.Name -notcontains $Name) {
        return [PSCustomObject]@{ Present = $false; Value = $null }
    }

    return [PSCustomObject]@{ Present = $true; Value = $result.$Name }
}

function Set-WtRegistryValue {
    <#
    .SYNOPSIS
        Writes one registry value, creating the key chain first if needed.
        Entirely behind -SetValueAction for the same reason as
        Get-WtRegistryValue - no registry PSProvider on this dev host.
    #>
    param(
        [Parameter(Mandatory)]
        [string]$Path,

        [Parameter(Mandatory)]
        [string]$Name,

        [Parameter(Mandatory)]
        [string]$RegType,

        [Parameter(Mandatory)]
        [AllowNull()]
        [object]$Value,

        [scriptblock]$SetValueAction = {
            param($p, $n, $t, $v)
            if (-not (Test-Path -LiteralPath $p)) {
                New-Item -Path $p -Force | Out-Null
            }
            New-ItemProperty -LiteralPath $p -Name $n -PropertyType $t -Value $v -Force | Out-Null
        }
    )

    & $SetValueAction $Path $Name $RegType $Value
}

function Remove-WtRegistryValue {
    <#
    .SYNOPSIS
        Removes one registry value. Removing a value that is already
        absent is a no-op, not an error. Entirely behind
        -RemoveValueAction for the same reason as Get-WtRegistryValue.
    #>
    param(
        [Parameter(Mandatory)]
        [string]$Path,

        [Parameter(Mandatory)]
        [string]$Name,

        [scriptblock]$RemoveValueAction = {
            param($p, $n)
            Remove-ItemProperty -LiteralPath $p -Name $n -ErrorAction SilentlyContinue
        }
    )

    & $RemoveValueAction $Path $Name
}

function Get-WtRegistryKeyValue {
    <#
    .SYNOPSIS
        Reads one value from a key addressed by hive + subkey through
        Microsoft.Win32.Registry, not the PSProvider (no HKCR: drive, and
        New-Item cannot address a key name containing '*'). Distinguishes
        "key absent" from "key present, value absent" via KeyPresent.
    #>
    param(
        [Parameter(Mandatory)]
        [ValidateSet('CurrentUser', 'LocalMachine')]
        [string]$Hive,

        [Parameter(Mandatory)]
        [string]$SubKey,

        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string]$Name,

        [scriptblock]$GetKeyValueAction = {
            param($h, $s, $n)
            $key = [Microsoft.Win32.Registry]::$h.OpenSubKey($s)
            if ($null -eq $key) { return $null }
            try {
                $v = $key.GetValue($n, $null)
                return [PSCustomObject]@{ Present = ($null -ne $v); Value = $v }
            }
            finally {
                $key.Close()
            }
        }
    )

    $result = & $GetKeyValueAction $Hive $SubKey $Name

    if ($null -eq $result) {
        return [PSCustomObject]@{ KeyPresent = $false; Present = $false; Value = $null }
    }

    return [PSCustomObject]@{ KeyPresent = $true; Present = [bool]$result.Present; Value = $result.Value }
}

function Set-WtRegistryKeyValues {
    <#
    .SYNOPSIS
        Creates the key (CreateSubKey opens an existing one unchanged) and
        writes every value in -Values, each @{ Name; Kind; Value } with
        Kind a Microsoft.Win32.RegistryValueKind name. One action call per
        key, not per value, so a fake can assert the whole write at once.
    #>
    param(
        [Parameter(Mandatory)]
        [ValidateSet('CurrentUser', 'LocalMachine')]
        [string]$Hive,

        [Parameter(Mandatory)]
        [string]$SubKey,

        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [array]$Values,

        [scriptblock]$SetKeyValuesAction = {
            param($h, $s, $v)
            $key = [Microsoft.Win32.Registry]::$h.CreateSubKey($s)
            try {
                foreach ($entry in @($v)) {
                    $key.SetValue($entry.Name, $entry.Value, [Microsoft.Win32.RegistryValueKind]$entry.Kind)
                }
            }
            finally {
                $key.Close()
            }
        }
    )

    & $SetKeyValuesAction $Hive $SubKey $Values
}

function Remove-WtRegistryKeyValue {
    <#
    .SYNOPSIS
        Removes one value from a key. A missing key (OpenSubKey returns
        $null - it does NOT throw) or a missing value (DeleteValue's
        throwOnMissingValue=$false) is a no-op, never an error, so a second
        undo of the same entry succeeds.
    #>
    param(
        [Parameter(Mandatory)]
        [ValidateSet('CurrentUser', 'LocalMachine')]
        [string]$Hive,

        [Parameter(Mandatory)]
        [string]$SubKey,

        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string]$Name,

        [scriptblock]$RemoveKeyValueAction = {
            param($h, $s, $n)
            $key = [Microsoft.Win32.Registry]::$h.OpenSubKey($s, $true)
            if ($null -eq $key) { return }
            try {
                $key.DeleteValue($n, $false)
            }
            finally {
                $key.Close()
            }
        }
    )

    & $RemoveKeyValueAction $Hive $SubKey $Name
}

function Remove-WtRegistryKeyTree {
    <#
    .SYNOPSIS
        Deletes a key and everything under it; a no-op if it is already
        gone. Only ever called with a CreatedRoot from
        Get-WtRegistryKeyCreationPlan or a removal root from
        Get-WtRegistryKeyRemovalRoot - never an arbitrary path.
    #>
    param(
        [Parameter(Mandatory)]
        [ValidateSet('CurrentUser', 'LocalMachine')]
        [string]$Hive,

        [Parameter(Mandatory)]
        [string]$SubKey,

        [scriptblock]$RemoveKeyTreeAction = {
            param($h, $s)
            [Microsoft.Win32.Registry]::$h.DeleteSubKeyTree($s, $false)
        }
    )

    & $RemoveKeyTreeAction $Hive $SubKey
}

function Get-WtRegistryKeyCreationPlan {
    <#
    .SYNOPSIS
        Capture-time answer to "which key tree will writing -SubKey
        create?": the first (highest) segment under -RootBoundary that
        does not exist yet, or $null if every segment already exists.
        Throws if -SubKey is not strictly under -RootBoundary.
    #>
    param(
        [Parameter(Mandatory)]
        [ValidateSet('CurrentUser', 'LocalMachine')]
        [string]$Hive,

        [Parameter(Mandatory)]
        [string]$SubKey,

        [Parameter(Mandatory)]
        [string]$RootBoundary,

        [scriptblock]$TestKeyAction = {
            param($h, $s)
            $key = [Microsoft.Win32.Registry]::$h.OpenSubKey($s)
            if ($null -eq $key) { return $false }
            $key.Close()
            return $true
        }
    )

    $boundary = $RootBoundary.TrimEnd('\')
    $prefix = $boundary + '\'
    if (-not $SubKey.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase) -or $SubKey.Length -le $prefix.Length) {
        throw "Get-WtRegistryKeyCreationPlan: '$SubKey' is not under root boundary '$RootBoundary'"
    }

    $current = $boundary
    foreach ($segment in $SubKey.Substring($prefix.Length).Split('\')) {
        if ([string]::IsNullOrEmpty($segment)) { continue }
        $current = $current + '\' + $segment
        if (-not (& $TestKeyAction $Hive $current)) {
            return $current
        }
    }

    return $null
}

function Get-WtRegistryKeyRemovalRoot {
    <#
    .SYNOPSIS
        PURE: the key a removal deletes for one KeyChanges item - the
        first segment below RootBoundary (the verb key; its \command
        child goes with it). Throws when SubKey is not strictly under
        the boundary.
    #>
    param(
        [Parameter(Mandatory)][string]$SubKey,
        [Parameter(Mandatory)][string]$RootBoundary
    )
    $boundary = $RootBoundary.TrimEnd('\')
    $prefix = $boundary + '\'
    if (-not $SubKey.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase) -or $SubKey.Length -le $prefix.Length) {
        throw "Get-WtRegistryKeyRemovalRoot: '$SubKey' is not under root boundary '$RootBoundary'"
    }
    $first = ($SubKey.Substring($prefix.Length).Split('\') | Where-Object { $_ } | Select-Object -First 1)
    if ([string]::IsNullOrEmpty($first)) {
        throw "Get-WtRegistryKeyRemovalRoot: '$SubKey' has no segment under '$RootBoundary'"
    }
    return $boundary + '\' + $first
}

function Restore-WtRegistryKeyTreeItem {
    <#
    .SYNOPSIS
        Undo for a RegistryKeyTree item (a context-menu verb removed from
        an apply screen): re-writes, from the live catalog, every
        KeyChanges entry at or below the removed root. Returns 'Restored',
        or 'NotRestorable' when the catalog no longer knows the entry.
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Item,
        [array]$Catalog = (Get-WtContextMenuCatalog),
        [scriptblock]$SetKeyValuesAction
    )
    $entry = $Catalog | Where-Object Name -eq $Item.CatalogEntry | Select-Object -First 1
    if (-not $entry) { return 'NotRestorable' }
    $setArgs = @{}
    if ($SetKeyValuesAction) { $setArgs['SetKeyValuesAction'] = $SetKeyValuesAction }
    $root = [string]$Item.SubKey
    $wrote = $false
    foreach ($change in @($entry.KeyChanges)) {
        if ($change.Hive -ne $Item.Hive) { continue }
        $sub = [string]$change.SubKey
        if (-not ($sub.Equals($root, [System.StringComparison]::OrdinalIgnoreCase) -or $sub.StartsWith($root + '\', [System.StringComparison]::OrdinalIgnoreCase))) { continue }
        $values = @($change.Values | ForEach-Object { @{ Name = $_.Name; Kind = $_.Kind; Value = $_.Value } })
        Set-WtRegistryKeyValues -Hive $change.Hive -SubKey $change.SubKey -Values $values @setArgs
        $wrote = $true
    }
    if (-not $wrote) { return 'NotRestorable' }
    return 'Restored'
}

function Restore-WtRegistryKeyItem {
    <#
    .SYNOPSIS
        Undo for a RegistryKey item: a recorded CreatedRoot means this
        run created the whole tree, so deleting it restores the exact
        pre-change state; otherwise only the recorded PreviousValues are
        put back, and the key itself is never deleted.
    #>
    param(
        [Parameter(Mandatory)]
        [PSCustomObject]$Item,

        [scriptblock]$RemoveKeyTreeAction,
        [scriptblock]$SetKeyValuesAction,
        [scriptblock]$RemoveKeyValueAction
    )

    if (-not [string]::IsNullOrEmpty($Item.CreatedRoot)) {
        $treeArgs = @{}
        if ($RemoveKeyTreeAction) { $treeArgs['RemoveKeyTreeAction'] = $RemoveKeyTreeAction }
        Remove-WtRegistryKeyTree -Hive $Item.Hive -SubKey $Item.CreatedRoot @treeArgs
        return
    }

    foreach ($previous in @($Item.PreviousValues)) {
        if ($previous.Present) {
            $setArgs = @{}
            if ($SetKeyValuesAction) { $setArgs['SetKeyValuesAction'] = $SetKeyValuesAction }
            Set-WtRegistryKeyValues -Hive $Item.Hive -SubKey $Item.SubKey -Values @(@{ Name = $previous.Name; Kind = $previous.Kind; Value = $previous.Value }) @setArgs
        }
        else {
            $removeArgs = @{}
            if ($RemoveKeyValueAction) { $removeArgs['RemoveKeyValueAction'] = $RemoveKeyValueAction }
            Remove-WtRegistryKeyValue -Hive $Item.Hive -SubKey $Item.SubKey -Name $previous.Name @removeArgs
        }
    }
}
#endregion src/00-core/registry.ps1

#region src/00-core/restore-point.ps1
# System Restore point detection, creation and the on-demand action.
# Covered by: tests/RestorePoint.Tests.ps1

function Test-WtUsesCimRestorePointApi {
    <#
    .SYNOPSIS
        True when the running PowerShell major version should use the CIM
        restore-point API (6+) instead of Checkpoint-Computer (5.1 and
        below); PS7 does not ship Checkpoint-Computer or Get-ComputerRestorePoint.
    #>
    param(
        [Parameter(Mandatory)]
        [int]$PSMajorVersion
    )
    return ($PSMajorVersion -ge 6)
}

function Test-WtSystemProtectionEnabled {
    <#
    .SYNOPSIS
        True when System Protection is enabled for the system drive
        (RPGlobalInterval is 0 when disabled, on Vista and later - one
        check, no version branch needed).
    #>
    $config = Get-CimInstance -Namespace 'root/default' -ClassName 'SystemRestoreConfig' -ErrorAction SilentlyContinue
    return ($null -ne $config -and $config.RPGlobalInterval -ne 0)
}

function Test-WtRestorePointRecent {
    <#
    .SYNOPSIS
        Returns the age in hours of the most recent restore point, or $null
        if none exists; branches on Test-WtUsesCimRestorePointApi between
        Get-ComputerRestorePoint (5.1) and Get-CimInstance (7).
    #>
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseCompatibleCommands', '',
        Justification = 'Get-ComputerRestorePoint only executes in the PS5.1 branch, guarded by Test-WtUsesCimRestorePointApi; PSScriptAnalyzer cannot see the runtime version guard.')]
    param()

    if (Test-WtUsesCimRestorePointApi -PSMajorVersion $PSVersionTable.PSVersion.Major) {
        $points = Get-CimInstance -Namespace 'root/default' -ClassName 'SystemRestore' -ErrorAction SilentlyContinue
    }
    else {
        $points = Get-ComputerRestorePoint -ErrorAction SilentlyContinue
    }

    $latest = $points | Sort-Object -Property CreationTime -Descending | Select-Object -First 1
    if (-not $latest) {
        return $null
    }

    $creationTime = [System.Management.ManagementDateTimeConverter]::ToDateTime($latest.CreationTime)
    return (New-TimeSpan -Start $creationTime -End (Get-Date)).TotalHours
}

function Get-WtRestorePointRecords {
    <#
    .SYNOPSIS
        Every restore point, with the read outcome kept separate from the
        result (Succeeded/Points/Error), since an unelevated session makes
        Get-ComputerRestorePoint throw rather than return nothing.
    #>
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseCompatibleCommands', '',
        Justification = 'Get-ComputerRestorePoint only executes in the PS5.1 branch, guarded by Test-WtUsesCimRestorePointApi; PSScriptAnalyzer cannot see the runtime version guard.')]
    param()

    try {
        if (Test-WtUsesCimRestorePointApi -PSMajorVersion $PSVersionTable.PSVersion.Major) {
            $points = @(Get-CimInstance -Namespace 'root/default' -ClassName 'SystemRestore' -ErrorAction Stop)
        }
        else {
            $points = @(Get-ComputerRestorePoint -ErrorAction Stop)
        }
        return [PSCustomObject]@{ Succeeded = $true; Points = @($points); Error = '' }
    }
    catch {
        return [PSCustomObject]@{ Succeeded = $false; Points = @(); Error = [string]$_.Exception.Message }
    }
}

function New-WtRestorePoint {
    <#
    .SYNOPSIS
        Creates a System Restore point with the API matching the running
        PowerShell version. Silently no-ops within 24h of the last point
        (callers must check Test-WtRestorePointRecent), and reads the CIM
        call's HRESULT directly since Invoke-CimMethod never throws on failure.
    #>
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseCompatibleCommands', '',
        Justification = 'Checkpoint-Computer only executes in the PS5.1 branch, guarded by Test-WtUsesCimRestorePointApi; PSScriptAnalyzer cannot see the runtime version guard.')]
    param(
        [Parameter(Mandatory)]
        [string]$Description,

        [int]$PSMajorVersion = $PSVersionTable.PSVersion.Major,

        [scriptblock]$InvokeCimAction = {
            param($Arguments)
            Invoke-CimMethod -Namespace 'root/default' -ClassName 'SystemRestore' -MethodName 'CreateRestorePoint' -Arguments $Arguments -ErrorAction Stop
        }
    )

    try {
        if (Test-WtUsesCimRestorePointApi -PSMajorVersion $PSMajorVersion) {
            $arguments = @{
                Description      = $Description
                RestorePointType = 12
                EventType        = 100
            }
            $cimResult = & $InvokeCimAction $arguments
            if ($null -ne $cimResult -and $cimResult.PSObject.Properties.Name -contains 'ReturnValue' -and [int64]$cimResult.ReturnValue -ne 0) {
                throw "CreateRestorePoint returned $($cimResult.ReturnValue) (0x$([Convert]::ToString([int64]$cimResult.ReturnValue, 16)))"
            }
        }
        else {
            Checkpoint-Computer -Description $Description -RestorePointType 'MODIFY_SETTINGS' -ErrorAction Stop
        }
        return $true
    }
    catch {
        Write-Warning ([string](Get-Translation 'RpCreateFailed') + ' ' + $_.Exception.Message)
        return $false
    }
}

function Invoke-WtCreateRestorePointAction {
    <#
    .SYNOPSIS
        The main menu's "Create System Restore Point" row: creates one on
        demand with no confirmation, or states why not (24h throttle or
        Windows' failure reason) - all rendered inside the panel since
        nothing may write to the raw host behind the painted frame.
    #>
    param(
        [scriptblock]$GetProtectionEnabled = { Test-WtSystemProtectionEnabled },
        [scriptblock]$GetLastPointAgeHours = { Test-WtRestorePointRecent },
        [scriptblock]$CreatePoint = {
            param($Description)
            $captured = $null
            $ok = New-WtRestorePoint -Description $Description -WarningAction SilentlyContinue -WarningVariable captured
            [PSCustomObject]@{ Created = [bool]$ok; Reason = ((@($captured) | ForEach-Object { [string]$_ }) -join ' ') }
        },
        [scriptblock]$ShowMessage = { param($Lines) Show-WtPanelMessage -Breadcrumb $script:WtPanelBreadcrumb -Lines $Lines -Risk 'CAUTION' -Layout 'Compact' },
        [scriptblock]$Acknowledge = { param($Lines) Read-WtPanelAnswer -Breadcrumb $script:WtPanelBreadcrumb -Lines $Lines -Prompt (Get-Translation 'PressEnterToReturn') -Risk 'CAUTION' -Layout 'Compact' },
        [int]$WrapWidth = 66
    )
    if (-not (& $GetProtectionEnabled)) {
        & $Acknowledge @((Get-Translation 'RpProtectionDisabled')) | Out-Null
        return $false
    }
    $age = & $GetLastPointAgeHours
    if ($null -ne $age -and $age -lt 24) {
        & $Acknowledge @((Get-Translation 'RpThrottled')) | Out-Null
        return $false
    }
    & $ShowMessage @((Get-Translation 'RpCreating'))
    $result = & $CreatePoint ('WinToolify: ' + [string](Get-Translation 'RpManualDescription'))
    if ($result -and $result.Created) {
        & $Acknowledge @((Get-Translation 'RpCreated')) | Out-Null
        return $true
    }
    $reason = if ($result) { [string]$result.Reason } else { '' }
    $lines = @(Split-WtWrappedLines -Text $reason -Width $WrapWidth)
    if ($lines.Count -eq 0) { $lines = @((Get-Translation 'RpCreateFailed')) }
    & $Acknowledge $lines | Out-Null
    return $false
}
#endregion src/00-core/restore-point.ps1

#region src/00-core/storage.ps1
# Local data root, JSON read/write, settings file.
# Covered by: tests/Storage.Tests.ps1, tests/Settings.Tests.ps1

function Get-WtDataPath {
    <#
    .SYNOPSIS
        Resolves WinToolify's local data root and creates it (and any
        -SubPath beneath it) on demand. -Scope is mandatory, not defaulted:
        an elevated Start-Process -Verb RunAs runs under the admin profile,
        so a wrong scope would hide machine state from the original user.
    #>
    param(
        [Parameter(Mandatory)]
        [ValidateSet('Machine', 'User')]
        [string]$Scope,

        [string]$SubPath,

        [string]$TestRootOverride
    )

    if ($TestRootOverride) {
        $root = Join-Path $TestRootOverride $Scope
    }
    elseif ($Scope -eq 'Machine') {
        $root = Join-Path $env:ProgramData 'WinToolify'
    }
    else {
        $root = Join-Path $env:LOCALAPPDATA 'WinToolify'
    }

    $target = if ($SubPath) { Join-Path $root $SubPath } else { $root }

    if (-not (Test-Path -LiteralPath $target)) {
        New-Item -ItemType Directory -Path $target -Force | Out-Null
    }

    return $target
}

function Write-WtJson {
    <#
    .SYNOPSIS
        Serializes an object to a JSON file with the project's fixed depth
        and encoding rules, so no caller has to remember them.
    #>
    param(
        [Parameter(Mandatory)]
        [string]$Path,

        [Parameter(Mandatory)]
        [object]$InputObject
    )

    $json = $InputObject | ConvertTo-Json -Depth 10
    Set-Content -LiteralPath $Path -Value $json -Encoding UTF8
}

function Read-WtJson {
    <#
    .SYNOPSIS
        Reads and deserializes a JSON file written by Write-WtJson.
        Returns $null (and warns) for a missing or corrupt file rather than
        throwing - a malformed undo log must not prevent the tool starting.
    #>
    param(
        [Parameter(Mandatory)]
        [string]$Path
    )

    if (-not (Test-Path -LiteralPath $Path)) {
        return $null
    }

    try {
        $raw = Get-Content -LiteralPath $Path -Raw -Encoding UTF8
        return $raw | ConvertFrom-Json
    }
    catch {
        Write-Warning "Read-WtJson: failed to parse '$Path' - $($_.Exception.Message)"
        return $null
    }
}

function ConvertTo-WtIsoText {
    <#
    .SYNOPSIS
        PURE: one timestamp as canonical round-trip ISO 8601 text ('o'),
        whatever shape it arrives in. PowerShell 7's ConvertFrom-Json turns an
        ISO string back into a [datetime], so a bare [string] cast renders it
        in the current culture ("09/01/2026 11:00:00") and no longer matches
        what was written, while Windows PowerShell 5.1 leaves the same value a
        string; every timestamp that comes out of Read-WtJson and is then
        compared, persisted or shown must pass through here so both hosts
        agree. Strings are canonicalized too, since the writers use several
        precisions ('o' for notes, whole seconds for the boot time) and a
        second-precision string must compare equal to the same instant read
        back as a [datetime]. Only the ISO shapes below are recognized, so a
        JSON blob, an id or free text is returned unchanged.
    #>
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return '' }
    $iso = 'o'
    $invariant = [System.Globalization.CultureInfo]::InvariantCulture
    if ($Value -is [datetime]) { return ([datetime]$Value).ToString($iso, $invariant) }
    $text = [string]$Value
    if (-not $text) { return '' }
    $parsed = [datetime]::MinValue
    $formats = [string[]]@($iso, 'yyyy-MM-ddTHH:mm:ss', 'yyyy-MM-ddTHH:mm:ss.fff', 'yyyy-MM-ddTHH:mm:ssK', 'yyyy-MM-ddTHH:mm:ss.fffffffK')
    if ([datetime]::TryParseExact($text, $formats, $invariant, [System.Globalization.DateTimeStyles]::RoundtripKind, [ref]$parsed)) {
        return $parsed.ToString($iso, $invariant)
    }
    return $text
}

function Get-WtSettingsFilePath {
    <#
    .SYNOPSIS
        <User data root>\settings.json - the per-user preferences file
        (language choice). User scope on purpose: the language is a
        personal preference, not machine state.
    #>
    param([string]$TestRootOverride)
    $dataPathArgs = @{ Scope = 'User' }
    if ($TestRootOverride) { $dataPathArgs['TestRootOverride'] = $TestRootOverride }
    return Join-Path (Get-WtDataPath @dataPathArgs) 'settings.json'
}

function Read-WtSettings {
    <#
    .SYNOPSIS
        Loads settings.json; never throws. A missing or corrupt file, or an
        unknown Language value, yields Language = $null so the caller falls
        back to the first-run language screen (Read-WtProfile idiom).
    #>
    param([string]$TestRootOverride)
    $raw = Read-WtJson -Path (Get-WtSettingsFilePath -TestRootOverride $TestRootOverride)
    $language = $null
    $endpoint = ''
    $model = ''
    $apiKey = ''
    $temperature = ''
    $maxTokens = ''
    $numCtx = ''
    $authMode = ''
    if ($null -ne $raw -and ($raw -is [PSCustomObject])) {
        $props = $raw.PSObject.Properties.Name
        if (($props -contains 'Language') -and (@('EN', 'TR') -contains [string]$raw.Language)) { $language = [string]$raw.Language }
        if ($props -contains 'AssistantEndpoint') { $endpoint = [string]$raw.AssistantEndpoint }
        if ($props -contains 'AssistantModel') { $model = [string]$raw.AssistantModel }
        if ($props -contains 'AssistantApiKey') { $apiKey = [string]$raw.AssistantApiKey }
        if ($props -contains 'AssistantTemperature') { $temperature = [string]$raw.AssistantTemperature }
        if ($props -contains 'AssistantMaxTokens') { $maxTokens = [string]$raw.AssistantMaxTokens }
        if ($props -contains 'AssistantNumCtx') { $numCtx = [string]$raw.AssistantNumCtx }
        if ($props -contains 'AssistantAuthMode') { $authMode = [string]$raw.AssistantAuthMode }
    }
    return [PSCustomObject]@{
        Language              = $language; AssistantEndpoint = $endpoint; AssistantModel = $model; AssistantApiKey = $apiKey
        AssistantTemperature  = $temperature; AssistantMaxTokens = $maxTokens; AssistantNumCtx = $numCtx
        AssistantAuthMode     = $authMode
    }
}

function Save-WtSettings {
    <#
    .SYNOPSIS
        Writes settings.json, merging into any existing content rather than
        overwriting it, because other builds/versions keep their own keys in
        this file (seen in the wild: Borders/HistoryPanel/RestorePointMode).
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Settings,
        [string]$TestRootOverride
    )
    $file = Get-WtSettingsFilePath -TestRootOverride $TestRootOverride
    $existing = Read-WtJson -Path $file
    $merged = if ($null -ne $existing -and ($existing -is [PSCustomObject])) { $existing } else { [PSCustomObject]@{} }
    $merged | Add-Member -NotePropertyName 'SchemaVersion' -NotePropertyValue 1 -Force
    foreach ($field in @('Language', 'AssistantEndpoint', 'AssistantModel', 'AssistantApiKey', 'AssistantTemperature', 'AssistantMaxTokens', 'AssistantNumCtx', 'AssistantAuthMode')) {
        if ($Settings.PSObject.Properties.Name -contains $field) {
            $merged | Add-Member -NotePropertyName $field -NotePropertyValue ([string]$Settings.$field) -Force
        }
    }
    Write-WtJson -Path $file -InputObject $merged
}

function Protect-WtAssistantSecret {
    <#
    .SYNOPSIS
        DPAPI-protects the assistant API key for settings.json. Empty in,
        empty out - a local server needs no key and stores none.
    #>
    param([AllowNull()][AllowEmptyString()][string]$PlainText)
    if (-not $PlainText) { return '' }
    $secure = ConvertTo-SecureString -String $PlainText -AsPlainText -Force
    return [string](ConvertFrom-SecureString -SecureString $secure)
}

function Unprotect-WtAssistantSecret {
    <#
    .SYNOPSIS
        The inverse of Protect-WtAssistantSecret. A corrupt blob, or one
        written under another user's DPAPI key (the elevation caveat the
        spec accepts), reads back as '' - "unset", never a crash.
    #>
    param([AllowNull()][AllowEmptyString()][string]$Blob)
    if (-not $Blob) { return '' }
    try {
        $secure = ConvertTo-SecureString -String $Blob -ErrorAction Stop
        $ptr = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
        try { return [System.Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr) }
        finally { [System.Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr) }
    }
    catch { return '' }
}

function Get-WtChatGptAuthPath {
    <#
    .SYNOPSIS
        <User data root>\chatgpt-auth.json - the ChatGPT OAuth session.
        A file of its own rather than settings.json: these values are
        rewritten every time a token is refreshed, while settings.json
        holds durable user preferences.
    #>
    param([string]$TestRootOverride)
    $dataPathArgs = @{ Scope = 'User' }
    if ($TestRootOverride) { $dataPathArgs['TestRootOverride'] = $TestRootOverride }
    return Join-Path (Get-WtDataPath @dataPathArgs) 'chatgpt-auth.json'
}

function Read-WtChatGptAuth {
    <#
    .SYNOPSIS
        The stored ChatGPT session with both tokens decrypted; never
        throws. A missing file, corrupt JSON, or a blob written under
        another user's DPAPI key all read back as an empty session -
        "signed out", never a crash. ExpiresAt goes through
        ConvertTo-WtIsoText: ConvertFrom-Json hands the timestamp back as
        a [datetime], and a bare cast would render it in the current
        culture without its UTC marker, so the expiry check would read a
        fresh token as local time and refresh a token that is still good.
    #>
    param([string]$TestRootOverride)
    $empty = @{ AccessToken = ''; RefreshToken = ''; ExpiresAt = ''; AccountId = ''; Email = ''; PlanType = '' }
    $raw = Read-WtJson -Path (Get-WtChatGptAuthPath -TestRootOverride $TestRootOverride)
    if ($null -eq $raw -or -not ($raw -is [PSCustomObject])) { return $empty }
    $props = @($raw.PSObject.Properties.Name)
    $plain = { param([string]$Name)
        if ($props -contains $Name) { return [string]$raw.$Name }
        return ''
    }
    $secret = { param([string]$Name)
        if ($props -contains $Name) { return [string](Unprotect-WtAssistantSecret -Blob ([string]$raw.$Name)) }
        return ''
    }
    $stamp = { param([string]$Name)
        if ($props -contains $Name) { return [string](ConvertTo-WtIsoText -Value $raw.$Name) }
        return ''
    }
    return @{
        AccessToken  = [string](& $secret 'AccessToken')
        RefreshToken = [string](& $secret 'RefreshToken')
        ExpiresAt    = [string](& $stamp 'ExpiresAt')
        AccountId    = [string](& $plain 'AccountId')
        Email        = [string](& $plain 'Email')
        PlanType     = [string](& $plain 'PlanType')
    }
}

function Save-WtChatGptAuth {
    <#
    .SYNOPSIS
        Writes the ChatGPT session, DPAPI-protecting both tokens. Merges
        into the existing file so a refresh that returns no new refresh
        token does not erase the one already stored, and the account id
        read once at sign-in survives every later refresh.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$Auth,
        [string]$TestRootOverride
    )
    $current = Read-WtChatGptAuth -TestRootOverride $TestRootOverride
    foreach ($field in @('AccessToken', 'RefreshToken', 'ExpiresAt', 'AccountId', 'Email', 'PlanType')) {
        if ($Auth.ContainsKey($field) -and [string]$Auth[$field]) { $current[$field] = [string]$Auth[$field] }
    }
    $out = [PSCustomObject]@{
        SchemaVersion = 1
        AccessToken   = [string](Protect-WtAssistantSecret -PlainText ([string]$current.AccessToken))
        RefreshToken  = [string](Protect-WtAssistantSecret -PlainText ([string]$current.RefreshToken))
        ExpiresAt     = [string]$current.ExpiresAt
        AccountId     = [string]$current.AccountId
        Email         = [string]$current.Email
        PlanType      = [string]$current.PlanType
    }
    Write-WtJson -Path (Get-WtChatGptAuthPath -TestRootOverride $TestRootOverride) -InputObject $out
}

function Clear-WtChatGptAuth {
    <#
    .SYNOPSIS
        Signs out: deletes the session file and empties AssistantAuthMode,
        so a half-cleared state - mode on, no tokens - can never be read
        back.
    #>
    param([string]$TestRootOverride)
    $path = Get-WtChatGptAuthPath -TestRootOverride $TestRootOverride
    if (Test-Path -LiteralPath $path) { Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue }
    Save-WtSettings -Settings ([PSCustomObject]@{ AssistantAuthMode = '' }) -TestRootOverride $TestRootOverride
}
#endregion src/00-core/storage.ps1

#region src/00-core/unblock-self.ps1
# Unblock-WtSelf - drops the Mark of the Web from WinToolify's own file.
# Covered by: tests/UnblockSelf.Tests.ps1

function Unblock-WtSelf {
    <#
    .SYNOPSIS
        Removes the Zone.Identifier stream from the running script, so a
        copy downloaded from the releases page stops being refused by
        RemoteSigned the next time someone launches it. A no-op without a
        script path: the irm | iex launch has no file to unmark. NEVER
        throws - it runs in the entry point ahead of everything, and a
        machine that refuses the write is not a reason to fail to start.
        Returns $true only when a marker was actually removed.
    #>
    param(
        [AllowEmptyString()][string]$Path = $PSCommandPath,
        [scriptblock]$TestBlockedAction = { param($P) $null -ne (Get-Content -LiteralPath $P -Stream 'Zone.Identifier' -ErrorAction SilentlyContinue) },
        [scriptblock]$UnblockAction = { param($P) Unblock-File -LiteralPath $P -ErrorAction Stop }
    )

    if (-not $Path) { return $false }
    try {
        if (-not [bool](& $TestBlockedAction $Path)) { return $false }
        $null = & $UnblockAction $Path
        return $true
    }
    catch { return $false }
}
#endregion src/00-core/unblock-self.ps1

#region src/10-i18n/00-language.ps1
# Default language, the empty translation table, Get-Translation, Resolve-WtCatalogText. en.ps1 and tr.ps1 fill the table.
# Covered by: tests/Translations.Tests.ps1, tests/CatalogI18n.Tests.ps1

$script:Language = "EN"
$script:Translations = @{}

function Get-Translation($Key) {
    return $script:Translations[$script:Language][$Key]
}

function Resolve-WtCatalogText {
    <#
    .SYNOPSIS
        Localizes catalog prose at build time: LabelKey -> DisplayLabel,
        ConsequenceKey -> Consequence, via the active language. A missing
        key leaves the shipped English literal in place, so a
        half-translated table degrades gracefully instead of blanking
        labels. With KeyPrefix, an entry with no explicit key gets one
        synthesized from its sanitized Name; the sanitizer uses
        -creplace, not -replace, because a culture-aware replace drops
        the capital I on Turkish systems.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Catalog,
        [string]$KeyPrefix
    )

    foreach ($entry in $Catalog) {
        $props = $entry.PSObject.Properties.Name
        if ($KeyPrefix) {
            $sanitized = ([string]$entry.Name) -creplace '[^A-Za-z0-9]', ''
            if ($props -contains 'DisplayLabel' -and $entry.DisplayLabel -and -not ($props -contains 'LabelKey' -and $entry.LabelKey)) {
                $entry | Add-Member -NotePropertyName 'LabelKey' -NotePropertyValue ('Cat{0}{1}Label' -f $KeyPrefix, $sanitized) -Force
            }
            if ($props -contains 'Consequence' -and $entry.Consequence -and -not ($props -contains 'ConsequenceKey' -and $entry.ConsequenceKey)) {
                $entry | Add-Member -NotePropertyName 'ConsequenceKey' -NotePropertyValue ('Cat{0}{1}Consequence' -f $KeyPrefix, $sanitized) -Force
            }
            $props = $entry.PSObject.Properties.Name
        }
        if ($props -contains 'LabelKey' -and $entry.LabelKey) {
            $text = Get-Translation $entry.LabelKey
            if ($text) {
                if ($props -contains 'LabelArgs' -and $null -ne $entry.LabelArgs) { $text = $text -f @($entry.LabelArgs) }
                $entry | Add-Member -NotePropertyName 'DisplayLabel' -NotePropertyValue $text -Force
            }
        }
        if ($props -contains 'ConsequenceKey' -and $entry.ConsequenceKey) {
            $text = Get-Translation $entry.ConsequenceKey
            if ($text) {
                if ($props -contains 'ConsequenceArgs' -and $null -ne $entry.ConsequenceArgs) { $text = $text -f @($entry.ConsequenceArgs) }
                $entry | Add-Member -NotePropertyName 'Consequence' -NotePropertyValue $text -Force
            }
        }
    }
    return $Catalog
}
#endregion src/10-i18n/00-language.ps1

