#region src/20-tui/console.ps1
# Initialize/Restore-WtTui, input batches, frame diff and cache, Write-WtFrame.
# Covered by: tests/Tui.Tests.ps1, tests/CtrlGuard.Tests.ps1 (the Ctrl+C / Ctrl+Break guard)

function Initialize-WtTui {
    <#
    .SYNOPSIS
        One-time console setup: glyphs, input mode, VT detection, the
        alternate screen buffer, admin flag. Disables progress bars via
        $global:, not $script:, ProgressPreference, because Appx cmdlets
        resolve it through their own session state and the stream can't
        be redirected.
    #>
    $script:WtGlyphs = Get-WtGlyphSet -Unicode (Test-WtUnicodeGlyphSupport)
    $script:WtPreviousProgressPreference = $global:ProgressPreference
    $global:ProgressPreference = 'SilentlyContinue'
    Reset-WtFrameCache
    $script:WtInputMode = 'Line'
    $script:WtVt = $false
    try {
        if (-not [Console]::IsInputRedirected -and $Host.Name -eq 'ConsoleHost') {
            $null = [Console]::KeyAvailable
            $script:WtInputMode = 'Key'
        }
    }
    catch { $script:WtInputMode = 'Line' }
    if ($script:WtInputMode -eq 'Key') {
        try { $script:WtVt = ([bool]$Host.UI.SupportsVirtualTerminal -and -not [Console]::IsOutputRedirected) } catch { $script:WtVt = $false }
        Enable-WtTuiCtrlCInput
    }
    if ($script:WtVt) {
        $Host.UI.Write($script:WtEsc + '[?1049h' + $script:WtEsc + '[?25l' + $script:WtEsc + '[2J' + $script:WtEsc + '[1;1H')
    }
    else {
        try { [Console]::CursorVisible = ($script:WtInputMode -ne 'Key') } catch { $null = $_ }
        if ($script:WtInputMode -eq 'Key') { Clear-Host }
    }
}

function Enable-WtTuiCtrlCInput {
    <#
    .SYNOPSIS
        Makes Ctrl+C a KEY for the whole session, not PowerShell's break
        signal, so a stray press cannot kill the app mid-action. Set here
        rather than only in the REPL, because a fast third press could
        otherwise slip through as a break signal and end WinToolify.
    #>
    param(
        [scriptblock]$GetConsole = { [Console]::TreatControlCAsInput },
        [scriptblock]$SetConsole = { param($Value) [Console]::TreatControlCAsInput = [bool]$Value }
    )
    try {
        $script:WtTuiSavedCtrlC = [bool](& $GetConsole)
        & $SetConsole $true
        $script:WtTuiCtrlCOwned = $true
    }
    catch { $script:WtTuiSavedCtrlC = $null; $script:WtTuiCtrlCOwned = $false }
}

function Restore-WtTuiCtrlCInput {
    param([scriptblock]$SetConsole = { param($Value) [Console]::TreatControlCAsInput = [bool]$Value })
    $script:WtTuiCtrlCOwned = $false
    if ($null -eq $script:WtTuiSavedCtrlC) { return }
    try { & $SetConsole ([bool]$script:WtTuiSavedCtrlC) } catch { $null = $_ }
    $script:WtTuiSavedCtrlC = $null
}

function Assert-WtTuiCtrlCInput {
    <#
    .SYNOPSIS
        Puts Ctrl+C back to being a KEY after a captured native command
        (sfc, DISM, winget, a child PowerShell) flips the shared
        console-mode bit back on. Called before every blocking key read
        and on the native runner's tick; returns $true when it changed it.
    #>
    param(
        [scriptblock]$GetConsole = { [Console]::TreatControlCAsInput },
        [scriptblock]$SetConsole = { param($Value) [Console]::TreatControlCAsInput = [bool]$Value }
    )
    if (-not $script:WtTuiCtrlCOwned) { return $false }
    try {
        if ([bool](& $GetConsole)) { return $false }
        & $SetConsole $true
        return $true
    }
    catch { return $false }
}

$script:WtCtrlGuardSource = @'
using System;
using System.Runtime.InteropServices;
using System.Threading;
public static class WtCtrlGuard
{
    public delegate bool HandlerRoutine(uint dwCtrlType);
    [DllImport("kernel32.dll", SetLastError = true)] public static extern bool SetConsoleCtrlHandler(HandlerRoutine handler, bool add);
    private static HandlerRoutine _handler;
    private static int _swallowed;
    public static bool IsInstalled { get { return _handler != null; } }
    public static int Swallowed { get { return _swallowed; } }
    private static bool OnCtrl(uint dwCtrlType)
    {
        // CTRL_C_EVENT = 0, CTRL_BREAK_EVENT = 1: handled here, the chain stops
        if (dwCtrlType == 0 || dwCtrlType == 1) { Interlocked.Increment(ref _swallowed); return true; }
        return false;
    }
    public static bool Install()
    {
        if (_handler != null) return true;
        HandlerRoutine handler = new HandlerRoutine(OnCtrl);
        if (!SetConsoleCtrlHandler(handler, true)) return false;
        _handler = handler;
        return true;
    }
    public static bool Remove()
    {
        if (_handler == null) return true;
        bool removed = SetConsoleCtrlHandler(_handler, false);
        _handler = null;
        return removed;
    }
}
'@

function Enable-WtCtrlGuard {
    <#
    .SYNOPSIS
        Registers the process-wide Ctrl+C / Ctrl+Break handler for the whole
        run (the main flow's first statement). Runs before the host's own
        handler (LIFO) so its true return hides the event from the host,
        though a child process still gets it. Returns $true when set up.
    #>
    param([scriptblock]$Apply = {
        if (-not ('WtCtrlGuard' -as [type])) { Add-Type -TypeDefinition $script:WtCtrlGuardSource -ErrorAction Stop }
        [bool][WtCtrlGuard]::Install()
    })
    $script:WtCtrlGuard = $false
    try { $script:WtCtrlGuard = [bool](& $Apply) } catch { $script:WtCtrlGuard = $false }
    return $script:WtCtrlGuard
}

function Disable-WtCtrlGuard {
    <#
    .SYNOPSIS
        Unregisters the handler in the main flow's finally, so a console the
        user opened themselves gets its Ctrl+C back at the prompt. No-op when
        Enable-WtCtrlGuard never took; never throws.
    #>
    param([scriptblock]$Apply = { $null = [WtCtrlGuard]::Remove() })
    if (-not $script:WtCtrlGuard) { return }
    $script:WtCtrlGuard = $false
    try { $null = & $Apply } catch { $null = $_ }
}

function Restore-WtTui {
    <#
    .SYNOPSIS
        Leaves the alternate buffer and shows the cursor again - the
        user's previous console content comes back. Safe to call when
        Initialize-WtTui never ran.
    #>
    if ($script:WtPreviousProgressPreference) { $global:ProgressPreference = $script:WtPreviousProgressPreference }
    Restore-WtTuiCtrlCInput
    if ($script:WtVt) {
        try { $Host.UI.Write($script:WtEsc + '[?1049l' + $script:WtEsc + '[?25h') } catch { $null = $_ }
    }
    else {
        try { [Console]::CursorVisible = $true } catch { $null = $_ }
    }
}

function Get-WtFrameChromeHeight {
    <#
    .SYNOPSIS
        Rows the frame spends outside the content viewport: header
        (banner rows + 4) plus 6 for a default box (borders, path,
        separators, footer) or 4 in banner mode (no path row). The
        layout (Full / Compact) does not change the count.
    #>
    param(
        [Parameter(Mandatory)][int]$Width,
        [bool]$ShowBanner = $false,
        [bool]$Searchable = $false,
        [int]$DescriptionRows = 0
    )
    $header = @(Get-WtBannerLines -Width $Width).Count + 4
    $search = $(if ($Searchable) { 2 } else { 0 })
    $desc = $(if ($DescriptionRows -gt 0) { $DescriptionRows + 1 } else { 0 })
    if ($ShowBanner) { return $header + 4 + $search + $desc }
    return $header + 6 + $search + $desc
}

function Read-WtInputBatch {
    <#
    .SYNOPSIS
        One blocking ReadKey, then drains any auto-repeat queued after a
        navigation key. Never mixes RawUI.ReadKey / FlushInputBuffer -
        separate caches, phantom keys. Converter: (Key, KeyChar) -> token;
        no GetNewClosure, it breaks in the built (non-dot-sourced) script.
        Exhausted redirected stdin returns 'Eof' and sets
        $script:WtInputExhausted, which is how the main menu tells this
        Back from an Esc: Esc stays, this leaves.
    #>
    param([scriptblock]$Converter)

    if ($script:WtInputMode -eq 'Key') {
        $null = Assert-WtTuiCtrlCInput
        $null = Assert-WtWindowMaximized
        try {
            $ki = [Console]::ReadKey($true)
            $first = if ($Converter) { [string](& $Converter ([string]$ki.Key) ([string]$ki.KeyChar)) }
                     else { ConvertTo-WtKeyToken -Key ([string]$ki.Key) -KeyChar ([string]$ki.KeyChar) }
            $tokens = New-Object System.Collections.Generic.List[string]
            $tokens.Add($first)
            if (Test-WtNavToken -Token $first) {
                while ($tokens.Count -lt 64 -and [Console]::KeyAvailable) {
                    $k = [Console]::ReadKey($true)
                    $t = if ($Converter) { [string](& $Converter ([string]$k.Key) ([string]$k.KeyChar)) }
                         else { ConvertTo-WtKeyToken -Key ([string]$k.Key) -KeyChar ([string]$k.KeyChar) }
                    $tokens.Add($t)
                    if (-not (Test-WtNavToken -Token $t)) { break }
                }
            }
            return [string[]]$tokens.ToArray()
        }
        catch {
            $null = Write-WtErrorLog -ErrorRecord $_ -Context 'Read-WtInputBatch: key input failed, falling back to line mode'
            $script:WtInputMode = 'Line'
            Reset-WtFrameCache
        }
    }
    $line = Read-Host (Get-Translation 'InputPrompt')
    if ($null -eq $line) {
        $script:WtInputExhausted = $true
        return [string[]]@('Eof')
    }
    return [string[]]@((ConvertTo-WtLineToken -Line $line))
}

function Clear-WtPendingInput {
    <#
    .SYNOPSIS
        Throws away every key sitting in the console queue and returns how
        many there were. Called after a long action ends and again when
        the nav screen regains control, so a key queued during the action
        (or its auto-repeat) cannot silently replay and repeat the row.
    #>
    param(
        [scriptblock]$KeyAvailable = { [Console]::KeyAvailable },
        [scriptblock]$ReadKey = { [Console]::ReadKey($true) },
        [int]$Cap = 1024
    )
    if ($script:WtInputMode -ne 'Key') { return 0 }
    $drained = 0
    try {
        while ($drained -lt $Cap -and [bool](& $KeyAvailable)) {
            $null = & $ReadKey
            $drained++
        }
    }
    catch { $null = $_ }
    return $drained
}

function Get-WtFrameDiff {
    <#
    .SYNOPSIS
        Indexes of the rows that differ from the previous frame (or every
        index when forced / the previous frame is shorter). Case-sensitive
        ordinal compare: the rows carry SGR payloads.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Rows,
        [AllowEmptyCollection()][string[]]$PrevRows = @(),
        [bool]$Force = $false
    )
    $changed = New-Object System.Collections.Generic.List[int]
    for ($i = 0; $i -lt $Rows.Count; $i++) {
        if ($Force -or $i -ge $PrevRows.Count -or -not [string]::Equals($Rows[$i], $PrevRows[$i], [System.StringComparison]::Ordinal)) { $changed.Add($i) }
    }
    return [int[]]$changed.ToArray()
}

function Reset-WtFrameCache {
    <#
    .SYNOPSIS
        Forget the previous frame so the next Write-WtFrame repaints every
        row. Called after anything that wrote to the console outside the
        painter (console-output mode, Read-Host prompts, native commands).
    #>
    $script:WtPrevRows = @()
    $script:WtPrevWidth = 0
    $script:WtPrevHeight = 0
}

function Get-WtConsoleSize {
    <#
    .SYNOPSIS
        Current window size as @{ Width; Height }, 100x40 when no console
        exists (redirected host, tests).
    #>
    $w = 100
    $h = 40
    try {
        $s = $Host.UI.RawUI.WindowSize
        if ($s.Width -gt 0 -and $s.Height -gt 0) { $w = [int]$s.Width; $h = [int]$s.Height }
    }
    catch { $null = $_ }
    return @{ Width = $w; Height = $h }
}

function Get-WtFrameWidth {
    <#
    .SYNOPSIS
        PURE: how many columns a framed screen may draw into. Rows stop
        one column short of the console by default: filling the last cell
        of a row leaves the console in its pending-wrap state and the next
        character written would push the frame down a line. With VT on
        every row Write-WtFrame paints is preceded by an absolute cursor
        move, which clears that state before anything else is written, so
        there the frame can have the whole width. VT is only ever set in
        Key mode, so this is also what keeps the Line-mode path - where
        each row is written with its own newline - one column short.
    #>
    param(
        [Parameter(Mandatory)][int]$Width,
        [bool]$Vt = $script:WtVt
    )
    return [Math]::Max(20, $(if ($Vt) { $Width } else { $Width - 1 }))
}

function Write-WtFrame {
    <#
    .SYNOPSIS
        Paints a frame: key mode + VT emits one SGR string per changed row
        via CUP in a single host write (DECSET 2026) without touching the
        last column; key mode without VT does the same diff via
        SetCursorPosition + Write; line mode is Clear-Host plus plain rows.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$FrameLines,
        [int]$Width = 0,
        [int]$Height = 0
    )
    if ($Width -le 0 -or $Height -le 0) {
        $size = Get-WtConsoleSize
        if ($Width -le 0) { $Width = $size.Width }
        if ($Height -le 0) { $Height = $size.Height }
    }
    $w = Get-WtFrameWidth -Width $Width
    $lines = @($FrameLines)
    if ($lines.Count -gt $Height) { $lines = @($lines[0..($Height - 1)]) }

    if ($script:WtInputMode -eq 'Line') {
        Clear-Host
        foreach ($line in $lines) { Write-Host (ConvertTo-WtRowString -Segments @($line) -Width $w -Vt $false) }
        return
    }

    $force = ($Width -ne $script:WtPrevWidth -or $Height -ne $script:WtPrevHeight -or @($script:WtPrevRows).Count -eq 0)
    $rows = New-Object string[] $lines.Count
    for ($i = 0; $i -lt $lines.Count; $i++) { $rows[$i] = ConvertTo-WtRowString -Segments @($lines[$i]) -Width $w -Vt $script:WtVt }
    $changed = Get-WtFrameDiff -Rows $rows -PrevRows ([string[]]@($script:WtPrevRows)) -Force $force

    if ($script:WtVt) {
        $e = $script:WtEsc
        $sb = New-Object System.Text.StringBuilder
        [void]$sb.Append($e + '[?2026h')
        if ($force) { [void]$sb.Append($e + '[2J') }
        foreach ($i in $changed) { [void]$sb.Append($e + '[' + ($i + 1) + ';1H').Append($rows[$i]) }
        [void]$sb.Append($e + '[1;1H' + $e + '[?2026l')
        $Host.UI.Write($sb.ToString())
    }
    else {
        if ($force) { Clear-Host }
        $defaultBg = $Host.UI.RawUI.BackgroundColor
        foreach ($i in $changed) {
            try { [Console]::SetCursorPosition(0, $i) } catch { continue }
            $used = 0
            foreach ($seg in @($lines[$i])) {
                $text = [string]$seg.T
                if (($used + $text.Length) -gt $w) { $text = $text.Substring(0, [Math]::Max(0, $w - $used)) }
                if ($text.Length -eq 0) { continue }
                $fg = if ($seg.F -and $script:WtSgrMap.ContainsKey([string]$seg.F)) { [ConsoleColor]$seg.F } else { [ConsoleColor]'Gray' }
                $bg = if ($seg.B -and $script:WtSgrMap.ContainsKey([string]$seg.B)) { [ConsoleColor]$seg.B } else { $defaultBg }
                $Host.UI.Write($fg, $bg, $text)
                $used += $text.Length
            }
            if ($used -lt $w) { $Host.UI.Write([ConsoleColor]'Gray', $defaultBg, (' ' * ($w - $used))) }
        }
        try { [Console]::SetCursorPosition(0, 0) } catch { $null = $_ }
    }
    $script:WtPrevRows = $rows
    $script:WtPrevWidth = $Width
    $script:WtPrevHeight = $Height
}
#endregion src/20-tui/console.ps1

#region src/20-tui/frame.ps1
# Segments, banner, state-column colouring, list rows, Get-WtFrameRows.
# Covered by: tests/Tui.Tests.ps1, tests/RowState.Tests.ps1

function New-WtSeg {
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Text,
        [string]$Fg = 'White',
        [string]$Bg = ''
    )
    return [PSCustomObject]@{ T = $Text; F = $Fg; B = $Bg }
}

$script:WtFrameHeaderCache = @{}

$script:WtRowColumnCache = @{}

function Get-WtRowColumnMetrics {
    <#
    .SYNOPSIS
        @{ RiskWidth; StateFloor; RiskLabels } for the active language,
        computed once per language: RiskWidth is the widest "[label]"
        of SAFE / CAUTION / ADVANCED, StateFloor the widest of the four
        state words a marked row can show, RiskLabels the three labels.
    #>
    $lang = [string]$script:Language
    $hit = $script:WtRowColumnCache[$lang]
    if ($null -ne $hit) { return $hit }
    $labels = @{}
    $riskWidth = 0
    foreach ($r in 'SAFE', 'CAUTION', 'ADVANCED') {
        $text = [string](Get-WtRiskLabel -Risk $r)
        $labels[$r] = $text
        $riskWidth = [Math]::Max($riskWidth, $text.Length + 2)
    }
    $floor = 0
    foreach ($k in 'Applied', 'NotApplied', 'WillApply', 'WillRemove') { $floor = [Math]::Max($floor, ([string](Get-Translation $k)).Length) }
    $metrics = @{ RiskWidth = $riskWidth; StateFloor = $floor; RiskLabels = $labels }
    $script:WtRowColumnCache[$lang] = $metrics
    return $metrics
}

$script:WtStateSegmentCache = @{}

function Get-WtStateSegmentsCached {
    <#
    .SYNOPSIS
        Cached wrapper around Split-WtStateSegments, keyed by
        language|colour|text. Returned segments are shared across rows
        and frames, so callers must never mutate one in place.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Text,
        [string]$DefaultFg = 'DarkGray'
    )
    $key = [string]$script:Language + '|' + $DefaultFg + '|' + $Text
    $hit = $script:WtStateSegmentCache[$key]
    if ($null -ne $hit) { return $hit }
    $segs = @(Split-WtStateSegments -Text $Text -DefaultFg $DefaultFg)
    $script:WtStateSegmentCache[$key] = $segs
    return $segs
}

$script:WtCompactNeedKey = ''
$script:WtCompactNeedValue = 0

$script:WtBrand = 'WinToolify V2'
$script:WtTagline = 'Windows Management Harness'
$script:WtRepoUrl = 'https://github.com/burakarslan0110/WinToolify'

function Get-WtWindowTitle {
    <#
    .SYNOPSIS
        What the console window's title bar reads: the brand, then what
        the tool is. Untranslated on purpose - it is the product name,
        and the title bar is read before any language choice is made.
        The banner keeps the bare brand: a narrow console falls back to
        that one line and has no room for more.
    #>
    return $script:WtBrand + ' - ' + $script:WtTagline
}

function Get-WtBannerCreditLines {
    <#
    .SYNOPSIS
        The two lines under the main-screen banner: author credit and the
        project's repository URL. Pure ASCII, language-independent.
    #>
    return @('Created by Burak Arslan', $script:WtRepoUrl)
}

function Get-WtBannerLines {
    <#
    .SYNOPSIS
        The main-screen brand header. The full 9-line block-letter banner
        needs 87 columns plus margin; anything narrower gets the one-line
        brand so the layout never breaks.
    #>
    param([Parameter(Mandatory)][int]$Width)

    if ($Width -lt 89) { return ,@($script:WtBrand) }

    return @(
        '+=====================================================================================+'
        '|##      ## #### ##    ## ########  #######   #######  ##       #### ######## ##    ##|'
        '|##  ##  ##  ##  ###   ##    ##    ##     ## ##     ## ##        ##  ##        ##  ## |'
        '|##  ##  ##  ##  ####  ##    ##    ##     ## ##     ## ##        ##  ##         ####  |'
        '|##  ##  ##  ##  ## ## ##    ##    ##     ## ##     ## ##        ##  ######      ##   |'
        '|##  ##  ##  ##  ##  ####    ##    ##     ## ##     ## ##        ##  ##          ##   |'
        '|##  ##  ##  ##  ##   ###    ##    ##     ## ##     ## ##        ##  ##          ##   |'
        '| ###  ###  #### ##    ##    ##     #######   #######  ######## #### ##          ##   |'
        '+=====================================================================================+'
    )
}

$script:WtStateColorCache = @{}

function Get-WtStateColorMap {
    <#
    .SYNOPSIS
        The state column's vocabulary: the localized word the app itself
        printed -> the colour that word means. Built from translation
        KEYS, never from literals, so a word and its colour cannot drift
        apart when a translation changes, and TR gets the same colours as
        EN for free. Sorted longest-first, because "currently: off" must
        match before anything shorter that lives inside it.
    #>
    param([string]$Language = $script:Language)
    if ($script:WtStateColorCache.ContainsKey($Language)) { return $script:WtStateColorCache[$Language] }
    $byKey = [ordered]@{
        'FirewallCurrentlyOff' = 'Red'
        'FirewallCurrentlyOn'  = 'Green'
        'NotSupportedWddm'     = 'DarkGray'
        'StateNotPresent'      = 'DarkGray'
        'SvcStart.Automatic'   = 'Green'
        'SvcStart.Disabled'    = 'Red'
        'SvcStart.Manual'      = 'Yellow'
        'SvcStatus.Running'    = 'Green'
        'SvcStatus.Stopped'    = 'Gray'
        'SvcStatus.Paused'     = 'Yellow'
        'SvcStatus.StartPending'    = 'Yellow'
        'SvcStatus.StopPending'     = 'Yellow'
        'SvcStatus.PausePending'    = 'Yellow'
        'SvcStatus.ContinuePending' = 'Yellow'
        'SvcStart.Boot'        = 'Green'
        'SvcStart.System'      = 'Green'
        'FlushAvailable'       = 'Green'
        'StateInstalled'       = 'Green'
        'StateRemoved'         = 'DarkGray'
        'StateUnknown'         = 'DarkGray'
        'FolderNotFound'       = 'DarkGray'
        'Applied'              = 'Green'
        'NotApplied'           = 'DarkGray'
    }
    $pairs = New-Object System.Collections.Generic.List[object]
    foreach ($key in $byKey.Keys) {
        $word = [string]$script:Translations[$Language][$key]
        if (-not $word) { continue }
        $pairs.Add([PSCustomObject]@{ Word = $word; Fg = [string]$byKey[$key] })
    }
    $map = @($pairs | Sort-Object -Property @{ Expression = { $_.Word.Length }; Descending = $true }, Word)
    $script:WtStateColorCache[$Language] = $map
    return $map
}

function Split-WtStateSegments {
    <#
    .SYNOPSIS
        PURE: turns the state column's text into colored segments. A
        vocabulary word gets its own colour; "/" and padding stay
        $DefaultFg. All-or-nothing: unless every character is a
        vocabulary word or the glue between them, the whole column comes
        back as one uncoloured segment, since a path or free-text state
        can match a word mid-string with no boundary. Joining the
        segments always returns $Text unchanged. Matching uses
        CompareOrdinal, not -match/-replace, because tr-TR's
        culture-aware comparison folds I/i the Turkish way.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Text,
        [string]$DefaultFg = 'DarkGray',
        [AllowEmptyCollection()][array]$Vocabulary = (Get-WtStateColorMap)
    )
    if (-not $Text) { return @() }
    $segs = New-Object System.Collections.Generic.List[object]
    $i = 0
    while ($i -lt $Text.Length) {
        $hit = $null
        foreach ($v in $Vocabulary) {
            $w = [string]$v.Word
            if ($w.Length -gt 0 -and $w.Length -le ($Text.Length - $i) -and
                [string]::CompareOrdinal($Text, $i, $w, 0, $w.Length) -eq 0) { $hit = $v; break }
        }
        if ($hit) {
            $segs.Add((New-WtSeg -Text ([string]$hit.Word) -Fg ([string]$hit.Fg)))
            $i += ([string]$hit.Word).Length
            continue
        }
        $start = $i
        while ($i -lt $Text.Length -and ($Text[$i] -eq ' ' -or $Text[$i] -eq '/')) { $i++ }
        if ($i -eq $start) { return @(New-WtSeg -Text $Text -Fg $DefaultFg) }
        $segs.Add((New-WtSeg -Text $Text.Substring($start, $i - $start) -Fg $DefaultFg))
    }
    return $segs.ToArray()
}

function Get-WtListRowSegments {
    <#
    .SYNOPSIS
        Renders one list row into colored segments:
        "{cursor}{number}{marker} {label}  [{risk}]  {state}", truncated
        to fit Width. A marked row shows [x], its pending verb
        (WillApply/WillRemove) instead of the live state, and its state
        column as one solid yellow block instead of vocabulary-coloured.
        Get-WtListRowLabelRoom mirrors this layout arithmetic for callers
        that wrap instead of truncate. NumberWidth right-aligns the row
        number so numbering past 9 still keeps markers and columns
        aligned; unnumbered callers leave it at its 1-digit default.
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Item,
        [Parameter(Mandatory)][bool]$IsCursor,
        [Parameter(Mandatory)][bool]$Selected,
        [Parameter(Mandatory)][PSCustomObject]$Glyphs,
        [Parameter(Mandatory)][int]$Width,
        [int]$VisibleNumber = 0,
        [int]$StateWidth = 0,
        [int]$NumberWidth = 1,
        [string]$PendingLabel = ''
    )

    if ($Item.Kind -eq 'Spacer') { return ,@([PSCustomObject]@{ T = ''; F = 'Gray'; B = '' }) }

    if ($Item.Kind -eq 'Header') {
        $text = '  ' + $Item.Label
        if ($text.Length -gt $Width) { $text = $text.Substring(0, $Width) }
        return ,@([PSCustomObject]@{ T = $text; F = 'Cyan'; B = '' })
    }

    if ($Item.Kind -eq 'Rule') {
        $rule = [string]$Glyphs.Rule
        $lead = '  ' + ($rule * 2) + ' '
        $title = [string]$Item.Label
        $room = $Width - $lead.Length - 2
        if ($title.Length -gt $room -and $room -gt 1) { $title = $title.Substring(0, $room - 1) + '~' }
        $tail = ' ' + ($rule * [Math]::Max(0, $Width - $lead.Length - $title.Length - 1))
        return @(([PSCustomObject]@{ T = $lead; F = 'DarkGray'; B = '' }), ([PSCustomObject]@{ T = $title; F = 'Cyan'; B = '' }), ([PSCustomObject]@{ T = $tail; F = 'DarkGray'; B = '' }))
    }

    $marker = ''
    $applied = ($Item.PSObject.Properties.Name -contains 'Applied') -and [bool]$Item.Applied
    if ($Item.Kind -eq 'Check') { $marker = if ($Selected) { $Glyphs.CheckOn } else { $Glyphs.CheckOff } }
    elseif ($Item.Kind -eq 'Radio') { $marker = if ($Selected) { $Glyphs.RadioOn } else { $Glyphs.RadioOff } }

    $cursorMark = if ($IsCursor) { $Glyphs.Cursor } else { ' ' * $Glyphs.Cursor.Length }
    $numberText = if ($VisibleNumber -gt 0) { ('{0}.' -f $VisibleNumber).PadLeft([Math]::Max(1, $NumberWidth) + 1) + ' ' } else { '' }

    $parts = Get-WtListRowRightParts -Item $Item -StateWidth $StateWidth -Selected $Selected -PendingLabel $PendingLabel
    $riskText = $parts.Risk
    $stateText = $parts.State

    $rightText = $parts.Text
    $leftFixed = $cursorMark + $numberText + $marker + ' '
    $labelRoom = $Width - $leftFixed.Length - $rightText.Length - 2
    $label = [string]$Item.Label
    if ($labelRoom -lt $label.Length -and $rightText) {
        $riskText = $riskText.TrimStart()
        $rightText = ($riskText + '  ' + $stateText).Trim()
        $labelRoom = $Width - $leftFixed.Length - $rightText.Length - 2
    }
    if ($labelRoom -lt 4) { $labelRoom = 4 }
    if ($label.Length -gt $labelRoom) { $label = $label.Substring(0, $labelRoom - 1) + '~' }
    $label = $label.PadRight($labelRoom)

    $rowFg = switch ($Item.Risk) { 'ADVANCED' { 'Red' } 'CAUTION' { 'Yellow' } default { 'White' } }
    if ($Item.Kind -eq 'Info' -and -not $Item.Risk) { $rowFg = 'Gray' }

    if ($IsCursor) {
        $text = $leftFixed + $label + '  ' + $rightText
        if ($text.Length -gt $Width) { $text = $text.Substring(0, $Width) }
        if ($text.Length -lt $Width) { $text = $text.PadRight($Width) }
        return ,@([PSCustomObject]@{ T = $text; F = 'Black'; B = 'DarkCyan' })
    }

    $pending = ($Selected -and $Item.Kind -eq 'Check' -and $stateText.Trim())
    $stateFg = if ($pending) { 'Yellow' } elseif ($applied) { 'Green' } else { 'DarkGray' }
    $stateOnly = $rightText.Substring($riskText.Length)
    $stateSegs = if ($pending) { @([PSCustomObject]@{ T = $stateOnly; F = $stateFg; B = '' }) }
                 else { @(Get-WtStateSegmentsCached -Text $stateOnly -DefaultFg $stateFg) }
    if ($stateSegs.Count -eq 0) { $stateSegs = @([PSCustomObject]@{ T = $stateOnly; F = $stateFg; B = '' }) }
    $segs = @(
        [PSCustomObject]@{ T = ($leftFixed + $label + '  '); F = $rowFg; B = '' }
        [PSCustomObject]@{ T = $riskText; F = $rowFg; B = '' }
    ) + $stateSegs
    $totalLength = 0
    foreach ($s in $segs) { $totalLength += ([string]$s.T).Length }
    if ($totalLength -gt $Width) {
        $total = ''
        foreach ($s in $segs) { $total += [string]$s.T }
        return ,@([PSCustomObject]@{ T = $total.Substring(0, $Width); F = $rowFg; B = '' })
    }
    return $segs
}

function Get-WtListRowRightParts {
    <#
    .SYNOPSIS
        PURE: builds the right-hand part of a list row as two
        fixed-width columns so rows line up - the risk tag right-aligned
        to the widest localized tag, then the state left-aligned and
        padded to the wider of the Applied/NotApplied labels. A row
        missing risk or state still reserves that column, unless no row
        on the screen has a state column at all (StateWidth 0), in which
        case nothing is reserved. PendingVerbKey lets a marked row show
        its own pending action (e.g. "Kaldirilacak") without touching
        Applied, which still decides direction and markability.
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Item,
        [int]$StateWidth = 0,
        [bool]$Selected = $false,
        [string]$PendingLabel = ''
    )
    $metrics = $script:WtRowColumnCache[[string]$script:Language]
    if ($null -eq $metrics) { $metrics = Get-WtRowColumnMetrics }
    $showTag = (-not ($Item.PSObject.Properties.Name -contains 'RiskTag')) -or [bool]$Item.RiskTag
    $riskRaw = ''
    if ($Item.Risk -and $showTag) {
        $riskKey = [string]$Item.Risk
        $riskText = $(if ($metrics.RiskLabels.ContainsKey($riskKey)) { [string]$metrics.RiskLabels[$riskKey] } else { [string](Get-WtRiskLabel -Risk $riskKey) })
        $riskRaw = '[' + $riskText + ']'
    }
    $stateRaw = [string]$Item.StateLabel
    if ($Selected -and $Item.Kind -eq 'Check' -and $PendingLabel) { $stateRaw = '-> ' + $PendingLabel }
    elseif ($Selected -and $Item.Kind -eq 'Check' -and $stateRaw) {
        $applied = ($Item.PSObject.Properties.Name -contains 'Applied') -and [bool]$Item.Applied
        $verbKey = if (($Item.PSObject.Properties.Name -contains 'PendingVerbKey') -and $Item.PendingVerbKey) { [string]$Item.PendingVerbKey }
                   elseif ($applied) { 'WillRemove' } else { 'WillApply' }
        $stateRaw = Get-Translation $verbKey
    }
    if (-not $riskRaw -and -not $stateRaw) { return @{ Risk = ''; State = ''; Text = '' } }
    $risk = $riskRaw.PadLeft([int]$metrics.RiskWidth)
    if (-not $stateRaw -and $StateWidth -le 0) { return @{ Risk = $risk; State = ''; Text = $risk } }
    $stateWidth = [Math]::Max($StateWidth, [int]$metrics.StateFloor)
    $state = $stateRaw.PadRight($stateWidth)
    return @{ Risk = $risk; State = $state; Text = ($risk + '  ' + $state) }
}

function Get-WtListRowLabelRoom {
    <#
    .SYNOPSIS
        PURE: how many characters this row's label may use at the given
        inner width - the same arithmetic Get-WtListRowSegments lays the
        row out with, exposed so callers can WRAP text to fit instead of
        letting the renderer cut it with '~'.
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Item,
        [Parameter(Mandatory)][PSCustomObject]$Glyphs,
        [Parameter(Mandatory)][int]$Width,
        [int]$VisibleNumber = 0,
        [int]$StateWidth = 0,
        [int]$NumberWidth = 1
    )
    $marker = if ($Item.Kind -eq 'Check' -or $Item.Kind -eq 'Radio') { 3 } else { 0 }
    $number = if ($VisibleNumber -gt 0) { [Math]::Max(1, $NumberWidth) + 2 } else { 0 }
    $right = (Get-WtListRowRightParts -Item $Item -StateWidth $StateWidth).Text
    $room = $Width - $Glyphs.Cursor.Length - $number - $marker - 1 - $right.Length - 2
    if ($room -lt 4) { $room = 4 }
    return $room
}

function ConvertTo-WtPanelLines {
    <#
    .SYNOPSIS
        Panel text wrapped so no row is ever cut with '~'. Every line is
        folded to the room a message row really has at this width; blank
        lines are kept because they are deliberate separators. All lines
        wrap to the FIRST row's room (the one carrying the risk tag), so
        a wrapped paragraph forms a straight block instead of widening on
        later lines.
    #>
    param(
        [AllowEmptyCollection()][string[]]$Lines = @(),
        [Parameter(Mandatory)][int]$Width,
        [string]$Risk = '',
        [PSCustomObject]$Glyphs = $script:WtGlyphs
    )
    $probe = New-WtListItem -Kind 'Info' -Name 'Probe' -Label '' -Risk $Risk
    $room = Get-WtListRowLabelRoom -Item $probe -Glyphs $Glyphs -Width $Width
    $out = New-Object System.Collections.Generic.List[string]
    foreach ($line in @($Lines)) {
        $text = [string]$line
        if (-not $text.Trim()) { $out.Add(''); continue }
        foreach ($piece in @(Split-WtWrappedLines -Text $text -Width $room)) { $out.Add($piece) }
    }
    return [string[]]$out.ToArray()
}

function Format-WtDirectionCounts {
    <#
    .SYNOPSIS
        PURE: "2 to apply, 1 to remove" - zero parts are omitted, both
        zero gives ''. Used by the list counter, the commit summary and
        the apply prompt so every place words the two directions alike.
    #>
    param(
        [Parameter(Mandatory)][int]$ApplyCount,
        [Parameter(Mandatory)][int]$RemoveCount
    )
    $parts = @()
    if ($ApplyCount -gt 0) { $parts += ((Get-Translation 'MarkSummaryApply') -f $ApplyCount) }
    if ($RemoveCount -gt 0) { $parts += ((Get-Translation 'MarkSummaryRemove') -f $RemoveCount) }
    return ($parts -join ', ')
}

function Get-WtMarkSummary {
    <#
    .SYNOPSIS
        PURE: how many marked rows will be applied and how many removed
        (a marked row whose Applied flag is set is a removal), plus the
        formatted counter text. Raw rows (no Applied property on any
        Item at all - the non-apply multi-select pickers such as the DNS
        flush / duplicate finder / cleanup screens) have no direction to
        speak of, so the counter just says how many are marked.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Items,
        [Parameter(Mandatory)][AllowEmptyCollection()][System.Collections.Generic.HashSet[string]]$Selection
    )
    $apply = 0
    $remove = 0
    $hasAppliedProperty = $false
    foreach ($item in $Items) {
        if ($item.PSObject.Properties.Name -contains 'Applied') { $hasAppliedProperty = $true }
        if (-not $Selection.Contains([string]$item.Name)) { continue }
        if (($item.PSObject.Properties.Name -contains 'Applied') -and [bool]$item.Applied) { $remove++ } else { $apply++ }
    }
    if (-not $hasAppliedProperty) {
        return @{ ApplyCount = $apply; RemoveCount = $remove; Text = ((Get-Translation 'MarkedCount') -f $Selection.Count) }
    }
    return @{ ApplyCount = $apply; RemoveCount = $remove; Text = (Format-WtDirectionCounts -ApplyCount $apply -RemoveCount $remove) }
}

function Get-WtListRowNaturalWidth {
    <#
    .SYNOPSIS
        Columns one row needs so Get-WtListRowSegments shows its label
        untruncated: cursor + the right-aligned number column + marker +
        space + label + two spaces + risk/state. Mirrors that function's
        layout math (same NumberWidth); the compact box is sized from the
        widest row.
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Item,
        [Parameter(Mandatory)][PSCustomObject]$Glyphs,
        [int]$StateWidth = 0,
        [int]$NumberWidth = 1
    )
    $label = [string]$Item.Label
    if ($Item.Kind -eq 'Spacer') { return 0 }
    if ($Item.Kind -eq 'Header') { return 2 + $label.Length }
    if ($Item.Kind -eq 'Rule') { return 5 + $label.Length + 4 }
    $marker = if ($Item.Kind -eq 'Check' -or $Item.Kind -eq 'Radio') { 3 } else { 0 }
    $right = (Get-WtListRowRightParts -Item $Item -StateWidth $StateWidth).Text
    $gap = if ($right) { 2 } else { 0 }
    return $Glyphs.Cursor.Length + [Math]::Max(1, $NumberWidth) + 2 + $marker + 1 + $label.Length + $gap + $right.Length
}

function Get-WtFrameDescriptionLines {
    <#
    .SYNOPSIS
        PURE: the text of the description band for the row the cursor is
        on - the row's Desc word-wrapped to Width, ALWAYS exactly Rows
        lines, padded with empty ones. Fixed height is the whole point:
        the box must not change shape as the cursor walks the menu, so a
        row with no description (a rule, a spacer, a screen that never
        set one) yields blank lines rather than a shorter band. A
        description too long for the band ends its last line with '~'
        instead of being cut off in silence.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Items,
        [Parameter(Mandatory)][int]$CursorIndex,
        [Parameter(Mandatory)][int]$Width,
        [int]$Rows = 2
    )
    $count = [Math]::Max(0, $Rows)
    $w = [Math]::Max(8, $Width)
    $text = ''
    if ($CursorIndex -ge 0 -and $CursorIndex -lt $Items.Count) {
        $item = $Items[$CursorIndex]
        if ($null -ne $item) { $text = [string]$item.Desc }
    }
    $wrapped = @(Split-WtWrappedLines -Text $text -Width $w)
    $out = New-Object System.Collections.Generic.List[string]
    for ($i = 0; $i -lt $count; $i++) {
        $line = $(if ($i -lt $wrapped.Count) { [string]$wrapped[$i] } else { '' })
        if ($i -eq ($count - 1) -and $wrapped.Count -gt $count) {
            if ($line.Length -ge $w) { $line = $line.Substring(0, $w - 1) }
            $line = $line.TrimEnd() + '~'
        }
        $out.Add($line)
    }
    return $out.ToArray()
}

function Get-WtFrameRows {
    <#
    .SYNOPSIS
        Composes one complete screen as an array of segment-lines that
        owns EVERY console row (Count == Height); pure, the painter only
        prints what this returns. Every row is exactly Width-1 columns so
        the last console column is never written and nothing can wrap or
        scroll. Layout 'Full' spans the console with a path row, content
        viewport, footer and border; 'Compact' menus/panels size to their
        rows and center horizontally, always sized by the worst case
        (full unfiltered list, longest footer guide) so a live filter or
        swapped footer never resizes it mid-interaction. Row segments are
        collected without wrapping calls in @(), which would re-box an
        already-array result instead of flattening it.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb,
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Items,
        [Parameter(Mandatory)][hashtable]$State,
        [Parameter(Mandatory)][int]$Width,
        [Parameter(Mandatory)][int]$Height,
        [Parameter(Mandatory)][PSCustomObject]$Glyphs,
        [string]$CounterText = '',
        [string]$FooterText = '',
        [bool]$LineMode = $false,
        [bool]$ShowBanner = $false,
        [ValidateSet('Full', 'Compact')][string]$Layout = 'Full',
        [hashtable]$CycleLabels = @{},
        [hashtable]$Search = $null,
        [AllowNull()][array]$SizeItems = $null,
        [string]$FooterSizeText = '',
        [int]$DescriptionRows = 0
    )
    $w = Get-WtFrameWidth -Width $Width
    $h = $Glyphs.H
    $v = $Glyphs.V
    $measureItems = $Items
    if ($null -ne $SizeItems) { $measureItems = $SizeItems }
    $stateWidth = 0
    foreach ($item in $measureItems) { if ($item.StateLabel) { $stateWidth = [Math]::Max($stateWidth, ([string]$item.StateLabel).Length) } }
    $rows = New-Object System.Collections.Generic.List[object]
    $blankRow = { ,@(New-WtSeg -Text (' ' * $w) -Fg 'Gray') }
    $centered = { param([string]$Text, [string]$Fg)
        if ($Text.Length -gt $w) { $Text = $Text.Substring(0, $w) }
        $pad = [Math]::Max(0, [Math]::Floor(($w - $Text.Length) / 2))
        ,@(New-WtSeg -Text ((' ' * $pad) + $Text + (' ' * ($w - $pad - $Text.Length))) -Fg $Fg)
    }

    $headerKey = [string]$Width + 'x' + [string]$w
    $header = $script:WtFrameHeaderCache[$headerKey]
    if ($null -eq $header) {
        $header = New-Object System.Collections.Generic.List[object]
        foreach ($b in (Get-WtBannerLines -Width $Width)) { $header.Add((& $centered $b 'Cyan')) }
        $header.Add((& $blankRow))
        $credit = @(Get-WtBannerCreditLines)
        $header.Add((& $centered ([string]$credit[0]) 'Gray'))
        $header.Add((& $centered ([string]$credit[1]) 'DarkGray'))
        $header.Add((& $blankRow))
        $script:WtFrameHeaderCache[$headerKey] = $header
    }
    foreach ($hr in $header) { $rows.Add($hr) }

    $searchable = ($null -ne $Search)
    $chromeCount = Get-WtFrameChromeHeight -Width $Width -ShowBanner $ShowBanner -Searchable $searchable -DescriptionRows $DescriptionRows
    $viewHeight = [Math]::Max(1, $Height - $chromeCount)
    if ($Layout -eq 'Compact') { $viewHeight = [Math]::Max(1, [Math]::Min($viewHeight, $measureItems.Count)) }
    $window = Get-WtViewportWindow -ItemCount $Items.Count -CursorIndex ([int]$State.CursorIndex) -ViewHeight $viewHeight -WindowStart ([int]$State.WindowStart)
    $listNumbers = 0
    foreach ($item in $measureItems) {
        $kind = [string]$item.Kind
        if ($kind -eq 'Check' -or $kind -eq 'Link' -or $kind -eq 'Action' -or $kind -eq 'Radio') { $listNumbers++ }
    }
    $numberWidth = [Math]::Max(1, ([string][Math]::Max(1, $listNumbers)).Length)
    $rangeText = ''
    if ($Items.Count -gt $viewHeight) {
        $rangeText = '{0}-{1}/{2}' -f ($window + 1), ([Math]::Min($window + $viewHeight, $Items.Count)), $Items.Count
    }
    $right = (@($CounterText, $rangeText) | Where-Object { $_ }) -join '  '
    $showPath = -not $ShowBanner
    $footerStatus = [string]$(if ($ShowBanner) { $rangeText })

    $bw = $w
    if ($Layout -eq 'Compact') {
        $needKey = [string][System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($measureItems) + '|' + $measureItems.Count + '|' + $stateWidth + '|' + $numberWidth + '|' + $DescriptionRows + '|' + [string]$script:Language
        if ($script:WtCompactNeedKey -eq $needKey) { $need = [int]$script:WtCompactNeedValue }
        else {
            $need = 0
            foreach ($item in $measureItems) { $need = [Math]::Max($need, (Get-WtListRowNaturalWidth -Item $item -Glyphs $Glyphs -StateWidth $stateWidth -NumberWidth $numberWidth)) }
            if ($DescriptionRows -gt 0) {
                $longestDesc = 0
                foreach ($item in $measureItems) { $longestDesc = [Math]::Max($longestDesc, ([string]$item.Desc).Length) }
                if ($longestDesc -gt 0) { $need = [Math]::Max($need, [int][Math]::Ceiling($longestDesc / [double]$DescriptionRows) + 4) }
            }
            $script:WtCompactNeedKey = $needKey
            $script:WtCompactNeedValue = $need
        }
        if ($showPath) {
            $sizeRange = ''
            if ($measureItems.Count -gt $viewHeight) { $sizeRange = '{0}-{1}/{2}' -f ($measureItems.Count - $viewHeight + 1), $measureItems.Count, $measureItems.Count }
            $sizeRight = (@($CounterText, $sizeRange) | Where-Object { $_ }) -join '  '
            $need = [Math]::Max($need, ([string]$Breadcrumb).Length + [Math]::Max($right.Length, $sizeRight.Length) + 2)
        }
        if ($searchable) {
            $sLabel = (Get-Translation 'ListSearchLabel') + ': '
            $sValue = ([string](Get-Translation 'ListSearchPlaceholder')).Length
            $sTotal = Get-WtFocusableCount -Items $measureItems
            $sCount = ((Get-Translation 'ListSearchCount') -f $sTotal, $sTotal) + ' - ' + (Get-Translation 'ListSearchClearHint')
            $need = [Math]::Max($need, $sLabel.Length + $sValue + 2 + $sCount.Length)
        }
        $footerNeed = [Math]::Max(([string]$FooterText).Length, ([string]$FooterSizeText).Length)
        if ($footerStatus) { $footerNeed += 2 + $footerStatus.Length }
        $need = [Math]::Max($need, $footerNeed)
        $bw = [Math]::Min($w, [Math]::Max(40, $need + 2 + 4))
    }
    $inner = $bw - 4
    $lead = [Math]::Max(0, [Math]::Floor(($w - $bw) / 2))
    $trail = [Math]::Max(0, $w - $bw - $lead)
    $boxRow = { param([array]$Segs)
        $out = @()
        if ($lead -gt 0) { $out += @(New-WtSeg -Text (' ' * $lead) -Fg 'Gray') }
        $out += @($Segs)
        if ($trail -gt 0) { $out += @(New-WtSeg -Text (' ' * $trail) -Fg 'Gray') }
        ,$out
    }
    $hline = { param([string]$L, [string]$R) ,@(New-WtSeg -Text ($L + ($h * ($bw - 2)) + $R) -Fg 'Cyan') }

    $rows.Add((& $boxRow (& $hline $Glyphs.TL $Glyphs.TR)))

    if ($showPath) {
        $crumb = [string]$Breadcrumb
        $gap = $inner - $crumb.Length - $right.Length
        if ($gap -lt 1) {
            $room = [Math]::Max(0, $inner - $right.Length - 2)
            $crumb = $crumb.Substring(0, $room) + '~'
            $gap = 1
        }
        $rows.Add((& $boxRow @(
            New-WtSeg -Text ($v + ' ') -Fg 'Cyan'
            New-WtSeg -Text $crumb -Fg 'White'
            New-WtSeg -Text ((' ' * $gap) + $right) -Fg 'DarkGray'
            New-WtSeg -Text (' ' + $v) -Fg 'Cyan'
        )))
        $rows.Add((& $boxRow (& $hline $Glyphs.LT $Glyphs.RT)))
    }

    if ($searchable) {
        $searchSegs = @(Get-WtStoreSearchRowSegments -State $Search -Inner $inner -CountText ([string]$Search.CountText) `
            -Label (Get-Translation 'ListSearchLabel') -Placeholder (Get-Translation 'ListSearchPlaceholder'))
        $rows.Add((& $boxRow (@(New-WtSeg -Text ($v + ' ') -Fg 'Cyan') + $searchSegs + @(New-WtSeg -Text (' ' + $v) -Fg 'Cyan'))))
        $rows.Add((& $boxRow (& $hline $Glyphs.LT $Glyphs.RT)))
    }

    $rowNumber = 0
    for ($i = 0; $i -lt $window; $i++) {
        $kind = [string]$Items[$i].Kind
        if ($kind -eq 'Check' -or $kind -eq 'Link' -or $kind -eq 'Action' -or $kind -eq 'Radio') { $rowNumber++ }
    }
    $limit = [Math]::Min($window + $viewHeight, $Items.Count)
    for ($i = $window; $i -lt $limit; $i++) {
        $item = $Items[$i]
        $num = 0
        $kind = [string]$item.Kind
        if ($kind -eq 'Check' -or $kind -eq 'Link' -or $kind -eq 'Action' -or $kind -eq 'Radio') { $rowNumber++; $num = $rowNumber }
        $isCursor = ($i -eq [int]$State.CursorIndex)
        $pending = ''
        if ($State.ContainsKey('Cycle') -and $null -ne $State.Cycle -and $State.Cycle.ContainsKey([string]$item.Name)) {
            $target = [string]$State.Cycle[[string]$item.Name]
            $pending = $(if ($CycleLabels.ContainsKey($target)) { [string]$CycleLabels[$target] } else { $target })
        }
        $segs = Get-WtListRowSegments -Item $item -IsCursor $isCursor -Selected ($State.Selection.Contains($item.Name)) -Glyphs $Glyphs -Width $inner -VisibleNumber $num -StateWidth $stateWidth -NumberWidth $numberWidth -PendingLabel $pending
        $segLen = 0
        foreach ($s in $segs) { $segLen += ([string]$s.T).Length }
        if ($segLen -lt $inner) {
            $padSeg = if ($isCursor) { [PSCustomObject]@{ T = (' ' * ($inner - $segLen)); F = 'Black'; B = 'DarkCyan' } } else { [PSCustomObject]@{ T = (' ' * ($inner - $segLen)); F = 'Gray'; B = '' } }
            $segs = @($segs) + @($padSeg)
        }
        $rows.Add((& $boxRow (@([PSCustomObject]@{ T = ($v + ' '); F = 'Cyan'; B = '' }) + $segs + @([PSCustomObject]@{ T = (' ' + $v); F = 'Cyan'; B = '' }))))
    }
    for ($i = ($limit - $window); $i -lt $viewHeight; $i++) {
        $rows.Add((& $boxRow @(New-WtSeg -Text ($v + (' ' * ($bw - 2)) + $v) -Fg 'Cyan')))
    }

    if ($DescriptionRows -gt 0) {
        $rows.Add((& $boxRow (& $hline $Glyphs.LT $Glyphs.RT)))
        foreach ($line in (Get-WtFrameDescriptionLines -Items $Items -CursorIndex ([int]$State.CursorIndex) -Width $inner -Rows $DescriptionRows)) {
            $text = [string]$line
            if ($text.Length -gt $inner) { $text = $text.Substring(0, $inner) }
            $rows.Add((& $boxRow @(
                New-WtSeg -Text ($v + ' ') -Fg 'Cyan'
                New-WtSeg -Text ($text + (' ' * ($inner - $text.Length))) -Fg 'Gray'
                New-WtSeg -Text (' ' + $v) -Fg 'Cyan'
            )))
        }
    }

    $rows.Add((& $boxRow (& $hline $Glyphs.LT $Glyphs.RT)))
    $footer = [string]$FooterText
    $statusPart = ''
    if ($footerStatus) {
        if ($footerStatus.Length -gt $inner) { $footerStatus = $footerStatus.Substring(0, $inner) }
        $statusRoom = [Math]::Max(0, $inner - $footerStatus.Length - 2)
        if ($footer.Length -gt $statusRoom) { $footer = $(if ($statusRoom -gt 1) { $footer.Substring(0, $statusRoom - 1) + '~' } else { $footer.Substring(0, $statusRoom) }) }
        $statusPart = (' ' * [Math]::Max(0, $inner - $footer.Length - $footerStatus.Length)) + $footerStatus
    }
    elseif ($footer.Length -gt $inner) { $footer = $(if ($inner -gt 1) { $footer.Substring(0, $inner - 1) + '~' } else { $footer.Substring(0, $inner) }) }
    $rows.Add((& $boxRow @(
        New-WtSeg -Text ($v + ' ') -Fg 'Cyan'
        New-WtSeg -Text $footer -Fg 'Yellow'
        New-WtSeg -Text $statusPart -Fg 'Yellow'
        New-WtSeg -Text ((' ' * [Math]::Max(0, $inner - $footer.Length - $statusPart.Length)) + ' ' + $v) -Fg 'Cyan'
    )))
    $rows.Add((& $boxRow (& $hline $Glyphs.BL $Glyphs.BR)))

    while ($rows.Count -lt $Height) { $rows.Add((& $blankRow)) }
    return $rows.ToArray()
}
#endregion src/20-tui/frame.ps1

#region src/20-tui/gates.ps1
# Yes/no letters, typed-word gates, Confirm-WtDestructiveAction.
# Covered by: tests/ApplyFlow.Tests.ps1

function Get-WtAnswerLetter {
    <#
    .SYNOPSIS
        The single upper-case letter the active language expects for
        "yes" / "no" - Y/N in English, E/H (Evet/Hayir) in Turkish. Falls
        back to the English letters if a language ever ships without the
        keys, so a prompt can never end up with no accepted answer.
    #>
    param([Parameter(Mandatory)][ValidateSet('Yes', 'No')][string]$Kind)
    $letter = [string](Get-Translation ($Kind + 'Letter'))
    if (-not $letter) { $letter = if ($Kind -eq 'Yes') { 'Y' } else { 'N' } }
    return $letter.Substring(0, 1).ToUpperInvariant()
}

function Test-WtAffirmativeAnswer {
    <#
    .SYNOPSIS
        True when a typed answer starts with the active language's "yes"
        letter (Y in English, E in Turkish). Every yes/no prompt in the
        script defaults to no, so this one predicate answers all of them:
        blank input, the "no" letter and any typo all mean no.
    #>
    param([AllowNull()][AllowEmptyString()][string]$Answer)
    $text = ([string]$Answer).Trim()
    if (-not $text) { return $false }
    return ($text.Substring(0, 1).ToUpperInvariant() -eq (Get-WtAnswerLetter -Kind 'Yes'))
}

function Format-WtYesNoHint {
    <#
    .SYNOPSIS
        The tail of a yes-no prompt, written the way the navigation guide
        writes everything else: "E: Evet - H: Hayir" in Turkish,
        "Y: Yes - N: No" in English. Prompt strings never carry this
        themselves, so no translation can drift away from the letters the
        code actually accepts.
    #>
    return '{0}: {1} - {2}: {3}' -f (Get-WtAnswerLetter -Kind 'Yes'), (Get-Translation 'AnswerYes'),
                                    (Get-WtAnswerLetter -Kind 'No'), (Get-Translation 'AnswerNo')
}

function Get-WtYesNoPrompt {
    <#
    .SYNOPSIS
        A prompt sentence plus its localized yes-no hint.
    #>
    param(
        [Parameter(Mandatory)][string]$Text
    )
    return ($Text.TrimEnd() + ' ' + (Format-WtYesNoHint))
}

function Get-WtTypedWord {
    <#
    .SYNOPSIS
        The word a destructive gate asks the user to type out in full -
        YES / CONFIRM in English, EVET / ONAYLA in Turkish. Upper-case in
        the prompt; what the user types is matched case-insensitively
        (see Test-WtTypedConfirmation).
    #>
    param([Parameter(Mandatory)][ValidateSet('Yes', 'Confirm')][string]$Kind)
    $word = [string](Get-Translation ('Typed' + $Kind + 'Word'))
    if (-not $word) { $word = if ($Kind -eq 'Yes') { 'YES' } else { 'CONFIRM' } }
    return $word
}

function Get-WtAcceptedTypedWords {
    <#
    .SYNOPSIS
        Every spelling a gate accepts: this gate's word in EVERY language
        the build ships, plus the English fallback. A user who switched
        the UI to English but still thinks in Turkish types ONAYLA and it
        works - refusing that only costs them their selection.
    #>
    param([Parameter(Mandatory)][ValidateSet('Yes', 'Confirm')][string]$Kind)
    $key = 'Typed' + $Kind + 'Word'
    $words = New-Object System.Collections.Generic.List[string]
    $words.Add($(if ($Kind -eq 'Yes') { 'YES' } else { 'CONFIRM' }))
    foreach ($lang in @($script:Translations.Keys)) {
        $word = [string]$script:Translations[$lang][$key]
        if ($word -and -not ($words -contains $word)) { $words.Add($word) }
    }
    return [string[]]$words.ToArray()
}

function Get-WtGateWordHint {
    <#
    .SYNOPSIS
        The line a gate panel shows above its prompt (and a refusal
        repeats): which word to type, case-insensitive. Names the
        English word too unless the screen is already in English.
    #>
    param([Parameter(Mandatory)][ValidateSet('Yes', 'Confirm')][string]$Kind)
    $local = Get-WtTypedWord -Kind $Kind
    $english = $(if ($Kind -eq 'Yes') { 'YES' } else { 'CONFIRM' })
    if ([string]::Equals($local, $english, [System.StringComparison]::OrdinalIgnoreCase)) { return ((Get-Translation 'GateWordHintOne') -f $local) }
    return ((Get-Translation 'GateWordHint') -f $local, $english)
}

function Get-WtGateRefusalLines {
    <#
    .SYNOPSIS
        PURE: what a gate dropped, said plainly. "Nothing left to apply"
        on its own tells the user nothing - this names the word they did
        not type, lists the rows it cost them, and repeats that case does
        not matter so they know the retry will work.
    #>
    param([AllowEmptyCollection()][array]$Dropped = @())
    $lines = New-Object System.Collections.Generic.List[string]
    $real = @($Dropped | Where-Object { $_ -and @($_.Labels).Count -gt 0 })
    foreach ($d in $real) {
        $kind = [string]$d.Kind
        $lines.Add($(if ($kind -eq 'Mechanism') { Get-Translation 'GateRefusedMechanism' }
                     else { (Get-Translation 'GateRefusedTyped') -f (Get-WtTypedWord -Kind $kind) }))
        foreach ($label in @($d.Labels)) { $lines.Add('  - ' + [string]$label) }
    }
    foreach ($kind in @($real | ForEach-Object { [string]$_.Kind } | Where-Object { $_ -ne 'Mechanism' } | Select-Object -Unique)) {
        $lines.Add('')
        $lines.Add((Get-WtGateWordHint -Kind $kind))
    }
    return [string[]]$lines.ToArray()
}

function Test-WtTypedConfirmation {
    <#
    .SYNOPSIS
        True when the user typed the gate word, in any shipped language,
        matched Ordinal-IgnoreCase rather than ToUpper/-eq because tr-TR
        maps i to I-with-dot and would otherwise miss the match.
    #>
    param(
        [AllowNull()][AllowEmptyString()][string]$Answer,
        [Parameter(Mandatory)][ValidateSet('Yes', 'Confirm')][string]$Kind
    )
    $text = ([string]$Answer).Trim()
    if (-not $text) { return $false }
    foreach ($word in (Get-WtAcceptedTypedWords -Kind $Kind)) {
        if ([string]::Equals($text, $word, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
    }
    return $false
}


function Confirm-WtDestructiveAction {
    <#
    .SYNOPSIS
        Typed-confirmation gate rendered in the panel: the consequence
        (red) plus optional detail lines, then the prompt on the footer
        row. The word the user must type is the localized one (YES in
        English, EVET in Turkish) and the match is case-sensitive.
    #>
    param(
        [Parameter(Mandatory)][string]$Consequence,
        [AllowEmptyCollection()][string[]]$Lines = @(),
        [string]$Breadcrumb = '',
        [scriptblock]$ReadAnswer = { param($Lines, $Prompt) Read-WtPanelAnswer -Breadcrumb $(if ($Breadcrumb) { $Breadcrumb } else { $script:WtPanelBreadcrumb }) -Lines $Lines -Prompt $Prompt -Risk 'ADVANCED' }
    )
    $all = @($Consequence) + @($Lines)
    $typed = & $ReadAnswer $all ((Get-Translation 'TypeYesToConfirm') -f (Get-WtTypedWord -Kind 'Yes'))
    return (Test-WtTypedConfirmation -Answer $typed -Kind 'Yes')
}
#endregion src/20-tui/gates.ps1

#region src/20-tui/glyphs-vt.ps1
# Glyph sets, VT escape map, row/segment text helpers, key and line tokens.
# Covered by: tests/Tui.Tests.ps1

function Test-WtUnicodeGlyphSupport {
    <#
    .SYNOPSIS
        Whether the host can be trusted to render Unicode box-drawing
        glyphs: Windows Terminal always (WT_SESSION set), PowerShell 7+
        otherwise; legacy 5.1 conhost may run raster fonts / OEM
        codepages, so it gets the ASCII set.
    #>
    param(
        [AllowNull()][AllowEmptyString()]
        [string]$WtSession = $env:WT_SESSION,

        [int]$PSMajorVersion = $PSVersionTable.PSVersion.Major
    )

    if (-not [string]::IsNullOrEmpty($WtSession)) { return $true }
    return ($PSMajorVersion -ge 7)
}

function Get-WtGlyphSet {
    <#
    .SYNOPSIS
        The drawing vocabulary for every screen. Unicode characters are
        produced via [char] casts so WinToolify.ps1 itself stays pure
        ASCII (the file has no BOM and must parse identically under any
        ANSI codepage).
    #>
    param(
        [Parameter(Mandatory)]
        [bool]$Unicode
    )

    if ($Unicode) {
        return [PSCustomObject]@{
            H        = [string][char]0x2500
            V        = [string][char]0x2502
            TL       = [string][char]0x250C
            TR       = [string][char]0x2510
            BL       = [string][char]0x2514
            BR       = [string][char]0x2518
            LT       = [string][char]0x251C
            RT       = [string][char]0x2524
            Cursor   = ([string][char]0x25B6) + ' '
            CheckOn  = '[x]'
            CheckOff = '[ ]'
            RadioOn  = '(*)'
            RadioOff = '( )'
            Bullet   = [string][char]0x25CF
            Branch   = [string][char]0x23BF
            Dot      = [string][char]0xB7
            Spinner  = -join @([char]0x280B, [char]0x2819, [char]0x2839, [char]0x2838, [char]0x283C, [char]0x2834, [char]0x2826, [char]0x2827, [char]0x2807, [char]0x280F)
            ListBullet = [string][char]0x2022
            Rule       = [string][char]0x2500
        }
    }

    return [PSCustomObject]@{
        H        = '-'
        V        = '|'
        TL       = '+'
        TR       = '+'
        BL       = '+'
        BR       = '+'
        LT       = '+'
        RT       = '+'
        Cursor   = '> '
        CheckOn  = '[x]'
        CheckOff = '[ ]'
        RadioOn  = '(*)'
        RadioOff = '( )'
        Bullet   = '*'
        Branch   = '\'
        Dot      = '-'
        Spinner  = '|/-\'
        ListBullet = '-'
        Rule       = '-'
    }
}

$script:WtGlyphs = Get-WtGlyphSet -Unicode $false

$script:WtEsc = [string][char]27
$script:WtSgrMap = @{
    Black = 30; DarkRed = 31; DarkGreen = 32; DarkYellow = 33; DarkBlue = 34; DarkMagenta = 35; DarkCyan = 36; Gray = 37
    DarkGray = 90; Red = 91; Green = 92; Yellow = 93; Blue = 94; Magenta = 95; Cyan = 96; White = 97
}

$script:WtSgrPrefixCache = @{}

function Get-WtSgrPrefix {
    <#
    .SYNOPSIS
        The SGR prefix for one colour pair, from the cache after the first
        time. An unknown or empty foreground is 37 (Gray), as before; an
        unknown background adds nothing.
    #>
    param(
        [AllowNull()][AllowEmptyString()][string]$Fg,
        [AllowNull()][AllowEmptyString()][string]$Bg
    )
    $key = [string]$Fg + '|' + [string]$Bg
    $hit = $script:WtSgrPrefixCache[$key]
    if ($null -ne $hit) { return $hit }
    $codes = '37'
    if ($Fg -and $script:WtSgrMap.ContainsKey($Fg)) { $codes = [string]$script:WtSgrMap[$Fg] }
    if ($Bg -and $script:WtSgrMap.ContainsKey($Bg)) { $codes += ';' + ([int]$script:WtSgrMap[$Bg] + 10) }
    $prefix = $script:WtEsc + '[' + $codes + 'm'
    $script:WtSgrPrefixCache[$key] = $prefix
    return $prefix
}

function ConvertTo-WtVtText {
    <#
    .SYNOPSIS
        One colored run as a VT string: ESC[<fg>[;<bg>]m + text + ESC[0m.
        Empty text yields an empty string so padding math stays exact.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Text,
        [string]$Fg = 'White',
        [AllowNull()][AllowEmptyString()][string]$Bg = ''
    )
    if ($Text.Length -eq 0) { return '' }
    return ((Get-WtSgrPrefix -Fg $Fg -Bg $Bg) + $Text + $script:WtEsc + '[0m')
}

function ConvertTo-WtRowString {
    <#
    .SYNOPSIS
        Renders one segment-line into a string that occupies EXACTLY Width
        visible columns: segments are concatenated (styled when Vt),
        truncated at Width, and space-padded (unstyled) to Width. Every
        frame row goes through here, so no stale characters can survive
        a redraw and the right border always lands in the same column.
        Styling goes through the SGR prefix cache rather than calling
        ConvertTo-WtVtText per segment: at 17 segments a store row that
        cost 70-280 ms a frame, the lag behind every cursor move.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Segments,
        [Parameter(Mandatory)][int]$Width,
        [bool]$Vt = $false
    )
    $sb = New-Object System.Text.StringBuilder
    $used = 0
    $cache = $script:WtSgrPrefixCache
    $reset = $script:WtEsc + '[0m'
    foreach ($seg in $Segments) {
        if ($used -ge $Width) { break }
        $text = [string]$seg.T
        if (($used + $text.Length) -gt $Width) { $text = $text.Substring(0, $Width - $used) }
        if ($text.Length -eq 0) { continue }
        if ($Vt) {
            $prefix = $cache[[string]$seg.F + '|' + [string]$seg.B]
            if ($null -eq $prefix) { $prefix = Get-WtSgrPrefix -Fg ([string]$seg.F) -Bg ([string]$seg.B) }
            [void]$sb.Append($prefix).Append($text).Append($reset)
        }
        else { [void]$sb.Append($text) }
        $used += $text.Length
    }
    if ($used -lt $Width) { [void]$sb.Append(' ' * ($Width - $used)) }
    return $sb.ToString()
}

function Get-WtVisibleLength {
    <#
    .SYNOPSIS
        Length of a string once every CSI sequence (ESC [ ... letter) is
        removed - what the console will actually occupy.
    #>
    param([AllowNull()][AllowEmptyString()][string]$Text)
    if (-not $Text) { return 0 }
    $pattern = [regex]::Escape($script:WtEsc) + '\[[0-9;?]*[A-Za-z]'
    return ([regex]::Replace($Text, $pattern, '')).Length
}

function ConvertTo-WtKeyToken {
    <#
    .SYNOPSIS
        Normalizes one ConsoleKeyInfo (passed as its Key name string +
        KeyChar string so tests never need a real console) into the
        screen-reducer token vocabulary. Unknown keys become 'None' and
        are ignored by the reducer.
    #>
    param(
        [Parameter(Mandatory)]
        [string]$Key,

        [AllowNull()][AllowEmptyString()]
        [string]$KeyChar = ''
    )

    switch ($Key) {
        'UpArrow'   { return 'Up' }
        'DownArrow' { return 'Down' }
        'PageUp'    { return 'PageUp' }
        'PageDown'  { return 'PageDown' }
        'Home'      { return 'Home' }
        'End'       { return 'End' }
        'Spacebar'  { return 'Space' }
        'Enter'     { return 'Enter' }
        'LeftArrow' { return 'Back' }
        'Escape'    { return 'Back' }
        'Backspace' { return 'Back' }
    }

    if ($KeyChar -match '^[0-9]$') { return "Digit:$KeyChar" }
    if ($KeyChar -match '^[A-Za-z]$') { return ('Char:' + $KeyChar.ToLowerInvariant()) }
    if ($KeyChar -eq '/') { return 'Char:/' }
    return 'None'
}

function ConvertTo-WtLineToken {
    <#
    .SYNOPSIS
        The line-input fallback (hosts without ReadKey: ISE, redirected
        stdin) speaks the same token vocabulary: empty line = Enter,
        digits = jump, n/p = paging, b = back, any other word = its
        first letter as a Char token.
    #>
    param(
        [AllowNull()][AllowEmptyString()]
        [string]$Line
    )

    $t = ([string]$Line).Trim()
    if ($t -eq '') { return 'Enter' }
    if ($t -match '^[0-9]+$') { return "Digit:$t" }
    if ($t -match '^[Nn]$') { return 'PageDown' }
    if ($t -match '^[Pp]$') { return 'PageUp' }
    if ($t -match '^[Bb]$') { return 'Back' }
    return ('Char:' + $t.Substring(0, 1).ToLowerInvariant())
}
#endregion src/20-tui/glyphs-vt.ps1

#region src/20-tui/grid-frame.ps1
# Store grid and table composers: cells, tab bar, search box, whole frame.
# Covered by: tests/WingetStoreFrame.Tests.ps1

function Get-WtStoreChromeHeight {
    <#
    .SYNOPSIS
        Rows a store frame spends outside its viewport, header included:
        the shared header (banner, credit, URL) plus 8 for Grid, 10 for
        Table, or 11 for Results - borders, breadcrumb+tabs, search row,
        and (Table/Results) a column header.
    #>
    param(
        [ValidateSet('Grid', 'Table', 'Results')][string]$Layout = 'Table',
        [Parameter(Mandatory)][int]$Width
    )
    $header = @(Get-WtBannerLines -Width $Width).Count + 4
    if ($Layout -eq 'Results') { return $header + 11 }
    if ($Layout -eq 'Table') { return $header + 10 }
    return $header + 8
}

$script:WtStoreHeaderCache = @{}

function Get-WtStoreHeaderRows {
    <#
    .SYNOPSIS
        The rows above the store box: block-letter banner, blank row,
        author credit, repository URL, blank row - matching what every
        other screen's header draws. Uses "return , $array" so a
        one-element result is not unwrapped to a scalar by the pipeline.
    #>
    param([Parameter(Mandatory)][int]$Width)
    $w = Get-WtFrameWidth -Width $Width
    $headerKey = [string]$Width + 'x' + [string]$w
    $cached = $script:WtStoreHeaderCache[$headerKey]
    if ($null -ne $cached) { return , $cached }
    $rows = New-Object System.Collections.Generic.List[object]
    $centered = { param([string]$Text, [string]$Fg)
        if ($Text.Length -gt $w) { $Text = $Text.Substring(0, $w) }
        $pad = [Math]::Max(0, [Math]::Floor(($w - $Text.Length) / 2))
        , @(New-WtSeg -Text ((' ' * $pad) + $Text + (' ' * ($w - $pad - $Text.Length))) -Fg $Fg)
    }
    $blankRow = { , @(New-WtSeg -Text (' ' * $w) -Fg 'Gray') }
    foreach ($b in (Get-WtBannerLines -Width $Width)) { $rows.Add((& $centered $b 'Cyan')) }
    $rows.Add((& $blankRow))
    $credit = @(Get-WtBannerCreditLines)
    $rows.Add((& $centered ([string]$credit[0]) 'Gray'))
    $rows.Add((& $centered ([string]$credit[1]) 'DarkGray'))
    $rows.Add((& $blankRow))
    $built = $rows.ToArray()
    $script:WtStoreHeaderCache[$headerKey] = $built
    return , $built
}

function Get-WtStoreTabSegments {
    <#
    .SYNOPSIS
        PURE: the tab switch as segments - "Sekme: [Magaza]  Kurulu" - the
        caption and the idle tab DarkGray, the active tab bracketed and
        White so the eye lands on the one that is open. Shared by the grid
        and the table composer so the two draw the same switch.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$State,
        [hashtable]$TabLabels = @{},
        [string]$Caption = ''
    )
    if (-not $Caption) { $Caption = [string](Get-Translation 'WsTabCaption') }
    $segs = New-Object System.Collections.Generic.List[object]
    $segs.Add((New-WtSeg -Text ($Caption + ': ') -Fg 'DarkGray'))
    $first = $true
    foreach ($t in @('Store', 'Installed')) {
        $label = if ($TabLabels.ContainsKey($t)) { [string]$TabLabels[$t] } else { $t }
        if (-not $first) { $segs.Add((New-WtSeg -Text ' ' -Fg 'DarkGray')) }
        $first = $false
        if ([string]$State.Tab -eq $t) { $segs.Add((New-WtSeg -Text "[$label]" -Fg 'White')) }
        else { $segs.Add((New-WtSeg -Text " $label " -Fg 'DarkGray')) }
    }
    return $segs.ToArray()
}

function Get-WtStoreCrumbSegments {
    <#
    .SYNOPSIS
        PURE: the store's breadcrumb row - breadcrumb, tab switch, mark
        counter on the right - sized to exactly Inner columns. A narrow
        console shrinks the breadcrumb first, then the counter, never the
        tabs: the tabs are functional, the breadcrumb only orientation.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb,
        [Parameter(Mandatory)][AllowEmptyString()][string]$Right,
        [Parameter(Mandatory)][int]$Inner,
        [AllowEmptyCollection()][array]$TabSegments = @()
    )
    $crumb = [string]$Breadcrumb
    $right = [string]$Right
    $tabs = @($TabSegments)
    $tabsLen = 0
    foreach ($s in $tabs) { $tabsLen += ([string]$s.T).Length }
    $sep = $(if ($tabs.Count -gt 0) { 3 } else { 0 })
    $room = $Inner - $sep - $tabsLen - $right.Length - 1
    if ($crumb.Length -gt $room) {
        $crumb = $(if ($room -gt 1) { $crumb.Substring(0, $room - 1) + '~' } else { '' })
    }
    $used = $crumb.Length + $sep + $tabsLen
    if (($used + $right.Length) -gt $Inner) {
        $right = $(if (($Inner - $used) -gt 0) { $right.Substring(0, $Inner - $used) } else { '' })
    }
    $gap = [Math]::Max(0, $Inner - $used - $right.Length)
    $segs = New-Object System.Collections.Generic.List[object]
    $segs.Add((New-WtSeg -Text $crumb -Fg 'White'))
    if ($tabs.Count -gt 0) {
        $segs.Add((New-WtSeg -Text (' ' * $sep) -Fg 'DarkGray'))
        foreach ($s in $tabs) { $segs.Add($s) }
    }
    $segs.Add((New-WtSeg -Text ((' ' * $gap) + $right) -Fg 'DarkGray'))
    return $segs.ToArray()
}

function Get-WtStoreSearchRowSegments {
    <#
    .SYNOPSIS
        PURE: the store's permanent search row - label, typed query with
        a caret only while focused, and the caller's right-aligned count -
        sized to exactly Inner columns so both store composers (grid and
        table) draw byte-for-byte the same row.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$State,
        [Parameter(Mandatory)][int]$Inner,
        [string]$CountText = '',
        [string]$Label = '',
        [string]$Placeholder = ''
    )
    $focused = ([string]$State.Focus -eq 'Input')
    $label = $(if ($Label) { $Label } else { Get-Translation 'WsSearchLabel' }) + ': '
    $query = [string]$State.Query
    $valueFg = if ($focused) { 'Yellow' } else { 'Gray' }
    if ($focused) { $query += '_' }
    elseif ($query -eq '' -and $Placeholder) { $query = $Placeholder; $valueFg = 'DarkGray' }
    $countText = [string]$CountText
    $used = $label.Length + $query.Length + $countText.Length
    $gap = [Math]::Max(1, $Inner - $used)
    $segs = New-Object System.Collections.Generic.List[object]
    $segs.Add((New-WtSeg -Text $label -Fg 'Cyan'))
    $segs.Add((New-WtSeg -Text $query -Fg $valueFg))
    $segs.Add((New-WtSeg -Text ((' ' * $gap) + $countText) -Fg 'DarkGray'))
    $total = 0
    foreach ($s in $segs) { $total += ([string]$s.T).Length }
    if ($total -gt $Inner) {
        $over = $total - $Inner
        for ($i = $segs.Count - 1; $i -ge 0 -and $over -gt 0; $i--) {
            $t = [string]$segs[$i].T
            if ($t.Length -le $over) { $over -= $t.Length; $segs.RemoveAt($i) }
            else { $segs[$i] = New-WtSeg -Text $t.Substring(0, $t.Length - $over) -Fg $segs[$i].F -Bg $segs[$i].B; $over = 0 }
        }
    }
    elseif ($total -lt $Inner) {
        $segs.Add((New-WtSeg -Text (' ' * ($Inner - $total)) -Fg 'DarkGray'))
    }
    return $segs.ToArray()
}

function Get-WtStoreCellSegments {
    <#
    .SYNOPSIS
        One grid cell: checkbox, then the name, padded to exactly
        NameWidth + 4 so cells in the rows above and below stay in line.
        An installed app is green with a dot instead of an empty box, so
        state reads without a legend; an overlong name is cut with '~'.
        Segments are built as literals rather than through New-WtSeg: at
        roughly 100 cells a frame, the constructor's parameter binding
        alone measured 0.23 ms each on PS 5.1.
    #>
    param(
        [Parameter(Mandatory)]$Cell,
        [Parameter(Mandatory)][int]$NameWidth,
        [bool]$IsCursor = $false,
        [bool]$Marked = $false,
        [bool]$Installed = $false,
        [Parameter(Mandatory)][PSCustomObject]$Glyphs
    )
    $box = if ($Marked) { '[x] ' } elseif ($Installed) { '[.] ' } else { '[ ] ' }
    $name = [string]$Cell.Name
    if ($name.Length -gt $NameWidth) {
        $name = if ($NameWidth -gt 1) { $name.Substring(0, $NameWidth - 1) + '~' } else { $name.Substring(0, $NameWidth) }
    }
    $name = $name.PadRight($NameWidth)

    if ($IsCursor) {
        return , @([PSCustomObject]@{ T = ($box + $name); F = 'Black'; B = 'DarkCyan' })
    }
    $nameFg = if ($Installed) { 'Green' } elseif ($Marked) { 'Yellow' } else { 'Gray' }
    $boxFg = if ($Marked) { 'Yellow' } else { 'DarkGray' }
    return , @(
        [PSCustomObject]@{ T = $box; F = $boxFg; B = '' }
        [PSCustomObject]@{ T = $name; F = $nameFg; B = '' }
    )
}

function Get-WtStoreFrameRows {
    <#
    .SYNOPSIS
        One complete store screen as segment-lines that own EVERY console row
        (Count == Height); Write-WtFrame prints exactly this. Builds into
        $frameRows, never $rows: PS is case-insensitive, so $rows would shadow
        the [array]$Rows parameter and .Add() would throw "fixed size".
        Cell rendering is inlined here rather than calling
        Get-WtStoreCellSegments, whose call alone measured 0.3 ms across
        roughly 100 cells a frame; the two must stay in step, and the
        frame tests compare them.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$State,
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()][array]$Rows,
        [Parameter(Mandatory)][int]$Width,
        [Parameter(Mandatory)][int]$Height,
        [Parameter(Mandatory)][PSCustomObject]$Glyphs,
        [string]$Breadcrumb = '',
        [hashtable]$TabLabels = @{},
        [string]$TabCaption = '',
        [string]$FooterText = '',
        [string]$CounterText = '',
        [string]$SearchCountText = '',
        [AllowEmptyCollection()][string[]]$InstalledIds = @()
    )
    $w = Get-WtFrameWidth -Width $Width
    $inner = $w - 4
    $h = $Glyphs.H
    $v = $Glyphs.V
    $geo = Get-WtGridGeometry -Inner $inner
    $nameWidth = [int]$geo.NameWidth
    $items = @()
    if ($null -ne $Rows) { $items = @($Rows) }
    $frameRows = New-Object System.Collections.Generic.List[object]
    $installedSet = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($installedId in @($InstalledIds)) { if ($null -ne $installedId) { $null = $installedSet.Add([string]$installedId) } }

    $pad = { param([string]$Text) if ($Text.Length -ge $inner) { $Text.Substring(0, $inner) } else { $Text.PadRight($inner) } }
    $boxed = { param([array]$Segs)
        , (@([PSCustomObject]@{ T = ($v + ' '); F = 'Cyan'; B = '' }) + @($Segs) + @([PSCustomObject]@{ T = (' ' + $v); F = 'Cyan'; B = '' }))
    }
    $hline = { param([string]$L, [string]$R) , @([PSCustomObject]@{ T = ($L + ($h * ($w - 2)) + $R); F = 'Cyan'; B = '' }) }
    $clampSegs = { param([System.Collections.Generic.List[object]]$Segs, [string]$PadFg)
        $total = 0
        foreach ($seg in $Segs) { $total += ([string]$seg.T).Length }
        if ($total -gt $inner) {
            $over = $total - $inner
            for ($i = $Segs.Count - 1; $i -ge 0 -and $over -gt 0; $i--) {
                $t = [string]$Segs[$i].T
                if ($t.Length -le $over) {
                    $over -= $t.Length
                    $Segs.RemoveAt($i)
                }
                else {
                    $Segs[$i] = [PSCustomObject]@{ T = $t.Substring(0, $t.Length - $over); F = [string]$Segs[$i].F; B = [string]$Segs[$i].B }
                    $over = 0
                }
            }
        }
        elseif ($total -lt $inner) {
            $Segs.Add([PSCustomObject]@{ T = (' ' * ($inner - $total)); F = $PadFg; B = '' })
        }
    }

    $headerRows = Get-WtStoreHeaderRows -Width $Width
    $boxChrome = (Get-WtStoreChromeHeight -Layout 'Grid' -Width $Width) - @($headerRows).Count
    if (($Height - @($headerRows).Count - $boxChrome) -lt 1) { $headerRows = @() }
    foreach ($hr in $headerRows) { $frameRows.Add($hr) }

    $frameRows.Add((& $hline $Glyphs.TL $Glyphs.TR))
    $tabSegs = @(Get-WtStoreTabSegments -State $State -TabLabels $TabLabels -Caption $TabCaption)
    $frameRows.Add((& $boxed (Get-WtStoreCrumbSegments -Breadcrumb $Breadcrumb -Right ([string]$CounterText) -Inner $inner -TabSegments $tabSegs)))
    $frameRows.Add((& $hline $Glyphs.LT $Glyphs.RT))

    $frameRows.Add((& $boxed (Get-WtStoreSearchRowSegments -State $State -Inner $inner -CountText $SearchCountText)))
    $frameRows.Add((& $hline $Glyphs.LT $Glyphs.RT))

    $bodyHeight = [Math]::Max(1, $Height - @($headerRows).Count - $boxChrome)
    $total = Get-WtGridRowCount -Rows $items
    $window = 0
    if ($bodyHeight -gt 0) {
        $window = Get-WtViewportWindow -ItemCount $total -CursorIndex ([int]$State.Cursor.Row) `
            -ViewHeight $bodyHeight -WindowStart ([int]$State.WindowStart)
    }
    for ($r = 0; $r -lt $bodyHeight; $r++) {
        $idx = $window + $r
        $line = New-Object System.Collections.Generic.List[object]
        if ($idx -ge 0 -and $idx -lt $total) {
            $item = $items[$idx]
            if ([string]$item.Kind -eq 'Header') {
                $title = $h + $h + ' ' + [string]$item.Label + ' (' + [string]$item.AppCount + ') '
                $line.Add((New-WtSeg -Text $title -Fg 'Cyan'))
                if ($title.Length -lt $inner) {
                    $line.Add((New-WtSeg -Text ($h * ($inner - $title.Length)) -Fg 'DarkGray'))
                }
            }
            elseif ([string]$item.Kind -eq 'Spacer') {
            }
            else {
                $cells = @()
                if ($null -ne $item.Cells) { $cells = @($item.Cells) }
                for ($c = 0; $c -lt $cells.Count; $c++) {
                    $cell = $cells[$c]
                    $isCursor = ($c -eq [int]$State.Cursor.Col -and $idx -eq [int]$State.Cursor.Row -and [string]$State.Focus -eq 'Grid')
                    $id = [string]$cell.Id
                    $marked = $State.Marks.Contains($id)
                    $installed = $installedSet.Contains($id)
                    $box = if ($marked) { '[x] ' } elseif ($installed) { '[.] ' } else { '[ ] ' }
                    $name = [string]$cell.Name
                    if ($name.Length -gt $nameWidth) {
                        $name = if ($nameWidth -gt 1) { $name.Substring(0, $nameWidth - 1) + '~' } else { $name.Substring(0, $nameWidth) }
                    }
                    $name = $name.PadRight($nameWidth)
                    if ($isCursor) {
                        $line.Add([PSCustomObject]@{ T = ($box + $name); F = 'Black'; B = 'DarkCyan' })
                    }
                    else {
                        $line.Add([PSCustomObject]@{ T = $box; F = $(if ($marked) { 'Yellow' } else { 'DarkGray' }); B = '' })
                        $line.Add([PSCustomObject]@{ T = $name; F = $(if ($installed) { 'Green' } elseif ($marked) { 'Yellow' } else { 'Gray' }); B = '' })
                    }
                    $line.Add([PSCustomObject]@{ T = '  '; F = 'Gray'; B = '' })
                }
            }
        }
        & $clampSegs $line 'Gray'
        $frameRows.Add((& $boxed @($line.ToArray())))
    }

    $frameRows.Add((& $hline $Glyphs.LT $Glyphs.RT))
    $range = ''
    if ($total -gt $bodyHeight -and $bodyHeight -gt 0) {
        $range = '{0}-{1}/{2}' -f ($window + 1), ([Math]::Min($window + $bodyHeight, $total)), $total
    }
    $foot = [string]$FooterText
    $footGap = [Math]::Max(1, $inner - $foot.Length - $range.Length)
    $frameRows.Add((& $boxed @(New-WtSeg -Text (& $pad ($foot + (' ' * $footGap) + $range)) -Fg 'Yellow')))
    $frameRows.Add((& $hline $Glyphs.BL $Glyphs.BR))

    while ($frameRows.Count -lt $Height) { $frameRows.Add((, @(New-WtSeg -Text (' ' * $w) -Fg 'Gray'))) }
    if ($frameRows.Count -gt $Height) { return @($frameRows.ToArray()[0..($Height - 1)]) }
    return $frameRows.ToArray()
}

function Get-WtStoreTableLayout {
    <#
    .SYNOPSIS
        Column widths for the search / installed tables. The id column is
        deliberately generous: it is the string a user copies to run
        winget by hand, and a truncated id is useless.
    #>
    param(
        [Parameter(Mandatory)][int]$Inner,
        [bool]$ShowAvailable = $false
    )
    $free = [Math]::Max(0, $Inner - 4 - 3)
    $version = [Math]::Min(12, [Math]::Max(0, [Math]::Floor($free * 0.12)))
    $available = 0
    if ($ShowAvailable) {
        $available = $version
        $free = $free - $available - 1
    }
    $id = [Math]::Max(0, [Math]::Floor(($free - $version) * 0.45))
    $name = [Math]::Max(0, $free - $version - $id)
    return @{ NameWidth = [int]$name; IdWidth = [int]$id; VersionWidth = [int]$version; AvailableWidth = [int]$available }
}

function Get-WtStoreRowSegments {
    <#
    .SYNOPSIS
        One table row: checkbox, name, winget id, installed version and -
        on the installed tab - the version an upgrade would bring. A row
        with an available version is yellow, so "what can be updated"
        reads off the screen without a legend.
    #>
    param(
        [Parameter(Mandatory)]$Row,
        [Parameter(Mandatory)][hashtable]$Layout,
        [bool]$IsCursor = $false,
        [bool]$Marked = $false,
        [Parameter(Mandatory)][PSCustomObject]$Glyphs
    )
    $fit = {
        param([string]$Text, [int]$Width)
        if ($Width -le 0) { return '' }
        $t = [string]$Text
        if ($t.Length -gt $Width) { $t = $(if ($Width -gt 1) { $t.Substring(0, $Width - 1) + '~' } else { $t.Substring(0, $Width) }) }
        return $t.PadRight($Width)
    }
    $box = if ($Marked) { '[x] ' } else { '[ ] ' }
    $text = $box +
        (& $fit ([string]$Row.Name) $Layout.NameWidth) + ' ' +
        (& $fit ([string]$Row.Id) $Layout.IdWidth) + ' ' +
        (& $fit ([string]$Row.Version) $Layout.VersionWidth)
    if ($Layout.AvailableWidth -gt 0) { $text += ' ' + (& $fit ([string]$Row.Available) $Layout.AvailableWidth) }

    if ($IsCursor) { return , @(New-WtSeg -Text $text -Fg 'Black' -Bg 'DarkCyan') }
    $fg = if ([string]$Row.Available) { 'Yellow' } elseif ($Marked) { 'Yellow' } else { 'Gray' }
    return , @(New-WtSeg -Text $text -Fg $fg)
}

function Get-WtStoreTableRows {
    <#
    .SYNOPSIS
        The installed tab, and the store page's winget results, as a full
        screen of segment-lines (Count == Height). Shares the store's
        header, chrome height, tab bar and footer with
        Get-WtStoreFrameRows; only the body is a table instead of a grid.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$State,
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Rows,
        [Parameter(Mandatory)][int]$Width,
        [Parameter(Mandatory)][int]$Height,
        [Parameter(Mandatory)][PSCustomObject]$Glyphs,
        [string]$Breadcrumb = '',
        [hashtable]$Headers = @{},
        [hashtable]$TabLabels = @{},
        [string]$TabCaption = '',
        [string]$FooterText = '',
        [string]$CounterText = '',
        [string]$SearchCountText = '',
        [string]$HeadingText = '',
        [string]$EmptyText = ''
    )
    $w = Get-WtFrameWidth -Width $Width
    $inner = $w - 4
    $h = $Glyphs.H
    $v = $Glyphs.V
    $showAvailable = ([string]$State.Tab -eq 'Installed')
    $layout = Get-WtStoreTableLayout -Inner $inner -ShowAvailable $showAvailable
    $out = New-Object System.Collections.Generic.List[object]

    $pad = { param([string]$Text) if ($Text.Length -ge $inner) { $Text.Substring(0, $inner) } else { $Text.PadRight($inner) } }
    $boxed = { param([array]$Segs)
        , (@(New-WtSeg -Text ($v + ' ') -Fg 'Cyan') + @($Segs) + @(New-WtSeg -Text (' ' + $v) -Fg 'Cyan'))
    }
    $hline = { param([string]$L, [string]$R) , @(New-WtSeg -Text ($L + ($h * ($w - 2)) + $R) -Fg 'Cyan') }
    $textRow = { param([string]$Text, [string]$Fg) & $boxed @(New-WtSeg -Text (& $pad $Text) -Fg $Fg) }

    $isResults = ([string]$State.Tab -eq 'Store' -and [string]$State.Mode -eq 'Results')
    $chromeLayout = $(if ($isResults) { 'Results' } else { 'Table' })
    $headerRows = Get-WtStoreHeaderRows -Width $Width
    $boxChrome = (Get-WtStoreChromeHeight -Layout $chromeLayout -Width $Width) - @($headerRows).Count
    if (($Height - @($headerRows).Count - $boxChrome) -lt 1) { $headerRows = @() }
    foreach ($hr in $headerRows) { $out.Add($hr) }

    $out.Add((& $hline $Glyphs.TL $Glyphs.TR))
    $tabSegs = @(Get-WtStoreTabSegments -State $State -TabLabels $TabLabels -Caption $TabCaption)
    $out.Add((& $boxed (Get-WtStoreCrumbSegments -Breadcrumb $Breadcrumb -Right ([string]$CounterText) -Inner $inner -TabSegments $tabSegs)))
    $out.Add((& $hline $Glyphs.LT $Glyphs.RT))

    $onInstalled = ([string]$State.Tab -eq 'Installed')
    if ($isResults -or $onInstalled) {
        $boxState = $State
        if ($onInstalled) { $boxState = @{ Focus = [string]$State.Focus; Query = [string]$State.InstalledQuery } }
        $out.Add((& $boxed (Get-WtStoreSearchRowSegments -State $boxState -Inner $inner -CountText $SearchCountText)))
        $out.Add((& $hline $Glyphs.LT $Glyphs.RT))
        if ($isResults) { $out.Add((& $textRow ([string]$HeadingText) 'Cyan')) }
    }

    $fit = { param([string]$T, [int]$W) if ($W -le 0) { '' } elseif ($T.Length -gt $W) { $T.Substring(0, $W) } else { $T.PadRight($W) } }
    $hdr = '    ' +
        (& $fit ([string]$Headers['Name']) $layout.NameWidth) + ' ' +
        (& $fit ([string]$Headers['Id']) $layout.IdWidth) + ' ' +
        (& $fit ([string]$Headers['Version']) $layout.VersionWidth)
    if ($layout.AvailableWidth -gt 0) { $hdr += ' ' + (& $fit ([string]$Headers['Available']) $layout.AvailableWidth) }
    $out.Add((& $textRow $hdr 'Cyan'))
    $out.Add((& $hline $Glyphs.LT $Glyphs.RT))

    $viewHeight = [Math]::Max(1, $Height - @($headerRows).Count - $boxChrome)
    $items = @($Rows)
    $window = Get-WtViewportWindow -ItemCount $items.Count -CursorIndex ([int]$State.Cursor.Row) `
        -ViewHeight $viewHeight -WindowStart ([int]$State.WindowStart)
    if ($items.Count -eq 0 -and $EmptyText) {
        $out.Add((& $textRow $EmptyText 'DarkGray'))
        for ($i = 1; $i -lt $viewHeight; $i++) { $out.Add((& $textRow '' 'Gray')) }
    }
    else {
        for ($i = 0; $i -lt $viewHeight; $i++) {
            $idx = $window + $i
            if ($idx -ge $items.Count) { $out.Add((& $textRow '' 'Gray')); continue }
            $row = $items[$idx]
            $isCursor = ($idx -eq [int]$State.Cursor.Row -and [string]$State.Focus -eq 'Grid')
            $segs = Get-WtStoreRowSegments -Row $row -Layout $layout -IsCursor $isCursor `
                -Marked ($State.Marks.Contains([string]$row.Id)) -Glyphs $Glyphs
            $rowFg = if (@($segs).Count -gt 0) { $segs[-1].F } else { 'Gray' }
            $used = 0
            foreach ($s in $segs) { $used += ([string]$s.T).Length }
            $line = New-Object System.Collections.Generic.List[object]
            foreach ($s in $segs) { $line.Add($s) }
            if ($used -gt $inner) {
                $over = $used - $inner
                for ($j = $line.Count - 1; $j -ge 0 -and $over -gt 0; $j--) {
                    $t = [string]$line[$j].T
                    if ($t.Length -le $over) {
                        $over -= $t.Length
                        $line.RemoveAt($j)
                    }
                    else {
                        $line[$j] = New-WtSeg -Text $t.Substring(0, $t.Length - $over) -Fg $line[$j].F -Bg $line[$j].B
                        $over = 0
                    }
                }
            }
            elseif ($used -lt $inner) {
                $fill = if ($isCursor) { New-WtSeg -Text (' ' * ($inner - $used)) -Fg 'Black' -Bg 'DarkCyan' }
                        else { New-WtSeg -Text (' ' * ($inner - $used)) -Fg $rowFg }
                $line.Add($fill)
            }
            $out.Add((& $boxed @($line.ToArray())))
        }
    }

    $out.Add((& $hline $Glyphs.LT $Glyphs.RT))
    $range = ''
    if ($items.Count -gt $viewHeight) { $range = '{0}-{1}/{2}' -f ($window + 1), ([Math]::Min($window + $viewHeight, $items.Count)), $items.Count }
    $footGap = [Math]::Max(1, $inner - ([string]$FooterText).Length - $range.Length)
    $out.Add((& $textRow ([string]$FooterText + (' ' * $footGap) + $range) 'Yellow'))
    $out.Add((& $hline $Glyphs.BL $Glyphs.BR))

    while ($out.Count -lt $Height) { $out.Add((, @(New-WtSeg -Text (' ' * $w) -Fg 'Gray'))) }
    if ($out.Count -gt $Height) { return @($out.ToArray()[0..($Height - 1)]) }
    return $out.ToArray()
}
#endregion src/20-tui/grid-frame.ps1

#region src/20-tui/grid-state.ps1
# Grid key vocabulary, grid geometry, the flowed row model and the store
# reducer.
# Covered by: tests/WingetStoreState.Tests.ps1, tests/WingetStoreGrid.Tests.ps1

function ConvertTo-WtGridKeyToken {
    <#
    .SYNOPSIS
        The winget store's own key vocabulary: unlike the shared converter,
        keeps case and passes RightArrow/Tab/Delete and any printable
        character through (IsControl, not regex - tr-TR mishandles
        dotted/dotless i under -match).
    #>
    param(
        [Parameter(Mandatory)][string]$Key,
        [AllowNull()][AllowEmptyString()][string]$KeyChar = ''
    )

    switch ($Key) {
        'UpArrow'    { return 'Up' }
        'DownArrow'  { return 'Down' }
        'LeftArrow'  { return 'Left' }
        'RightArrow' { return 'Right' }
        'PageUp'     { return 'PageUp' }
        'PageDown'   { return 'PageDown' }
        'Home'       { return 'Home' }
        'End'        { return 'End' }
        'Tab'        { return 'Tab' }
        'Escape'     { return 'Esc' }
        'Backspace'  { return 'Backspace' }
        'Delete'     { return 'Delete' }
        'Enter'      { return 'Enter' }
        'Spacebar'   { return 'Space' }
    }

    if ($KeyChar.Length -eq 1 -and -not [char]::IsControl($KeyChar[0])) { return 'Char:' + $KeyChar }
    return 'None'
}

function Get-WtGridGeometry {
    <#
    .SYNOPSIS
        Cell layout for the store grid: cell width, per-cell start offsets,
        and the room left for the name after the "[ ] " marker. ColumnCount
        means cells-per-row, not category count, and a row collapses to a
        single cell once cells would fall below MinCell.
    #>
    param(
        [Parameter(Mandatory)][int]$Inner,
        [int]$ColumnCount = 5,
        [int]$Gap = 2,
        [int]$MinCell = 12
    )
    $cols = [Math]::Max(1, $ColumnCount)
    $cell = [Math]::Floor(($Inner - ($Gap * ($cols - 1))) / $cols)
    if ($cell -lt $MinCell) {
        $cols = 1
        $cell = $Inner
    }
    $starts = New-Object System.Collections.Generic.List[int]
    for ($i = 0; $i -lt $cols; $i++) { $starts.Add($i * ($cell + $Gap)) }
    return @{
        ColumnCount = $cols
        CellWidth   = [int]$cell
        NameWidth   = [Math]::Max(1, [int]$cell - 4)
        Starts      = [int[]]$starts.ToArray()
    }
}

function Test-WtGridCellFocusable {
    <#
    .SYNOPSIS
        Only App cells take the cursor. Kept as its own predicate so a
        non-App cell can never be marked, installed or highlighted even if
        one ever reaches a Cells row.
    #>
    param([AllowNull()]$Cell)
    if ($null -eq $Cell) { return $false }
    return ([string]$Cell.Kind -eq 'App')
}

function Get-WtGridRowCellCount {
    <#
    .SYNOPSIS
        How many cells one row of the flowed grid holds - 0 for a Header
        row, which makes "skip headers" and "stop at list end" the same
        test everywhere. Checks Row for $null explicitly, since @($null)
        wraps to a one-element array in PowerShell and would otherwise
        count as a row with one unfocusable cell.
    #>
    param([AllowNull()]$Row)
    if ($null -eq $Row) { return 0 }
    if ([string]$Row.Kind -ne 'Cells') { return 0 }
    if ($null -eq $Row.Cells) { return 0 }
    return @($Row.Cells).Count
}

function Get-WtGridCellsRowIndex {
    <#
    .SYNOPSIS
        The first row index past From, walking in direction Delta, that
        actually holds cells. -1 when the walk runs off the end. Delta 0
        tests From itself.
    #>
    param(
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()][array]$Rows,
        [Parameter(Mandatory)][int]$From,
        [Parameter(Mandatory)][int]$Delta
    )
    $list = @()
    if ($null -ne $Rows) { $list = @($Rows) }
    if ($Delta -eq 0) {
        if ($From -ge 0 -and $From -lt $list.Count -and (Get-WtGridRowCellCount -Row $list[$From]) -gt 0) { return $From }
        return -1
    }
    $i = $From + $Delta
    while ($i -ge 0 -and $i -lt $list.Count) {
        if ((Get-WtGridRowCellCount -Row $list[$i]) -gt 0) { return $i }
        $i += $Delta
    }
    return -1
}

function Get-WtGridNearestCellsRow {
    <#
    .SYNOPSIS
        The cells-row nearest to PreferredRow in either direction, a tie
        going upwards. -1 when the list holds no cells at all. This is
        what makes a page jump, or a cursor carried over from a changed
        frame, land on something real rather than a Header row.
    #>
    param(
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()][array]$Rows,
        [int]$PreferredRow = 0
    )
    $list = @()
    if ($null -ne $Rows) { $list = @($Rows) }
    if ($list.Count -eq 0) { return -1 }
    $p = [Math]::Max(0, [Math]::Min($PreferredRow, $list.Count - 1))
    if ((Get-WtGridRowCellCount -Row $list[$p]) -gt 0) { return $p }
    $up = Get-WtGridCellsRowIndex -Rows $list -From $p -Delta -1
    $down = Get-WtGridCellsRowIndex -Rows $list -From $p -Delta 1
    if ($up -lt 0) { return $down }
    if ($down -lt 0) { return $up }
    if (($p - $up) -le ($down - $p)) { return $up }
    return $down
}

function Get-WtStoreGridRows {
    <#
    .SYNOPSIS
        The catalog as a FLAT list of rows: a full-width Header row per
        category, then that category's apps flowed CellsPerRow at a time,
        left to right, then the next category's Header, with a blank
        Spacer row before every Header but the first. A category with no
        apps produces no rows at all, and the last row of a category is
        short rather than padded, so no unfocusable filler cell ever sits
        under the cursor.
    #>
    param(
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()][array]$Apps,
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()][string[]]$CategoryKeys,
        [int]$CellsPerRow = 5,
        [hashtable]$CategoryLabels = @{}
    )
    $appList = @()
    if ($null -ne $Apps) { $appList = @($Apps) }
    $keys = @()
    if ($null -ne $CategoryKeys) { $keys = @($CategoryKeys) }
    $per = [Math]::Max(1, $CellsPerRow)
    $labels = if ($null -eq $CategoryLabels) { @{} } else { $CategoryLabels }
    $rows = New-Object System.Collections.Generic.List[object]

    foreach ($key in $keys) {
        $cells = New-Object System.Collections.Generic.List[object]
        foreach ($app in $appList) {
            if ([string]$app.Category -eq [string]$key) {
                $cells.Add(@{
                        Kind     = 'App'
                        Id       = [string]$app.Id
                        Name     = [string]$app.Name
                        Category = [string]$app.Category
                    })
            }
        }
        if ($cells.Count -eq 0) { continue }

        if ($rows.Count -gt 0) {
            $rows.Add(@{ Kind = 'Spacer'; Label = ''; Category = ''; AppCount = 0; Cells = @() })
        }

        $label = if ($labels.ContainsKey($key)) { [string]$labels[$key] } else { [string]$key }
        if (-not $label) { $label = [string]$key }
        $rows.Add(@{ Kind = 'Header'; Label = $label; Category = [string]$key; AppCount = $cells.Count; Cells = @() })

        for ($i = 0; $i -lt $cells.Count; $i += $per) {
            $take = [Math]::Min($per, $cells.Count - $i)
            $slice = New-Object 'object[]' $take
            for ($j = 0; $j -lt $take; $j++) { $slice[$j] = $cells[$i + $j] }
            $rows.Add(@{ Kind = 'Cells'; Label = ''; Category = [string]$key; AppCount = $take; Cells = $slice })
        }
    }
    return , $rows.ToArray()
}

function Get-WtStoreListRows {
    <#
    .SYNOPSIS
        The same row model over a TABLE: one cell per row, no headers, so
        the search and installed tabs share the grid's cursor logic.
        Returns with a protecting unary comma - a bare statement-block
        assignment once unrolled a one-row result back to a scalar, so
        Enter installed a package the cursor was not on.
    #>
    param(
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()][array]$Rows,
        [int]$CellsPerRow = 1
    )
    $per = [Math]::Max(1, $CellsPerRow)
    $items = New-Object System.Collections.Generic.List[object]
    if ($null -ne $Rows) {
        foreach ($row in $Rows) {
            if ($null -eq $row) { continue }
            $items.Add(@{ Kind = 'App'; Id = [string]$row.Id; Name = [string]$row.Name; Category = '' })
        }
    }
    $out = New-Object System.Collections.Generic.List[object]
    for ($i = 0; $i -lt $items.Count; $i += $per) {
        $take = [Math]::Min($per, $items.Count - $i)
        $slice = New-Object 'object[]' $take
        for ($j = 0; $j -lt $take; $j++) { $slice[$j] = $items[$i + $j] }
        $out.Add(@{ Kind = 'Cells'; Label = ''; Category = ''; AppCount = $take; Cells = $slice })
    }
    return , $out.ToArray()
}

function Get-WtGridRowCount {
    <#
    .SYNOPSIS
        Rows the grid occupies, headers included - they are drawn and
        scrolled like everything else. One WindowStart over this one list
        is the whole scroll model.
    #>
    param([Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()][array]$Rows)
    if ($null -eq $Rows) { return 0 }
    return @($Rows).Count
}

function Move-WtGridCursor {
    <#
    .SYNOPSIS
        One movement token applied to the grid cursor. Up/Down skip
        header rows and clamp Col to the landing row; Left/Right follow
        READING ORDER, continuing onto the adjacent cells-row instead of
        wrapping in place. Nothing moves past either end of the list.
    #>
    param(
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()][array]$Rows,
        [Parameter(Mandatory)][hashtable]$Cursor,
        [Parameter(Mandatory)][string]$Token,
        [int]$ViewHeight = 10
    )
    $list = @()
    if ($null -ne $Rows) { $list = @($Rows) }
    $row = [int]$Cursor.Row
    $col = [int]$Cursor.Col
    $same = @{ Row = $row; Col = $col }
    if ($list.Count -eq 0) { return @{ Row = 0; Col = 0 } }

    $cur = [Math]::Max(0, [Math]::Min($row, $list.Count - 1))
    $curCount = Get-WtGridRowCellCount -Row $list[$cur]
    $land = {
        param([int]$Index, [int]$WantCol)
        $n = Get-WtGridRowCellCount -Row $list[$Index]
        @{ Row = $Index; Col = [Math]::Max(0, [Math]::Min($WantCol, $n - 1)) }
    }

    switch ($Token) {
        'Up' {
            $i = Get-WtGridCellsRowIndex -Rows $list -From $cur -Delta -1
            if ($i -lt 0) { return $same }
            return (& $land $i $col)
        }
        'Down' {
            $i = Get-WtGridCellsRowIndex -Rows $list -From $cur -Delta 1
            if ($i -lt 0) { return $same }
            return (& $land $i $col)
        }
        'Left' {
            if ($curCount -gt 0 -and $col -gt 0) { return (& $land $cur ($col - 1)) }
            $i = Get-WtGridCellsRowIndex -Rows $list -From $cur -Delta -1
            if ($i -lt 0) { return $same }
            return (& $land $i ([int]::MaxValue))
        }
        'Right' {
            if ($curCount -gt 0 -and $col -lt ($curCount - 1)) { return (& $land $cur ($col + 1)) }
            $i = Get-WtGridCellsRowIndex -Rows $list -From $cur -Delta 1
            if ($i -lt 0) { return $same }
            return (& $land $i 0)
        }
        'Home' {
            $i = Get-WtGridNearestCellsRow -Rows $list -PreferredRow 0
            if ($i -lt 0) { return $same }
            return (& $land $i 0)
        }
        'End' {
            $i = Get-WtGridNearestCellsRow -Rows $list -PreferredRow ($list.Count - 1)
            if ($i -lt 0) { return $same }
            return (& $land $i ([int]::MaxValue))
        }
        'PageUp' {
            $i = Get-WtGridNearestCellsRow -Rows $list -PreferredRow ([Math]::Max(0, $cur - $ViewHeight))
            if ($i -lt 0) { return $same }
            return (& $land $i $col)
        }
        'PageDown' {
            $i = Get-WtGridNearestCellsRow -Rows $list -PreferredRow ([Math]::Min($list.Count - 1, $cur + $ViewHeight))
            if ($i -lt 0) { return $same }
            return (& $land $i $col)
        }
    }
    return $same
}

function New-WtStoreState {
    <#
    .SYNOPSIS
        A fresh winget store screen: catalog tab, cursor on the first
        cell, nothing marked, no query. Mode (Catalog or Results) tracks
        what the store page shows, kept separate from Tab so a search
        result page is never an unreachable third tab.
    #>
    param([AllowNull()][AllowEmptyString()][string]$Query = '')
    return @{
        Tab         = 'Store'
        Mode        = 'Catalog'
        Focus       = 'Grid'
        Cursor      = @{ Row = 0; Col = 0 }
        WindowStart = 0
        Marks       = (New-Object 'System.Collections.Generic.HashSet[string]')
        Query       = [string]$Query
        Results     = @()
        Installed   = @()
        InstalledQuery = ''
        Hint        = ''
    }
}

function Get-WtStoreCursorCell {
    <#
    .SYNOPSIS
        The cell the cursor stands on, or $null when the grid is empty or
        the cursor sits on a header row. Rows is copied via an if
        STATEMENT, not a statement-block expression: the pipeline a
        statement block emits through unrolls a one-row result back to a
        bare hashtable, silently turning $list.Count into a key count.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$State,
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()][array]$Rows
    )
    $list = @()
    if ($null -ne $Rows) { $list = @($Rows) }
    $r = [int]$State.Cursor.Row
    $c = [int]$State.Cursor.Col
    if ($r -lt 0 -or $r -ge $list.Count) { return $null }
    $n = Get-WtGridRowCellCount -Row $list[$r]
    if ($c -lt 0 -or $c -ge $n) { return $null }
    $cell = @($list[$r].Cells)[$c]
    if (-not (Test-WtGridCellFocusable -Cell $cell)) { return $null }
    return $cell
}

function Get-WtStoreValidCursor {
    <#
    .SYNOPSIS
        A cursor guaranteed to sit on a focusable cell of THESE rows:
        unchanged when it already does, otherwise Col clamped into its
        own row, and failing that the nearest row that holds cells.
        Applied once per frame, since rows are re-derived every frame (a
        filter, a reload, an uninstall) while the cursor carries over from
        the one before, and a stale cursor makes Enter do nothing at all.
    #>
    param(
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()][array]$Rows,
        [Parameter(Mandatory)][hashtable]$Cursor
    )
    $list = @()
    if ($null -ne $Rows) { $list = @($Rows) }
    if ($list.Count -eq 0) { return @{ Row = 0; Col = 0 } }
    $r = [int]$Cursor.Row
    $c = [int]$Cursor.Col
    if ($r -ge 0 -and $r -lt $list.Count) {
        $n = Get-WtGridRowCellCount -Row $list[$r]
        if ($n -gt 0) { return @{ Row = $r; Col = [Math]::Max(0, [Math]::Min($c, $n - 1)) } }
    }
    $near = Get-WtGridNearestCellsRow -Rows $list -PreferredRow $r
    if ($near -lt 0) { return @{ Row = 0; Col = 0 } }
    $nearCount = Get-WtGridRowCellCount -Row $list[$near]
    return @{ Row = $near; Col = [Math]::Max(0, [Math]::Min($c, $nearCount - 1)) }
}

function Update-WtStoreState {
    <#
    .SYNOPSIS
        The pure winget-store reducer: one token in, a new state and an
        emit out (None, Back, Install, Upgrade, Uninstall, Search,
        Refresh, Refused). While Focus is 'Input' every printable
        character is typed into the query; only Enter/Esc leave the box.
        Eof (line-mode stdin exhausted) returns Back, not None - mapped to
        None it once spun an infinite repaint loop on an empty Read-Host.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$State,
        [Parameter(Mandatory)][string]$Token,
        [Parameter(Mandatory)][AllowNull()][AllowEmptyCollection()][array]$Rows,
        [int]$ViewHeight = 10,
        [AllowEmptyCollection()][string[]]$InstalledIds = @()
    )
    $s = @{}
    foreach ($k in $State.Keys) { $s[$k] = $State[$k] }
    $s.Cursor = @{ Row = [int]$State.Cursor.Row; Col = [int]$State.Cursor.Col }
    $s.Marks = New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($m in $State.Marks) { $null = $s.Marks.Add($m) }
    $s.Hint = ''
    $tabs = @('Store', 'Installed')
    $done = { param($E) return @{ State = $s; Emit = $E } }
    $setTab = { param([string]$Name)
        $s.Tab = $Name
        $s.Mode = 'Catalog'
        $s.Cursor = @{ Row = 0; Col = 0 }
        $s.WindowStart = 0
        $s.Marks.Clear()
    }

    if ($Token -eq 'Eof') { return (& $done 'Back') }

    if ([string]$s.Focus -eq 'Input') {
        $onInstalled = ([string]$s.Tab -eq 'Installed')
        $field = $(if ($onInstalled) { 'InstalledQuery' } else { 'Query' })
        if ($Token -eq 'Enter') {
            $s.Focus = 'Grid'
            $s.Cursor = @{ Row = 0; Col = 0 }
            $s.WindowStart = 0
            if ($onInstalled) { return (& $done 'None') }
            if (([string]$s.Query).Trim() -eq '') {
                $s.Mode = 'Catalog'
                return (& $done 'None')
            }
            $s.Mode = 'Results'
            return (& $done 'Search')
        }
        if ($Token -eq 'Esc') {
            $s.Focus = 'Grid'
            if (-not $onInstalled) { $s.Mode = 'Catalog' }
            $s[$field] = ''
            $s.Cursor = @{ Row = 0; Col = 0 }
            $s.WindowStart = 0
            return (& $done 'None')
        }
        if ($Token -eq 'Backspace') {
            $q = [string]$s[$field]
            if ($q.Length -gt 0) { $s[$field] = $q.Substring(0, $q.Length - 1) }
            return (& $done 'None')
        }
        if ($Token -eq 'Space') { $s[$field] = [string]$s[$field] + ' '; return (& $done 'None') }
        if ($Token.StartsWith('Char:', [StringComparison]::Ordinal)) {
            $s[$field] = [string]$s[$field] + $Token.Substring(5)
            return (& $done 'None')
        }
        return (& $done 'None')
    }

    if (@('Up', 'Down', 'Left', 'Right', 'Home', 'End', 'PageUp', 'PageDown') -contains $Token) {
        $moved = Move-WtGridCursor -Rows $Rows -Cursor $s.Cursor -Token $Token -ViewHeight $ViewHeight
        if ([int]$moved.Row -ge 0) { $s.Cursor = @{ Row = [int]$moved.Row; Col = [int]$moved.Col } }
        $total = Get-WtGridRowCount -Rows $Rows
        $s.WindowStart = Get-WtViewportWindow -ItemCount $total -CursorIndex ([int]$s.Cursor.Row) `
            -ViewHeight $ViewHeight -WindowStart ([int]$s.WindowStart)
        return (& $done 'None')
    }

    if ($Token -eq 'Tab') {
        $i = [Array]::IndexOf($tabs, [string]$s.Tab)
        & $setTab $tabs[(($i + 1) % $tabs.Count)]
        return (& $done 'None')
    }

    if ($Token -eq 'Back') { return (& $done 'Back') }
    if ($Token.StartsWith('Digit:', [StringComparison]::Ordinal)) {
        $number = 0
        if ([int]::TryParse($Token.Substring(6), [ref]$number)) {
            $index = $number - 1
            if ($index -ge 0 -and $index -lt $tabs.Count) { & $setTab $tabs[$index] }
        }
        return (& $done 'None')
    }

    if ($Token -eq 'Space') {
        $cell = Get-WtStoreCursorCell -State $s -Rows $Rows
        if ($null -eq $cell) { return (& $done 'None') }
        $id = [string]$cell.Id
        if ([string]$s.Tab -ne 'Installed' -and ($InstalledIds -contains $id)) {
            return (& $done 'Refused')
        }
        if ($s.Marks.Contains($id)) { $null = $s.Marks.Remove($id) } else { $null = $s.Marks.Add($id) }
        return (& $done 'None')
    }

    if ($Token -eq 'Enter') {
        if ([string]$s.Tab -eq 'Installed') { return (& $done 'None') }
        if ($s.Marks.Count -eq 0) {
            $cell = Get-WtStoreCursorCell -State $s -Rows $Rows
            if ($null -eq $cell) { return (& $done 'None') }
            $id = [string]$cell.Id
            if ([string]$s.Tab -ne 'Installed' -and ($InstalledIds -contains $id)) {
                return (& $done 'Refused')
            }
            $null = $s.Marks.Add($id)
        }
        return (& $done 'Install')
    }

    if ($Token -eq 'Delete') {
        if ([string]$s.Tab -eq 'Installed' -and $s.Marks.Count -gt 0) { return (& $done 'Uninstall') }
        return (& $done 'None')
    }

    if ($Token -eq 'Esc') {
        if ([string]$s.Mode -eq 'Results') {
            $s.Mode = 'Catalog'
            $s.Query = ''
            $s.Cursor = @{ Row = 0; Col = 0 }
            $s.WindowStart = 0
            $s.Marks.Clear()
            return (& $done 'None')
        }
        if ([string]$s.Tab -eq 'Installed' -and ([string]$s.InstalledQuery).Trim() -ne '') {
            $s.InstalledQuery = ''
            $s.Cursor = @{ Row = 0; Col = 0 }
            $s.WindowStart = 0
            return (& $done 'None')
        }
        return (& $done 'Back')
    }

    if ($Token.StartsWith('Char:', [StringComparison]::Ordinal)) {
        $ch = $Token.Substring(5).ToLowerInvariant()
        switch ($ch) {
            '/' {
                if ([string]$s.Tab -eq 'Installed') {
                    $s.Focus = 'Input'
                    $s.InstalledQuery = ''
                    $s.Cursor = @{ Row = 0; Col = 0 }
                    $s.WindowStart = 0
                    return (& $done 'None')
                }
                $s.Focus = 'Input'
                $s.Mode = 'Catalog'
                $s.Query = ''
                $s.Cursor = @{ Row = 0; Col = 0 }
                $s.WindowStart = 0
                return (& $done 'None')
            }
            'q' { return (& $done 'Back') }
            'r' { return (& $done 'Refresh') }
            'a' {
                foreach ($row in @($Rows)) {
                    if ($null -eq $row -or $null -eq $row.Cells) { continue }
                    foreach ($cell in @($row.Cells)) {
                        if (-not (Test-WtGridCellFocusable -Cell $cell)) { continue }
                        $id = [string]$cell.Id
                        if ([string]$s.Tab -ne 'Installed' -and ($InstalledIds -contains $id)) { continue }
                        $null = $s.Marks.Add($id)
                    }
                }
                return (& $done 'None')
            }
            'n' { $s.Marks.Clear(); return (& $done 'None') }
            'u' {
                if ([string]$s.Tab -eq 'Installed' -and $s.Marks.Count -gt 0) { return (& $done 'Upgrade') }
                return (& $done 'None')
            }
            '1' { & $setTab 'Store'; return (& $done 'None') }
            '2' { & $setTab 'Installed'; return (& $done 'None') }
        }
    }

    return (& $done 'None')
}
#endregion src/20-tui/grid-state.ps1

#region src/20-tui/list-screen.ps1
# Invoke-WtListScreen - the generic list screen loop.
# Covered by: tests/Tui.Tests.ps1, tests/Screens.Tests.ps1

function Invoke-WtListScreen {
    <#
    .SYNOPSIS
        The one interactive loop: frame -> key batch -> reducer, until the
        reducer emits @{ Emit; Char; Item; Selection; CursorIndex }. With
        Searchable on, CursorIndex always indexes the caller's Items, not
        the filtered view shown while a query is active.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb,
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Items,
        [bool]$MultiSelect = $false,
        [System.Collections.Generic.HashSet[string]]$Selection,
        [string]$FooterText = '',
        [scriptblock]$OnSelectionChanged,
        [bool]$ShowBanner = $false,
        [string]$CounterText = '',
        [int]$InitialCursor = -1,
        [ValidateSet('Full', 'Compact')][string]$Layout = 'Full',
        [hashtable]$Cycle,
        [hashtable]$CycleLabels = @{},
        [bool]$Searchable = $false,
        [int]$DescriptionRows = 0
    )
    if ($null -eq $Selection) { $Selection = New-Object 'System.Collections.Generic.HashSet[string]' }
    if ($null -eq $Cycle) { $Cycle = @{} }
    $cursor = 0
    $anyFocusable = $false
    foreach ($probe in $Items) { if (Test-WtItemFocusable -Item $probe) { $anyFocusable = $true; break } }
    if (-not $anyFocusable) {
        $cursor = -1
    }
    elseif ($InitialCursor -ge 0 -and $InitialCursor -lt $Items.Count -and (Test-WtItemFocusable -Item $Items[$InitialCursor])) { $cursor = $InitialCursor }
    elseif ($Items.Count -gt 0 -and -not (Test-WtItemFocusable -Item $Items[0])) {
        $cursor = Get-WtNextFocusableIndex -Items $Items -FromIndex 0 -Direction 1
    }
    $state = @{ CursorIndex = $cursor; WindowStart = 0; Selection = $Selection; Cycle = $Cycle; Focus = 'List'; Query = '' }
    $shown = $Items
    $result = { param($Emit, $Char, $Item)
        $at = [int]$state.CursorIndex
        if ($Searchable -and $at -ge 0 -and $at -lt $shown.Count) {
            $name = [string]$shown[$at].Name
            $at = -1
            for ($i = 0; $i -lt $Items.Count; $i++) {
                if ([string]::Equals([string]$Items[$i].Name, $name, [System.StringComparison]::Ordinal)) { $at = $i; break }
            }
        }
        @{ Emit = $Emit; Char = $Char; Item = $Item; Selection = $Selection; Cycle = $Cycle; CursorIndex = $at }
    }
    $hintFooter = ''
    $footerSize = [string]$FooterText
    if ($Searchable) {
        foreach ($candidate in @((Get-WtSearchableFooter -Footer $FooterText -Hint (Get-Translation 'ListSearchKeyHint')), (Get-Translation 'ListSearchFooter'))) {
            if (([string]$candidate).Length -gt $footerSize.Length) { $footerSize = [string]$candidate }
        }
    }

    while ($true) {
        $shown = $Items
        $search = $null
        if ($Searchable) {
            $q = [string]$state.Query
            $filtered = ($q.Trim() -ne '')
            if ($filtered) {
                $shown = @(Select-WtListItems -Items $Items -Query $q)
                if ($shown.Count -eq 0) { $shown = @(Get-WtListSearchEmptyItem) }
            }
            $countText = ''
            if ($filtered) {
                $countText = (Get-Translation 'ListSearchCount') -f (Get-WtFocusableCount -Items $shown), (Get-WtFocusableCount -Items $Items)
                if ([string]$state.Focus -ne 'Input') { $countText += ' - ' + (Get-Translation 'ListSearchClearHint') }
            }
            $search = @{ Focus = [string]$state.Focus; Query = $q; CountText = $countText }
            $state.CursorIndex = Get-WtValidListCursor -Items $shown -CursorIndex ([int]$state.CursorIndex)
        }
        $size = Get-WtConsoleSize
        $viewHeight = [Math]::Max(1, $size.Height - (Get-WtFrameChromeHeight -Width $size.Width -ShowBanner $ShowBanner -Searchable $Searchable -DescriptionRows $DescriptionRows))
        $counter = $CounterText
        if ($MultiSelect) {
            $marked = (Get-WtMarkSummary -Items $Items -Selection $Selection).Text
            $counter = (@($CounterText, $marked) | Where-Object { $_ }) -join '  '
        }
        $footer = if ($hintFooter) { $hintFooter }
                  elseif ($Searchable -and [string]$state.Focus -eq 'Input') { Get-Translation 'ListSearchFooter' }
                  elseif ($Searchable) { Get-WtSearchableFooter -Footer $FooterText -Hint (Get-Translation 'ListSearchKeyHint') }
                  else { $FooterText }
        $hintFooter = ''
        $frame = Get-WtFrameRows -Breadcrumb $Breadcrumb -Items $shown -State $state -Width $size.Width -Height $size.Height `
            -Glyphs $script:WtGlyphs -CounterText $counter -FooterText $footer -CycleLabels $CycleLabels `
            -LineMode ($script:WtInputMode -eq 'Line') -ShowBanner $ShowBanner -Layout $Layout -Search $search `
            -SizeItems $Items -FooterSizeText $footerSize -DescriptionRows $DescriptionRows
        Write-WtFrame -FrameLines $frame -Width $size.Width -Height $size.Height

        $before = (@($Selection) | Sort-Object) -join "`n"
        $converter = $null
        if ($Searchable -and [string]$state.Focus -eq 'Input') {
            $converter = { param($Key, $KeyChar) ConvertTo-WtGridKeyToken -Key $Key -KeyChar $KeyChar }
        }
        $tokens = Read-WtInputBatch -Converter $converter
        $r = Invoke-WtTokenBatch -State $state -Tokens $tokens -Items $shown -ViewHeight $viewHeight -MultiSelect $MultiSelect -Searchable $Searchable
        $state = $r.State
        $after = (@($Selection) | Sort-Object) -join "`n"
        if ($OnSelectionChanged -and $after -ne $before) { & $OnSelectionChanged }

        if ($r.Emit -eq 'Back') { return (& $result 'Back' '' $null) }
        if ($r.Emit -eq 'Refused') { $hintFooter = Get-Translation 'RemoveUnavailableHint'; continue }
        if ($r.Emit -eq 'Activate') {
            $item = if ($state.CursorIndex -ge 0 -and $state.CursorIndex -lt $shown.Count) { $shown[$state.CursorIndex] } else { $null }
            return (& $result 'Activate' '' $item)
        }
        if ($r.Emit -eq 'Global') {
            if ($r.EmitChar -eq 'q') { return (& $result 'Quit' '' $null) }
            return (& $result 'Global' $r.EmitChar $null)
        }
    }
}
#endregion src/20-tui/list-screen.ps1

#region src/20-tui/list-state.ps1
# Viewport, focus, cursor memory, radio groups, mark toggles, Update-WtListState, token batching.
# Covered by: tests/Tui.Tests.ps1, tests/CursorMemory.Tests.ps1, tests/RowState.Tests.ps1

function Get-WtViewportWindow {
    <#
    .SYNOPSIS
        Scroll-window math: given the cursor and previous window start,
        returns the new start so the cursor stays visible and the window
        never runs past either end. A negative CursorIndex means "no
        cursor" (read-only view): the window is honoured as-is, clamped.
    #>
    param(
        [Parameter(Mandatory)][int]$ItemCount,
        [Parameter(Mandatory)][int]$CursorIndex,
        [Parameter(Mandatory)][int]$ViewHeight,
        [Parameter(Mandatory)][int]$WindowStart
    )

    if ($ItemCount -le $ViewHeight) { return 0 }
    if ($CursorIndex -lt 0) { return [Math]::Max(0, [Math]::Min($WindowStart, $ItemCount - $ViewHeight)) }

    $start = $WindowStart
    if ($CursorIndex -lt $start) { $start = $CursorIndex }
    elseif ($CursorIndex -ge ($start + $ViewHeight)) { $start = $CursorIndex - $ViewHeight + 1 }

    return [Math]::Max(0, [Math]::Min($start, $ItemCount - $ViewHeight))
}

function Test-WtItemFocusable {
    param([Parameter(Mandatory)][PSCustomObject]$Item)
    return (@('Link', 'Action', 'Check', 'Radio') -contains $Item.Kind)
}

function Get-WtNextFocusableIndex {
    <#
    .SYNOPSIS
        The next focusable row index in the given direction (+1/-1),
        skipping Header/Info rows. Returns FromIndex unchanged when no
        focusable row exists in that direction (no wrap-around).
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Items,
        [Parameter(Mandatory)][int]$FromIndex,
        [Parameter(Mandatory)][ValidateSet(-1, 1)][int]$Direction
    )

    $i = $FromIndex + $Direction
    while ($i -ge 0 -and $i -lt $Items.Count) {
        if (Test-WtItemFocusable -Item $Items[$i]) { return $i }
        $i += $Direction
    }
    return $FromIndex
}

function Get-WtFocusableCount {
    param([Parameter(Mandatory)][AllowEmptyCollection()][array]$Items)
    $n = 0
    foreach ($item in $Items) { if (Test-WtItemFocusable -Item $item) { $n++ } }
    return $n
}

function Get-WtValidListCursor {
    <#
    .SYNOPSIS
        PURE: the cursor a list can actually show - the given index when it
        lands on a focusable row, else the first focusable row, else -1
        (nothing to focus: a read-only page, or a filter that matched
        nothing). Keeps the highlight on a real row as the search box changes.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Items,
        [int]$CursorIndex = -1
    )
    if ($CursorIndex -ge 0 -and $CursorIndex -lt $Items.Count -and (Test-WtItemFocusable -Item $Items[$CursorIndex])) { return $CursorIndex }
    for ($i = 0; $i -lt $Items.Count; $i++) { if (Test-WtItemFocusable -Item $Items[$i]) { return $i } }
    return -1
}

function Select-WtListItems {
    <#
    .SYNOPSIS
        PURE: the rows a search query leaves. Every word of the query has
        to occur in the row's label or state column, in any order, compared
        OrdinalIgnoreCase - never a culture compare, which on tr-TR folds I
        to the dotless i. A Header/Rule stays only when a row of its group
        matched. Uses -split, not .Split(), since PS7 binds that call to the
        (string, options) overload and joins the terms into one separator.
        Emitted bare: wrap the call in @(), or empty comes back $null.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Items,
        [AllowNull()][AllowEmptyString()][string]$Query = ''
    )
    $terms = @((([string]$Query).Trim() -split '\s+') | Where-Object { $_ -ne '' })
    if ($terms.Count -eq 0) { return @($Items) }
    $out = New-Object System.Collections.Generic.List[object]
    $pendingHeader = $null
    $headerShown = $false
    $pendingSpacer = $null
    foreach ($item in $Items) {
        $kind = [string]$item.Kind
        if ($kind -eq 'Header' -or $kind -eq 'Rule') { $pendingHeader = $item; $headerShown = $false; continue }
        if ($kind -eq 'Spacer') { if ($out.Count -gt 0) { $pendingSpacer = $item }; continue }
        if (-not (Test-WtItemFocusable -Item $item)) { continue }
        $hay = [string]$item.Label + ' ' + [string]$item.StateLabel
        $hit = $true
        foreach ($term in $terms) {
            if ($hay.IndexOf($term, [System.StringComparison]::OrdinalIgnoreCase) -lt 0) { $hit = $false; break }
        }
        if (-not $hit) { continue }
        if ($null -ne $pendingSpacer) { $out.Add($pendingSpacer); $pendingSpacer = $null }
        if ($null -ne $pendingHeader -and -not $headerShown) { $out.Add($pendingHeader); $headerShown = $true }
        $out.Add($item)
    }
    return $out.ToArray()
}

function Get-WtSearchableFooter {
    <#
    .SYNOPSIS
        PURE: a screen's navigation guide with the search key added: "/: ara"
        goes in front of the Esc item, so the guide reads doing-to-leaving. A
        footer without an Esc item is not a guide and comes back untouched.
        Ordinal IndexOf, never -replace, to avoid tr-TR casefolding.
    #>
    param(
        [AllowNull()][AllowEmptyString()][string]$Footer,
        [Parameter(Mandatory)][string]$Hint
    )
    $text = [string]$Footer
    $at = $text.IndexOf(' - Esc:', [System.StringComparison]::Ordinal)
    if ($at -lt 0) { return $text }
    return $text.Substring(0, $at) + ' - ' + $Hint + $text.Substring($at)
}

function Get-WtListSearchEmptyItem {
    <#
    .SYNOPSIS
        The one Info row a filter that matched nothing shows. The shape is
        New-WtListItem's, spelled out here so the TUI layer does not call
        up into the screens layer for it.
    #>
    return [PSCustomObject]@{
        Kind           = 'Info'
        Name           = 'ListSearchEmpty'
        Label          = [string](Get-Translation 'ListSearchEmpty')
        Risk           = $null
        StateLabel     = ''
        PendingVerbKey = ''
        Selectable     = $false
        Data           = $null
        Group          = ''
        Applied        = $false
        Removable      = $false
        RiskTag        = $true
        CycleTargets   = [string[]]@()
    }
}

$script:WtMainMenuCursor = $null

function Resolve-WtCursorIndex {
    <#
    .SYNOPSIS
        PURE: which row a re-entered list opens on, given the row NAME and
        INDEX it was left on (only the main menu restores this way). Name is
        tried first since rows can be added/dropped/moved between visits, and
        compared via Ordinal equality (not -eq) since tr-TR would fold a
        dotted/dotless I; a stale index is clamped and walked to the nearest
        focusable row, forward before backward, since the row above a group
        is usually its header or spacer. Returns -1 for "nothing to restore".
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Items,
        [AllowEmptyString()][string]$Name = '',
        [int]$Index = -1
    )

    if ($Items.Count -eq 0) { return -1 }

    if ($Name) {
        for ($i = 0; $i -lt $Items.Count; $i++) {
            if ([string]::Equals([string]$Items[$i].Name, $Name, [System.StringComparison]::Ordinal) -and (Test-WtItemFocusable -Item $Items[$i])) {
                return $i
            }
        }
    }

    if ($Index -lt 0) { return -1 }

    $target = [Math]::Min($Index, $Items.Count - 1)
    if (Test-WtItemFocusable -Item $Items[$target]) { return $target }
    $forward = Get-WtNextFocusableIndex -Items $Items -FromIndex $target -Direction 1
    if ($forward -ne $target) { return $forward }
    $back = Get-WtNextFocusableIndex -Items $Items -FromIndex $target -Direction -1
    if ($back -ne $target) { return $back }
    return -1
}

function Get-WtMainMenuCursor {
    <#
    .SYNOPSIS
        The row the main menu was last left on, resolved against the rows
        it is about to show; -1 before the first visit. The main menu is
        the only screen that remembers a cursor - row names are
        language-independent ids, so the position survives a language switch.
    #>
    param([Parameter(Mandatory)][AllowEmptyCollection()][array]$Items)
    if ($null -eq $script:WtMainMenuCursor) { return -1 }
    return (Resolve-WtCursorIndex -Items $Items -Name ([string]$script:WtMainMenuCursor.Name) -Index ([int]$script:WtMainMenuCursor.Index))
}

function Set-WtMainMenuCursor {
    <#
    .SYNOPSIS
        Records where the cursor stands so the next return to the main
        menu opens there, keeping both the row name and index (see
        Resolve-WtCursorIndex for why). A negative index means no cursor
        to remember.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Items,
        [Parameter(Mandatory)][int]$Index
    )
    if ($Index -lt 0) { return }
    $name = if ($Index -lt $Items.Count) { [string]$Items[$Index].Name } else { '' }
    $script:WtMainMenuCursor = @{ Name = $name; Index = $Index }
}

function Get-WtItemGroup {
    param([Parameter(Mandatory)][PSCustomObject]$Item)
    if ($Item.PSObject.Properties.Name -contains 'Group' -and $Item.Group) { return [string]$Item.Group }
    return ''
}

function Set-WtRadioSelection {
    <#
    .SYNOPSIS
        Radio semantics scoped to a group: removes every Radio item of the
        SAME group from the selection, then adds the chosen one. Items in
        other groups (and all Check items) are untouched, so one screen can
        host a single-choice DNS block next to multi-select blocks.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][System.Collections.Generic.HashSet[string]]$SelectionSet,
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Items,
        [Parameter(Mandatory)][PSCustomObject]$Item
    )
    $group = Get-WtItemGroup -Item $Item
    foreach ($other in $Items) {
        if ($other.Kind -eq 'Radio' -and (Get-WtItemGroup -Item $other) -eq $group) { $SelectionSet.Remove([string]$other.Name) | Out-Null }
    }
    $SelectionSet.Add([string]$Item.Name) | Out-Null
}

function Test-WtNavToken {
    <#
    .SYNOPSIS
        Whether a token is a navigation key. Includes 'Left'/'Right'
        (grid-only; ConvertTo-WtKeyToken never emits them) so
        Read-WtInputBatch can drain horizontal auto-repeat the same way it
        drains vertical.
    #>
    param([Parameter(Mandatory)][string]$Token)
    return (@('Up', 'Down', 'Left', 'Right', 'PageUp', 'PageDown', 'Home', 'End') -contains $Token)
}

function Invoke-WtListMarkToggle {
    <#
    .SYNOPSIS
        Space / digit on one row. Check rows toggle their mark ("apply" on a
        not-applied row, "remove" on an applied one - the checkbox never
        encodes live state); Radio rows move their group's single mark. An
        applied, non-Removable Check row cannot be marked: returns 'Refused'
        so the shell shows the hint; 'None' otherwise.
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Item,
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Items,
        [Parameter(Mandatory)][AllowEmptyCollection()][System.Collections.Generic.HashSet[string]]$Selection,
        [hashtable]$Cycle
    )
    $props = $Item.PSObject.Properties.Name
    if ($Item.Kind -eq 'Check') {
        $applied = ($props -contains 'Applied') -and [bool]$Item.Applied
        $removable = ($props -contains 'Removable') -and [bool]$Item.Removable
        if ($applied -and -not $removable) { return 'Refused' }
        $targets = @($(if ($props -contains 'CycleTargets') { $Item.CycleTargets } else { @() }))
        if ($targets.Count -gt 0 -and $null -ne $Cycle) {
            $name = [string]$Item.Name
            $at = if ($Cycle.ContainsKey($name)) { [Array]::IndexOf($targets, [string]$Cycle[$name]) } else { -1 }
            $next = $at + 1
            if ($next -ge $targets.Count) { $Cycle.Remove($name); $Selection.Remove($name) | Out-Null }
            else { $Cycle[$name] = [string]$targets[$next]; $Selection.Add($name) | Out-Null }
            return 'None'
        }
        Set-WtSelectionToggle -SelectionSet $Selection -Item $Item | Out-Null
    }
    elseif ($Item.Kind -eq 'Radio' -and $Item.Selectable) {
        Set-WtRadioSelection -SelectionSet $Selection -Items $Items -Item $Item
    }
    return 'None'
}

function Update-WtListState {
    <#
    .SYNOPSIS
        The pure list-screen reducer: one input token in, a new state and an
        emit out. The interactive shell (Invoke-WtListScreen) is a dumb loop
        around this; every navigation rule lives here where Pester can reach
        it. Movement keys scroll the window directly when nothing is
        focusable (no cursor to chase); the search-box branch runs before
        that check so an empty-match filter still answers '/' and Back. A
        Digit token counts position through the whole list, not just the
        page, via TryParse (line mode can hand it a digit run too long for
        a plain [int] cast). Returns
        @{ State = <same shape as input>; Emit = 'None'|'Activate'|'Refused'|'Back'|'Global'; EmitChar = [string] }.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$State,
        [Parameter(Mandatory)][string]$Token,
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Items,
        [int]$ViewHeight = 10,
        [bool]$MultiSelect = $false,
        [bool]$Searchable = $false
    )

    $cursor = [int]$State.CursorIndex
    $window = [int]$State.WindowStart
    $selection = $State.Selection
    $cycle = $(if ($State.ContainsKey('Cycle') -and $null -ne $State.Cycle) { $State.Cycle } else { @{} })
    $focus = $(if ($State.ContainsKey('Focus') -and [string]$State.Focus -eq 'Input') { 'Input' } else { 'List' })
    $query = $(if ($State.ContainsKey('Query') -and $null -ne $State.Query) { [string]$State.Query } else { '' })
    $emit = 'None'
    $emitChar = ''
    $finish = { param([int]$c, [int]$w)
        @{
            State    = @{ CursorIndex = $c; WindowStart = $w; Selection = $selection; Cycle = $cycle; Focus = $focus; Query = $query }
            Emit     = $emit
            EmitChar = $emitChar
        }
    }

    if ($Searchable -and $focus -eq 'Input') {
        $moveWith = ''
        switch -Regex ($Token) {
            '^Eof$'        { $emit = 'Back' }
            '^(Esc|Back)$' { $focus = 'List'; $query = ''; $cursor = 0; $window = 0 }
            '^Enter$'      { $focus = 'List'; $cursor = 0; $window = 0 }
            '^Backspace$'  { if ($query.Length -gt 0) { $query = $query.Substring(0, $query.Length - 1) }; $cursor = 0; $window = 0 }
            '^Space$'      { $query += ' '; $cursor = 0; $window = 0 }
            '^Char:'       { $query += $Token.Substring(5); $cursor = 0; $window = 0 }
            '^Digit:'      { $query += $Token.Substring(6); $cursor = 0; $window = 0 }
            '^(Up|Down|PageUp|PageDown|Home|End)$' { $focus = 'List'; $moveWith = $Token }
        }
        if (-not $moveWith) { return (& $finish $cursor $window) }
        $Token = $moveWith
    }
    elseif ($Searchable) {
        if ($Token -eq 'Char:/') {
            $focus = 'Input'
            $query = ''
            return (& $finish 0 0)
        }
        if ($Token -eq 'Back' -and $query.Trim() -ne '') {
            $query = ''
            return (& $finish 0 0)
        }
    }

    $hasFocusable = $false
    foreach ($item in $Items) { if (Test-WtItemFocusable -Item $item) { $hasFocusable = $true; break } }
    if (-not $hasFocusable) {
        $maxStart = [Math]::Max(0, $Items.Count - $ViewHeight)
        switch -Regex ($Token) {
            '^Up$'       { $window-- }
            '^Down$'     { $window++ }
            '^PageUp$'   { $window -= $ViewHeight }
            '^PageDown$' { $window += $ViewHeight }
            '^Home$'     { $window = 0 }
            '^End$'      { $window = $maxStart }
            '^Enter$'    { $emit = 'Activate' }
            '^Back$'     { $emit = 'Back' }
            '^Eof$'      { $emit = 'Back' }
            '^Char:'     { $emit = 'Global'; $emitChar = $Token.Substring(5) }
        }
        $window = [Math]::Max(0, [Math]::Min($window, $maxStart))
        return (& $finish (-1) $window)
    }

    switch -Regex ($Token) {
        '^Up$'   { $cursor = Get-WtNextFocusableIndex -Items $Items -FromIndex $cursor -Direction -1 }
        '^Down$' { $cursor = Get-WtNextFocusableIndex -Items $Items -FromIndex $cursor -Direction 1 }
        '^Home$' {
            $cursor = -1
            $cursor = Get-WtNextFocusableIndex -Items $Items -FromIndex $cursor -Direction 1
            if ($cursor -lt 0) { $cursor = [int]$State.CursorIndex }
        }
        '^End$' {
            $cursor = $Items.Count
            $cursor = Get-WtNextFocusableIndex -Items $Items -FromIndex $cursor -Direction -1
            if ($cursor -ge $Items.Count) { $cursor = [int]$State.CursorIndex }
        }
        '^PageDown$' {
            $target = [Math]::Min($cursor + $ViewHeight, $Items.Count - 1)
            if (-not (Test-WtItemFocusable -Item $Items[$target])) {
                $target = Get-WtNextFocusableIndex -Items $Items -FromIndex $target -Direction -1
            }
            $cursor = $target
        }
        '^PageUp$' {
            $target = [Math]::Max($cursor - $ViewHeight, 0)
            if (-not (Test-WtItemFocusable -Item $Items[$target])) {
                $target = Get-WtNextFocusableIndex -Items $Items -FromIndex $target -Direction 1
            }
            $cursor = $target
        }
        '^Space$' {
            if ($cursor -ge 0 -and $cursor -lt $Items.Count) {
                $emit = Invoke-WtListMarkToggle -Item $Items[$cursor] -Items $Items -Selection $selection -Cycle $cycle
            }
        }
        '^Enter$' { $emit = 'Activate' }
        '^Back$'  { $emit = 'Back' }
        '^Eof$'   { $emit = 'Back' }
        '^Digit:' {
            $n = 0
            if ([int]::TryParse($Token.Substring(6), [ref]$n) -and $n -ge 1) {
                $seen = 0
                for ($i = 0; $i -lt $Items.Count; $i++) {
                    if (-not (Test-WtItemFocusable -Item $Items[$i])) { continue }
                    $seen++
                    if ($seen -eq $n) {
                        $cursor = $i
                        $emit = Invoke-WtListMarkToggle -Item $Items[$cursor] -Items $Items -Selection $selection -Cycle $cycle
                        break
                    }
                }
            }
        }
        '^Char:a$' {
            if ($MultiSelect) {
                $limit = [Math]::Min($window + $ViewHeight, $Items.Count)
                for ($i = $window; $i -lt $limit; $i++) {
                    $item = $Items[$i]
                    $isApplied = ($item.PSObject.Properties.Name -contains 'Applied') -and [bool]$item.Applied
                    if ($item.Kind -eq 'Check' -and $item.Selectable -and -not $isApplied -and -not $selection.Contains($item.Name)) {
                        $selection.Add($item.Name) | Out-Null
                        $ct = @($(if ($item.PSObject.Properties.Name -contains 'CycleTargets') { $item.CycleTargets } else { @() }))
                        if ($ct.Count -gt 0) { $cycle[[string]$item.Name] = [string]$ct[0] }
                    }
                }
            }
            else { $emit = 'Global'; $emitChar = 'a' }
            break
        }
        '^Char:c$' {
            if ($MultiSelect) {
                $limit = [Math]::Min($window + $ViewHeight, $Items.Count)
                for ($i = $window; $i -lt $limit; $i++) {
                    if ($selection.Contains($Items[$i].Name)) { $selection.Remove($Items[$i].Name) | Out-Null }
                    if ($cycle.ContainsKey([string]$Items[$i].Name)) { $cycle.Remove([string]$Items[$i].Name) }
                }
            }
            else { $emit = 'Global'; $emitChar = 'c' }
            break
        }
        '^Char:' { $emit = 'Global'; $emitChar = $Token.Substring(5) }
    }

    $window = Get-WtViewportWindow -ItemCount $Items.Count -CursorIndex $cursor -ViewHeight $ViewHeight -WindowStart $window

    return (& $finish $cursor $window)
}

function Invoke-WtTokenBatch {
    <#
    .SYNOPSIS
        Runs a batch of input tokens through the pure reducer with NO
        rendering in between (that is how a held arrow key stays smooth:
        N reducer steps, one paint). Stops at the first emitting token;
        tokens after it are dropped on purpose (they were typed before
        the user saw the result).
    #>
    param(
        [Parameter(Mandatory)][hashtable]$State,
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Tokens,
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Items,
        [int]$ViewHeight = 10,
        [bool]$MultiSelect = $false,
        [bool]$Searchable = $false
    )
    $state = $State
    $emit = 'None'
    $emitChar = ''
    $processed = 0
    foreach ($token in $Tokens) {
        $r = Update-WtListState -State $state -Token $token -Items $Items -ViewHeight $ViewHeight -MultiSelect $MultiSelect -Searchable $Searchable
        $state = $r.State
        $processed++
        if ($r.Emit -ne 'None') { $emit = $r.Emit; $emitChar = $r.EmitChar; break }
    }
    return @{ State = $state; Emit = $emit; EmitChar = $emitChar; Processed = $processed }
}
#endregion src/20-tui/list-state.ps1

#region src/20-tui/panel.ps1
# Panel breadcrumb, output lines, wrapped text, panel messages and answers, Wait-WtEnter.
# Covered by: tests/Tui.Tests.ps1, tests/ApplyFlow.Tests.ps1

$script:WtPanelBreadcrumb = ''

function Get-WtPanelItems {
    <#
    .SYNOPSIS
        Plain text lines as non-focusable Info rows (one per line), with
        an optional risk so notices render red/yellow. Only the first
        line carries the risk tag, since a message wrapped over several
        rows is one message, not one per row.
    #>
    param(
        [AllowEmptyCollection()][string[]]$Lines = @(),
        [string]$Risk = ''
    )
    $items = New-Object System.Collections.Generic.List[object]
    $n = 0
    foreach ($l in @($Lines)) {
        $n++
        $items.Add((New-WtListItem -Kind 'Info' -Name ('Line:' + $n) -Label ([string]$l) -Risk $Risk -RiskTag ($n -eq 1)))
    }
    return $items.ToArray()
}

function ConvertTo-WtOutputLines {
    <#
    .SYNOPSIS
        One captured pipeline object -> the text lines a panel should
        show: errors and warnings become their message, not a stack
        trace, and other objects go through Out-String. A lone carriage
        return overwrites the current row instead of starting a new one,
        since tools like sfc write their whole progress as one
        CR-separated line.
    #>
    param([AllowNull()][object]$InputObject)

    if ($null -eq $InputObject) { return @() }

    $text = $null
    if ($InputObject -is [string]) { $text = $InputObject }
    elseif ($InputObject -is [System.Management.Automation.InformationRecord]) {
        $data = $InputObject.MessageData
        $text = if ($null -ne $data -and $data.PSObject.Properties.Name -contains 'Message') { [string]$data.Message } else { [string]$data }
    }
    elseif ($InputObject -is [System.Management.Automation.ErrorRecord]) { $text = [string]$InputObject.Exception.Message }
    elseif ($InputObject -is [System.Management.Automation.WarningRecord]) { $text = [string]$InputObject.Message }
    elseif ($InputObject -is [System.Management.Automation.VerboseRecord] -or $InputObject -is [System.Management.Automation.DebugRecord]) { $text = [string]$InputObject.Message }
    else {
        $text = ($InputObject | Out-String).TrimEnd("`r", "`n")
        $text = $text -replace '^(\r?\n)+', ''
    }

    if ($null -eq $text) { return @() }
    $lines = @($text -split '\r?\n')
    if ($lines.Count -eq 1 -and -not $lines[0]) { return @('') }
    $rows = New-Object System.Collections.Generic.List[string]
    foreach ($line in $lines) {
        if ($line.IndexOf("`r") -lt 0) { $rows.Add($line); continue }
        $segments = @($line -split "`r" | Where-Object { $_ -ne '' })
        $rows.Add($(if ($segments.Count -gt 0) { [string]$segments[-1] } else { '' }))
    }
    return $rows.ToArray()
}

function New-WtNativeOutputState {
    <#
    .SYNOPSIS
        The state Add-WtNativeOutputChunk carries across chunks:
        @{ Lines; Current; Column }. Lines lives inside the hashtable, not
        as its own parameter, since a typed List[string] parameter lets
        PowerShell's binder silently unwrap and reject it without
        [CmdletBinding()], dropping every chunk with the panel left blank.
    #>
    return @{ Lines = (New-Object System.Collections.Generic.List[string]); Current = ''; Column = 0 }
}

function Add-WtNativeOutputChunk {
    <#
    .SYNOPSIS
        Applies one raw chunk of a native tool's stdout to the line state
        the panel renders, the way a terminal would: LF commits the row,
        CR returns to column 1, BS steps back one, anything else
        overwrites and advances. PadRight covers a CR followed by a
        shorter write, so the previous row's tail does not linger.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$State,
        [AllowEmptyString()][string]$Chunk = ''
    )
    $committed = $State.Lines
    foreach ($char in $Chunk.ToCharArray()) {
        if ($char -eq "`n") { $committed.Add([string]$State.Current); $State.Current = ''; $State.Column = 0; continue }
        if ($char -eq "`r") { $State.Column = 0; continue }
        if ($char -eq "`b") { if ([int]$State.Column -gt 0) { $State.Column = [int]$State.Column - 1 }; continue }
        $text = [string]$State.Current
        $column = [int]$State.Column
        if ($column -ge $text.Length) { $State.Current = $text.PadRight($column) + $char }
        else { $State.Current = $text.Remove($column, 1).Insert($column, $char) }
        $State.Column = $column + 1
    }
}

function Format-WtElapsed {
    <#
    .SYNOPSIS
        PURE: seconds -> "mm:ss" for the "still running" footer. Minutes
        keep counting past 60 instead of rolling into hours, so a
        90-minute run reads "90:12" rather than "1:30:12".
    #>
    param([Parameter(Mandatory)][int]$Seconds)
    $s = [Math]::Max(0, $Seconds)
    return ('{0:00}:{1:00}' -f [int][Math]::Floor($s / 60), ($s % 60))
}

function Split-WtWrappedLines {
    <#
    .SYNOPSIS
        PURE: word-wraps one long message into panel-width lines. Runs of
        whitespace collapse to single spaces, a word longer than Width is
        hard-broken, and blank input yields no lines at all.
    #>
    param(
        [AllowNull()][AllowEmptyString()][string]$Text,
        [Parameter(Mandatory)][int]$Width
    )
    $w = [Math]::Max(8, $Width)
    $words = @(([string]$Text) -split '\s+' | Where-Object { $_ })
    $lines = New-Object System.Collections.Generic.List[string]
    $current = ''
    foreach ($word in $words) {
        $piece = [string]$word
        while ($piece.Length -gt $w) {
            if ($current) { $lines.Add($current); $current = '' }
            $lines.Add($piece.Substring(0, $w))
            $piece = $piece.Substring($w)
        }
        if (-not $current) { $current = $piece }
        elseif (($current.Length + 1 + $piece.Length) -le $w) { $current += ' ' + $piece }
        else { $lines.Add($current); $current = $piece }
    }
    if ($current) { $lines.Add($current) }
    return $lines.ToArray()
}

function Get-WtPanelInnerWidth {
    <#
    .SYNOPSIS
        PURE: the widest inner area a box can offer on this console. A
        Compact box is never wider, so wrapping to this fits both
        layouts.
    #>
    param([Parameter(Mandatory)][int]$Width)
    return [Math]::Max(20, (Get-WtFrameWidth -Width $Width) - 4)
}

function Show-WtPanelMessage {
    <#
    .SYNOPSIS
        Paints a frame whose content is a list of text lines (summaries,
        progress, results). No input. Returns the console size used.
        Long lines are wrapped to the box, never cut with '~'.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb,
        [AllowEmptyCollection()][string[]]$Lines = @(),
        [string]$FooterText = '',
        [string]$Risk = '',
        [ValidateSet('Full', 'Compact')][string]$Layout = 'Full'
    )
    $size = Get-WtConsoleSize
    $items = @(Get-WtPanelItems -Lines (ConvertTo-WtPanelLines -Lines $Lines -Width (Get-WtPanelInnerWidth -Width $size.Width) -Risk $Risk) -Risk $Risk)
    $state = @{ CursorIndex = -1; WindowStart = 0; Selection = (New-Object 'System.Collections.Generic.HashSet[string]') }
    $frame = Get-WtFrameRows -Breadcrumb $Breadcrumb -Items $items -State $state -Width $size.Width -Height $size.Height `
        -Glyphs $script:WtGlyphs -FooterText $FooterText -LineMode ($script:WtInputMode -eq 'Line') `
        -Layout $Layout
    Write-WtFrame -FrameLines $frame -Width $size.Width -Height $size.Height
    $geo = Get-WtFrameFooterCell -FrameLines $frame -Glyphs $script:WtGlyphs
    return @{ Width = $size.Width; Height = $size.Height; FooterRow = $geo.Row; FooterCol = $geo.Col }
}

function Show-WtListLoading {
    <#
    .SYNOPSIS
        The one-line "Yukleniyor..." panel a catalog screen paints before
        it builds its rows: the screen's own breadcrumb, no footer,
        nothing to answer. Key mode only, since in line mode a frame is a
        full Clear-Host repaint not worth doing for a screen replaced a
        moment later.
    #>
    param([Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb)
    if ($script:WtInputMode -ne 'Key') { return }
    $null = Show-WtPanelMessage -Breadcrumb $Breadcrumb -Lines @((Get-Translation 'ListLoading')) -FooterText ''
}

function Get-WtFrameFooterCell {
    <#
    .SYNOPSIS
        PURE: the footer row of a painted frame - the last box row before
        the bottom border - and the column just inside its left border.
        Full layout: (Height-2, 2); Compact: wherever the box ends.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$FrameLines,
        [Parameter(Mandatory)][PSCustomObject]$Glyphs
    )
    $row = [Math]::Max(0, $FrameLines.Count - 2)
    $col = 2
    for ($i = $FrameLines.Count - 1; $i -ge 0; $i--) {
        $text = (@($FrameLines[$i]) | ForEach-Object T) -join ''
        $lead = $text.Length - $text.TrimStart().Length
        if ($text.TrimStart().StartsWith($Glyphs.V)) { $row = $i; $col = $lead + 2; break }
    }
    return @{ Row = $row; Col = $col }
}

function Read-WtPanelAnswer {
    <#
    .SYNOPSIS
        The in-panel modal: paints the lines, parks the cursor on the
        footer row inside the box, and reads one line there; $null when
        input is exhausted. Content taller than the viewport is shown
        first in the scrollable output screen, since Read-Host blocks and
        cannot be scrolled while the prompt is up. -Secret reads through
        Read-Host -AsSecureString and hands back plain text, so a typed
        secret echoes as '*' instead of in the clear. Resets the frame
        cache afterwards, since Read-Host's echo dirties the row.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb,
        [AllowEmptyCollection()][string[]]$Lines = @(),
        [Parameter(Mandatory)][string]$Prompt,
        [string]$Risk = '',
        [ValidateSet('Full', 'Compact')][string]$Layout = 'Full',
        [switch]$Secret,
        [scriptblock]$ShowScrollable = { param($Crumb, $Rows) Show-WtOutputScreen -Breadcrumb $Crumb -Lines $Rows -FooterText (Get-Translation 'OutputFooterThenAsk') | Out-Null }
    )
    $readAnswerLine = {
        if ($Secret) {
            $secure = Read-Host -AsSecureString $Prompt
            if ($null -eq $secure) { return $null }
            return ([System.Net.NetworkCredential]::new('', $secure)).Password
        }
        return (Read-Host $Prompt)
    }
    if ($script:WtInputMode -eq 'Line') {
        Clear-Host
        foreach ($l in @($Lines)) { Write-Host $l }
        $answer = & $readAnswerLine
        Reset-WtFrameCache
        return $answer
    }
    $size0 = Get-WtConsoleSize
    $Prompt = [string](Get-WtPanelPromptFit -Prompt $Prompt -Width ([int]$size0.Width))
    $wrapped = @(ConvertTo-WtPanelLines -Lines $Lines -Width (Get-WtPanelInnerWidth -Width $size0.Width) -Risk $Risk)
    $viewHeight = [Math]::Max(1, $size0.Height - (Get-WtFrameChromeHeight -Width $size0.Width))
    if ($wrapped.Count -gt $viewHeight) {
        & $ShowScrollable $Breadcrumb $wrapped
        $Lines = @()
        Reset-WtFrameCache
    }
    $footerText = if ($Layout -eq 'Compact') { $Prompt + ': ' } else { '' }
    $size = Show-WtPanelMessage -Breadcrumb $Breadcrumb -Lines $Lines -FooterText $footerText -Risk $Risk -Layout $Layout
    $footerRow = [int]$size.FooterRow
    $footerCol = [int]$size.FooterCol
    try {
        if ($script:WtVt) { $Host.UI.Write($script:WtEsc + '[' + ($footerRow + 1) + ';' + ($footerCol + 1) + 'H' + $script:WtEsc + '[?25h') }
        else { [Console]::SetCursorPosition($footerCol, $footerRow); [Console]::CursorVisible = $true }
    }
    catch { $null = $_ }
    $null = Assert-WtTuiCtrlCInput
    $null = Assert-WtWindowMaximized
    $answer = & $readAnswerLine
    try {
        if ($script:WtVt) { $Host.UI.Write($script:WtEsc + '[?25l') } else { [Console]::CursorVisible = $false }
    }
    catch { $null = $_ }
    Reset-WtFrameCache
    return $answer
}

function Wait-WtEnter {
    <#
    .SYNOPSIS
        The pause used by every transient flow, shown IN THE PANEL: the
        optional lines, then the translated prompt on the footer. The
        next TUI frame is drawn from scratch afterwards.
    #>
    param([AllowEmptyCollection()][string[]]$Lines = @())
    $null = Read-WtPanelAnswer -Breadcrumb $script:WtPanelBreadcrumb -Lines @($Lines) -Prompt (Get-Translation 'PressEnterContinue') -Layout 'Compact'
    Reset-WtFrameCache
}

function Get-WtPanelPromptFit {
    <#
    .SYNOPSIS
        PURE: cuts a Read-Host prompt so prompt + ': ' still fits between
        the panel's footer column and the right border. Read-Host retypes
        the prompt at the footer column; an unfit prompt once wrapped onto
        the bottom border and the answering Enter scrolled the alt buffer.
        Budget: Width minus the footer column, border/pad, and the ': '
        Read-Host appends, floored at 10; overflow is cut and marked '~'.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Prompt,
        [Parameter(Mandatory)][int]$Width
    )
    $budget = [Math]::Max(10, $Width - 8)
    if ($Prompt.Length -le $budget) { return $Prompt }
    return ($Prompt.Substring(0, $budget - 1) + '~')
}
#endregion src/20-tui/panel.ps1

#region src/20-tui/repl-console.ps1
# The console side of the assistant's plain-console REPL: mode entry/exit,
# the alt-buffer hop, the append-only printers, and the ReadKey line reader.
# Covered by: tests/ReplConsole.Tests.ps1

function Get-WtReplDefaultWriter {
    <#
    .SYNOPSIS
        The one place a REPL line reaches the host: Write-Host with a
        colour, optionally without the newline (streaming). Works in
        conhost, Windows Terminal, ISE and a redirected host alike.
    #>
    return { param($Text, $Fg, $NoNewline)
        $color = $(if ($Fg) { [ConsoleColor]$Fg } else { [ConsoleColor]'Gray' })
        if ($NoNewline) { Write-Host -NoNewline -ForegroundColor $color ([string]$Text) }
        else { Write-Host -ForegroundColor $color ([string]$Text) }
    }
}

function Get-WtReplRawWriter {
    <#
    .SYNOPSIS
        VT sequences and the edit line go straight to the host: no colour,
        no newline.
    #>
    return { param($Text) $Host.UI.Write([string]$Text) }
}

function Hide-WtReplLive {
    <#
    .SYNOPSIS
        Erases the live region: carriage return, up to the region's
        first row (relative - never an absolute cursor position), erase
        to the end of the screen, cursor back on. No-op when nothing is
        painted, so every transcript writer can call it unconditionally.
    #>
    param([scriptblock]$Write = (Get-WtReplRawWriter))
    if ($null -eq $script:WtReplLive -or [int]$script:WtReplLive.Rows -le 0) { return }
    $text = "`r"
    if ([int]$script:WtReplLive.CaretRow -gt 0) { $text += $script:WtEsc + '[' + [int]$script:WtReplLive.CaretRow + 'A' }
    $text += $script:WtEsc + '[J' + $script:WtEsc + '[?25h'
    & $Write $text
    $script:WtReplLive = @{ Rows = 0; CaretRow = 0 }
}

function Show-WtReplLive {
    <#
    .SYNOPSIS
        Paints the live region below the committed transcript in ONE
        console write: cursor off, back to the region's first row, rows
        joined by LF (no trailing newline - Hide relies on the caret
        being INSIDE the region), erase-to-end after the last row, caret
        parked on CaretRow/CaretCol (-1 hides it). Rows overwrite the
        old region in place rather than erase-then-redraw, which
        flickered on every keystroke. A region taller than the window is
        cut from the FRONT, since the relative ESC[nA can no longer
        reach rows that scrolled out of the viewport.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Rows,
        [int]$CaretRow = -1,
        [int]$CaretCol = 0,
        [int]$Width = 0,
        [int]$Height = 0,
        [scriptblock]$Write = (Get-WtReplRawWriter)
    )
    if (-not $script:WtReplLiveEnabled) { return }
    $rows = @($Rows)
    if ($rows.Count -eq 0) { Hide-WtReplLive -Write $Write; return }
    if (-not $script:WtReplLastBlank -and -not $script:WtReplToolBoxOpen) {
        $rows = @(, @(, (New-WtSeg -Text '' -Fg 'Gray'))) + $rows
        if ($CaretRow -ge 0) { $CaretRow++ }
    }
    if ($Width -le 0 -or ($Height -le 0 -and $rows.Count -gt 1)) {
        $size = Get-WtConsoleSize
        if ($Width -le 0) { $Width = [int]$size.Width }
        if ($Height -le 0) { $Height = [int]$size.Height }
    }
    $max = [Math]::Max(1, $Height - 1)
    if ($Height -gt 0 -and $rows.Count -gt $max) {
        $dropped = $rows.Count - $max
        $rows = @($rows[$dropped..($rows.Count - 1)])
        if ($CaretRow -ge 0) {
            $CaretRow = $CaretRow - $dropped
            if ($CaretRow -lt 0) { $CaretRow = -1 }
        }
    }
    $w = [Math]::Max(20, $Width - 1)
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append($script:WtEsc + '[?25l' + "`r")
    $previous = $script:WtReplLive
    if ($null -ne $previous -and [int]$previous.Rows -gt 0 -and [int]$previous.CaretRow -gt 0) {
        [void]$sb.Append($script:WtEsc + '[' + [int]$previous.CaretRow + 'A')
    }
    for ($i = 0; $i -lt $rows.Count; $i++) {
        if ($i -gt 0) { [void]$sb.Append("`n") }
        [void]$sb.Append((ConvertTo-WtRowString -Segments @($rows[$i]) -Width $w -Vt $script:WtVt))
    }
    [void]$sb.Append($script:WtEsc + '[J')
    $caret = $(if ($CaretRow -ge 0 -and $CaretRow -lt $rows.Count) { $CaretRow } else { $rows.Count - 1 })
    $up = $rows.Count - 1 - $caret
    if ($up -gt 0) { [void]$sb.Append($script:WtEsc + '[' + $up + 'A') }
    [void]$sb.Append("`r" + $script:WtEsc + '[' + ([Math]::Max(0, $CaretCol) + 1) + 'G')
    [void]$sb.Append($script:WtEsc + $(if ($CaretRow -ge 0) { '[?25h' } else { '[?25l' }))
    & $Write $sb.ToString()
    $script:WtReplLive = @{ Rows = $rows.Count; CaretRow = $caret }
}

function Write-WtReplRows {
    <#
    .SYNOPSIS
        Commits segment rows (a box, the banner) to the transcript: each
        row rendered Width-1 wide, coloured when VT is on, one console
        line each, through the line writer so tests see plain lines.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Rows,
        [int]$Width = 0,
        [scriptblock]$Write = (Get-WtReplDefaultWriter)
    )
    Hide-WtReplLive
    if ($Width -le 0) { $Width = (Get-WtConsoleSize).Width }
    $w = [Math]::Max(20, $Width - 1)
    foreach ($row in @($Rows)) { & $Write (ConvertTo-WtRowString -Segments @($row) -Width $w -Vt $script:WtVt) 'Gray' $false }
}

$script:WtReplLastBlank = $true
$script:WtReplLastGroup = ''

$script:WtReplPageWidth = 0

$script:WtReplToolBoxOpen = $false
$script:WtReplToolBoxWidth = 0

$script:WtReplResizePoll = $false
$script:WtReplResizeChecked = [datetime]::MinValue

function Get-WtReplMargin {
    <#
    .SYNOPSIS
        PURE: the transcript's side margin in columns - where you, the
        answer and the info lines start, and how far short of the right
        edge they wrap. Two columns is exactly where the text sits inside
        the input box ("| > "), so a committed line stays in the column it
        was typed in.
    #>
    return [int]$script:WtReplMargin
}

function Get-WtReplTextWidth {
    <#
    .SYNOPSIS
        PURE: the width the transcript's text is wrapped at - the console
        width less the right margin. The rows themselves still render
        Width-1 wide (padding), so the frames around them do not change.
    #>
    param([int]$Width = 80)
    return [Math]::Max(12, $Width - (Get-WtReplMargin))
}

function Reset-WtReplBlockState {
    $script:WtReplLastBlank = $true
    $script:WtReplLastGroup = ''
    $script:WtReplToolBoxOpen = $false
}

function Get-WtReplToolBoxRow {
    <#
    .SYNOPSIS
        PURE: one row of the tool box - its top border, its bottom
        border, or one content row ("| " + segments + padding + " |",
        cut with '~' past the inner width) - Width-1 wide, DarkGray so
        the box sits behind the answer rather than in front of it.
    #>
    param(
        [ValidateSet('Top', 'Bottom', 'Row')][string]$Part = 'Row',
        [AllowEmptyCollection()][array]$Segments = @(),
        [int]$Width = 80,
        [PSCustomObject]$Glyphs = $script:WtGlyphs,
        [string]$Fg = 'DarkGray'
    )
    $box = @(Get-WtReplBoxRows -Title '' -Rows @(, @($Segments)) -Width $Width -Glyphs $Glyphs -Fg $Fg)
    switch ($Part) {
        'Top' { return , $box[0] }
        'Bottom' { return , $box[2] }
        default { return , $box[1] }
    }
}

function Close-WtReplToolBox {
    <#
    .SYNOPSIS
        Prints the bottom border of the open tool box, if one is open.
        Every transcript writer calls it before printing anything that
        is not a tool row, so the box always closes exactly once.
    #>
    param([int]$Width = 0, [scriptblock]$Write = (Get-WtReplDefaultWriter))
    if (-not $script:WtReplToolBoxOpen) { return }
    $script:WtReplToolBoxOpen = $false
    if ($Width -le 0) { $Width = [int]$script:WtReplToolBoxWidth }
    if ($Width -le 0) { $Width = (Get-WtConsoleSize).Width }
    Write-WtReplBlock -Rows @(, (Get-WtReplToolBoxRow -Part 'Bottom' -Width $Width)) -Width $Width -Write $Write -ToolBox
}

function Get-WtReplEntryGroup {
    <#
    .SYNOPSIS
        PURE: which of the three speakers an entry kind belongs to. Tool,
        Info and Error are one group - the app talking - so a tool call,
        its results, a permission decision and the turn summary stay one
        block, while you -> tool, answer -> tool and answer -> summary
        each get their own blank line.
    #>
    param([AllowEmptyString()][string]$Kind = '')
    if ($Kind -eq 'User') { return 'User' }
    if ($Kind -eq 'Assistant') { return 'Assistant' }
    return 'System'
}

function Write-WtReplBlock {
    <#
    .SYNOPSIS
        The ONE door into the transcript. Hides the live region, closes
        an open tool box unless these rows belong to it (-ToolBox), then
        writes segment rows. -Separate asks for a blank line before the
        block (only when the speaker changed); two blanks in a row are
        never printed, here or across calls, so no caller has to track
        what the previous one left behind.
    #>
    param(
        [AllowNull()][AllowEmptyCollection()][array]$Rows = @(),
        [switch]$Separate,
        [int]$Width = 0,
        [scriptblock]$Write = (Get-WtReplDefaultWriter),
        [scriptblock]$HideWrite = $null,
        [switch]$ToolBox
    )
    if ($null -ne $HideWrite) { Hide-WtReplLive -Write $HideWrite } else { Hide-WtReplLive }
    if ($Width -le 0) { $Width = (Get-WtConsoleSize).Width }
    if (-not $ToolBox) { Close-WtReplToolBox -Width $Width -Write $Write }
    $w = [Math]::Max(20, $Width - 1)
    if ($Separate -and -not $script:WtReplLastBlank) {
        & $Write '' 'Gray' $false
        $script:WtReplLastBlank = $true
    }
    foreach ($row in @($Rows)) {
        $plain = (@($row) | ForEach-Object { [string]$_.T }) -join ''
        $isBlank = ($plain.Trim().Length -eq 0)
        if ($isBlank -and $script:WtReplLastBlank) { continue }
        & $Write (ConvertTo-WtRowString -Segments @($row) -Width $w -Vt $script:WtVt) 'Gray' $false
        $script:WtReplLastBlank = $isBlank
    }
}

function Sync-WtReplResize {
    <#
    .SYNOPSIS
        The mid-turn resize: while the model works nothing is reading a
        line, so the prompt's own resize path cannot fire and the banner
        would sit off-centre until the turn ended. Called from the cancel
        poll and the status-row tick, at most once per 250 ms; when the
        console width differs from the one the page was painted at, the
        whole page is repainted - banner, transcript so far, and the
        streamed answer re-run through the stream so its wrap and state
        match the new width. Returns $true when it repainted.
    #>
    param([scriptblock]$Write = (Get-WtReplRawWriter), [switch]$Force)
    if (-not $script:WtReplMode -or -not $script:WtReplLiveEnabled) { return $false }
    $now = [datetime]::UtcNow
    if (-not $Force -and ($now - [datetime]$script:WtReplResizeChecked).TotalMilliseconds -lt 250) { return $false }
    $script:WtReplResizeChecked = $now
    $pageWidth = [int]$script:WtReplPageWidth
    if ($pageWidth -le 0) { return $false }
    $width = [int](Get-WtConsoleSize).Width
    if ($width -eq $pageWidth) { return $false }
    Hide-WtReplLive -Write $Write
    Clear-WtReplScreen
    Write-WtReplHeader -Width $width
    Write-WtReplWelcome -Width $width
    $chat = $script:WtAssistantChat
    if ($null -ne $chat) { Write-WtReplTranscriptTail -Session $chat -Count 400 -Width $width }
    if ($null -ne $script:WtReplStream) {
        $content = $script:WtReplStream.Content.ToString()
        $reasoning = $script:WtReplStream.Reasoning.ToString()
        Reset-WtReplStream
        $script:WtReplStream.Width = $width
        [void]$script:WtReplStream.Reasoning.Append($reasoning)
        if ($content) { Write-WtReplStream -Piece $content -Width $width }
    }
    return $true
}

function Show-WtReplSpinner {
    param(
        [AllowEmptyString()][string]$Label = '',
        [scriptblock]$Now = { Get-Date },
        [scriptblock]$Write = (Get-WtReplRawWriter),
        [int]$Width = 0
    )
    $started = [datetime](& $Now)
    $script:WtReplSpinner = @{ Started = $started; LastPaint = [datetime]::MinValue; LastSig = ''; Label = $Label; Chars = 0; Active = $true; Tail = @() }
    Update-WtReplSpinner -Force -Now $Now -Write $Write -Width $Width
}

function Update-WtReplSpinner {
    <#
    .SYNOPSIS
        One tick: add streamed chars, and at most every 120 ms repaint the
        spinner line in the live region. Called from the client's
        ShouldCancel poll and from every reasoning delta, so a thinking
        model keeps the seconds moving without printing a word of it. Box
        rows are built into a List, not an array literal: @( (row) (row) )
        would flatten the two row-arrays into four rows instead of two.
    #>
    param(
        [int]$AddChars = 0,
        [switch]$Force,
        [scriptblock]$Now = { Get-Date },
        [scriptblock]$Write = (Get-WtReplRawWriter),
        [int]$Width = 0,
        [AllowNull()][AllowEmptyCollection()][string[]]$Tail = $null
    )
    $s = $script:WtReplSpinner
    if ($null -eq $s -or -not $s.Active) { return }
    $s.Chars = [int]$s.Chars + $AddChars
    if ($null -ne $Tail) { $s.Tail = @($Tail | ForEach-Object { [string]$_ } | Where-Object { $_.Trim().Length -gt 0 }) }
    $t = [datetime](& $Now)
    if (-not $Force -and ($t - [datetime]$s.LastPaint).TotalMilliseconds -lt 120) { return }
    $s.LastPaint = $t
    if (-not $script:WtReplLiveEnabled) { return }
    $resized = [bool](Sync-WtReplResize -Write $Write)
    $line = Format-WtReplSpinnerLine -Label ([string]$s.Label) -Seconds ($t - [datetime]$s.Started).TotalSeconds -Chars ([int]$s.Chars)
    $tail = @($(if ($s.ContainsKey('Tail')) { $s.Tail } else { @() }))
    $sig = $line + "`n" + ($tail -join "`n") + "`n" + [string]$script:WtReplToolBoxOpen
    if (-not $Force -and -not $resized -and [string]::Equals([string]$s.LastSig, $sig, [System.StringComparison]::Ordinal)) { return }
    $s.LastSig = $sig
    $seg = New-WtSeg -Text $line -Fg 'DarkYellow'
    if ($script:WtReplToolBoxOpen -or $tail.Count -gt 0) {
        $boxWidth = [int]$script:WtReplToolBoxWidth
        if (-not $script:WtReplToolBoxOpen -or $boxWidth -le 0) { $boxWidth = $(if ($Width -gt 0) { $Width } else { (Get-WtConsoleSize).Width }) }
        $rows = New-Object System.Collections.Generic.List[object]
        if (-not $script:WtReplToolBoxOpen) { $rows.Add((Get-WtReplToolBoxRow -Part 'Top' -Width $boxWidth)) }
        $rows.Add((Get-WtReplToolBoxRow -Part 'Row' -Segments @(, $seg) -Width $boxWidth))
        foreach ($outLine in $tail) { $rows.Add((Get-WtReplToolBoxRow -Part 'Row' -Segments @(, (New-WtSeg -Text ('      ' + $outLine) -Fg 'Gray')) -Width $boxWidth)) }
        $rows.Add((Get-WtReplToolBoxRow -Part 'Bottom' -Width $boxWidth))
        Show-WtReplLive -Rows $rows.ToArray() -CaretRow -1 -Width $Width -Write $Write
        return
    }
    $marginSeg = New-WtSeg -Text ((' ' * (Get-WtReplMargin)) + $line) -Fg 'DarkYellow'
    Show-WtReplLive -Rows @(, @(, $marginSeg)) -CaretRow -1 -Width $Width -Write $Write
}

function Hide-WtReplSpinner {
    param([scriptblock]$Write = (Get-WtReplRawWriter))
    if ($null -ne $script:WtReplSpinner) { $script:WtReplSpinner.Active = $false }
    Hide-WtReplLive -Write $Write
}

$script:WtReplConsoleModeSource = @'
using System;
using System.Runtime.InteropServices;
public static class WtConsoleMode
{
    [DllImport("kernel32.dll", SetLastError = true)] public static extern IntPtr GetStdHandle(int nStdHandle);
    [DllImport("kernel32.dll", SetLastError = true)] public static extern bool GetConsoleMode(IntPtr hConsoleHandle, out uint lpMode);
    [DllImport("kernel32.dll", SetLastError = true)] public static extern bool SetConsoleMode(IntPtr hConsoleHandle, uint dwMode);
}
'@

function Enable-WtReplQuickEdit {
    <#
    .SYNOPSIS
        Mouse selection in conhost while the REPL runs (Windows Terminal
        handles selection itself and ignores this). Returns the mode to
        restore, $null when the console API is not available - every
        failure is swallowed, the REPL works without it. The P/Invoke
        source (compiled once per process) needs ENABLE_QUICK_EDIT_MODE
        (0x40) and ENABLE_EXTENDED_FLAGS (0x80) set together in the same
        call, and is C# 5 only, since that is what PS 5.1's compiler
        accepts.
    #>
    param([scriptblock]$Apply = {
        if (-not ('WtConsoleMode' -as [type])) { Add-Type -TypeDefinition $script:WtReplConsoleModeSource -ErrorAction Stop }
        $handle = [WtConsoleMode]::GetStdHandle(-10)
        $mode = [uint32]0
        if (-not [WtConsoleMode]::GetConsoleMode($handle, [ref]$mode)) { return $null }
        $null = [WtConsoleMode]::SetConsoleMode($handle, ($mode -bor [uint32]0x40 -bor [uint32]0x80))
        return $mode
    })
    try { return (& $Apply) } catch { return $null }
}

function Restore-WtReplQuickEdit {
    param(
        [AllowNull()]$Mode,
        [scriptblock]$Apply = { param($M)
            $handle = [WtConsoleMode]::GetStdHandle(-10)
            $null = [WtConsoleMode]::SetConsoleMode($handle, [uint32]$M)
        }
    )
    if ($null -eq $Mode) { return }
    try { & $Apply $Mode } catch { $null = $_ }
}

function Clear-WtReplScreen {
    <#
    .SYNOPSIS
        A fresh page: viewport AND scrollback wiped (ESC[3J - a conhost
        that ignores it just keeps the old scrollback), cursor homed.
        Without VT, Clear-Host through a seam. Clear-Host runs FIRST on
        every host: conhost's ESC[2J does not erase the buffer, it
        scrolls the viewport INTO the scrollback, leaving a window-high
        gap above the banner; Clear-Host wipes conhost's whole buffer,
        while in Windows Terminal it clears only the viewport, leaving
        the ESC[3J that follows to drop the scrollback there.
    #>
    param(
        [scriptblock]$Write = (Get-WtReplRawWriter),
        [scriptblock]$ClearHost = { Clear-Host }
    )
    Hide-WtReplLive -Write $Write
    try { & $ClearHost } catch { $null = $_ }
    if ($script:WtVt) { & $Write ($script:WtEsc + '[3J' + $script:WtEsc + '[1;1H') }
    Reset-WtFrameCache
    Reset-WtReplBlockState
}

function Write-WtReplHeader {
    <#
    .SYNOPSIS
        The top of the assistant page: the same banner every framed screen
        shows (centered, cyan), the credit lines, then the breadcrumb -
        "Main Menu > WinToolify Assistant" - as the path row of a
        full-width box (cyan border, white text), exactly the row every
        framed screen opens its frame with, and one blank row under it.
        The model and what the assistant remembers live in the status line
        under the input box instead, so the page opens with six fewer
        rows. Sets $script:WtReplPageWidth, the resize baseline every
        later check compares against. Uses Write-WtReplLine, never
        Write-WtReplRows, since only the line/block writers keep
        $script:WtReplLastBlank and the speaker group current.
    #>
    param(
        [int]$Width = 0,
        [scriptblock]$Write = (Get-WtReplDefaultWriter)
    )
    if ($Width -le 0) { $Width = (Get-WtConsoleSize).Width }
    $script:WtReplPageWidth = [int]$Width
    $w = [Math]::Max(20, $Width - 1)
    $center = { param([string]$Text) $pad = [Math]::Max(0, [Math]::Floor(($w - $Text.Length) / 2)); (' ' * $pad) + $Text }
    foreach ($b in @(Get-WtBannerLines -Width $Width)) { Write-WtReplLine -Text (& $center $b) -Fg 'Cyan' -Write $Write -NoMargin }
    Write-WtReplLine -Text '' -Write $Write
    $credit = @(Get-WtBannerCreditLines)
    Write-WtReplLine -Text (& $center ([string]$credit[0])) -Fg 'Gray' -Write $Write -NoMargin
    Write-WtReplLine -Text (& $center ([string]$credit[1])) -Fg 'DarkGray' -Write $Write -NoMargin
    Write-WtReplLine -Text '' -Write $Write
    $crumbRow = @(, (New-WtSeg -Text ([string](Get-WtBreadcrumb -Keys 'MainMenu', 'Assistant')) -Fg 'White'))
    $crumb = @(Get-WtReplBoxRows -Title '' -Rows @(, $crumbRow) -Width $Width -Glyphs $script:WtGlyphs -Fg 'Cyan')
    foreach ($row in $crumb) { Write-WtReplLine -Text (ConvertTo-WtRowString -Segments $row -Width $w -Vt $script:WtVt) -Fg 'Cyan' -Write $Write -NoMargin }
    Write-WtReplLine -Text '' -Write $Write
}

function Write-WtReplWelcome {
    <#
    .SYNOPSIS
        The introduction under the breadcrumb: who the assistant is, what it
        does, five example questions and the key hints. A PERMANENT part of
        the page, printed on every paint (menu entry, /yeni, a pushed-screen
        return, any resize) with the transcript piling up under it - it
        used to print only on an empty page, so the first repaint after the
        first message wiped it. Lives next to Write-WtReplHeader since the
        mid-turn resize repaints the page from this layer.
    #>
    param([int]$Width = 0, [scriptblock]$Write = (Get-WtReplDefaultWriter))
    if ($Width -le 0) { $Width = (Get-WtConsoleSize).Width }
    $margin = Get-WtReplMargin
    $textWidth = Get-WtReplTextWidth -Width $Width
    $rows = New-Object System.Collections.Generic.List[object]
    $paragraph = { param([string]$Text, [string]$Fg)
        $block = @{ Kind = 'Paragraph'; Level = 0; Marker = ''; Text = $Text; State = @{ InFence = $false } }
        $colors = @{ Normal = $Fg; Strong = 'White'; Code = 'DarkCyan'; Link = $Fg; Url = $Fg }
        foreach ($r in (Split-WtWrappedSegments -Parts (Split-WtRichInline -Text ([string]$block.Text)) -Width $textWidth -Indent $margin -Colors $colors)) { $rows.Add($r) }
    }
    & $paragraph ([string](Get-Translation 'AsWelcome1')) 'Gray'
    $rows.Add(@(, (New-WtSeg -Text '' -Fg 'Gray')))
    & $paragraph ([string](Get-Translation 'AsWelcome2')) 'Gray'
    foreach ($key in 'AsWelcomeEx1', 'AsWelcomeEx2', 'AsWelcomeEx3', 'AsWelcomeEx4', 'AsWelcomeEx5') {
        $block = @{ Kind = 'Bullet'; Level = 0; Marker = ''; Text = [string](Get-Translation $key); State = @{ InFence = $false } }
        foreach ($r in (Get-WtRichBlockRows -Block $block -Width $textWidth -Indent $margin)) { $rows.Add($r) }
    }
    $rows.Add(@(, (New-WtSeg -Text '' -Fg 'Gray')))
    & $paragraph ([string](Get-Translation 'AsWelcome3')) 'DarkGray'
    Write-WtReplBlock -Rows $rows.ToArray() -Width $Width -Write $Write
    $script:WtReplLastGroup = 'System'
}

function Enter-WtReplMode {
    <#
    .SYNOPSIS
        Framed TUI -> plain console: leave the alternate buffer and show
        the cursor (VT), unpin the buffer height so the console has
        scrollback, take Ctrl+C as input. Idempotent. WtInputMode stays
        'Key' on purpose: the 'Line' paths Clear-Host.
    #>
    param(
        [scriptblock]$Write = (Get-WtReplRawWriter),
        [scriptblock]$SetConsole = { param($Name, $Value)
            switch ($Name) {
                'BufferHeight' { [Console]::BufferHeight = [int]$Value }
                'CtrlC' { [Console]::TreatControlCAsInput = [bool]$Value }
                'Cursor' { [Console]::CursorVisible = [bool]$Value }
                'Repin' { $Host.UI.RawUI.BufferSize = $Host.UI.RawUI.WindowSize }
            }
        },
        [scriptblock]$GetConsole = { param($Name)
            switch ($Name) {
                'BufferHeight' { [Console]::BufferHeight }
                'CtrlC' { [Console]::TreatControlCAsInput }
                'WindowHeight' { [Console]::WindowHeight }
            }
        }
    )
    if ($script:WtReplMode) { return }
    $saved = @{ BufferHeight = 0; CtrlC = $false }
    if ($script:WtInputMode -eq 'Key') {
        try { $saved.BufferHeight = [int](& $GetConsole 'BufferHeight') } catch { $null = $_ }
        try { $saved.CtrlC = [bool](& $GetConsole 'CtrlC') } catch { $null = $_ }
    }
    $script:WtReplSaved = $saved
    if ($script:WtVt) { & $Write ($script:WtEsc + '[?1049l' + $script:WtEsc + '[?25h') }
    else { try { & $SetConsole 'Cursor' $true } catch { $null = $_ } }
    if ($script:WtInputMode -eq 'Key') {
        $script:WtReplConsoleModeSaved = Enable-WtReplQuickEdit
        $windowHeight = 50
        try { $windowHeight = [int](& $GetConsole 'WindowHeight') } catch { $null = $_ }
        try { & $SetConsole 'BufferHeight' ([Math]::Max(3000, $windowHeight)) } catch { $null = $_ }
        try { & $SetConsole 'CtrlC' $true } catch { $null = $_ }
    }
    $script:WtReplLiveEnabled = [bool]($script:WtVt -and $script:WtInputMode -eq 'Key')
    $script:WtReplResizePoll = [bool]($script:WtInputMode -eq 'Key')
    $script:WtReplLive = @{ Rows = 0; CaretRow = 0 }
    $script:WtReplMode = $true
    Reset-WtFrameCache
}

function Exit-WtReplMode {
    <#
    .SYNOPSIS
        Plain console -> framed TUI: give Ctrl+C back, repin the buffer
        to the window (destroys the REPL scrollback - the transcript lives
        in the session, not the console), re-enter the alternate buffer
        with a cleared screen. Idempotent; safe in a finally.
    #>
    param(
        [scriptblock]$Write = (Get-WtReplRawWriter),
        [scriptblock]$SetConsole = { param($Name, $Value)
            switch ($Name) {
                'CtrlC' { [Console]::TreatControlCAsInput = [bool]$Value }
                'Cursor' { [Console]::CursorVisible = [bool]$Value }
                'Repin' { $Host.UI.RawUI.BufferSize = $Host.UI.RawUI.WindowSize }
            }
        }
    )
    if (-not $script:WtReplMode) { return }
    Hide-WtReplLive -Write $Write
    $saved = $script:WtReplSaved
    if ($script:WtInputMode -eq 'Key') {
        try { & $SetConsole 'CtrlC' ([bool]$(if ($null -ne $saved) { $saved.CtrlC } else { $false })) } catch { $null = $_ }
        try { & $SetConsole 'Repin' $true } catch { $null = $_ }
        Restore-WtReplQuickEdit -Mode $script:WtReplConsoleModeSaved
        $script:WtReplConsoleModeSaved = $null
    }
    if ($script:WtVt) { & $Write ($script:WtEsc + '[?1049h' + $script:WtEsc + '[?25l' + $script:WtEsc + '[2J' + $script:WtEsc + '[1;1H') }
    else { try { & $SetConsole 'Cursor' ($script:WtInputMode -ne 'Key') } catch { $null = $_ } }
    $script:WtReplMode = $false
    $script:WtReplLiveEnabled = $false
    $script:WtReplResizePoll = $false
    Reset-WtFrameCache
}

function Invoke-WtReplHop {
    <#
    .SYNOPSIS
        Runs something that paints a frame (a panel gate, a captured
        action, a screen) from inside the REPL: hop into the alternate
        buffer, run it, hop back, keeping the scrollback intact. Outside
        the REPL it just runs the action. A host without VT has no
        alternate buffer to hop into, so the framed action's own
        Clear-Host wipes the transcript off the console; when the REPL is
        active there, the transcript tail is reprinted afterward so the
        conversation is not lost from view.
    #>
    param(
        [Parameter(Mandatory)][scriptblock]$Action,
        [scriptblock]$Write = (Get-WtReplRawWriter)
    )
    if (-not $script:WtVt) {
        Hide-WtReplLive -Write $Write
        $result = & $Action
        if ($script:WtReplMode) {
            Reset-WtFrameCache
            Write-WtReplLine -Text ''
            if ($null -ne $script:WtAssistantChat) { Write-WtReplTranscriptTail -Session $script:WtAssistantChat -Count 40 }
        }
        return $result
    }
    if (-not $script:WtReplMode) { return (& $Action) }
    Hide-WtReplLive -Write $Write
    & $Write ($script:WtEsc + '[?1049h' + $script:WtEsc + '[?25l' + $script:WtEsc + '[2J' + $script:WtEsc + '[1;1H')
    Reset-WtFrameCache
    try { return (& $Action) }
    finally {
        & $Write ($script:WtEsc + '[?1049l' + $script:WtEsc + '[?25h')
        Reset-WtFrameCache
    }
}

function Write-WtReplLine {
    <#
    .SYNOPSIS
        One plain row onto the transcript. It keeps the same two flags
        Write-WtReplBlock keeps: these ~60 call sites (every slash
        command, the header, the low-mode question branches) commit real
        rows, so a block that follows must know whether the last row was
        blank and that the app - not you, not the answer - spoke last.
    #>
    param(
        [AllowNull()][AllowEmptyString()][string]$Text = '',
        [string]$Fg = 'Gray',
        [scriptblock]$Write = (Get-WtReplDefaultWriter),
        [switch]$NoMargin
    )
    Hide-WtReplLive
    Close-WtReplToolBox -Write $Write
    $plain = [string]$Text
    $shown = $(if ($NoMargin -or $plain.Trim().Length -eq 0) { $plain } else { (' ' * (Get-WtReplMargin)) + $plain })
    & $Write $shown $Fg $false
    $script:WtReplLastBlank = ($plain.Trim().Length -eq 0)
    $script:WtReplLastGroup = 'System'
}

function Reset-WtReplStream {
    $script:WtReplStream = @{
        Content   = (New-Object System.Text.StringBuilder)
        Reasoning = (New-Object System.Text.StringBuilder)
        Open      = $false
        LastKind  = ''
        Buffer    = (New-Object System.Text.StringBuilder)
        Rich      = @{ InFence = $false }
        Width     = 0
    }
}

function Write-WtReplLineBuffered {
    <#
    .SYNOPSIS
        One COMPLETED source line out of the stream buffer and onto the
        screen, through the rich layer and the one transcript door.
        Rich.Continuation marks a chunk the overflow cut broke off a
        paragraph: it is rendered AS a paragraph rather than classified
        again, so a tail that happens to start "- " or "# " is never
        re-read as a bullet or a heading in the middle of a sentence.
    #>
    param([AllowEmptyString()][string]$Line = '', [int]$Width = 80, [scriptblock]$Write)
    $rich = $script:WtReplStream.Rich
    $continuing = [bool]($rich.Continuation -and -not $rich.InFence)
    $margin = Get-WtReplMargin
    $indent = $(if ($continuing) { [int]$rich.ContinuationIndent } else { $margin })
    if ($continuing) {
        $block = @{ Kind = 'Paragraph'; Level = 0; Marker = ''; Text = ([string]$Line).Trim(); State = @{ InFence = $false } }
    }
    else {
        $block = Get-WtRichBlock -Line $Line -State $rich
    }
    $state = $block.State
    $state.ContinuationIndent = $(if ($continuing) { $indent } else { [int](Get-WtRichBlockIndents -Block $block -Indent $margin).Continuation })
    $script:WtReplStream.Rich = $state
    $rows = (Get-WtRichBlockRows -Block $block -Width (Get-WtReplTextWidth -Width $Width) -Indent $indent)
    if ($rows.Count -eq 0) { return }
    Write-WtReplBlock -Rows $rows -Separate:(-not $script:WtReplStream.Open) -Width $Width -Write $Write
    $script:WtReplStream.Open = $true
    $script:WtReplLastGroup = 'Assistant'
}

function Test-WtReplCutSafe {
    <#
    .SYNOPSIS
        PURE: may the overflow cut take this chunk on its own? A ** or a
        backtick that opens inside it and closes after the cut would be
        printed literally, putting raw markdown on the screen - so the
        chunk waits instead. Nothing is lost: the newline path or
        Complete flushes it.
    #>
    param([AllowNull()][AllowEmptyString()][string]$Text = '')
    foreach ($part in @(Split-WtRichInline -Text ([string]$Text))) {
        if ([string]$part.Style -ne 'Normal') { continue }
        $plain = [string]$part.Text
        if ($plain.IndexOf([char]96) -ge 0) { return $false }
        if ($plain.IndexOf('**', [System.StringComparison]::Ordinal) -ge 0) { return $false }
        if ($plain.IndexOf('__', [System.StringComparison]::Ordinal) -ge 0) { return $false }
    }
    return $true
}

function Write-WtReplStream {
    <#
    .SYNOPSIS
        One streamed piece. Reasoning is COLLECTED AND NEVER PRINTED.
        Content is appended raw to Content - that is what the transcript
        records and /kopyala copies - and also to a line buffer: a
        completed line goes through the rich layer, a half line waits. A
        buffer that outgrows the wrap width without ever seeing a newline
        is broken at its last space, so a model that streams one huge
        paragraph still shows progress. Width is settled once per turn,
        since a console query per delta would cost a syscall per token
        and can corrupt a paste mid-drain. The cut reserves the RENDERED
        row's extra columns (a bullet's "  * " vs its "- " source, or a
        continuation's own indent), not the source text's own width, so a
        word is never stranded above its continuation.
    #>
    param(
        [AllowNull()][AllowEmptyString()][string]$Piece = '',
        [ValidateSet('Content', 'Reasoning')][string]$Kind = 'Content',
        [int]$Width = 0,
        [scriptblock]$Write = (Get-WtReplDefaultWriter)
    )
    if ($null -eq $script:WtReplStream) { Reset-WtReplStream }
    if (-not $Piece) { return }
    [void]$script:WtReplStream[$Kind].Append([string]$Piece)
    if ($Kind -eq 'Reasoning') { $script:WtReplStream.LastKind = 'Reasoning'; return }
    $script:WtReplStream.LastKind = 'Content'
    if ($Width -le 0) { $Width = [int]$script:WtReplStream.Width }
    if ($Width -le 0) { $Width = (Get-WtConsoleSize).Width; $script:WtReplStream.Width = $Width }
    [void]$script:WtReplStream.Buffer.Append([string]$Piece)

    $margin = Get-WtReplMargin
    $limit = Get-WtRichWrapWidth -Width (Get-WtReplTextWidth -Width $Width)
    while ($true) {
        $buf = $script:WtReplStream.Buffer.ToString()
        $nl = $buf.IndexOf([char]10)
        if ($nl -ge 0) {
            $line = $buf.Substring(0, $nl).TrimEnd([char]13)
            [void]$script:WtReplStream.Buffer.Remove(0, $nl + 1)
            Write-WtReplLineBuffered -Line $line -Width $Width -Write $Write
            continue
        }
        $rich = $script:WtReplStream.Rich
        $reserve = 0
        if ($rich.Continuation -and -not $rich.InFence) { $reserve = [int]$rich.ContinuationIndent }
        else { $reserve = $margin + [int](Get-WtRichBlockIndents -Block (Get-WtRichBlock -Line $buf -State $rich)).First }
        $cutLimit = [Math]::Max(10, $limit - $reserve)
        if ($buf.Length -le $cutLimit) { break }
        $cut = $buf.LastIndexOf([char]' ', $cutLimit - 1)
        if ($cut -le 0) { break }
        if (-not (Test-WtReplCutSafe -Text ($buf.Substring(0, $cut)))) { break }
        [void]$script:WtReplStream.Buffer.Remove(0, $cut + 1)
        Write-WtReplLineBuffered -Line ($buf.Substring(0, $cut)) -Width $Width -Write $Write
        $script:WtReplStream.Rich.Continuation = $true
    }
}

function Complete-WtReplStream {
    <#
    .SYNOPSIS
        End of turn (or of a stream broken by a tool call): flush what is
        left in the buffer and forget an unterminated fence, so the next
        answer does not start inside a code block.
    #>
    param([int]$Width = 0, [scriptblock]$Write = (Get-WtReplDefaultWriter))
    if ($null -eq $script:WtReplStream) { return }
    if ($Width -le 0) { $Width = [int]$script:WtReplStream.Width }
    if ($Width -le 0) { $Width = (Get-WtConsoleSize).Width }
    $rest = $script:WtReplStream.Buffer.ToString()
    [void]$script:WtReplStream.Buffer.Clear()
    if ($rest.Trim().Length -gt 0) { Write-WtReplLineBuffered -Line $rest -Width $Width -Write $Write }
    $script:WtReplStream.Rich = @{ InFence = $false }
    $script:WtReplStream.Open = $false
}

function Get-WtReplStreamText {
    param([ValidateSet('All', 'Content', 'Reasoning')][string]$Kind = 'All')
    if ($null -eq $script:WtReplStream) { return '' }
    switch ($Kind) {
        'Content' { return $script:WtReplStream.Content.ToString() }
        'Reasoning' { return $script:WtReplStream.Reasoning.ToString() }
    }
    $reasoning = $script:WtReplStream.Reasoning.ToString()
    $content = $script:WtReplStream.Content.ToString()
    if ($reasoning -and $content) { return ($reasoning + "`n" + $content) }
    return ($reasoning + $content)
}

function Get-WtReplEntryLines {
    <#
    .SYNOPSIS
        PURE: a transcript entry as printable segment rows. The user's
        own text sits behind "> " in cyan; the answer goes through the
        rich layer (markdown off the screen, wrapped at the window);
        a tool line carries its own indent and is printed as it was
        formatted, its name white up to the arguments; info and error
        lines are marked two columns in.
    #>
    param(
        [Parameter(Mandatory)][ValidateSet('User', 'Assistant', 'Tool', 'Error', 'Info')][string]$Kind,
        [AllowNull()][AllowEmptyString()][string]$Text = '',
        [int]$Width = 80,
        [PSCustomObject]$Glyphs = $script:WtGlyphs
    )
    $rows = New-Object System.Collections.Generic.List[object]
    $margin = Get-WtReplMargin
    $textWidth = Get-WtReplTextWidth -Width $Width
    switch ($Kind) {
        'Assistant' {
            foreach ($r in (Get-WtRichLines -Text ([string]$Text) -Width $textWidth -Indent $margin -Glyphs $Glyphs)) { $rows.Add($r) }
        }
        'User' {
            $colors = @{ Normal = 'Cyan'; Strong = 'Cyan'; Code = 'Cyan'; Link = 'Cyan'; Url = 'Cyan' }
            foreach ($line in (([string]$Text).Split([char]10))) {
                $parts = @(@{ Text = ([string]$line).TrimEnd([char]13); Style = 'Normal' })
                foreach ($r in (Split-WtWrappedSegments -Parts $parts -Width $textWidth -Indent $margin -Hanging 2 -Prefix '> ' -PrefixFg 'Cyan' -Colors $colors)) { $rows.Add($r) }
            }
        }
        'Tool' {
            $limit = Get-WtRichWrapWidth -Width $Width
            foreach ($line in (([string]$Text).Split([char]10))) {
                $t = ([string]$line).TrimEnd([char]13)
                if ($t.Length -gt $limit) { $t = $t.Substring(0, $limit - 1) + [string][char]0x2026 }
                $bullet = [string]$Glyphs.Bullet
                $isCall = $t.TrimStart().StartsWith($bullet, [System.StringComparison]::Ordinal)
                $cut = $(if ($isCall) { $t.IndexOf('(') } else { -1 })
                if ($cut -gt 0) {
                    $rows.Add(@((New-WtSeg -Text $t.Substring(0, $cut) -Fg 'White'), (New-WtSeg -Text $t.Substring($cut) -Fg 'DarkGray')))
                }
                elseif ($isCall) { $rows.Add(@(, (New-WtSeg -Text $t -Fg 'White'))) }
                else { $rows.Add(@(, (New-WtSeg -Text $t -Fg 'DarkGray'))) }
            }
        }
        default {
            $fg = $(if ($Kind -eq 'Error') { 'Red' } else { 'DarkYellow' })
            $mark = $(if ($Kind -eq 'Error') { '! ' } else { 'i ' })
            $colors = @{ Normal = $fg; Strong = $fg; Code = $fg; Link = $fg; Url = $fg }
            foreach ($line in (([string]$Text).Split([char]10))) {
                $parts = @(@{ Text = ([string]$line).TrimEnd([char]13); Style = 'Normal' })
                foreach ($r in (Split-WtWrappedSegments -Parts $parts -Width $textWidth -Indent $margin -Hanging $mark.Length -Prefix $mark -PrefixFg $fg -Colors $colors)) { $rows.Add($r) }
            }
        }
    }
    return , $rows.ToArray()
}

function Write-WtReplEntry {
    <#
    .SYNOPSIS
        Commits one transcript entry (User/Assistant/Tool/Info/Error),
        opening or continuing the shared tool box for consecutive Tool
        entries. The speaker GROUP decides whether a blank line goes in
        before it, not the raw Kind: two Tool entries (a call and its
        result) stay glued, but a Tool entry after the answer opens a
        new block.
    #>
    param(
        [Parameter(Mandatory)][string]$Kind,
        [AllowNull()][AllowEmptyString()][string]$Text = '',
        [int]$Width = 0,
        [scriptblock]$Write = (Get-WtReplDefaultWriter)
    )
    if ($Width -le 0) { $Width = (Get-WtConsoleSize).Width }
    $group = Get-WtReplEntryGroup -Kind $Kind
    $separate = ($group -ne $script:WtReplLastGroup)
    if ($Kind -eq 'Tool') {
        $rows = New-Object System.Collections.Generic.List[object]
        if (-not $script:WtReplToolBoxOpen) { $rows.Add((Get-WtReplToolBoxRow -Part 'Top' -Width $Width)) }
        foreach ($line in (Get-WtReplEntryLines -Kind 'Tool' -Text $Text -Width ($Width - 4))) { $rows.Add((Get-WtReplToolBoxRow -Part 'Row' -Segments @($line) -Width $Width)) }
        Write-WtReplBlock -Rows $rows.ToArray() -Separate:$separate -Width $Width -Write $Write -ToolBox
        $script:WtReplToolBoxOpen = $true
        $script:WtReplToolBoxWidth = [int]$Width
        $script:WtReplLastGroup = $group
        return
    }
    Write-WtReplBlock -Rows (Get-WtReplEntryLines -Kind $Kind -Text $Text -Width $Width) -Separate:$separate -Width $Width -Write $Write
    $script:WtReplLastGroup = $group
}

function Get-WtReplSuggestionLines {
    <#
    .SYNOPSIS
        PURE: the suggestion block as plain lines. -Suggestions can be a
        hashtable (Chat.Suggestions) or a PSCustomObject (unit tests), so
        membership is checked both ways rather than by dot-notation alone.
    #>
    param([AllowEmptyCollection()][array]$Suggestions = @())
    $rows = @($Suggestions)
    if ($rows.Count -eq 0) { return [string[]]@() }
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add('  ' + [string](Get-Translation 'AsSuggestionsHeading'))
    $n = 0
    foreach ($s in $rows) {
        $n++
        if ($n -gt 1) { $lines.Add('') }
        $line = '  [' + $n + '] ' + [string]$s.Label
        if ($s.Risk) { $line += '  [' + [string](Get-Translation ('Risk' + [string]$s.Risk)) + ']' }
        if ($s.Path) { $line += ' - ' + [string]$s.Path }
        $lines.Add($line)
        $hasWhat = $(if ($s -is [System.Collections.IDictionary]) { $s.ContainsKey('What') } else { $s.PSObject.Properties.Name -contains 'What' })
        if ($hasWhat -and [string]$s.What) { $lines.Add('      ' + [string]$s.What) }
    }
    return [string[]]$lines.ToArray()
}

function Write-WtReplSuggestions {
    param([AllowEmptyCollection()][array]$Suggestions = @(), [int]$Width = 0, [scriptblock]$Write = (Get-WtReplDefaultWriter))
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($line in @(Get-WtReplSuggestionLines -Suggestions $Suggestions)) { $rows.Add(@(, (New-WtSeg -Text ([string]$line) -Fg 'Yellow'))) }
    if ($rows.Count -eq 0) { return }
    Write-WtReplBlock -Rows $rows.ToArray() -Separate -Width $Width -Write $Write
    $script:WtReplLastGroup = 'System'
}

function Get-WtReplTranscriptTail {
    <#
    .SYNOPSIS
        What is reprinted when the REPL is re-entered from the menu: the
        last Count printed lines of the transcript, then the current
        suggestions. The console buffer is never the record - the session
        is - so this rebuilds the view from it. Get-WtReplEntryLines is
        called in plain parentheses, not wrapped in @(): its own
        "return ,$rows.ToArray()" already hands back one array as a single
        output object, and @() around that would nest it one level deeper.
    #>
    param([Parameter(Mandatory)][hashtable]$Session, [int]$Count = 400, [int]$Width = 80)
    $all = New-Object System.Collections.Generic.List[object]
    $previous = ''
    $boxOpen = $false
    foreach ($entry in @($Session.Entries.ToArray())) {
        $kind = [string]$entry.Kind
        $group = Get-WtReplEntryGroup -Kind $kind
        $lines = (Get-WtReplEntryLines -Kind $kind -Text ([string]$entry.Text) -Width $(if ($kind -eq 'Tool') { $Width - 4 } else { $Width }))
        if (@($lines).Count -eq 0) { continue }
        if ($kind -ne 'Tool' -and $boxOpen) { $all.Add((Get-WtReplToolBoxRow -Part 'Bottom' -Width $Width)); $boxOpen = $false }
        if ($previous -and $group -ne $previous) { $all.Add(@(, (New-WtSeg -Text '' -Fg 'Gray'))) }
        if ($kind -eq 'Tool') {
            if (-not $boxOpen) { $all.Add((Get-WtReplToolBoxRow -Part 'Top' -Width $Width)); $boxOpen = $true }
            foreach ($row in $lines) { $all.Add((Get-WtReplToolBoxRow -Part 'Row' -Segments @($row) -Width $Width)) }
        }
        else { foreach ($row in $lines) { $all.Add($row) } }
        $previous = $group
    }
    if ($boxOpen) { $all.Add((Get-WtReplToolBoxRow -Part 'Bottom' -Width $Width)) }
    $rows = $all.ToArray()
    if ($rows.Count -gt $Count) { $rows = @($rows[($rows.Count - $Count)..($rows.Count - 1)]) }
    $tail = New-Object System.Collections.Generic.List[object]
    foreach ($r in $rows) { $tail.Add($r) }
    $suggestions = @(Get-WtReplSuggestionLines -Suggestions @($Session.Suggestions))
    if ($suggestions.Count -gt 0 -and $tail.Count -gt 0) { $tail.Add(@(, (New-WtSeg -Text '' -Fg 'Gray'))) }
    foreach ($s in $suggestions) {
        $tail.Add(@(, (New-WtSeg -Text ([string]$s) -Fg 'Yellow')))
    }
    return , $tail.ToArray()
}

function Write-WtReplTranscriptTail {
    <#
    .SYNOPSIS
        Commits the transcript tail (and current suggestions) to the
        screen. Resets the tool-box-open and last-speaker-group flags
        first, since a box or a group left over from the page this
        replaces does not describe what is on screen now.
    #>
    param([Parameter(Mandatory)][hashtable]$Session, [int]$Count = 400, [int]$Width = 0, [scriptblock]$Write = (Get-WtReplDefaultWriter))
    if ($Width -le 0) { $Width = (Get-WtConsoleSize).Width }
    $script:WtReplToolBoxOpen = $false
    Write-WtReplBlock -Rows (Get-WtReplTranscriptTail -Session $Session -Count $Count -Width $Width) -Separate -Width $Width -Write $Write
    $script:WtReplLastGroup = ''
}

function Read-WtReplLine {
    <#
    .SYNOPSIS
        The REPL's line reader, returning
        @{ Kind = 'Submit'|'Cancel'|'CtrlC'|'Eof'|'Resize'; Text }.
        Key mode runs a ReadKey loop over the pure editor and paints the
        box, slash popup and caret through Show-WtReplLive; keys already
        queued behind one another are a paste burst, applied as one edit.
        Line mode (ISE, redirected stdin) falls back to Read-Host with no
        editing. Two traps hold it together: the console size is queried
        only between keys, since querying it while a paste drains corrupts
        the input (dotnet/runtime #88343), and the wait-for-a-key
        scriptblock is bound to $awaitKey rather than $waitKey, which
        would shadow the -WaitKey parameter and recurse until the stack
        overflowed.
    #>
    param(
        [string]$Prompt = '> ',
        [AllowEmptyCollection()][string[]]$History = @(),
        [switch]$Secret,
        [AllowEmptyString()][string]$Placeholder = '',
        [AllowEmptyCollection()][array]$StatusRows = @(),
        [scriptblock]$GetClipboard = { try { [string](Get-Clipboard -Raw -ErrorAction Stop) } catch { '' } },
        [scriptblock]$ReadKey = { [Console]::ReadKey($true) },
        [scriptblock]$KeyAvailable = { [Console]::KeyAvailable },
        [scriptblock]$Write = (Get-WtReplRawWriter),
        [int]$Width = 0,
        [AllowEmptyCollection()][string[]]$QuestionLines = @(),
        [AllowEmptyString()][string]$QuestionTitle = '',
        [AllowEmptyString()][string]$QuestionRisk = '',
        [switch]$EchoAsUser,
        [switch]$AllowResize,
        [AllowNull()][AllowEmptyString()][string]$InitialText = '',
        [scriptblock]$WaitKey = $null
    )
    if ($script:WtInputMode -ne 'Key') {
        $line = $null
        if ($Secret) {
            $secure = Read-Host -AsSecureString $Prompt
            if ($null -ne $secure) { $line = ([System.Net.NetworkCredential]::new('', $secure)).Password }
        }
        else { $line = Read-Host $Prompt }
        if ($null -eq $line) { return @{ Kind = 'Eof'; Text = '' } }
        return @{ Kind = 'Submit'; Text = [string]$line }
    }
    $widthFixed = ($Width -gt 0)
    $size = Get-WtConsoleSize
    if (-not $widthFixed) { $Width = [int]$size.Width }
    $boxHeight = [int]$size.Height
    $live = [bool]$script:WtReplLiveEnabled
    $askEntry = (@($QuestionLines).Count -gt 0)
    if ($AllowResize -and -not $widthFixed -and -not $askEntry -and [int]$script:WtReplPageWidth -gt 0 -and $Width -ne [int]$script:WtReplPageWidth) {
        if ($live) { Hide-WtReplLive -Write $Write }
        return @{ Kind = 'Resize'; Text = '' }
    }
    $state = New-WtReplLineState -History $History
    if ($InitialText) { $state.Text = [string]$InitialText; $state.Cursor = ([string]$InitialText).Length }
    $shownText = { if ($Secret) { ('*' * ([string]$state.Text).Length) } else { [string]$state.Text } }
    $awaitKey = {
        if ($null -ne $WaitKey) { return [string](& $WaitKey) }
        if ($widthFixed -or -not $script:WtReplResizePoll -or -not $script:WtReplMode) { return 'Key' }
        while ($true) {
            $ready = $false
            try { $ready = [bool](& $KeyAvailable) } catch { return 'Key' }
            if ($ready) { return 'Key' }
            $polled = Get-WtConsoleSize
            if ([int]$polled.Width -ne $Width -or [int]$polled.Height -ne $boxHeight) { return 'Resize' }
            Start-Sleep -Milliseconds 50
        }
    }
    $paint = {
        $shown = & $shownText
        if ($live) {
            $box = Get-WtReplInputLines -Prompt $Prompt -Text $shown -Cursor ([int]$state.Cursor) -Width $Width -Placeholder $Placeholder
            $below = @()
            if (@($state.Popup).Count -gt 0) { $below = @(Get-WtReplPopupRows -Popup @($state.Popup) -Index ([int]$state.PopupIndex) -Width $Width) }
            else { $below = @($StatusRows) }
            $above = @()
            if (@($QuestionLines).Count -gt 0) {
                $fg = switch ($QuestionRisk) { 'ADVANCED' { 'Red' } 'CAUTION' { 'Yellow' } default { 'Cyan' } }
                $qRows = @(Get-WtReplQuestionRows -Lines $QuestionLines -Width $Width -Fg $fg)
                $above = @(Get-WtReplBoxRows -Title $QuestionTitle -Rows $qRows -Width $Width -Fg $fg)
            }
            $rows = @($above) + @($box.Rows) + @($below)
            Show-WtReplLive -Rows $rows -CaretRow ([int]$box.CaretRow + @($above).Count) -CaretCol ([int]$box.CaretCol) -Width $Width -Height $boxHeight -Write $Write
        }
        else {
            $render = Get-WtReplLineRender -Prompt $Prompt -Text $shown -Cursor ([int]$state.Cursor) -Width $Width
            & $Write ("`r" + $script:WtEsc + '[2K' + [string]$render.Line + "`r" + $script:WtEsc + '[' + ([int]$render.CursorCol + 1) + 'G')
        }
    }
    $finish = { param([string]$Kind)
        if ($live) {
            Hide-WtReplLive -Write $Write
            if ($Kind -eq 'Submit') {
                $shown = [string](& $shownText)
                if ($EchoAsUser) { if ($shown.Trim().Length -gt 0) { Write-WtReplEntry -Kind 'User' -Text $shown -Width $Width } }
                else { Write-WtReplLine -Text ($Prompt + $shown) -Fg 'Cyan' }
            }
        }
        else { & $Write "`n" }
        return @{ Kind = $Kind; Text = [string]$state.Text }
    }
    & $paint
    while ($true) {
        $null = Assert-WtTuiCtrlCInput
        $null = Assert-WtWindowMaximized
        if ((& $awaitKey) -eq 'Resize') {
            $size = Get-WtConsoleSize
            $Width = [int]$size.Width
            $boxHeight = [int]$size.Height
            if ($AllowResize -and @($QuestionLines).Count -eq 0) { return (& $finish 'Resize') }
            Sync-WtReplResize -Force -Write $Write | Out-Null
            & $paint
            continue
        }
        $key = $null
        try { $key = & $ReadKey } catch { $null = Write-WtErrorLog -ErrorRecord $_ -Context 'Read-WtReplLine: ReadKey failed'; $key = $null }
        if ($null -eq $key) { return (& $finish 'Eof') }
        $emit = 'None'
        while ($true) {
            $burst = $false
            try { $burst = [bool](& $KeyAvailable) } catch { $burst = $false }
            $token = ConvertTo-WtReplKeyToken -Key ([string]$key.Key) -KeyChar ([string]$key.KeyChar) -Modifiers ([string]$key.Modifiers) -Burst $burst
            if ($token.Ctrl -and [string]$token.Key -eq 'V') {
                $clip = ''
                try { $clip = [string](& $GetClipboard) } catch { $clip = '' }
                $token = @{ Key = 'Paste'; Text = $clip; Char = ''; Ctrl = $false; Burst = $burst }
            }
            $r = Update-WtReplLine -State $state -Token $token
            $state = $r.State
            $emit = [string]$r.Emit
            if (-not $live -and $emit -eq 'None') { & $paint }
            if ($emit -ne 'None' -and $emit -ne 'Clear') { break }
            if (-not $burst) { break }
            $key = $null
            try { $key = & $ReadKey } catch { $key = $null }
            if ($null -eq $key) { break }
        }
        switch ($emit) {
            'Submit' { return (& $finish 'Submit') }
            'Cancel' { return (& $finish 'Cancel') }
            'CtrlC' { return (& $finish 'CtrlC') }
        }
        if (-not $burst -and -not $widthFixed) {
            $size = Get-WtConsoleSize
            $wasWidth = $Width
            $Width = [int]$size.Width
            $boxHeight = [int]$size.Height
            $askingSomething = (@($QuestionLines).Count -gt 0)
            $pageWidth = [int]$script:WtReplPageWidth
            $stale = ($Width -ne $wasWidth) -or ($pageWidth -gt 0 -and $Width -ne $pageWidth)
            if ($AllowResize -and -not $askingSomething -and $stale) { return (& $finish 'Resize') }
            if ($askingSomething -and $Width -ne $wasWidth) { Sync-WtReplResize -Force -Write $Write | Out-Null }
        }
        & $paint
    }
}

function Read-WtReplPick {
    <#
    .SYNOPSIS
        The one selector every REPL choice uses: arrows + Enter, digits,
        hotkey letters, Esc. Live mode paints the box in the live region;
        plain mode prints a numbered list and reads a number (or free
        text when a text option exists) through -ReadLine. The text
        option hands over to the line reader. A question taller than the
        window is committed to the scrollable transcript first, wrapped,
        since the live region would otherwise cut it from the TOP - the
        part that says where the data goes. Returns
        @{ Index = 1..N (0 = cancelled or free text); Text = label / typed text }.
    #>
    param(
        [AllowEmptyString()][string]$Title = '',
        [AllowEmptyCollection()][string[]]$Lines = @(),
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Options,
        [AllowEmptyString()][string]$TextOption = '',
        [AllowEmptyString()][string]$Risk = '',
        [scriptblock]$ReadKey = { [Console]::ReadKey($true) },
        [scriptblock]$ReadLine = { param($P) Read-WtReplLine -Prompt $P },
        [scriptblock]$Write = (Get-WtReplRawWriter),
        [int]$Width = 0
    )
    $state = New-WtReplPickState -Options $Options -TextOption $TextOption
    $rows = @($state.Rows)
    if (-not $script:WtReplLiveEnabled) {
        $fg = switch ($Risk) { 'ADVANCED' { 'Red' } 'CAUTION' { 'Yellow' } default { 'White' } }
        if ($Title) { Write-WtReplLine -Text $Title -Fg 'White' }
        foreach ($l in @($Lines)) { Write-WtReplLine -Text ([string]$l) -Fg $fg }
        $listed = @($rows | Where-Object { -not $_.IsText })
        for ($i = 0; $i -lt $listed.Count; $i++) { Write-WtReplLine -Text ('  ' + ($i + 1) + ') ' + [string]$listed[$i].Label) }
        $r = & $ReadLine ([string](Get-Translation 'AsPickPrompt') + ': ')
        if ([string]$r.Kind -ne 'Submit') { return @{ Index = 0; Text = '' } }
        $text = ([string]$r.Text).Trim()
        $index = 0
        if ([int]::TryParse($text, [ref]$index) -and $index -ge 1 -and $index -le $listed.Count) { return @{ Index = $index; Text = [string]$listed[$index - 1].Label } }
        if ($TextOption -and $text) { return @{ Index = 0; Text = $text } }
        return @{ Index = 0; Text = '' }
    }
    $pickSize = Get-WtConsoleSize
    if ($Width -le 0) { $Width = [int]$pickSize.Width }
    $pickHeight = [int]$pickSize.Height
    $probe = @(Get-WtReplPickLines -Title $Title -Lines $Lines -State $state -Width $Width -Glyphs $script:WtGlyphs -Risk $Risk)
    if (@($Lines).Count -gt 0 -and $probe.Count -gt [Math]::Max(1, $pickHeight - 1)) {
        $textFg = switch ($Risk) { 'ADVANCED' { 'Red' } 'CAUTION' { 'Yellow' } default { 'White' } }
        Hide-WtReplLive -Write $Write
        Write-WtReplBlock -Rows @(Get-WtReplQuestionRows -Lines $Lines -Width $Width -Fg $textFg) -Separate -Width $Width
        $Lines = @()
    }
    while ($true) {
        Show-WtReplLive -Rows @(Get-WtReplPickLines -Title $Title -Lines $Lines -State $state -Width $Width -Risk $Risk) -CaretRow -1 -Width $Width -Height $pickHeight -Write $Write
        $null = Assert-WtTuiCtrlCInput
        $null = Assert-WtWindowMaximized
        $key = $null
        try { $key = & $ReadKey } catch { $key = $null }
        if ($null -eq $key) { Hide-WtReplLive -Write $Write; return @{ Index = 0; Text = '' } }
        $token = ConvertTo-WtReplKeyToken -Key ([string]$key.Key) -KeyChar ([string]$key.KeyChar) -Modifiers ([string]$key.Modifiers) -Burst $false
        $r = Update-WtReplPickState -State $state -Token $token
        $state = $r.State
        if ([string]$r.Emit -eq 'Cancel') { Hide-WtReplLive -Write $Write; return @{ Index = 0; Text = '' } }
        if ([string]$r.Emit -eq 'Pick') {
            Hide-WtReplLive -Write $Write
            $picked = $rows[[int]$state.Index]
            if ($picked.IsText) {
                $line = & $ReadLine ([string]$picked.Label + ': ')
                if ([string]$line.Kind -ne 'Submit') { return @{ Index = 0; Text = '' } }
                return @{ Index = 0; Text = ([string]$line.Text).Trim() }
            }
            return @{ Index = ([int]$state.Index + 1); Text = [string]$picked.Label }
        }
    }
}

function Read-WtReplAnswer {
    <#
    .SYNOPSIS
        The REPL's stand-in for Read-WtPanelAnswer. With -Choices (the
        privacy gate) it is a selector and hands back the chosen LETTER,
        so every existing letter parser keeps working; without, the
        lines are printed (risk-coloured) and a line of text is read.
        $null = cancelled, which every gate treats as no.
    #>
    param(
        [AllowEmptyCollection()][string[]]$Lines = @(),
        [Parameter(Mandatory)][AllowEmptyString()][string]$Prompt,
        [AllowEmptyString()][string]$Risk = '',
        [AllowNull()][array]$Choices = $null,
        [scriptblock]$ReadLine = { param($P, $QLines, $QTitle, $QRisk) Read-WtReplLine -Prompt $P -QuestionLines ([string[]]@($QLines)) -QuestionTitle ([string]$QTitle) -QuestionRisk ([string]$QRisk) },
        [scriptblock]$ReadPick = { param($T, $L, $O, $R) Read-WtReplPick -Title $T -Lines $L -Options $O -Risk $R },
        [scriptblock]$Write = (Get-WtReplDefaultWriter)
    )
    $fg = switch ($Risk) { 'ADVANCED' { 'Red' } 'CAUTION' { 'Yellow' } default { 'White' } }
    if ($null -ne $Choices -and @($Choices).Count -gt 0 -and $script:WtReplLiveEnabled) {
        $options = @(foreach ($c in @($Choices)) { @{ Label = [string]$c.Label; Hotkey = [string]$c.Letter } })
        $title = [string]$Prompt
        $yesNo = ' ' + [string](Format-WtYesNoHint)
        if ($title.EndsWith($yesNo, [System.StringComparison]::Ordinal)) { $title = $title.Substring(0, $title.Length - $yesNo.Length) }
        $r = & $ReadPick $title ([string[]]@($Lines)) $options $Risk
        if ([int]$r.Index -lt 1) { return $null }
        return [string]@($Choices)[[int]$r.Index - 1].Letter
    }
    if (-not $script:WtReplLiveEnabled) {
        foreach ($line in @($Lines)) { & $Write ([string]$line) $fg $false }
        & $Write $Prompt $fg $false
        $r = & $ReadLine ([string](Get-Translation 'AsReplAnswerPrompt')) ([string[]]@()) '' ''
        if ([string]$r.Kind -ne 'Submit') { return $null }
        return [string]$r.Text
    }
    $r = & $ReadLine ([string](Get-Translation 'AsReplAnswerPrompt')) ([string[]]@($Lines)) $Prompt $Risk
    if ([string]$r.Kind -ne 'Submit') { return $null }
    return [string]$r.Text
}

function Test-WtReplCancelRequested {
    <#
    .SYNOPSIS
        The ShouldCancel poll while the model generates: drain whatever
        keys are queued; Esc or Ctrl+C (Char 3 with TreatControlCAsInput)
        means stop. Other keys are discarded - typing during a stream
        must not land in the next prompt.
    #>
    param(
        [scriptblock]$KeyAvailable = { $script:WtInputMode -eq 'Key' -and [Console]::KeyAvailable },
        [scriptblock]$ReadKey = { [Console]::ReadKey($true) }
    )
    $cancel = $false
    $guard = 0
    $null = Assert-WtTuiCtrlCInput
    $null = Assert-WtWindowMaximized
    while ($guard -lt 64) {
        $available = $false
        try { $available = [bool](& $KeyAvailable) } catch { $available = $false }
        if (-not $available) { break }
        $guard++
        $key = $null
        try { $key = & $ReadKey } catch { $key = $null }
        if ($null -eq $key) { break }
        if ([string]$key.Key -eq 'Escape') { $cancel = $true }
        if ([string]$key.KeyChar -eq ([string][char]3)) { $cancel = $true }
        if ([string]$key.Key -eq 'C' -and (([string]$key.Modifiers).IndexOf('Control', [System.StringComparison]::OrdinalIgnoreCase) -ge 0)) { $cancel = $true }
    }
    return $cancel
}

function Set-WtReplTitle {
    param([AllowEmptyString()][string]$Text)
    try { $Host.UI.RawUI.WindowTitle = [string]$Text } catch { $null = $_ }
}
#endregion src/20-tui/repl-console.ps1

#region src/20-tui/repl-state.ps1
# The pure side of the assistant's plain-console REPL: formatters, the
# line-editor reducer, the key-to-token map, the command classifier and
# the slash-command table. Nothing here touches the console.
# Covered by: tests/ReplState.Tests.ps1

function Format-WtReplNumber {
    <#
    .SYNOPSIS
        One decimal, invariant digits, a comma as the decimal mark (e.g.
        "0,4 s"): never the thread culture, which would flip the mark
        with the user's locale.
    #>
    param([double]$Value)
    return ([Math]::Round($Value, 1)).ToString('0.0', [System.Globalization.CultureInfo]::InvariantCulture).Replace('.', ',')
}

function Format-WtReplTokenCount {
    <#
    .SYNOPSIS
        PURE: a token count with a dot as the thousands mark (e.g.
        "4.312"), invariant digits - never the thread culture.
    #>
    param([int]$Value)
    return $Value.ToString('#,0', [System.Globalization.CultureInfo]::InvariantCulture).Replace(',', '.')
}

function Format-WtReplUsageLine {
    <#
    .SYNOPSIS
        PURE: the /durum line for the last turn's token usage: input /
        output, plus the cached count only when the server reported one;
        a missing or empty usage says so instead of printing zeros.
    #>
    param([AllowNull()]$Usage)
    if ($null -eq $Usage -or [int]$Usage.Rounds -le 0) { return [string](Get-Translation 'AsStatusUsageNone') }
    $cache = ''
    if ([int]$Usage.CachedTokens -gt 0) { $cache = [string]((Get-Translation 'AsStatusUsageCache') -f (Format-WtReplTokenCount -Value ([int]$Usage.CachedTokens))) }
    return [string]((Get-Translation 'AsStatusUsage') -f (Format-WtReplTokenCount -Value ([int]$Usage.PromptTokens)), (Format-WtReplTokenCount -Value ([int]$Usage.CompletionTokens)), $cache)
}

function ConvertTo-WtReplArgText {
    <#
    .SYNOPSIS
        PURE, recursive: one parsed JSON value as compact prose for the
        tool start line. Objects become "key: value" pairs (nested
        objects collapse to {...}), arrays "[a, b, +N]", strings bare,
        booleans lower-case. Depth 0 is the argument object itself.
    #>
    param($Value, [int]$Depth = 0, [int]$MaxItems = 3)
    if ($null -eq $Value) { return 'null' }
    if ($Value -is [bool]) { return $Value.ToString().ToLowerInvariant() }
    if ($Value -is [string]) { return $Value }
    if ($Value -is [System.Collections.IDictionary] -or $Value -is [PSCustomObject]) {
        if ($Depth -ge 1) { return '{...}' }
        $pairs = New-Object System.Collections.Generic.List[string]
        if ($Value -is [System.Collections.IDictionary]) {
            foreach ($k in $Value.Keys) { $pairs.Add([string]$k + ': ' + (ConvertTo-WtReplArgText -Value $Value[$k] -Depth ($Depth + 1) -MaxItems $MaxItems)) }
        }
        else {
            foreach ($p in $Value.PSObject.Properties) { $pairs.Add([string]$p.Name + ': ' + (ConvertTo-WtReplArgText -Value $p.Value -Depth ($Depth + 1) -MaxItems $MaxItems)) }
        }
        return ($pairs.ToArray() -join ', ')
    }
    if ($Value -is [System.Collections.IEnumerable]) {
        $items = @($Value)
        $shown = New-Object System.Collections.Generic.List[string]
        for ($i = 0; $i -lt [Math]::Min($items.Count, $MaxItems); $i++) { $shown.Add((ConvertTo-WtReplArgText -Value $items[$i] -Depth ($Depth + 1) -MaxItems $MaxItems)) }
        if ($items.Count -gt $MaxItems) { $shown.Add('+' + ($items.Count - $MaxItems)) }
        return ('[' + ($shown.ToArray() -join ', ') + ']')
    }
    return [string]$Value
}

function Format-WtReplToolArgs {
    param([AllowNull()][AllowEmptyString()][string]$ArgumentsJson = '')
    $text = ([string]$ArgumentsJson).Trim()
    if (-not $text -or $text -eq '{}') { return '' }
    $parsed = $null
    try { $parsed = $text | ConvertFrom-Json } catch { return $text }
    return [string](ConvertTo-WtReplArgText -Value $parsed -Depth 0)
}

function Format-WtReplToolStart {
    <#
    .SYNOPSIS
        The line a tool call opens with: "  * name(args)". One line, no
        newlines, clamped to Width-1 with a '~' tail (the frames' cut
        mark) so the console never wraps it.
    #>
    param(
        [Parameter(Mandatory)][string]$Name,
        [AllowNull()][AllowEmptyString()][string]$ArgumentsJson = '',
        [int]$Width = 0,
        [PSCustomObject]$Glyphs = $script:WtGlyphs
    )
    $text = '  ' + [string]$Glyphs.Bullet + ' ' + $Name + '(' + (Format-WtReplToolArgs -ArgumentsJson $ArgumentsJson) + ')'
    $text = $text.Replace("`r", ' ').Replace("`n", ' ')
    if ($Width -gt 2 -and $text.Length -gt ($Width - 1)) { $text = $text.Substring(0, $Width - 2) + '~' }
    return $text
}

function Format-WtReplToolResult {
    <#
    .SYNOPSIS
        The branch line under a tool call: "    \ 0,4 s - 1,8 KB"; a
        failed call carries a "! " mark after the branch.
    #>
    param([double]$Seconds = 0, [int]$Chars = 0, [bool]$Ok = $true, [PSCustomObject]$Glyphs = $script:WtGlyphs)
    $mark = $(if ($Ok) { '' } else { '! ' })
    return ('    ' + [string]$Glyphs.Branch + ' ' + $mark + (Format-WtReplNumber -Value $Seconds) + ' s ' + [string]$Glyphs.Dot + ' ' + (Format-WtReplNumber -Value ([double]$Chars / 1024)) + ' KB')
}

function Format-WtReplToolLines {
    <#
    .SYNOPSIS
        A header under the branch mark, then the last Max output lines
        indented under it, and a "(+N lines ...)" note when more were
        cut. Max 0 (or less) means every line, no note.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Header,
        [AllowEmptyCollection()][string[]]$Lines = @(),
        [int]$Max = 5,
        [PSCustomObject]$Glyphs = $script:WtGlyphs
    )
    $out = New-Object System.Collections.Generic.List[string]
    $out.Add('    ' + [string]$Glyphs.Branch + ' ' + $Header)
    $rows = @($Lines)
    $start = $(if ($Max -le 0) { 0 } else { [Math]::Max(0, $rows.Count - $Max) })
    for ($i = $start; $i -lt $rows.Count; $i++) { $out.Add('      ' + [string]$rows[$i]) }
    if ($start -gt 0) { $out.Add('      ' + ((Get-Translation 'AsReplMoreLines') -f $start)) }
    return [string[]]$out.ToArray()
}

function Format-WtReplToolRunLines {
    <#
    .SYNOPSIS
        PURE: a tool row the USER ran by number, shaped like a tool call
        the model made: "  * <label>" on the bullet line (the row's own
        name, no arguments), the outcome under the branch, then the tail
        of the output through Format-WtReplToolLines' rules.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Label,
        [Parameter(Mandatory)][AllowEmptyString()][string]$Status,
        [AllowEmptyCollection()][string[]]$Lines = @(),
        [int]$Max = 5,
        [PSCustomObject]$Glyphs = $script:WtGlyphs
    )
    $out = New-Object System.Collections.Generic.List[string]
    $out.Add('  ' + [string]$Glyphs.Bullet + ' ' + ([string]$Label).Replace("`r", ' ').Replace("`n", ' '))
    foreach ($l in @(Format-WtReplToolLines -Header $Status -Lines $Lines -Max $Max -Glyphs $Glyphs)) { $out.Add([string]$l) }
    return [string[]]$out.ToArray()
}

function Format-WtReplSpinnerLine {
    <#
    .SYNOPSIS
        PURE: the "working" status row - label, whole seconds, streamed
        size, the Esc hint. No animated glyph: braille frames render at
        another width on some console fonts and bend the box edge, and a
        once-a-second row lets the painter leave the screen alone.
    #>
    param(
        [AllowEmptyString()][string]$Label = '',
        [double]$Seconds = 0,
        [int]$Chars = 0,
        [PSCustomObject]$Glyphs = $script:WtGlyphs
    )
    $dot = ' ' + [string]$Glyphs.Dot + ' '
    $parts = @(([string][int][Math]::Floor($Seconds)) + ' s')
    if ($Chars -gt 0) { $parts += @((Format-WtReplNumber -Value ([double]$Chars / 1024)) + ' KB') }
    $parts += @([string](Get-Translation 'AsSpinTail'))
    return ($Label + ' (' + ($parts -join $dot) + ')')
}

function Get-WtReplStatusLeft {
    <#
    .SYNOPSIS
        PURE: the left half of the status line under the input box - the
        model, where it runs, how full the context is and what the
        assistant remembers. Parts fall off from the END as the window
        narrows; the model name never falls off.
    #>
    param(
        [AllowEmptyString()][string]$Model = '',
        [AllowEmptyString()][string]$WhereTag = '',
        [int]$Percent = 0,
        [int]$MessageCount = -1,
        [int]$NoteCount = -1,
        [int]$PermCount = -1,
        [int]$Width = 80,
        [int]$Reserve = 0,
        [PSCustomObject]$Glyphs = $script:WtGlyphs
    )
    $name = $(if ($Model) { $Model } else { [string](Get-Translation 'AsNotSet') })
    $parts = New-Object System.Collections.Generic.List[string]
    $parts.Add($name)
    if ($WhereTag) { $parts.Add([string]$WhereTag) }
    $parts.Add(((Get-Translation 'AsStatusContextShort') -f $Percent))
    if ($MessageCount -ge 0) { $parts.Add(((Get-Translation 'AsStatusMessagesShort') -f $MessageCount)) }
    if ($NoteCount -gt 0) { $parts.Add(((Get-Translation 'AsStatusNotesShort') -f $NoteCount)) }
    if ($PermCount -gt 0) { $parts.Add(((Get-Translation 'AsStatusPermsShort') -f $PermCount)) }

    $sep = ' ' + [string]$Glyphs.Dot + ' '
    $budget = [Math]::Max(8, $Width - 5 - $Reserve)
    while ($parts.Count -gt 1) {
        if ((($parts.ToArray()) -join $sep).Length -le $budget) { break }
        $parts.RemoveAt($parts.Count - 1)
    }
    return (($parts.ToArray()) -join $sep)
}

function Get-WtReplStatusRight {
    param([PSCustomObject]$Glyphs = $script:WtGlyphs)
    return (@((Get-Translation 'AsStatusHintEnter'), (Get-Translation 'AsStatusHintEsc'), (Get-Translation 'AsStatusHintHelp')) -join (' ' + [string]$Glyphs.Dot + ' '))
}

function Format-WtReplStatusLine {
    <#
    .SYNOPSIS
        PURE: the one-line status under the input box, two spaces in,
        left text then the right-hand hints right-aligned - dropped
        whole when they do not fit. Exactly Width-1 wide at most.
    #>
    param(
        [AllowEmptyString()][string]$Left = '',
        [AllowEmptyString()][string]$Right = '',
        [int]$Width = 80
    )
    $w = [Math]::Max(20, $Width - 1)
    $line = '  ' + $Left
    if ($Right -and ($line.Length + 2 + $Right.Length) -le $w) { $line = $line + (' ' * ($w - $line.Length - $Right.Length)) + $Right }
    if ($line.Length -gt $w) { $line = $line.Substring(0, $w) }
    return $line
}

function Get-WtReplContextPercent {
    <#
    .SYNOPSIS
        How full the model context is, as the trimming cap sees it:
        message chars over MaxChars, clamped to 0..100.
    #>
    param(
        [AllowEmptyCollection()][array]$Messages = @(),
        [int]$MaxChars = 60000
    )
    if ($MaxChars -le 0) { return 0 }
    $total = 0
    foreach ($message in @($Messages)) { $total += Get-WtAssistantMessageChars -Message $message }
    return [int][Math]::Min(100, [Math]::Round(100.0 * $total / $MaxChars))
}

function ConvertTo-WtReplKeyToken {
    <#
    .SYNOPSIS
        One ConsoleKeyInfo (passed as strings so tests need no console)
        into the REPL editor's token: navigation keys by ConsoleKey name,
        printable characters as Key='Char', Ctrl+letter as the letter
        with Ctrl set. Burst marks a key that arrived with more keys
        already queued (a paste).
    #>
    param(
        [Parameter(Mandatory)][string]$Key,
        [AllowNull()][AllowEmptyString()][string]$KeyChar = '',
        [AllowNull()][AllowEmptyString()][string]$Modifiers = '',
        [bool]$Burst = $false
    )
    $ctrl = (([string]$Modifiers).IndexOf('Control', [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
    $named = @('Enter', 'Escape', 'Backspace', 'Delete', 'LeftArrow', 'RightArrow', 'Home', 'End', 'UpArrow', 'DownArrow', 'Tab', 'PageUp', 'PageDown')
    if ($named -contains $Key) { return @{ Key = $Key; Char = ''; Ctrl = $ctrl; Burst = $Burst } }
    if ($ctrl) { return @{ Key = $Key; Char = ''; Ctrl = $true; Burst = $Burst } }
    $text = [string]$KeyChar
    if ($text.Length -eq 1 -and -not [char]::IsControl($text[0])) { return @{ Key = 'Char'; Char = $text; Ctrl = $false; Burst = $Burst } }
    return @{ Key = 'None'; Char = ''; Ctrl = $ctrl; Burst = $Burst }
}

function New-WtReplLineState {
    param([AllowEmptyCollection()][string[]]$History = @())
    return @{ Text = ''; Cursor = 0; History = [string[]]@($History); HistIdx = -1; Draft = ''; Popup = @(); PopupIndex = 0 }
}

function Update-WtReplLine {
    <#
    .SYNOPSIS
        The line editor. Pure: returns a copy. Enter submits (a newline
        inside a paste burst instead), Esc clears then cancels, Ctrl+C
        is its own emit, and Up/Down walk history newest-first with the
        draft preserved across the walk.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$State,
        [Parameter(Mandatory)][hashtable]$Token
    )
    $s = @{}
    foreach ($key in $State.Keys) { $s[$key] = $State[$key] }
    $done = { param($Emit)
        $s.Popup = @(Get-WtReplSlashMatches -Text ([string]$s.Text))
        if ($s.Popup.Count -eq 0) { $s.PopupIndex = 0 }
        elseif ([int]$s.PopupIndex -ge $s.Popup.Count) { $s.PopupIndex = $s.Popup.Count - 1 }
        return @{ State = $s; Emit = $Emit }
    }
    $text = [string]$s.Text
    $cursor = [int]$s.Cursor
    $insert = { param([string]$Piece)
        $s.Text = $text.Substring(0, $cursor) + $Piece + $text.Substring($cursor)
        $s.Cursor = $cursor + $Piece.Length
        $s.HistIdx = -1
    }
    $popup = @($State.Popup)
    $popupOpen = ($popup.Count -gt 0)
    $complete = { param([bool]$TrailingSpace)
        $pick = $popup[[Math]::Max(0, [Math]::Min([int]$State.PopupIndex, $popup.Count - 1))]
        $s.Text = '/' + [string]$pick.Alias + $(if ($TrailingSpace) { ' ' } else { '' })
        $s.Cursor = $s.Text.Length
        $s.HistIdx = -1
    }
    if ([string]$Token.Key -eq 'Paste') {
        $piece = ([string]$Token.Text).Replace("`r`n", "`n").Replace("`r", "`n")
        if ($piece) { & $insert $piece }
        return (& $done 'None')
    }
    if ($Token.Ctrl) {
        if ([string]$Token.Key -eq 'C') { return (& $done 'CtrlC') }
        return (& $done 'None')
    }
    switch ([string]$Token.Key) {
        'Char' { & $insert ([string]$Token.Char); return (& $done 'None') }
        'Enter' {
            if ($Token.Burst) { & $insert "`n"; return (& $done 'None') }
            if ($popupOpen) { & $complete $false; return (& $done 'Submit') }
            if ($text.EndsWith('\', [System.StringComparison]::Ordinal) -and $cursor -eq $text.Length) {
                $s.Text = $text.Substring(0, $text.Length - 1) + "`n"
                $s.Cursor = $s.Text.Length
                $s.HistIdx = -1
                return (& $done 'None')
            }
            return (& $done 'Submit')
        }
        'Tab' {
            if ($popupOpen) { & $complete $true }
            return (& $done 'None')
        }
        'Escape' {
            if ($text.Length -eq 0) { return (& $done 'Cancel') }
            $s.Text = ''; $s.Cursor = 0; $s.HistIdx = -1
            return (& $done 'Clear')
        }
        'Backspace' {
            if ($cursor -gt 0) { $s.Text = $text.Substring(0, $cursor - 1) + $text.Substring($cursor); $s.Cursor = $cursor - 1; $s.HistIdx = -1 }
            return (& $done 'None')
        }
        'Delete' {
            if ($cursor -lt $text.Length) { $s.Text = $text.Substring(0, $cursor) + $text.Substring($cursor + 1); $s.HistIdx = -1 }
            return (& $done 'None')
        }
        'LeftArrow' { if ($cursor -gt 0) { $s.Cursor = $cursor - 1 }; return (& $done 'None') }
        'RightArrow' { if ($cursor -lt $text.Length) { $s.Cursor = $cursor + 1 }; return (& $done 'None') }
        'Home' { $s.Cursor = 0; return (& $done 'None') }
        'End' { $s.Cursor = $text.Length; return (& $done 'None') }
        'UpArrow' {
            if ($popupOpen) { $s.PopupIndex = [Math]::Max(0, [int]$State.PopupIndex - 1); return (& $done 'None') }
            $history = [string[]]@($s.History)
            if ($history.Count -eq 0) { return (& $done 'None') }
            $index = [int]$s.HistIdx
            if ($index -lt 0) { $s.Draft = $text; $index = $history.Count - 1 }
            elseif ($index -gt 0) { $index-- }
            $s.HistIdx = $index
            $s.Text = [string]$history[$index]
            $s.Cursor = $s.Text.Length
            return (& $done 'None')
        }
        'DownArrow' {
            if ($popupOpen) { $s.PopupIndex = [Math]::Min($popup.Count - 1, [int]$State.PopupIndex + 1); return (& $done 'None') }
            $history = [string[]]@($s.History)
            $index = [int]$s.HistIdx
            if ($index -lt 0) { return (& $done 'None') }
            if ($index -lt ($history.Count - 1)) { $index++; $s.HistIdx = $index; $s.Text = [string]$history[$index] }
            else { $s.HistIdx = -1; $s.Text = [string]$s.Draft }
            $s.Cursor = $s.Text.Length
            return (& $done 'None')
        }
    }
    return (& $done 'None')
}

function Get-WtReplLineRender {
    <#
    .SYNOPSIS
        PURE: what one repaint of the edit line prints (prompt + the
        visible slice of the text, LF shown as the newline mark) and
        where the caret goes. A line longer than the console slides so
        the caret stays visible - the input line is never wrapped.
    #>
    param(
        [AllowEmptyString()][string]$Prompt = '> ',
        [AllowEmptyString()][string]$Text = '',
        [int]$Cursor = 0,
        [int]$Width = 80,
        [string]$NewlineMark = ([string][char]0xB6)
    )
    if ($Prompt.Length -ge $Width - 1) { $Prompt = $Prompt.Substring(0, [Math]::Max(0, $Width - 2)) }
    $shown = ([string]$Text).Replace("`n", $NewlineMark)
    $room = [Math]::Max(1, $Width - 1 - $Prompt.Length)
    $cursor = [Math]::Max(0, [Math]::Min($Cursor, $shown.Length))
    $offset = 0
    if ($cursor -ge $room) { $offset = $cursor - $room + 1 }
    $slice = $shown.Substring($offset, [Math]::Min($room, $shown.Length - $offset))
    return @{ Line = ($Prompt + $slice); CursorCol = ($Prompt.Length + $cursor - $offset); Offset = $offset }
}

function Get-WtReplSlashTable {
    <#
    .SYNOPSIS
        The slash commands as data: canonical name, the Turkish and
        English words that reach it, and the help line's key. /temizle
        and /clear are the SAME command as /yeni: a cleared screen with
        the old context still behind it was two commands the user had to
        tell apart, and the ask was one - a fresh page AND a fresh
        conversation.
    #>
    return @(
        @{ Name = 'new';      Aliases = @('yeni', 'new', 'temizle', 'clear');   HelpKey = 'AsSlashNew' }
        @{ Name = 'model';    Aliases = @('model');                            HelpKey = 'AsSlashModel' }
        @{ Name = 'endpoint'; Aliases = @('uc', 'endpoint');                    HelpKey = 'AsSlashEndpoint' }
        @{ Name = 'key';      Aliases = @('anahtar', 'key');                    HelpKey = 'AsSlashKey' }
        @{ Name = 'scan';     Aliases = @('tara', 'scan');                      HelpKey = 'AsSlashScan' }
        @{ Name = 'test';     Aliases = @('sina', 'test');                      HelpKey = 'AsSlashTest' }
        @{ Name = 'settings'; Aliases = @('ayarlar', 'settings', 'config');     HelpKey = 'AsSlashSettings' }
        @{ Name = 'perms';    Aliases = @('izinler', 'perms');                  HelpKey = 'AsSlashPerms' }
        @{ Name = 'tools';    Aliases = @('araclar', 'tools');                  HelpKey = 'AsSlashTools' }
        @{ Name = 'profile';  Aliases = @('profil', 'profile');                 HelpKey = 'AsSlashProfile' }
        @{ Name = 'notes';    Aliases = @('notlar', 'notes');                   HelpKey = 'AsSlashNotes' }
        @{ Name = 'status';   Aliases = @('durum', 'status');                   HelpKey = 'AsSlashStatus' }
        @{ Name = 'save';     Aliases = @('kaydet', 'save');                    HelpKey = 'AsSlashSave' }
        @{ Name = 'copy';     Aliases = @('kopyala', 'copy');                   HelpKey = 'AsSlashCopy' }
        @{ Name = 'forget';   Aliases = @('unut', 'forget');                    HelpKey = 'AsSlashForget' }
        @{ Name = 'help';     Aliases = @('yardim', 'help');                    HelpKey = 'AsSlashHelp' }
        @{ Name = 'quit';     Aliases = @('cik', 'quit', 'cikis', 'exit', 'q'); HelpKey = 'AsSlashQuit' }
    )
}

function Resolve-WtReplSlash {
    param([AllowNull()][AllowEmptyString()][string]$Word)
    $folded = ConvertTo-WtAssistantSearchText -Text ([string]$Word)
    foreach ($row in @(Get-WtReplSlashTable)) {
        foreach ($alias in @($row.Aliases)) {
            if ([string]::Equals($alias, $folded, [System.StringComparison]::Ordinal)) { return [string]$row.Name }
        }
    }
    return ''
}

function Get-WtReplHelpLines {
    <#
    .SYNOPSIS
        PURE: one help row per slash command - every alias, then the
        description. No leading indent: Write-WtReplLine puts every
        slash-command line in the page margin itself.
    #>
    return [string[]]@(foreach ($row in @(Get-WtReplSlashTable)) {
        (((@($row.Aliases) | ForEach-Object { '/' + [string]$_ }) -join ', ') + ' - ' + [string](Get-Translation ([string]$row.HelpKey)))
    })
}

function Get-WtReplSlashMatches {
    <#
    .SYNOPSIS
        PURE: the popup rows for what is typed so far - only a bare
        "/word" has one, matched by folded alias prefix, each command
        once, capped at 8. Returns a plain array, not "return , $x":
        Hashtable's own [0] indexer would collapse a size-1
        comma-guarded array to $null.
    #>
    param([AllowNull()][AllowEmptyString()][string]$Text = '')
    $text = [string]$Text
    if (-not $text.StartsWith('/', [System.StringComparison]::Ordinal)) { return @() }
    if ($text -cmatch '\s') { return @() }
    $word = ConvertTo-WtAssistantSearchText -Text $text.Substring(1)
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($row in @(Get-WtReplSlashTable)) {
        foreach ($alias in @($row.Aliases)) {
            $folded = ConvertTo-WtAssistantSearchText -Text ([string]$alias)
            if ($folded.StartsWith($word, [System.StringComparison]::Ordinal)) {
                $rows.Add([PSCustomObject]@{ Name = [string]$row.Name; Alias = [string]$alias; Help = [string](Get-Translation ([string]$row.HelpKey)) })
                break
            }
        }
        if ($rows.Count -ge 8) { break }
    }
    return $rows.ToArray()
}

function Get-WtReplPopupRows {
    <#
    .SYNOPSIS
        PURE: the popup as segment rows under the input box - the
        highlighted alias in yellow behind the cursor glyph, the rest
        grey, the help text dark grey. Each row is clamped to Width-1.
        Returns a plain array, not "return , $x" (see
        Get-WtReplSlashMatches).
    #>
    param(
        [AllowEmptyCollection()][array]$Popup = @(),
        [int]$Index = 0,
        [int]$Width = 80,
        [PSCustomObject]$Glyphs = $script:WtGlyphs
    )
    $w = [Math]::Max(20, $Width - 1)
    $rows = New-Object System.Collections.Generic.List[object]
    $items = @($Popup)
    for ($i = 0; $i -lt $items.Count; $i++) {
        $selected = ($i -eq $Index)
        $lead = '  ' + $(if ($selected) { [string]$Glyphs.Cursor } else { '  ' })
        $alias = ('/' + [string]$items[$i].Alias).PadRight(12)
        $help = [string]$items[$i].Help
        $room = $w - $lead.Length - $alias.Length
        if ($help.Length -gt $room) { $help = $(if ($room -gt 1) { $help.Substring(0, $room - 1) + '~' } else { '' }) }
        $rows.Add(@(
            New-WtSeg -Text $lead -Fg $(if ($selected) { 'Yellow' } else { 'Gray' })
            New-WtSeg -Text $alias -Fg $(if ($selected) { 'Yellow' } else { 'Gray' })
            New-WtSeg -Text $help -Fg 'DarkGray'
        ))
    }
    return $rows.ToArray()
}

function ConvertTo-WtReplCommand {
    <#
    .SYNOPSIS
        What a submitted line means: digits-only is a suggestion index
        (Unknown if out of range), a leading slash is a local command
        (Unknown if unmatched), a bare /yeni word (yeni, new, temizle,
        clear) is 'Slash' new so "clear" never reaches the model, a bare
        /cik word (q, quit, exit, cik, cikis) is a 'Hint' rather than
        being sent to the model or dropping the conversation, anything
        else is 'Send', and $null is 'Eof'. Digits are matched with [0-9],
        never \d, which admits every Unicode digit and would make [int]
        throw on a full-width one.
    #>
    param(
        [AllowNull()][object]$Line,
        [int]$SuggestionCount = 0
    )
    $none = @{ Kind = 'None'; Text = ''; Index = 0; Command = ''; Argument = '' }
    if ($null -eq $Line) { $none.Kind = 'Eof'; return $none }
    $text = ([string]$Line).Trim()
    if ($text -eq '') { return $none }
    if ($text.IndexOf(' ') -lt 0) {
        $bareWord = Resolve-WtReplSlash -Word $text
        if ($bareWord -eq 'new') { return @{ Kind = 'Slash'; Text = $text; Index = 0; Command = 'new'; Argument = '' } }
        if ($bareWord -eq 'quit') { return @{ Kind = 'Hint'; Text = $text; Index = 0; Command = 'quit'; Argument = '' } }
    }
    if ($text -cmatch '^[0-9]{1,2}\z') {
        $index = [int]$text
        $kind = $(if ($index -ge 1 -and $index -le $SuggestionCount) { 'Suggest' } else { 'Unknown' })
        return @{ Kind = $kind; Text = $text; Index = $index; Command = ''; Argument = '' }
    }
    if ($text.StartsWith('/', [System.StringComparison]::Ordinal)) {
        $body = $text.Substring(1).Trim()
        $word = $body
        $argument = ''
        $space = $body.IndexOf(' ')
        if ($space -ge 0) { $word = $body.Substring(0, $space); $argument = $body.Substring($space + 1).Trim() }
        $name = Resolve-WtReplSlash -Word $word
        if ($name) { return @{ Kind = 'Slash'; Text = $text; Index = 0; Command = $name; Argument = $argument } }
        return @{ Kind = 'Unknown'; Text = $text; Index = 0; Command = $word; Argument = $argument }
    }
    return @{ Kind = 'Send'; Text = $text; Index = 0; Command = ''; Argument = '' }
}

function New-WtReplSession {
    <#
    .SYNOPSIS
        One conversation: the model messages (OpenAI array, never
        reformatted), the transcript entries the console already
        printed, the current suggestions, the input history and the
        Ctrl+C double-press clock.
    #>
    return @{
        Messages    = (New-Object System.Collections.Generic.List[object])
        Entries     = (New-Object System.Collections.Generic.List[object])
        Suggestions = @()
        History     = (New-Object System.Collections.Generic.List[string])
        LastCtrlC   = [datetime]::MinValue
        LastEsc     = [datetime]::MinValue
        EscCount    = 0
        Busy        = $false
        ProfileEnabled = $true
        SystemExtra = $null
        Schemas     = $null
        Disabled    = $null
        PendingNotes = (New-Object System.Collections.Generic.List[string])
        FollowUp    = ''
        ClientCompat = @{}
        SessionId   = [string][guid]::NewGuid()
        LastUsage = $null
        HistoryMaxChars = 0
    }
}

function Add-WtChatEntry {
    <#
    .SYNOPSIS
        Appends a transcript entry; while the REPL owns the console it
        is printed at once (append-only), unless -Silent says the text
        is already on screen (a streamed answer).
    #>
    param(
        [Parameter(Mandatory)][hashtable]$State,
        [Parameter(Mandatory)][ValidateSet('User', 'Assistant', 'Tool', 'Error', 'Info')][string]$Kind,
        [AllowNull()][AllowEmptyString()][string]$Text = '',
        [switch]$Silent
    )
    $State.Entries.Add(@{ Kind = $Kind; Text = [string]$Text })
    if ($script:WtReplMode -and -not $Silent) { Write-WtReplEntry -Kind $Kind -Text ([string]$Text) }
}

function Get-WtReplBoxRows {
    <#
    .SYNOPSIS
        PURE: a bordered box as segment rows, Width-1 wide, the title
        set into the top border ("+- Title ---+"). Each content row is
        "| " + segments + padding + " |"; a row wider than the inside is
        cut with '~' (the frames' cut mark). Fg colours the border.
    #>
    param(
        [AllowEmptyString()][string]$Title = '',
        [AllowEmptyCollection()][array]$Rows = @(),
        [int]$Width = 80,
        [PSCustomObject]$Glyphs = $script:WtGlyphs,
        [string]$Fg = 'Cyan'
    )
    $w = [Math]::Max(20, $Width - 1)
    $inner = $w - 4
    $out = New-Object System.Collections.Generic.List[object]
    $top = [string]$Glyphs.TL + [string]$Glyphs.H
    if ($Title) {
        $t = ' ' + $Title + ' '
        if ($t.Length -gt ($w - 4)) { $t = $t.Substring(0, $w - 5) + '~ ' }
        $top += $t
    }
    $top += ([string]$Glyphs.H * ($w - 1 - $top.Length)) + [string]$Glyphs.TR
    $out.Add(@(, (New-WtSeg -Text $top -Fg $Fg)))
    foreach ($row in @($Rows)) {
        $segs = New-Object System.Collections.Generic.List[object]
        $used = 0
        foreach ($seg in @($row)) {
            $text = [string]$seg.T
            if (($used + $text.Length) -gt $inner) {
                $room = $inner - $used
                $text = $(if ($room -gt 1) { $text.Substring(0, $room - 1) + '~' } elseif ($room -eq 1) { '~' } else { '' })
            }
            if ($text.Length -gt 0) { $segs.Add((New-WtSeg -Text $text -Fg ([string]$seg.F) -Bg ([string]$seg.B))); $used += $text.Length }
            if ($used -ge $inner) { break }
        }
        $line = New-Object System.Collections.Generic.List[object]
        $line.Add((New-WtSeg -Text ([string]$Glyphs.V + ' ') -Fg $Fg))
        foreach ($s in $segs) { $line.Add($s) }
        $line.Add((New-WtSeg -Text ((' ' * ($inner - $used)) + ' ' + [string]$Glyphs.V) -Fg $Fg))
        $out.Add($line.ToArray())
    }
    $out.Add(@(, (New-WtSeg -Text ([string]$Glyphs.BL + ([string]$Glyphs.H * ($w - 2)) + [string]$Glyphs.BR) -Fg $Fg)))
    return $out.ToArray()
}

function Get-WtReplInputLines {
    <#
    .SYNOPSIS
        PURE: the three rows of the input box and where the caret sits.
        The text slides through Get-WtReplLineRender so the caret is
        always visible; an empty line shows the placeholder dimmed.
    #>
    param(
        [AllowEmptyString()][string]$Prompt = '> ',
        [AllowEmptyString()][string]$Text = '',
        [int]$Cursor = 0,
        [int]$Width = 80,
        [PSCustomObject]$Glyphs = $script:WtGlyphs,
        [AllowEmptyString()][string]$Placeholder = (Get-Translation 'AsReplPlaceholder')
    )
    $w = [Math]::Max(20, $Width - 1)
    $inner = $w - 4
    $shown = $Text
    $fg = 'White'
    $cursor = $Cursor
    if (-not $Text -and $Placeholder) { $shown = $Placeholder; $fg = 'DarkGray'; $cursor = 0 }
    $render = Get-WtReplLineRender -Prompt $Prompt -Text $shown -Cursor $cursor -Width ($inner + 1)
    $line = [string]$render.Line
    $promptPart = $line.Substring(0, [Math]::Min($Prompt.Length, $line.Length))
    $textPart = $(if ($line.Length -gt $Prompt.Length) { $line.Substring($Prompt.Length) } else { '' })
    $rows = Get-WtReplBoxRows -Title '' -Rows @(, @((New-WtSeg -Text $promptPart -Fg 'Cyan'), (New-WtSeg -Text $textPart -Fg $fg))) -Width $Width -Glyphs $Glyphs
    return @{ Rows = $rows; CaretRow = 1; CaretCol = (2 + [int]$render.CursorCol) }
}

function New-WtReplPickState {
    param(
        [AllowEmptyCollection()][array]$Options = @(),
        [AllowEmptyString()][string]$TextOption = ''
    )
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($o in @($Options)) {
        if ($o -is [string]) { $rows.Add(@{ Label = [string]$o; Hotkey = ''; IsText = $false }) }
        else { $rows.Add(@{ Label = [string]$o.Label; Hotkey = [string]$o.Hotkey; IsText = $false }) }
    }
    if ($TextOption) { $rows.Add(@{ Label = $TextOption; Hotkey = ''; IsText = $true }) }
    return @{ Rows = $rows.ToArray(); Index = 0; WindowStart = 0 }
}

function Update-WtReplPickState {
    <#
    .SYNOPSIS
        PURE: the selector reducer. Arrows/Home/End/PageUp/PageDown move,
        Enter picks the current row, a digit 1-9 picks that row, a
        hotkey letter picks its row (OrdinalIgnoreCase - never ToUpper
        under tr-TR), Esc and Ctrl+C cancel.
    #>
    param([Parameter(Mandatory)][hashtable]$State, [Parameter(Mandatory)][hashtable]$Token)
    $s = @{}
    foreach ($key in $State.Keys) { $s[$key] = $State[$key] }
    $rows = @($s.Rows)
    $last = [Math]::Max(0, $rows.Count - 1)
    $index = [int]$s.Index
    $done = { param($Emit) return @{ State = $s; Emit = $Emit } }
    if ($Token.Ctrl) {
        if ([string]$Token.Key -eq 'C') { return (& $done 'Cancel') }
        return (& $done 'None')
    }
    switch ([string]$Token.Key) {
        'UpArrow' { $s.Index = [Math]::Max(0, $index - 1); return (& $done 'None') }
        'DownArrow' { $s.Index = [Math]::Min($last, $index + 1); return (& $done 'None') }
        'Home' { $s.Index = 0; return (& $done 'None') }
        'End' { $s.Index = $last; return (& $done 'None') }
        'PageUp' { $s.Index = [Math]::Max(0, $index - 10); return (& $done 'None') }
        'PageDown' { $s.Index = [Math]::Min($last, $index + 10); return (& $done 'None') }
        'Enter' { if ($rows.Count -gt 0) { return (& $done 'Pick') }; return (& $done 'Cancel') }
        'Escape' { return (& $done 'Cancel') }
        'Char' {
            $c = [string]$Token.Char
            if ($c -cmatch '^[1-9]$') {
                $n = [int]$c
                if ($n -le $rows.Count) { $s.Index = $n - 1; return (& $done 'Pick') }
                return (& $done 'None')
            }
            for ($i = 0; $i -lt $rows.Count; $i++) {
                $hot = [string]$rows[$i].Hotkey
                if ($hot -and [string]::Equals($hot, $c, [System.StringComparison]::OrdinalIgnoreCase)) { $s.Index = $i; return (& $done 'Pick') }
            }
            return (& $done 'None')
        }
    }
    return (& $done 'None')
}

function Get-WtReplQuestionRows {
    <#
    .SYNOPSIS
        PURE: question lines wrapped to the INSIDE of a REPL box, as
        segment rows - needed because Get-WtReplBoxRows just cuts an
        overlong row with '~', which mangles long consent text. A blank
        line stays blank, a "- " bullet keeps a hanging indent, and
        every other line word-wraps at the inside width.
    #>
    param(
        [AllowEmptyCollection()][string[]]$Lines = @(),
        [int]$Width = 80,
        [string]$Fg = 'White'
    )
    $inner = [Math]::Max(20, $Width - 1) - 4
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($raw in @($Lines)) {
        $line = [string]$raw
        if ($line.Trim().Length -eq 0) { $rows.Add(@(, (New-WtSeg -Text '' -Fg 'Gray'))); continue }
        $lead = $line.Length - $line.TrimStart().Length
        $body = $line.TrimStart()
        $marker = ''
        if ($body.StartsWith('- ', [System.StringComparison]::Ordinal)) { $marker = '- '; $body = $body.Substring(2) }
        $indent = ' ' * $lead
        $room = [Math]::Max(8, $inner - $lead - $marker.Length)
        $first = $true
        foreach ($piece in @(Split-WtWrappedLines -Text $body -Width $room)) {
            $prefix = $indent + $(if ($first) { $marker } else { ' ' * $marker.Length })
            $rows.Add(@(, (New-WtSeg -Text ($prefix + [string]$piece) -Fg $Fg)))
            $first = $false
        }
    }
    return $rows.ToArray()
}

function Get-WtReplPickLines {
    <#
    .SYNOPSIS
        PURE: the selector box: title in the border, the question lines
        (wrapped to the box through Get-WtReplQuestionRows), a blank row,
        the option rows (cursor glyph on the selected one, "(h)" after a
        hotkey label), then the key hint. Tall lists are windowed around
        the selection. Risk colours the border.
    #>
    param(
        [AllowEmptyString()][string]$Title = '',
        [AllowEmptyCollection()][string[]]$Lines = @(),
        [Parameter(Mandatory)][hashtable]$State,
        [int]$Width = 80,
        [PSCustomObject]$Glyphs = $script:WtGlyphs,
        [AllowEmptyString()][string]$Risk = '',
        [int]$ViewHeight = 10
    )
    $fg = switch ($Risk) { 'ADVANCED' { 'Red' } 'CAUTION' { 'Yellow' } default { 'Cyan' } }
    $textFg = switch ($Risk) { 'ADVANCED' { 'Red' } 'CAUTION' { 'Yellow' } default { 'White' } }
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($r in @(Get-WtReplQuestionRows -Lines $Lines -Width $Width -Fg $textFg)) { $rows.Add($r) }
    if (@($Lines).Count -gt 0) { $rows.Add(@(, (New-WtSeg -Text '' -Fg 'Gray'))) }
    $items = @($State.Rows)
    $view = [Math]::Max(1, [Math]::Min($ViewHeight, $items.Count))
    $start = Get-WtViewportWindow -ItemCount $items.Count -CursorIndex ([int]$State.Index) -ViewHeight $view -WindowStart ([int]$State.WindowStart)
    for ($i = $start; $i -lt [Math]::Min($start + $view, $items.Count); $i++) {
        $selected = ($i -eq [int]$State.Index)
        $label = [string]$items[$i].Label
        if ([string]$items[$i].Hotkey) { $label += ' (' + ([string]$items[$i].Hotkey).ToLowerInvariant() + ')' }
        $lead = $(if ($selected) { [string]$Glyphs.Cursor } else { '  ' })
        $rows.Add(@((New-WtSeg -Text $lead -Fg 'Yellow'), (New-WtSeg -Text $label -Fg $(if ($selected) { 'Yellow' } else { 'Gray' }))))
    }
    $box = @(Get-WtReplBoxRows -Title $Title -Rows $rows.ToArray() -Width $Width -Glyphs $Glyphs -Fg $fg)
    $hint = '  ' + [string](Get-Translation 'AsPickHint')
    $w = [Math]::Max(20, $Width - 1)
    if ($hint.Length -gt $w) { $hint = $hint.Substring(0, $w) }
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($r in $box) { $list.Add($r) }
    $list.Add(@(, (New-WtSeg -Text $hint -Fg 'DarkGray')))
    return $list.ToArray()
}
#endregion src/20-tui/repl-state.ps1

#region src/20-tui/richtext.ps1
# Rich text for the assistant transcript: markdown-ish source text into
# printable, coloured segment rows. PURE - no console, no translation.

function Get-WtRichWrapWidth {
    <#
    .SYNOPSIS
        PURE: the one wrap width formula - the console width less the
        last column (a character written there wraps by itself). No cap:
        the text fills the window it is printed in, however wide that is.
    #>
    param([int]$Width = 80)
    return [Math]::Max(10, $Width - 1)
}

function Get-WtRichBlockIndents {
    <#
    .SYNOPSIS
        PURE: how many columns a block's rows take beyond its source
        text, for the streaming overflow cut. First = the extra columns
        of the FIRST rendered row over the raw line (a bullet renders
        "  * text" for "- text": two more); Continuation = the column
        every later row starts at, which is also where the tail of a cut
        block must be printed so it stays under the block's own text.
    #>
    param([Parameter(Mandatory)][hashtable]$Block, [int]$Indent = 0)
    switch ([string]$Block.Kind) {
        'Bullet'   { return @{ First = 2; Continuation = $Indent + 4 } }
        'Numbered' { return @{ First = 2; Continuation = $Indent + 2 + ([string]$Block.Marker).Length + 1 } }
        'Quote'    { return @{ First = 0; Continuation = $Indent + 2 } }
        default    { return @{ First = 0; Continuation = $Indent } }
    }
}

function Get-WtRichBlock {
    <#
    .SYNOPSIS
        PURE: one raw line plus the streaming state into the block it
        forms - @{ Kind; Level; Marker; Text; State }. A fence line
        toggles State.InFence and prints nothing; while the fence is
        open EVERY line is Code, so a '# comment' inside a code block
        is never mistaken for a heading. A rule is three or more of the
        same -, * or _ and nothing else, tested BEFORE the bullet so
        '---' does not read as a '-' item.
    #>
    param(
        [AllowNull()][AllowEmptyString()][string]$Line = '',
        [AllowNull()][hashtable]$State = $null
    )
    $inFence = $(if ($null -ne $State) { [bool]$State.InFence } else { $false })
    $raw = [string]$Line
    $lead = $raw.Trim()
    $next = @{ InFence = $inFence }
    $fence = ([string][char]96) * 3

    if ($lead.StartsWith($fence, [System.StringComparison]::Ordinal)) {
        $next.InFence = (-not $inFence)
        return @{ Kind = 'Fence'; Level = 0; Marker = ''; Text = ''; State = $next }
    }
    if ($inFence) { return @{ Kind = 'Code'; Level = 0; Marker = ''; Text = $raw; State = $next } }
    if ($lead.Length -eq 0) { return @{ Kind = 'Blank'; Level = 0; Marker = ''; Text = ''; State = $next } }

    if ($lead.Length -ge 3) {
        $c0 = $lead[0]
        if ($c0 -eq '-' -or $c0 -eq '*' -or $c0 -eq '_') {
            $same = $true
            foreach ($ch in $lead.ToCharArray()) { if ($ch -ne $c0) { $same = $false; break } }
            if ($same) { return @{ Kind = 'Rule'; Level = 0; Marker = ''; Text = ''; State = $next } }
        }
    }

    if ($lead[0] -eq '#') {
        $h = 0
        while ($h -lt $lead.Length -and $lead[$h] -eq '#') { $h++ }
        if ($h -ge 1 -and $h -le 6 -and $h -lt $lead.Length -and $lead[$h] -eq ' ') {
            return @{ Kind = 'Heading'; Level = $h; Marker = ''; Text = $lead.Substring($h + 1).Trim(); State = $next }
        }
        return @{ Kind = 'Paragraph'; Level = 0; Marker = ''; Text = $lead; State = $next }
    }

    if ($lead.Length -ge 2 -and $lead[1] -eq ' ' -and ($lead[0] -eq '-' -or $lead[0] -eq '*' -or $lead[0] -eq '+')) {
        return @{ Kind = 'Bullet'; Level = 0; Marker = ''; Text = $lead.Substring(2).Trim(); State = $next }
    }

    $d = 0
    while ($d -lt $lead.Length -and [char]::IsDigit($lead[$d])) { $d++ }
    if ($d -gt 0 -and ($d + 1) -lt $lead.Length -and ($lead[$d] -eq '.' -or $lead[$d] -eq ')') -and $lead[$d + 1] -eq ' ') {
        return @{ Kind = 'Numbered'; Level = 0; Marker = $lead.Substring(0, $d + 1); Text = $lead.Substring($d + 2).Trim(); State = $next }
    }

    if ($lead[0] -eq '>') {
        return @{ Kind = 'Quote'; Level = 0; Marker = ''; Text = $lead.Substring(1).Trim(); State = $next }
    }

    if ($lead[0] -eq '|' -and $lead[$lead.Length - 1] -eq '|') {
        return @{ Kind = 'Table'; Level = 0; Marker = ''; Text = $lead; State = $next }
    }

    return @{ Kind = 'Paragraph'; Level = 0; Marker = ''; Text = $lead; State = $next }
}

function Split-WtRichInline {
    <#
    .SYNOPSIS
        PURE: one line of text into styled parts - @(@{ Text; Style }),
        Style in Normal/Strong/Code/Link/Url. Backticked code wins over
        every other mark (a ** inside code stays literal), and a mark
        that never closes stays literal text since the stream hands us
        half-written lines.
    #>
    param([AllowNull()][AllowEmptyString()][string]$Text = '')
    $s = [string]$Text
    $parts = New-Object System.Collections.Generic.List[object]
    $buf = New-Object System.Text.StringBuilder
    $tick = [char]96
    $i = 0
    while ($i -lt $s.Length) {
        $c = $s[$i]
        $taken = $false

        if ($c -eq $tick) {
            $close = $s.IndexOf($tick, $i + 1)
            if ($close -gt $i) {
                if ($buf.Length -gt 0) { $parts.Add(@{ Text = $buf.ToString(); Style = 'Normal' }); [void]$buf.Clear() }
                $parts.Add(@{ Text = $s.Substring($i + 1, $close - $i - 1); Style = 'Code' })
                $i = $close + 1
                $taken = $true
            }
        }
        elseif (($c -eq '*' -or $c -eq '_') -and ($i + 1) -lt $s.Length -and $s[$i + 1] -eq $c) {
            $mark = [string]$c + [string]$c
            $close = $s.IndexOf($mark, $i + 2, [System.StringComparison]::Ordinal)
            if ($close -gt ($i + 1)) {
                if ($buf.Length -gt 0) { $parts.Add(@{ Text = $buf.ToString(); Style = 'Normal' }); [void]$buf.Clear() }
                $parts.Add(@{ Text = $s.Substring($i + 2, $close - $i - 2); Style = 'Strong' })
                $i = $close + 2
                $taken = $true
            }
        }
        elseif ($c -eq '[') {
            $rb = $s.IndexOf(']', $i + 1)
            if ($rb -gt $i -and ($rb + 1) -lt $s.Length -and $s[$rb + 1] -eq '(') {
                $rp = $s.IndexOf(')', $rb + 2)
                if ($rp -gt ($rb + 1)) {
                    if ($buf.Length -gt 0) { $parts.Add(@{ Text = $buf.ToString(); Style = 'Normal' }); [void]$buf.Clear() }
                    $parts.Add(@{ Text = $s.Substring($i + 1, $rb - $i - 1); Style = 'Link' })
                    $parts.Add(@{ Text = ' (' + $s.Substring($rb + 2, $rp - $rb - 2) + ')'; Style = 'Url' })
                    $i = $rp + 1
                    $taken = $true
                }
            }
        }

        if (-not $taken) {
            [void]$buf.Append($c)
            $i++
        }
    }
    if ($buf.Length -gt 0) { $parts.Add(@{ Text = $buf.ToString(); Style = 'Normal' }) }
    return , $parts.ToArray()
}

function Get-WtRichDefaultColors {
    return @{ Normal = 'Gray'; Strong = 'White'; Code = 'DarkCyan'; Link = 'Gray'; Url = 'DarkGray' }
}

function Split-WtWrappedSegments {
    <#
    .SYNOPSIS
        PURE: styled parts into rows of segments, broken at spaces so no
        row is wider than Get-WtRichWrapWidth. -Prefix lands on the first
        row only (a list marker); every later row starts at Indent +
        Hanging. A word longer than a whole row is cut hard. Internal
        helpers take -SegFg, not -Fg: these are dot-sourced closures, so
        a -Fg param would collide (case-insensitively) with the
        caller's own $fg loop variable and get clobbered.
    #>
    param(
        [AllowNull()][AllowEmptyCollection()][array]$Parts = @(),
        [int]$Width = 80,
        [int]$Indent = 0,
        [int]$Hanging = 0,
        [AllowEmptyString()][string]$Prefix = '',
        [string]$PrefixFg = 'Gray',
        [AllowNull()][hashtable]$Colors = $null
    )
    $map = $(if ($null -ne $Colors) { $Colors } else { Get-WtRichDefaultColors })
    $limit = Get-WtRichWrapWidth -Width $Width
    $sepFg = [string]$map['Normal']
    if (-not $sepFg) { $sepFg = 'Gray' }
    $rows = New-Object System.Collections.Generic.List[object]
    $line = New-Object System.Collections.Generic.List[object]
    $col = 0
    $hasWord = $false
    $leadPad = ' ' * [Math]::Max(0, [Math]::Min($Indent, $limit - 1))
    $contPad = ' ' * [Math]::Max(0, [Math]::Min($Indent + $Hanging, $limit - 1))

    $append = {
        param([string]$Text, [string]$SegFg)
        if ($line.Count -gt 0 -and ([string]$line[$line.Count - 1].F) -eq $SegFg) {
            $line[$line.Count - 1] = New-WtSeg -Text (([string]$line[$line.Count - 1].T) + $Text) -Fg $SegFg
        }
        else { $line.Add((New-WtSeg -Text $Text -Fg $SegFg)) }
        $col += $Text.Length
    }
    $startRow = {
        param([string]$Pad, [string]$Lead, [string]$LeadFg)
        $line = New-Object System.Collections.Generic.List[object]
        $col = 0
        $hasWord = $false
        if ($Pad -or $Lead) { . $append ($Pad + $Lead) $LeadFg }
    }
    $flush = { $rows.Add($line.ToArray()) }

    . $startRow $leadPad $Prefix $PrefixFg

    $tokens = New-Object System.Collections.Generic.List[object]
    foreach ($p in @($Parts)) {
        $style = [string]$p.Style
        foreach ($w in (([string]$p.Text).Split([char]' '))) {
            if ([string]$w) { $tokens.Add(@{ Text = [string]$w; Style = $style }) }
        }
    }

    foreach ($t in $tokens) {
        $fg = [string]$map[[string]$t.Style]
        if (-not $fg) { $fg = 'Gray' }
        $word = [string]$t.Text
        $sep = $(if ($hasWord) { 1 } else { 0 })

        if ($hasWord -and ($col + $sep + $word.Length) -gt $limit) {
            . $flush
            . $startRow $contPad '' $fg
            $sep = 0
        }

        if (($col + $sep + $word.Length) -gt $limit) {
            while ($word.Length -gt 0) {
                $room = $limit - $col - $(if ($hasWord) { 1 } else { 0 })
                if ($room -le 0) {
                    . $flush
                    . $startRow $contPad '' $fg
                    continue
                }
                if ($hasWord) { . $append ' ' $sepFg }
                $take = [Math]::Min($room, $word.Length)
                . $append ($word.Substring(0, $take)) $fg
                $hasWord = $true
                $word = $word.Substring($take)
                if ($word.Length -gt 0) {
                    . $flush
                    . $startRow $contPad '' $fg
                }
            }
            continue
        }

        if ($sep -eq 1) { . $append ' ' $sepFg }
        . $append $word $fg
        $hasWord = $true
    }

    if ($line.Count -gt 0) { . $flush }
    return , $rows.ToArray()
}

function Get-WtRichBlockRows {
    <#
    .SYNOPSIS
        PURE: one classified block into printable segment rows. Code and
        table rows are clipped, not wrapped, since breaking a command or
        a column at a space would corrupt it. A heading always emits a
        blank row before itself; Write-WtReplBlock collapses blank runs
        and drops one at the top of a page, so a heading that opens an
        answer still prints no stray leading blank.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$Block,
        [int]$Width = 80,
        [int]$Indent = 0,
        [PSCustomObject]$Glyphs = $script:WtGlyphs
    )
    $limit = Get-WtRichWrapWidth -Width $Width
    $padWidth = [Math]::Max(0, [Math]::Min($Indent, $limit - 1))
    $pad = ' ' * $padWidth
    $rows = New-Object System.Collections.Generic.List[object]
    $clip = {
        param([string]$Text, [string]$Fg)
        $t = $pad + $Text
        if ($t.Length -gt $limit) { $t = $t.Substring(0, $limit - 1) + [string][char]0x2026 }
        $rows.Add(@(, (New-WtSeg -Text $t -Fg $Fg)))
    }
    switch ([string]$Block.Kind) {
        'Fence' { }
        'Blank' { $rows.Add(@(, (New-WtSeg -Text '' -Fg 'Gray'))) }
        'Rule'  { $rows.Add(@(, (New-WtSeg -Text ($pad + ([string]$Glyphs.Rule * [Math]::Max(1, $limit - $padWidth))) -Fg 'DarkGray'))) }
        'Code'  { . $clip ([string]$Block.Text) 'DarkCyan' }
        'Table' { . $clip ([string]$Block.Text) 'Gray' }
        'Heading' {
            $rows.Add(@(, (New-WtSeg -Text '' -Fg 'Gray')))
            $colors = @{ Normal = 'Cyan'; Strong = 'Cyan'; Code = 'Cyan'; Link = 'Cyan'; Url = 'Cyan' }
            foreach ($r in (Split-WtWrappedSegments -Parts (Split-WtRichInline -Text ([string]$Block.Text)) -Width $Width -Indent $Indent -Colors $colors)) { $rows.Add($r) }
        }
        'Quote' {
            $colors = @{ Normal = 'DarkGray'; Strong = 'DarkGray'; Code = 'DarkGray'; Link = 'DarkGray'; Url = 'DarkGray' }
            foreach ($r in (Split-WtWrappedSegments -Parts (Split-WtRichInline -Text ([string]$Block.Text)) -Width $Width -Indent ($Indent + 2) -Colors $colors)) { $rows.Add($r) }
        }
        'Bullet' {
            $lead = [string]$Glyphs.ListBullet + ' '
            foreach ($r in (Split-WtWrappedSegments -Parts (Split-WtRichInline -Text ([string]$Block.Text)) -Width $Width -Indent ($Indent + 2) -Hanging $lead.Length -Prefix $lead -PrefixFg 'Gray')) { $rows.Add($r) }
        }
        'Numbered' {
            $lead = [string]$Block.Marker + ' '
            foreach ($r in (Split-WtWrappedSegments -Parts (Split-WtRichInline -Text ([string]$Block.Text)) -Width $Width -Indent ($Indent + 2) -Hanging $lead.Length -Prefix $lead -PrefixFg 'Gray')) { $rows.Add($r) }
        }
        default {
            foreach ($r in (Split-WtWrappedSegments -Parts (Split-WtRichInline -Text ([string]$Block.Text)) -Width $Width -Indent $Indent)) { $rows.Add($r) }
        }
    }
    return , $rows.ToArray()
}

function Get-WtRichLines {
    <#
    .SYNOPSIS
        PURE: a whole answer (the raw text as the model wrote it) into
        printable rows. The streaming path calls Get-WtRichBlock and
        Get-WtRichBlockRows itself, one completed line at a time; this is
        the batch door used for reprints and for the low mode.
    #>
    param(
        [AllowNull()][AllowEmptyString()][string]$Text = '',
        [int]$Width = 80,
        [int]$Indent = 0,
        [PSCustomObject]$Glyphs = $script:WtGlyphs
    )
    $state = @{ InFence = $false }
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($raw in (([string]$Text).Split([char]10))) {
        $line = ([string]$raw).TrimEnd([char]13)
        $block = Get-WtRichBlock -Line $line -State $state
        $state = $block.State
        foreach ($r in (Get-WtRichBlockRows -Block $block -Width $Width -Indent $Indent -Glyphs $Glyphs)) { $rows.Add($r) }
    }
    return , $rows.ToArray()
}
#endregion src/20-tui/richtext.ps1

#region src/20-tui/selector.ps1
# Legacy page selector (Show-WtSelector).
# Covered by: tests/Selector.Tests.ps1

function Get-WtSelectorPage {
    <#
    .SYNOPSIS
        Catalog-agnostic paging: slices $Items into pages of $PageSize and
        returns the requested page, clamped into range. No empty trailing
        page when Count is an exact multiple of PageSize (uses ceiling, not
        floor+1), and no out-of-range index on a partial last page.
    #>
    param(
        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [array]$Items,

        [Parameter(Mandatory)]
        [int]$PageIndex,

        [int]$PageSize = 10
    )

    if ($Items.Count -eq 0) {
        return [PSCustomObject]@{ Items = @(); PageIndex = 0; TotalPages = 1; StartIndex = 0; EndIndex = 0 }
    }

    $totalPages = [Math]::Max(1, [int][Math]::Ceiling($Items.Count / [double]$PageSize))
    $clampedIndex = [Math]::Max(0, [Math]::Min($PageIndex, $totalPages - 1))
    $start = $clampedIndex * $PageSize
    $end = [Math]::Min($start + $PageSize, $Items.Count)

    return [PSCustomObject]@{
        Items      = @($Items[$start..($end - 1)])
        PageIndex  = $clampedIndex
        TotalPages = $totalPages
        StartIndex = $start
        EndIndex   = $end
    }
}

function Set-WtSelectionToggle {
    <#
    .SYNOPSIS
        Toggles $Item.Name in/out of $SelectionSet, keyed by name (not
        page-relative index) so a selection survives paging away and back.
        Refuses to add an item whose .Selectable is $false (already in the
        target state - e.g. an absent service or a removed package).
    #>
    param(
        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [System.Collections.Generic.HashSet[string]]$SelectionSet,

        [Parameter(Mandatory)]
        [PSCustomObject]$Item
    )

    if ($SelectionSet.Contains($Item.Name)) {
        $SelectionSet.Remove($Item.Name) | Out-Null
    }
    elseif ($Item.Selectable) {
        $SelectionSet.Add($Item.Name) | Out-Null
    }

    return $SelectionSet
}

function Test-WtSelectionNeedsAdvancedConfirm {
    <#
    .SYNOPSIS
        True when the selected names include at least one catalog entry
        tagged ADVANCED.
    #>
    param(
        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [array]$Catalog,

        [Parameter(Mandatory)]
        [AllowNull()]
        [AllowEmptyCollection()]
        [object[]]$SelectionSet
    )

    $selectedNames = @($SelectionSet)
    if ($selectedNames.Count -eq 0) {
        return $false
    }

    $advancedSelected = $Catalog | Where-Object { $selectedNames -contains $_.Name -and $_.Risk -eq 'ADVANCED' }
    return @($advancedSelected).Count -gt 0
}

function Get-WtSelectorDisplayLabel {
    <#
    .SYNOPSIS
        What Show-WtSelector should render for one catalog entry: its own
        DisplayLabel when the catalog supplies a non-empty one, falling
        back to Name otherwise. The existing Services/Packages catalogs
        supply no DisplayLabel and render exactly as before this function
        existed - purely additive.
    #>
    param(
        [Parameter(Mandatory)]
        [PSCustomObject]$Entry
    )

    if ($Entry.PSObject.Properties.Name -contains 'DisplayLabel' -and $Entry.DisplayLabel) {
        return $Entry.DisplayLabel
    }
    return $Entry.Name
}

function Show-WtSelector {
    <#
    .SYNOPSIS
        Interactive multi-select over a catalog on the arrow-key TUI
        engine: Up/Down move, Space toggles, digits jump-toggle the
        visible row, A/C select/clear all on the viewport, Enter
        confirms, Left/Esc/q cancels. An ADVANCED item in the selection
        requires typing CONFIRM; anything else drops the ADVANCED items
        and keeps the rest. Returns the confirmed names, empty if the
        user quit. -PageSize is unused - kept only for signature
        stability; the TUI engine paginates by viewport height instead.
    #>
    param(
        [Parameter(Mandatory)]
        [array]$Catalog,

        [Parameter(Mandatory)]
        [array]$StateItems,

        [string]$Title = 'Select items',

        [int]$PageSize = 10,

        [string]$UnselectableNote = (Get-Translation 'AlreadyInTargetState'),

        [string[]]$InfoLines = @()
    )

    $stateByName = @{}
    foreach ($state in $StateItems) { $stateByName[$state.Name] = $state }

    $infoItems = @($InfoLines | Where-Object { $_ } | ForEach-Object { [PSCustomObject]@{ Kind = 'Info'; Name = ('Info:' + $_); Label = $_; Risk = $null; StateLabel = ''; Selectable = $false; Data = $null } })
    $selectorItems = foreach ($entry in $Catalog) {
        $state = $stateByName[$entry.Name]
        $selectable = if ($state) { [bool]$state.Selectable } else { $true }
        $stateLabel = if ($state) { [string]$state.StateLabel } else { Get-Translation 'StateUnknown' }
        if (-not $selectable) { $stateLabel = $stateLabel + $UnselectableNote }
        [PSCustomObject]@{
            Kind = 'Check'; Name = $entry.Name
            Label = (Get-WtSelectorDisplayLabel -Entry $entry)
            Risk = $entry.Risk; StateLabel = $stateLabel
            Selectable = $selectable; Data = $entry
        }
    }

    $selection = New-Object 'System.Collections.Generic.HashSet[string]'
    while ($true) {
        $r = Invoke-WtListScreen -Breadcrumb $Title -Items @($infoItems + @($selectorItems)) -MultiSelect $true `
            -Selection $selection -FooterText (Get-Translation 'SelectorFooter') -CounterText ((Get-Translation 'SettingsCount') -f $Catalog.Count)
        if ($r.Emit -eq 'Back' -or $r.Emit -eq 'Quit') { return @() }
        if ($r.Emit -eq 'Activate') {
            if (Test-WtSelectionNeedsAdvancedConfirm -Catalog $Catalog -SelectionSet @($selection)) {
                $advancedEntries = $Catalog | Where-Object { $selection.Contains($_.Name) -and $_.Risk -eq 'ADVANCED' }
                $advancedTag = Get-WtRiskLabel -Risk 'ADVANCED'
                $lines = @(((Get-Translation 'SelectorAdvancedHeader') -f $advancedTag)) + @($advancedEntries | ForEach-Object { "  - $($_.Name): $($_.Consequence)" })
                $typed = Read-WtPanelAnswer -Breadcrumb $Title -Lines $lines -Prompt ((Get-Translation 'SelectorAdvancedPrompt') -f $advancedTag, (Get-WtTypedWord -Kind 'Confirm')) -Risk 'ADVANCED'
                if (-not (Test-WtTypedConfirmation -Answer $typed -Kind 'Confirm')) {
                    foreach ($advancedEntry in $advancedEntries) { $selection.Remove($advancedEntry.Name) | Out-Null }
                }
            }
            return @($selection)
        }
    }
}
#endregion src/20-tui/selector.ps1

#region src/20-tui/window.ps1
# Set-WindowSize, the window lock and the console window icon.
# Covered by: tests/Guard.Tests.ps1, tests/WindowLock.Tests.ps1

function Set-WindowSize {
    <#
    .SYNOPSIS
        Sets the console window and buffer to a target size (falling back
        to a fixed 120x65 default). The buffer is grown before the
        window, since Windows never allows a window larger than its
        buffer, then pinned back to match so there is no scrollback and
        (0,0) is always the visible top-left. Returns $false, never
        throws, when the console does not support resizing.
    #>
    param (
        [int]$contentWidth = 120,
        [int]$contentHeight = 65
    )

    try {
        $pswindow = $Host.UI.RawUI
        $Host.UI.RawUI.WindowTitle = Get-WtWindowTitle
        $max = $pswindow.MaxWindowSize
        $targetW = [Math]::Min($contentWidth, [int]$max.Width)
        $targetH = [Math]::Min($contentHeight, [int]$max.Height)
        $current = $pswindow.WindowSize
        if ($current.Width -lt $targetW -or $current.Height -lt $targetH) {
            $buf = $pswindow.BufferSize
            $buf.Width = [Math]::Max([int]$buf.Width, $targetW)
            $buf.Height = [Math]::Max([int]$buf.Height, $targetH)
            $pswindow.BufferSize = $buf
            $win = $pswindow.WindowSize
            $win.Width = [Math]::Max([int]$current.Width, $targetW)
            $win.Height = [Math]::Max([int]$current.Height, $targetH)
            $pswindow.WindowSize = $win
        }
        $pswindow.BufferSize = $pswindow.WindowSize
        return $true
    }
    catch {
        Write-Host (Get-Translation 'WindowSizeFailed') -ForegroundColor Yellow
        return $false
    }
}

$script:WtWindowNativeSource = @'
using System;
using System.Runtime.InteropServices;
public static class WtWindowNative
{
    [DllImport("kernel32.dll")] public static extern IntPtr GetConsoleWindow();
    [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
    [DllImport("user32.dll")] public static extern bool IsZoomed(IntPtr hWnd);
    [DllImport("user32.dll")] public static extern int GetWindowLong(IntPtr hWnd, int nIndex);
    [DllImport("user32.dll")] public static extern int SetWindowLong(IntPtr hWnd, int nIndex, int dwNewLong);
    [DllImport("user32.dll")] public static extern bool SetWindowPos(IntPtr hWnd, IntPtr hWndInsertAfter, int x, int y, int cx, int cy, uint uFlags);
    [DllImport("user32.dll")] public static extern IntPtr GetSystemMenu(IntPtr hWnd, bool bRevert);
    [DllImport("user32.dll")] public static extern bool DeleteMenu(IntPtr hMenu, uint uPosition, uint uFlags);
    [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
    [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr hWnd, uint Msg, IntPtr wParam, IntPtr lParam);
    [DllImport("user32.dll")] public static extern IntPtr CreateIconFromResourceEx(byte[] pbIconBits, uint cbIconBits, bool fIcon, uint dwVer, int cxDesired, int cyDesired, uint uFlags);
    [DllImport("user32.dll")] public static extern bool DestroyIcon(IntPtr hIcon);
}
'@

function Get-WtLockedWindowStyle {
    <#
    .SYNOPSIS
        GWL_STYLE value without WS_THICKFRAME (sizing border), WS_MAXIMIZEBOX
        (restore box, caption double-click) and WS_MINIMIZEBOX (minimize
        box, taskbar minimize). Pure; every other bit is kept.
    #>
    param([int]$Style)
    return [int]($Style -band (-bnot ([int]0x00040000 -bor [int]0x00010000 -bor [int]0x00020000)))
}

function Sync-WtBufferToWindow {
    <#
    .SYNOPSIS
        Pins the buffer to the window size so there is no scrollback and
        (0,0) is always the visible top-left. Skipped while the assistant
        REPL is open, which keeps a tall scrollback on purpose and whose
        BufferSize resize is exactly the console path known to FAST_FAIL.
    #>
    param([scriptblock]$Apply = {
        $raw = $Host.UI.RawUI
        for ($i = 0; $i -lt 2; $i++) { $raw.BufferSize = $raw.WindowSize }
    })
    if ($script:WtReplMode) { return }
    try { & $Apply } catch { $null = $_ }
}

function Lock-WtWindow {
    <#
    .SYNOPSIS
        Maximizes the console window and removes the ways to shrink it
        (sizing border, minimize/maximize boxes, the system menu's
        Restore/Move/Size/Minimize/Maximize). Inside Windows Terminal,
        GetConsoleWindow returns a hidden pseudo-console that ShowWindow
        would make visible, so only the terminal's own foreground window
        is maximized there and nothing is locked. Returns the state
        Unlock-WtWindow needs, kept in $script:WtWindowLock; $null when
        there is no console window or any call fails.
    #>
    param([scriptblock]$Apply = {
        if (-not ('WtWindowNative' -as [type])) { Add-Type -TypeDefinition $script:WtWindowNativeSource -ErrorAction Stop }
        if ($env:WT_SESSION) {
            $fg = [WtWindowNative]::GetForegroundWindow()
            $ownerPid = [uint32]0
            $null = [WtWindowNative]::GetWindowThreadProcessId($fg, [ref]$ownerPid)
            if ($ownerPid -gt 0 -and (Get-Process -Id $ownerPid -ErrorAction SilentlyContinue).ProcessName -eq 'WindowsTerminal') {
                $null = [WtWindowNative]::ShowWindow($fg, 3)
            }
            return $null
        }
        $hwnd = [WtWindowNative]::GetConsoleWindow()
        if ($hwnd -eq [IntPtr]::Zero) { return $null }
        $null = [WtWindowNative]::ShowWindow($hwnd, 3)
        $style = [WtWindowNative]::GetWindowLong($hwnd, -16)
        $null = [WtWindowNative]::SetWindowLong($hwnd, -16, (Get-WtLockedWindowStyle -Style $style))
        $null = [WtWindowNative]::SetWindowPos($hwnd, [IntPtr]::Zero, 0, 0, 0, 0, [uint32]0x27)
        $menu = [WtWindowNative]::GetSystemMenu($hwnd, $false)
        foreach ($sc in 0xF120, 0xF010, 0xF000, 0xF020, 0xF030) {
            $null = [WtWindowNative]::DeleteMenu($menu, [uint32]$sc, 0)
        }
        Sync-WtBufferToWindow
        return @{ Handle = $hwnd; Style = $style }
    })
    $script:WtWindowLock = $null
    try { $state = & $Apply } catch { $state = $null }
    if ($null -eq $state) { return $null }
    $script:WtWindowLock = $state
    return $state
}

function Unlock-WtWindow {
    <#
    .SYNOPSIS
        Puts the original window style and system menu back, so a console
        the user opened themselves behaves normally again. No-op when
        Lock-WtWindow never took; never throws.
    #>
    param([scriptblock]$Apply = { param($State)
        $null = [WtWindowNative]::SetWindowLong($State.Handle, -16, [int]$State.Style)
        $null = [WtWindowNative]::SetWindowPos($State.Handle, [IntPtr]::Zero, 0, 0, 0, 0, [uint32]0x27)
        $null = [WtWindowNative]::GetSystemMenu($State.Handle, $true)
    })
    $state = $script:WtWindowLock
    $script:WtWindowLock = $null
    if ($null -eq $state) { return }
    try { $null = & $Apply $state } catch { $null = $_ }
}

function Assert-WtWindowMaximized {
    <#
    .SYNOPSIS
        Maximizes the locked window again when something restored or
        minimized it: Win+Down, a caption drag, a programmatic SC_RESTORE
        - none of these check the removed style bits. Called before every
        blocking input wait, next to Assert-WtTuiCtrlCInput; one cheap
        IsZoomed query when nothing changed. No-op without a lock; never
        throws. Returns $true when it had to maximize.
    #>
    param(
        [scriptblock]$IsZoomed = { param($Handle) [bool][WtWindowNative]::IsZoomed($Handle) },
        [scriptblock]$Maximize = { param($Handle) $null = [WtWindowNative]::ShowWindow($Handle, 3); Sync-WtBufferToWindow }
    )
    $state = $script:WtWindowLock
    if ($null -eq $state) { return $false }
    try {
        if ([bool](& $IsZoomed $state.Handle)) { return $false }
        $null = & $Maximize $state.Handle
        return $true
    }
    catch { return $false }
}

function Set-WtWindowIcon {
    <#
    .SYNOPSIS
        Puts the WinToolify logo on the console window - title bar,
        Alt+Tab and the taskbar - in place of the host's own PowerShell
        icon. WM_SETICON takes one handle per slot, so the embedded logo
        becomes a 16- and a 32-pixel icon at its own size rather than one
        bitmap Windows shrinks twice. CreateIconFromResourceEx reads a
        PNG directly on Vista and later, which keeps this on user32 next
        to the rest of the window work instead of pulling System.Drawing
        into a script that loads no other assembly. Inside Windows
        Terminal GetConsoleWindow is a hidden pseudo-console and the tab
        icon comes from the profile, so nothing is set there - the same
        case Lock-WtWindow steps around. What the window had is kept in
        $script:WtWindowIcon for Restore-WtWindowIcon. Returns $false and
        changes nothing when there is no window to brand; never throws.
    #>
    param([scriptblock]$Apply = {
        if ($env:WT_SESSION) { return $null }
        if (-not ('WtWindowNative' -as [type])) { Add-Type -TypeDefinition $script:WtWindowNativeSource -ErrorAction Stop }
        $hwnd = [WtWindowNative]::GetConsoleWindow()
        if ($hwnd -eq [IntPtr]::Zero) { return $null }
        $bytes = [byte[]][Convert]::FromBase64String([string](Get-WtWinToolifyLogoBase64))
        $set = New-Object System.Collections.Generic.List[object]
        foreach ($slot in @(@{ Which = 0; Size = 16 }, @{ Which = 1; Size = 32 })) {
            $made = [WtWindowNative]::CreateIconFromResourceEx($bytes, [uint32]$bytes.Length, $true, 0x00030000, [int]$slot.Size, [int]$slot.Size, 0)
            if ($made -eq [IntPtr]::Zero) { continue }
            $previous = [WtWindowNative]::SendMessage($hwnd, 0x0080, [IntPtr][int]$slot.Which, $made)
            $set.Add(@{ Which = [int]$slot.Which; Made = $made; Previous = $previous })
        }
        if ($set.Count -eq 0) { return $null }
        return @{ Handle = $hwnd; Icons = $set.ToArray() }
    })
    $script:WtWindowIcon = $null
    try { $state = & $Apply } catch { $state = $null }
    if ($null -eq $state) { return $false }
    $script:WtWindowIcon = $state
    return $true
}

function Restore-WtWindowIcon {
    <#
    .SYNOPSIS
        Gives the console window its own icon back and frees the ones
        this script made, so a console the user opened themselves is not
        left branded once WinToolify exits. A saved handle of zero goes
        back as zero on purpose: that is the window saying it had no icon
        of its own and drew its class icon, which is what it will draw
        again. No-op when Set-WtWindowIcon never took; never throws.
    #>
    param([scriptblock]$Apply = { param($State)
        foreach ($icon in @($State.Icons)) {
            $null = [WtWindowNative]::SendMessage([IntPtr]$State.Handle, 0x0080, [IntPtr][int]$icon.Which, [IntPtr]$icon.Previous)
            if ([IntPtr]$icon.Made -ne [IntPtr]::Zero) { $null = [WtWindowNative]::DestroyIcon([IntPtr]$icon.Made) }
        }
    })
    $state = $script:WtWindowIcon
    $script:WtWindowIcon = $null
    if ($null -eq $state) { return }
    try { $null = & $Apply $state } catch { $null = $_ }
}
#endregion src/20-tui/window.ps1

#region src/30-engine/apply.ps1
# Apply records, commit plan, change-set commit, apply gates.
# Covered by: tests/ApplyEngine.Tests.ps1, tests/ApplyFlow.Tests.ps1

function New-WtApplyRecord {
    <#
    .SYNOPSIS
        One "apply this entry" record in the shape Get-WtCommitPlan
        consumes. Records are built from a screen's marks at apply time
        and live only for that apply - nothing is staged across screens.
        Direction: Apply writes the target, Remove writes the Windows
        default, derived from the row's Applied flag.
    #>
    param(
        [Parameter(Mandatory)][string]$SectionKey,
        [Parameter(Mandatory)][string]$EntryName,
        [string]$DisplayLabel = '',
        [ValidateSet('SAFE', 'CAUTION', 'ADVANCED')][string]$Risk = 'SAFE',
        [bool]$RestartsExplorer = $false,
        [bool]$RequiresReboot = $false,
        [hashtable]$Data,
        [ValidateSet('Apply', 'Remove')][string]$Direction = 'Apply'
    )
    $label = if ($DisplayLabel) { $DisplayLabel } else { $EntryName }
    return [PSCustomObject]@{
        SectionKey       = $SectionKey
        EntryName        = $EntryName
        DisplayLabel     = $label
        Risk             = $Risk
        RestartsExplorer = $RestartsExplorer
        RequiresReboot   = $RequiresReboot
        Data             = $Data
        Direction        = $Direction
    }
}

function ConvertTo-WtApplyRecords {
    <#
    .SYNOPSIS
        Marked names -> apply records, via the screen's Meta map
        (Name -> @{ SectionKey; Entry; Data }). Names without Meta are
        ignored (group headers, info rows never reach the selection).
        Items (the screen's rows) decides the direction: a marked name
        whose row is Applied becomes a Remove record.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][System.Collections.Generic.HashSet[string]]$Selection,
        [Parameter(Mandatory)][AllowEmptyCollection()][hashtable]$Meta,
        [AllowEmptyCollection()][array]$Items = @(),
        [hashtable]$Cycle = @{}
    )
    $appliedNames = New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($item in @($Items)) {
        if (($item.PSObject.Properties.Name -contains 'Applied') -and [bool]$item.Applied) { $appliedNames.Add([string]$item.Name) | Out-Null }
    }
    $records = New-Object System.Collections.Generic.List[object]
    foreach ($name in @(@($Selection) | Sort-Object)) {
        if (-not $Meta.ContainsKey($name)) { continue }
        $m = $Meta[$name]
        $entry = $m.Entry
        $props = $entry.PSObject.Properties.Name
        $args = @{
            SectionKey       = [string]$m.SectionKey
            EntryName        = [string]$name
            DisplayLabel     = (Get-WtSelectorDisplayLabel -Entry $entry)
            Risk             = $(if ($props -contains 'Risk' -and $entry.Risk) { [string]$entry.Risk } else { 'SAFE' })
            RestartsExplorer = [bool](($props -contains 'RestartsExplorer') -and $entry.RestartsExplorer)
            RequiresReboot   = [bool](($props -contains 'RestartRequired') -and $entry.RestartRequired)
            Direction        = $(if ($appliedNames.Contains([string]$name)) { 'Remove' } else { 'Apply' })
        }
        if ($m.Data) { $args['Data'] = [hashtable]$m.Data }
        if ($Cycle.ContainsKey([string]$name)) {
            $data = $(if ($args.ContainsKey('Data')) { @{} + $args['Data'] } else { @{} })
            $data['Target'] = [string]$Cycle[[string]$name]
            $args['Data'] = $data
        }
        $records.Add((New-WtApplyRecord @args))
    }
    return $records.ToArray()
}

function Get-WtCommitPlan {
    <#
    .SYNOPSIS
        Pure planning half of an apply: orders records by section-catalog
        priority and pre-computes every gate the summary needs (ADVANCED
        CONFIRM, non-restorable-package YES, Explorer/reboot). Each
        section plan splits names into ApplyNames/RemoveNames, and a
        cycling screen (Services) gets a Targets map alongside Data,
        since one Data slot cannot hold a per-row target.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$ChangeSet,
        [array]$Sections = (Get-WtApplySectionCatalog),
        [scriptblock]$GetPackageCatalog = { Get-WtPackageCatalog }
    )

    $sectionPlans = New-Object System.Collections.Generic.List[object]
    foreach ($section in $Sections) {
        $entries = @($ChangeSet | Where-Object { $_.SectionKey -eq $section.Key })
        if ($entries.Count -eq 0) { continue }
        if ($section.Key -eq 'Firewall' -and $entries.Count -gt 1) { $entries = @($entries[-1]) }
        $data = $null
        foreach ($e in $entries) { if ($e.Data) { $data = $e.Data; break } }
        $targets = @{}
        foreach ($e in $entries) { if ($e.Data -and $e.Data.ContainsKey('Target')) { $targets[[string]$e.EntryName] = [string]$e.Data['Target'] } }
        if ($targets.Count -gt 0) {
            $data = $(if ($data) { @{} + $data } else { @{} })
            $data['Targets'] = $targets
        }
        $sectionPlans.Add([PSCustomObject]@{
            Key              = $section.Key
            TitleKey         = $section.TitleKey
            RestartsExplorer = [bool]$section.RestartsExplorer
            EntryNames       = [string[]]@($entries | ForEach-Object EntryName)
            ApplyNames       = [string[]]@($entries | Where-Object { $_.Direction -ne 'Remove' } | ForEach-Object EntryName)
            RemoveNames      = [string[]]@($entries | Where-Object { $_.Direction -eq 'Remove' } | ForEach-Object EntryName)
            Entries          = $entries
            Data             = $data
        })
    }

    $knownKeys = @($Sections | ForEach-Object Key)
    $pkgCatalog = @(& $GetPackageCatalog)
    $nonRestorable = @($ChangeSet | Where-Object { $_.SectionKey -eq 'Packages' } | Where-Object {
        $entryName = $_.EntryName
        $catalogEntry = $pkgCatalog | Where-Object Name -eq $entryName | Select-Object -First 1
        ($catalogEntry -and -not $catalogEntry.Restorable)
    } | ForEach-Object EntryName)

    return [PSCustomObject]@{
        Sections                  = $sectionPlans.ToArray()
        UnknownEntries            = @($ChangeSet | Where-Object { $knownKeys -notcontains $_.SectionKey })
        AdvancedEntries           = @($ChangeSet | Where-Object { $_.Risk -eq 'ADVANCED' -and $_.Direction -ne 'Remove' })
        NonRestorablePackageNames = [string[]]$nonRestorable
        HasExplorerRestart        = (@($sectionPlans | Where-Object RestartsExplorer).Count -gt 0)
        RebootEntryNames          = [string[]]@($ChangeSet | Where-Object RequiresReboot | ForEach-Object EntryName)
    }
}

function New-WtSectionFailureRow {
    <#
    .SYNOPSIS
        PURE: the result row Invoke-WtCommitChangeSet reports for one entry
        whose section delegate threw. Same shape every Apply delegate
        returns, so Get-WtApplyResultLines prints it as
        "<name>: Not applied - <message>" with no special case.
    #>
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][AllowEmptyString()][string]$Message,
        [Parameter(Mandatory)][ValidateSet('Apply', 'Remove')][string]$Direction
    )
    return [PSCustomObject]@{
        Item      = [PSCustomObject]@{ Name = $Name }
        Applied   = $false
        Error     = $Message
        Direction = $Direction
    }
}

function Invoke-WtCommitChangeSet {
    <#
    .SYNOPSIS
        The apply half of the commit: every planned section through its
        guarded Apply delegate for the Apply names, then TurnOff for the
        Remove names, one undo entry per section - all interactive gates
        already ran before this is called. A section whose TurnOff half
        aborts still reports the rows its Apply half already wrote, and
        those count toward NeedsExplorerRestart/RebootEntryNames since
        the writes already happened. A delegate that throws is contained
        as a failed row per entry; any other exception still unwinds the
        navigation loop and closes the window.
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Plan,
        [array]$Sections = (Get-WtApplySectionCatalog),
        [scriptblock]$OnSectionStart
    )

    $outcomes = New-Object System.Collections.Generic.List[object]
    $aborted = $false
    foreach ($sectionPlan in @($Plan.Sections)) {
        $section = $Sections | Where-Object Key -eq $sectionPlan.Key | Select-Object -First 1
        $outcome = 'NothingToApply'
        $results = @()
        if ($aborted) { $outcome = 'Skipped' }
        elseif ($section -and @($sectionPlan.EntryNames).Count -gt 0) {
            if ($OnSectionStart) { & $OnSectionStart $sectionPlan.Key }
            $applyNames = [string[]]@($sectionPlan.ApplyNames)
            $removeNames = [string[]]@($sectionPlan.RemoveNames)
            $rows = New-Object System.Collections.Generic.List[object]
            $sectionAborted = $false
            if ($applyNames.Count -gt 0) {
                $applyResult = $null
                try { $applyResult = & $section.Apply $applyNames $sectionPlan.Data }
                catch { foreach ($n in $applyNames) { $rows.Add((New-WtSectionFailureRow -Name $n -Message $_.Exception.Message -Direction 'Apply')) } }
                if ($applyResult -and $applyResult.Aborted) { $sectionAborted = $true }
                elseif ($applyResult) {
                    foreach ($row in @($applyResult.Results)) { $rows.Add(($row | Add-Member -NotePropertyName 'Direction' -NotePropertyValue 'Apply' -Force -PassThru)) }
                }
            }
            if (-not $sectionAborted -and $removeNames.Count -gt 0) {
                $turnOff = $section.TurnOff
                if ($turnOff) {
                    $removeResult = $null
                    try { $removeResult = & $turnOff $removeNames $sectionPlan.Data }
                    catch { foreach ($n in $removeNames) { $rows.Add((New-WtSectionFailureRow -Name $n -Message $_.Exception.Message -Direction 'Remove')) } }
                    if ($removeResult -and $removeResult.Aborted) { $sectionAborted = $true }
                    elseif ($removeResult) {
                        foreach ($row in @($removeResult.Results)) { $rows.Add(($row | Add-Member -NotePropertyName 'Direction' -NotePropertyValue 'Remove' -Force -PassThru)) }
                    }
                }
                else {
                    foreach ($n in $removeNames) {
                        $rows.Add([PSCustomObject]@{ Item = [PSCustomObject]@{ Name = $n }; Applied = $false; Error = (Get-Translation 'RemoveUnavailable'); Direction = 'Remove' })
                    }
                }
            }
            $results = $rows.ToArray()
            if ($sectionAborted) { $outcome = 'Aborted'; $aborted = $true }
            else { $outcome = 'Applied' }
        }
        $outcomes.Add([PSCustomObject]@{
            Key              = $sectionPlan.Key
            TitleKey         = $sectionPlan.TitleKey
            RestartsExplorer = [bool]$sectionPlan.RestartsExplorer
            Outcome          = $outcome
            Results          = $results
        })
    }

    $needsExplorer = $false
    $anyApplied = $false
    foreach ($o in $outcomes) {
        if (@($o.Results | Where-Object Applied).Count -gt 0) {
            $anyApplied = $true
            if ($o.RestartsExplorer) { $needsExplorer = $true }
        }
    }
    $rebootNames = if ($anyApplied) { [string[]]@($Plan.RebootEntryNames) } else { [string[]]@() }

    return [PSCustomObject]@{
        Aborted              = $aborted
        Sections             = $outcomes.ToArray()
        NeedsExplorerRestart = $needsExplorer
        RebootEntryNames     = $rebootNames
    }
}

function ConvertTo-WtBlocklistMechanism {
    param([AllowNull()][AllowEmptyString()][string]$Answer)
    switch (([string]$Answer).Trim()) {
        '1' { return 'Hosts' }
        '2' { return 'Firewall' }
        '3' { return 'Both' }
        default { return $null }
    }
}

function Invoke-WtApplyGates {
    <#
    .SYNOPSIS
        Every confirmation an apply needs, collected BEFORE anything is
        applied: ADVANCED -> typed CONFIRM, non-restorable packages ->
        typed YES, DNS preset -> disclosure + typed YES, blocklist tiers
        -> mechanism 1/2/3. Returns the surviving records and their
        commit plan. Named $recordList, not $records: PowerShell's
        case-insensitive scoping would otherwise alias the -Records
        parameter, coercing every reassignment back to a plain array and
        losing the List[object] surface this function needs.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Records,
        [array]$Sections = (Get-WtApplySectionCatalog),
        [scriptblock]$GetPackageCatalog = { Get-WtPackageCatalog },
        [scriptblock]$ReadAnswer = { param($Lines, $Prompt, $Risk) Read-WtPanelAnswer -Breadcrumb $script:WtPanelBreadcrumb -Lines $Lines -Prompt $Prompt -Risk $Risk },
        [switch]$PreApprovedAdvanced,
        [scriptblock]$GetDnsDisclosure = {
            param($PresetName)
            $preset = (Get-WtDnsPresetCatalog) | Where-Object Name -eq $PresetName | Select-Object -First 1
            $adapterNames = ''
            if ($preset) {
                try {
                    $adapters = @(Get-WtDnsAdapterCaptureState -Preset $preset -DohSupported (Test-WtDohSupported))
                    $adapterNames = ($adapters | ForEach-Object { "Adapter $($_.InterfaceIndex)" }) -join ', '
                }
                catch { $adapterNames = '?' }
            }
            (Get-Translation 'DnsChangeConsequence') -f $adapterNames, $PresetName
        }
    )
    $recordList = New-Object System.Collections.Generic.List[object]
    foreach ($r in $Records) { $recordList.Add($r) }
    $dropNames = {
        param($Key, [string[]]$Names)
        for ($i = $recordList.Count - 1; $i -ge 0; $i--) {
            if ($recordList[$i].SectionKey -eq $Key -and $Names -contains $recordList[$i].EntryName) { $recordList.RemoveAt($i) }
        }
    }
    $replan = { Get-WtCommitPlan -ChangeSet $recordList.ToArray() -Sections $Sections -GetPackageCatalog $GetPackageCatalog }
    $plan = & $replan
    $typedConfirmation = $false
    $dropped = New-Object System.Collections.Generic.List[object]
    $labelsFor = {
        param($Key, [string[]]$Names)
        [string[]]@($recordList | Where-Object { $_.SectionKey -eq $Key -and $Names -contains $_.EntryName } | ForEach-Object DisplayLabel)
    }

    foreach ($u in @($plan.UnknownEntries)) { & $dropNames $u.SectionKey @($u.EntryName) }
    if (@($plan.UnknownEntries).Count -gt 0) { $plan = & $replan }

    if ($PreApprovedAdvanced -and @($plan.AdvancedEntries).Count -gt 0) { $typedConfirmation = $true }
    elseif (@($plan.AdvancedEntries).Count -gt 0) {
        $advancedTag = Get-WtRiskLabel -Risk 'ADVANCED'
        $lines = @(((Get-Translation 'SelectorAdvancedHeader') -f $advancedTag))
        foreach ($rec in @($plan.AdvancedEntries)) {
            $consequence = Get-WtRecordConsequence -Record $rec -Sections $Sections
            $lines += $(if ($consequence) { "  - $($rec.DisplayLabel): $consequence" } else { "  - $($rec.DisplayLabel)" })
        }
        $lines += ''
        $lines += (Get-WtGateWordHint -Kind 'Confirm')
        $typed = [string](& $ReadAnswer $lines ((Get-Translation 'SelectorAdvancedPrompt') -f $advancedTag, (Get-WtTypedWord -Kind 'Confirm')) 'ADVANCED')
        if (Test-WtTypedConfirmation -Answer $typed -Kind 'Confirm') { $typedConfirmation = $true }
        else {
            $dropped.Add([PSCustomObject]@{ Kind = 'Confirm'; Labels = [string[]]@($plan.AdvancedEntries | ForEach-Object DisplayLabel) })
            foreach ($rec in @($plan.AdvancedEntries)) { & $dropNames $rec.SectionKey @($rec.EntryName) }
            $plan = & $replan
        }
    }

    if ($PreApprovedAdvanced -and @($plan.NonRestorablePackageNames).Count -gt 0) { $typedConfirmation = $true }
    elseif (@($plan.NonRestorablePackageNames).Count -gt 0) {
        $lines = @((Get-Translation 'NonRestorableWarning')) + @($plan.NonRestorablePackageNames | ForEach-Object { "  - $_" })
        $lines += ''
        $lines += (Get-WtGateWordHint -Kind 'Yes')
        $typed = [string](& $ReadAnswer $lines ((Get-Translation 'TypeYesToConfirm') -f (Get-WtTypedWord -Kind 'Yes')) 'ADVANCED')
        if (Test-WtTypedConfirmation -Answer $typed -Kind 'Yes') { $typedConfirmation = $true }
        else {
            $dropped.Add([PSCustomObject]@{ Kind = 'Yes'; Labels = (& $labelsFor 'Packages' ([string[]]@($plan.NonRestorablePackageNames))) })
            & $dropNames 'Packages' ([string[]]@($plan.NonRestorablePackageNames))
            $plan = & $replan
        }
    }

    $dnsPlan = @($plan.Sections) | Where-Object Key -eq 'DnsPreset' | Select-Object -First 1
    if ($dnsPlan -and @($dnsPlan.EntryNames).Count -gt 0) {
        $presetName = [string]$dnsPlan.EntryNames[0]
        $dnsLines = @((& $GetDnsDisclosure $presetName), '', (Get-WtGateWordHint -Kind 'Yes'))
        $typed = [string](& $ReadAnswer $dnsLines ((Get-Translation 'TypeYesToConfirm') -f (Get-WtTypedWord -Kind 'Yes')) 'CAUTION')
        if (Test-WtTypedConfirmation -Answer $typed -Kind 'Yes') { $typedConfirmation = $true }
        else {
            $dropped.Add([PSCustomObject]@{ Kind = 'Yes'; Labels = (& $labelsFor 'DnsPreset' ([string[]]@($dnsPlan.EntryNames))) })
            & $dropNames 'DnsPreset' ([string[]]@($dnsPlan.EntryNames))
            $plan = & $replan
        }
    }

    $blPlan = @($plan.Sections) | Where-Object Key -eq 'Blocklist' | Select-Object -First 1
    if ($blPlan -and @($blPlan.EntryNames).Count -gt 0) {
        $lines = @((Get-Translation 'SelectMechanism'), ('  [1] ' + (Get-Translation 'HostsFile')), ('  [2] ' + (Get-Translation 'FirewallRules')), ('  [3] ' + (Get-Translation 'Both')))
        $mechanism = ConvertTo-WtBlocklistMechanism -Answer ([string](& $ReadAnswer $lines (Get-Translation 'YourChoice') 'CAUTION'))
        if ($mechanism) {
            foreach ($rec in @($recordList | Where-Object SectionKey -eq 'Blocklist')) { $rec.Data = @{ Mechanism = $mechanism } }
        }
        else {
            $dropped.Add([PSCustomObject]@{ Kind = 'Mechanism'; Labels = (& $labelsFor 'Blocklist' ([string[]]@($blPlan.EntryNames))) })
            & $dropNames 'Blocklist' ([string[]]@($blPlan.EntryNames))
        }
        $plan = & $replan
    }

    return @{ Records = $recordList.ToArray(); Plan = $plan; TypedConfirmation = $typedConfirmation; Dropped = $dropped.ToArray() }
}
#endregion src/30-engine/apply.ps1

#region src/30-engine/guarded-change.ps1
# Invoke-WtGuardedChange.
# Covered by: tests/FirewallFastStartup.Tests.ps1

function Invoke-WtGuardedChange {
    <#
    .SYNOPSIS
        Shared orchestrator behind both the service and package apply
        paths: capture pre-change state -> write undo entry -> apply per
        item -> re-read post-apply state. Order is load-bearing: applying
        before the undo entry is written means a crash mid-apply leaves no
        record of what to restore. The re-read runs after Apply returns
        regardless of whether Apply threw, since a cmdlet can succeed while
        policy or a pending reboot leaves the item unchanged.
    #>
    param(
        [Parameter(Mandatory)]
        [scriptblock]$CaptureState,

        [Parameter(Mandatory)]
        [scriptblock]$Apply,

        [Parameter(Mandatory)]
        [scriptblock]$ReReadState,

        [Parameter(Mandatory)]
        [ValidateSet('Machine', 'User')]
        [string]$Scope,

        [Parameter(Mandatory)]
        [string]$ActionName,

        [scriptblock]$WriteUndoAction = {
            param($Scope, $ActionName, $Items, $TestRootOverride)
            if ($TestRootOverride) {
                Write-WtUndoEntry -Scope $Scope -Action $ActionName -Items $Items -TestRootOverride $TestRootOverride
            }
            else {
                Write-WtUndoEntry -Scope $Scope -Action $ActionName -Items $Items
            }
        },

        [string]$TestRootOverride
    )

    $items = @(& $CaptureState)

    & $WriteUndoAction $Scope $ActionName $items $TestRootOverride | Out-Null

    $results = New-Object System.Collections.Generic.List[object]
    foreach ($item in $items) {
        $applyError = $null
        try {
            & $Apply $item
        }
        catch {
            $applyError = $_.Exception.Message
        }

        $applied = $false
        try {
            $applied = [bool](& $ReReadState $item)
        }
        catch {
            $applied = $false
        }

        $results.Add([PSCustomObject]@{
            Item    = $item
            Applied = $applied
            Error   = $applyError
        })
    }

    return [PSCustomObject]@{ Aborted = $false; Results = $results.ToArray() }
}
#endregion src/30-engine/guarded-change.ps1

#region src/30-engine/sections.ps1
# Get-WtApplySectionCatalog - section key -> apply/remove function dispatch table.
# Covered by: tests/ApplyEngine.Tests.ps1

function Get-WtApplySectionCatalog {
    <#
    .SYNOPSIS
        The apply engine's section table: every profile section plus the
        stage-only sections whose state is not cleanly diffable the way
        profiles need (DNS preset choice, downloaded blocklists, per-app
        permission sets). Stage-only rows carry StageOnly=$true and a
        $null GetState; profile export/import never sees them. Apply
        delegates here take (Names, Data) - profile rows ignore the
        second argument via $args.
    #>
    $stageOnly = @(
        [PSCustomObject]@{
            Key = 'DnsPreset'; TitleKey = 'DnsPreset'; RestartsExplorer = $false; StageOnly = $true
            GetCatalog = { Get-WtDnsPresetCatalog }; GetState = $null
            Apply = { param([string[]]$Names, $Data) Invoke-WtApplyDnsPreset -PresetName $Names[0] -SkipConfirmation }
        }
        [PSCustomObject]@{
            Key = 'Blocklist'; TitleKey = 'BlocklistSection'; RestartsExplorer = $false; StageOnly = $true
            GetCatalog = { Get-WtBlocklistTierCatalog }; GetState = $null
            Apply = { param([string[]]$Names, $Data) Invoke-WtApplyBlocklistSelection -SelectedTiers $Names -Mechanism $Data.Mechanism }
        }
        [PSCustomObject]@{
            Key = 'PerAppPermissions'; TitleKey = 'PerAppPermissions'; RestartsExplorer = $false; StageOnly = $true
            GetCatalog = { @() }; GetState = $null
            Apply = { param([string[]]$Names, $Data) Invoke-WtApplyPerAppPermissionGroups -Names $Names -Sid $Data.Sid }
            TurnOff = { param([string[]]$Names, $Data) Invoke-WtApplyPerAppPermissionGroups -Names $Names -Sid $Data.Sid -Value 'Allow' }
        }
    )

    $result = New-Object System.Collections.Generic.List[object]
    $spliced = $false
    foreach ($row in @(Get-WtProfileSectionCatalog)) {
        if (-not $spliced -and $row.RestartsExplorer) {
            foreach ($s in $stageOnly) { $result.Add($s) }
            $spliced = $true
        }
        $result.Add($row)
    }
    if (-not $spliced) { foreach ($s in $stageOnly) { $result.Add($s) } }
    return $result.ToArray()
}
#endregion src/30-engine/sections.ps1

#region src/30-engine/undo.ps1
# Undo log: write, read, restore, closed/retired state.
# Covered by: tests/UndoLog.Tests.ps1, tests/UndoRetire.Tests.ps1

function Write-WtUndoEntry {
    <#
    .SYNOPSIS
        Records the pre-change state of a set of items as one JSON file
        under the scope-appropriate undo\ directory, named
        yyyyMMdd-HHmmss-<action>.json. Must be called with state captured
        BEFORE the change is applied - a backup written afterwards records
        the new state and is worthless for undo.
    #>
    param(
        [Parameter(Mandatory)]
        [ValidateSet('Machine', 'User')]
        [string]$Scope,

        [Parameter(Mandatory)]
        [string]$Action,

        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [array]$Items,

        [string]$TestRootOverride
    )

    $timestamp = Get-Date
    $id = '{0}-{1}' -f $timestamp.ToString('yyyyMMdd-HHmmss'), $Action

    $dataPathArgs = @{ Scope = $Scope; SubPath = 'undo' }
    if ($TestRootOverride) { $dataPathArgs['TestRootOverride'] = $TestRootOverride }
    $undoDir = Get-WtDataPath @dataPathArgs
    $entryPath = Join-Path $undoDir "$id.json"

    $entry = [PSCustomObject]@{
        Id        = $id
        Timestamp = $timestamp.ToString('o')
        Action    = $Action
        Scope     = $Scope
        Items     = $Items
    }

    Write-WtJson -Path $entryPath -InputObject $entry
    return $entryPath
}

function Get-WtUndoEntries {
    <#
    .SYNOPSIS
        Reads both the Machine- and User-scoped undo\ directories and
        returns the merged set newest first, ordered by the recorded
        Timestamp field, not filename or mtime. A corrupt entry is skipped,
        not fatal, with Read-WtJson's warning captured (-WarningVariable)
        rather than printed, since this runs behind a painted frame.
    #>
    param(
        [string]$TestRootOverride
    )

    $entries = New-Object System.Collections.Generic.List[object]

    foreach ($scope in @('Machine', 'User')) {
        $dataPathArgs = @{ Scope = $scope; SubPath = 'undo' }
        if ($TestRootOverride) { $dataPathArgs['TestRootOverride'] = $TestRootOverride }
        $undoDir = Get-WtDataPath @dataPathArgs

        $files = Get-ChildItem -LiteralPath $undoDir -Filter '*.json' -File -ErrorAction SilentlyContinue
        foreach ($file in $files) {
            $entry = Read-WtJson -Path $file.FullName -WarningAction SilentlyContinue
            if ($null -eq $entry) {
                continue
            }
            $entry | Add-Member -NotePropertyName 'Path' -NotePropertyValue $file.FullName -Force
            $entries.Add($entry)
        }
    }

    return @($entries | Sort-Object -Property { [datetime]$_.Timestamp } -Descending)
}

function Restore-WtUndoEntry {
    <#
    .SYNOPSIS
        Restores every item in an undo entry and returns a per-item result
        (Restored / Failed / NotRestorable) rather than one aggregate verdict,
        in reverse capture order - load-bearing for a combined Ultimate
        Performance + core parking entry, where forward order would delete
        the Ultimate copy before the core-parking indexes could be written
        back into it. -ItemFilter (Item -> bool) restores only matching items
        for a per-setting revert, stamping each with its own RestoredAt; the
        entry is marked closed only once nothing restorable is left in it, and
        never deleted. Returns via .ToArray(), not @($results): wrapping a
        List[object] of PSCustomObjects directly in @() throws "Argument types
        do not match".
    #>
    param(
        [Parameter(Mandatory)]
        [string]$EntryPath,

        [scriptblock]$ItemFilter,

        [scriptblock]$RestoreServiceItem = {
            param($Item)
            if ($Item.PSObject.Properties.Name -contains 'PreviousTemplateStart' -and $null -ne $Item.PreviousTemplateStart) {
                Set-WtServiceTemplateStart -Template $Item.Template -Start ([int]$Item.PreviousTemplateStart)
            }
            Set-Service -Name $Item.Name -StartupType $Item.PreviousStartType -ErrorAction Stop
            if ($Item.PreviousStatus -eq 'Running') {
                Start-Service -Name $Item.Name -ErrorAction Stop
            }
            elseif ($Item.PreviousStatus -eq 'Stopped') {
                Stop-Service -Name $Item.Name -Force -ErrorAction Stop
            }
        },

        [scriptblock]$RestorePackageItem = {
            param($Item)
            if (-not $Item.InstallLocation) { return 'NotRestorable' }
            $manifestPath = Join-Path $Item.InstallLocation 'AppxManifest.xml'
            if (-not (Test-Path -LiteralPath $manifestPath)) {
                return 'NotRestorable'
            }
            if ($Item.IsProvisioned) {
                Add-AppxProvisionedPackage -Online -PackagePath $manifestPath -SkipLicense -ErrorAction Stop | Out-Null
            }
            else {
                Add-AppxPackage -Register $manifestPath -DisableDevelopmentMode -ErrorAction Stop
            }
            return 'Restored'
        },

        [scriptblock]$RestoreRegistryItem = {
            param($Item)
            if ($Item.PreviousPresent) {
                Set-WtRegistryValue -Path $Item.Path -Name $Item.Name -RegType $Item.RegType -Value $Item.PreviousValue
            }
            else {
                Remove-WtRegistryValue -Path $Item.Path -Name $Item.Name
            }
        },

        [scriptblock]$RestoreDnsItem = {
            param($Item)
            if (@($Item.PreviousIPv4).Count -eq 0 -and @($Item.PreviousIPv6).Count -eq 0) {
                Set-DnsClientServerAddress -InterfaceIndex $Item.InterfaceIndex -ResetServerAddresses
            }
            else {
                Set-DnsClientServerAddress -InterfaceIndex $Item.InterfaceIndex -ServerAddresses (@($Item.PreviousIPv4) + @($Item.PreviousIPv6))
            }
            foreach ($addr in @($Item.AddedDohAddresses)) {
                Remove-DnsClientDohServerAddress -ServerAddress $addr -Confirm:$false -ErrorAction SilentlyContinue
            }
            foreach ($prev in @($Item.PreviousDohEntries)) {
                try {
                    Set-DnsClientDohServerAddress -ServerAddress $prev.Address -DohTemplate $prev.Template -AllowFallbackToUdp ([bool]$prev.AllowFallbackToUdp) -AutoUpgrade ([bool]$prev.AutoUpgrade) -ErrorAction Stop
                }
                catch {
                    Add-DnsClientDohServerAddress -ServerAddress $prev.Address -DohTemplate $prev.Template -AllowFallbackToUdp ([bool]$prev.AllowFallbackToUdp) -AutoUpgrade ([bool]$prev.AutoUpgrade) -ErrorAction SilentlyContinue
                }
            }
        },

        [scriptblock]$RestoreHostsItem = {
            param($Item)
            $hostsPath = Join-Path $env:WinDir 'System32\drivers\etc\hosts'
            $content = [System.IO.File]::ReadAllText($hostsPath, [System.Text.Encoding]::UTF8)
            $updated = Remove-WtHostsBlocklistLines -Content $content -Lines $Item.Lines
            [System.IO.File]::WriteAllText($hostsPath, $updated, [System.Text.Encoding]::UTF8)
        },

        [scriptblock]$RestoreFirewallItem = {
            param($Item)
            foreach ($ruleName in @($Item.RuleNames)) {
                Remove-NetFirewallRule -DisplayName $ruleName -ErrorAction SilentlyContinue
            }
        },

        [scriptblock]$RestoreFirewallProfileItem = {
            param($Item)
            Set-NetFirewallProfile -Profile $Item.ProfileName -Enabled (ConvertTo-WtGpoBoolean -Enabled ([bool]$Item.WasEnabled))
        },

        [scriptblock]$RestoreHibernationItem = {
            param($Item)
            if ([bool]$Item.WasEnabled) { powercfg /h on } else { powercfg /h off }
        },

        [scriptblock]$RestorePowerPlanItem = {
            param($Item)
            Restore-WtPowerPlanItem -Item $Item
        },

        [scriptblock]$RestorePowerSettingItem = {
            param($Item)
            Restore-WtPowerSettingItem -Item $Item
        },

        [scriptblock]$RestoreRegistryKeyItem = {
            param($Item)
            Restore-WtRegistryKeyItem -Item $Item
        },

        [scriptblock]$RestoreRegistryKeyTreeItem = {
            param($Item)
            Restore-WtRegistryKeyTreeItem -Item $Item
        }
    )

    $entry = Read-WtJson -Path $EntryPath
    if ($null -eq $entry) {
        return @()
    }

    $results = New-Object System.Collections.Generic.List[object]
    $orderedItems = @($entry.Items)
    [array]::Reverse($orderedItems)
    $restoredItems = New-Object System.Collections.Generic.List[object]
    foreach ($item in $orderedItems) {
        if (Test-WtUndoItemClosed -Item $item) { continue }
        if ($ItemFilter -and -not (& $ItemFilter $item)) { continue }
        $itemName = switch ($item.ItemType) {
            'Service' { $item.Name }
            'Package' { $item.PackageFullName }
            'Registry' { "$($item.Path)\$($item.Name)" }
            'DnsConfig' { "Adapter $($item.InterfaceIndex)" }
            'HostsBlock' { "hosts ($($item.Tier), $(@($item.Lines).Count) lines)" }
            'FirewallBlock' { "$($item.Tier) firewall rules ($(@($item.RuleNames).Count))" }
            'FirewallProfile' { $item.Name }
            'HibernationState' { $item.Name }
            'PowerPlan' { "Power plan -> $($item.PreviousActiveScheme)" }
            'PowerSetting' { "$($item.SettingLabel) on $($item.SchemeGuid)" }
            'RegistryKey' { "$($item.Hive)\$($item.SubKey)" }
            'RegistryKeyTree' { "$($item.Hive)\$($item.SubKey)" }
            default { $item.ItemType }
        }
        $outcome = 'Failed'
        try {
            if ($item.ItemType -eq 'Service') {
                & $RestoreServiceItem $item
                $outcome = 'Restored'
            }
            elseif ($item.ItemType -eq 'Package') {
                $outcome = & $RestorePackageItem $item
            }
            elseif ($item.ItemType -eq 'Registry') {
                & $RestoreRegistryItem $item
                $outcome = 'Restored'
            }
            elseif ($item.ItemType -eq 'DnsConfig') {
                & $RestoreDnsItem $item
                $outcome = 'Restored'
            }
            elseif ($item.ItemType -eq 'HostsBlock') {
                & $RestoreHostsItem $item
                $outcome = 'Restored'
            }
            elseif ($item.ItemType -eq 'FirewallBlock') {
                & $RestoreFirewallItem $item
                $outcome = 'Restored'
            }
            elseif ($item.ItemType -eq 'FirewallProfile') {
                & $RestoreFirewallProfileItem $item
                $outcome = 'Restored'
            }
            elseif ($item.ItemType -eq 'HibernationState') {
                & $RestoreHibernationItem $item
                $outcome = 'Restored'
            }
            elseif ($item.ItemType -eq 'PowerPlan') {
                & $RestorePowerPlanItem $item
                $outcome = 'Restored'
            }
            elseif ($item.ItemType -eq 'PowerSetting') {
                & $RestorePowerSettingItem $item
                $outcome = 'Restored'
            }
            elseif ($item.ItemType -eq 'RegistryKey') {
                & $RestoreRegistryKeyItem $item
                $outcome = 'Restored'
            }
            elseif ($item.ItemType -eq 'RegistryKeyTree') {
                $outcome = & $RestoreRegistryKeyTreeItem $item
            }
            else {
                $outcome = 'NotRestorable'
            }
        }
        catch {
            $outcome = 'Failed'
        }
        $results.Add([PSCustomObject]@{
            ItemType = $item.ItemType
            Name     = $itemName
            Outcome  = $outcome
            Item     = $item
        })
        if ($outcome -eq 'Restored') { $restoredItems.Add($item) }
    }

    if ($ItemFilter) {
        $stamp = (Get-Date).ToString('o')
        foreach ($item in $restoredItems) { $item | Add-Member -NotePropertyName 'RestoredAt' -NotePropertyValue $stamp -Force }
        $pending = @(@($entry.Items) | Where-Object { -not (Test-WtUndoItemClosed -Item $_) })
        if ($restoredItems.Count -gt 0 -and $pending.Count -eq 0) {
            $entry | Add-Member -NotePropertyName 'RestoredAt' -NotePropertyValue $stamp -Force
        }
        if ($restoredItems.Count -gt 0) { Write-WtJson -Path $EntryPath -InputObject $entry }
        return $results.ToArray()
    }

    $restoredAny = [bool]($results | Where-Object { $_.Outcome -eq 'Restored' } | Select-Object -First 1)
    $failedAny = [bool]($results | Where-Object { $_.Outcome -eq 'Failed' } | Select-Object -First 1)
    if ($restoredAny -or -not $failedAny) {
        $entry | Add-Member -NotePropertyName 'RestoredAt' -NotePropertyValue ((Get-Date).ToString('o')) -Force
        Write-WtJson -Path $EntryPath -InputObject $entry
    }

    return $results.ToArray()
}

function Test-WtUndoItemClosed {
    <#
    .SYNOPSIS
        PURE: is this single item finished with? Either a per-setting
        revert put it back (RestoredAt) or another action wiped what it
        records and it was retired (RetiredAt). A closed item is skipped
        by the restore loop and no longer keeps its entry pending.
    #>
    param([Parameter(Mandatory)][object]$Item)
    $names = $Item.PSObject.Properties.Name
    if (($names -contains 'RestoredAt') -and $Item.RestoredAt) { return $true }
    if (($names -contains 'RetiredAt') -and $Item.RetiredAt) { return $true }
    return $false
}

function Test-WtUndoEntryClosed {
    <#
    .SYNOPSIS
        PURE: is this entry finished with? Either the user restored it
        (RestoredAt) or another action wiped the state it records and it
        was retired (RetiredAt). Either way the Undo screen must not
        offer it - restoring it would put back a setting that no longer
        exists anywhere.
    #>
    param([Parameter(Mandatory)][object]$Entry)
    $names = $Entry.PSObject.Properties.Name
    if (($names -contains 'RestoredAt') -and $Entry.RestoredAt) { return $true }
    if (($names -contains 'RetiredAt') -and $Entry.RetiredAt) { return $true }
    return $false
}

function Set-WtUndoEntryRetired {
    <#
    .SYNOPSIS
        Marks still-open undo records as retired because the caller has just
        wiped the state they record; the entry file stays on disk. Without
        -ItemFilter the whole entry is retired; with it, only the matching
        items, closing the entry only once nothing restorable is left in it -
        e.g. an 'Apply Blocklist' entry carries HostsBlock and FirewallBlock
        together, and resetting the firewall must not drop the hosts undo too.
        Returns how many entries were touched.
    #>
    param(
        [Parameter(Mandatory)][string[]]$ActionNames,
        [Parameter(Mandatory)][string]$RetiredBy,
        [scriptblock]$ItemFilter,
        [string]$TestRootOverride
    )
    $entryArgs = @{}
    if ($TestRootOverride) { $entryArgs['TestRootOverride'] = $TestRootOverride }

    $stamp = (Get-Date).ToString('o')
    $touched = 0
    foreach ($entry in @(Get-WtUndoEntries @entryArgs)) {
        if ($ActionNames -notcontains [string]$entry.Action) { continue }
        if (Test-WtUndoEntryClosed -Entry $entry) { continue }

        if (-not $ItemFilter) {
            $entry | Add-Member -NotePropertyName 'RetiredAt' -NotePropertyValue $stamp -Force
            $entry | Add-Member -NotePropertyName 'RetiredBy' -NotePropertyValue $RetiredBy -Force
            Write-WtJson -Path ([string]$entry.Path) -InputObject $entry
            $touched++
            continue
        }

        $stamped = 0
        foreach ($item in @($entry.Items)) {
            if (Test-WtUndoItemClosed -Item $item) { continue }
            if (-not (& $ItemFilter $item)) { continue }
            $item | Add-Member -NotePropertyName 'RetiredAt' -NotePropertyValue $stamp -Force
            $item | Add-Member -NotePropertyName 'RetiredBy' -NotePropertyValue $RetiredBy -Force
            $stamped++
        }
        if ($stamped -eq 0) { continue }

        $open = @(@($entry.Items) | Where-Object { -not (Test-WtUndoItemClosed -Item $_) })
        if ($open.Count -eq 0) {
            $entry | Add-Member -NotePropertyName 'RetiredAt' -NotePropertyValue $stamp -Force
            $entry | Add-Member -NotePropertyName 'RetiredBy' -NotePropertyValue $RetiredBy -Force
        }
        Write-WtJson -Path ([string]$entry.Path) -InputObject $entry
        $touched++
    }
    return $touched
}
#endregion src/30-engine/undo.ps1

#region src/40-catalogs/app-permissions.ps1
# App permission catalog and state.
# Covered by: tests/AiAndPermissionCatalogs.Tests.ps1

function Get-WtAppPermissionCatalog {
    <#
    .SYNOPSIS
        The individually-selectable app-permission capability-defaults
        catalog: 25 CapabilityAccessManager\ConsentStore capabilities,
        each with a friendly DisplayLabel. 17 are
        SAFE; the 8 library/broad-file-access/screen-capture capabilities
        are CAUTION (denying them can break apps that need broad access to
        a media library, the file system, or the screen). Nothing here is
        ADVANCED.
    #>
    return Resolve-WtCatalogText -KeyPrefix 'AppPermission' -Catalog @(
        [PSCustomObject]@{ Name = 'location'; DisplayLabel = 'Location'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'webcam'; DisplayLabel = 'Camera'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'microphone'; DisplayLabel = 'Microphone'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'userNotificationListener'; DisplayLabel = 'Notifications'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'userAccountInformation'; DisplayLabel = 'Account Info'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'appDiagnostics'; DisplayLabel = 'App Diagnostics'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'contacts'; DisplayLabel = 'Contacts'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'appointments'; DisplayLabel = 'Calendar'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'email'; DisplayLabel = 'Email'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'chat'; DisplayLabel = 'Messaging'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'phoneCall'; DisplayLabel = 'Phone Calls'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'phoneCallHistory'; DisplayLabel = 'Call History'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'userDataTasks'; DisplayLabel = 'Tasks'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'activity'; DisplayLabel = 'Activity History'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'bluetoothSync'; DisplayLabel = 'Other Devices (Bluetooth Sync)'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'radios'; DisplayLabel = 'Radios'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'cellularData'; DisplayLabel = 'Cellular Data'; Risk = 'SAFE'; Consequence = $null }
        [PSCustomObject]@{ Name = 'documentsLibrary'; DisplayLabel = 'Documents Library'; Risk = 'CAUTION'; Consequence = 'Apps that need broad access to your Documents folder (backup tools, some editors) may stop working' }
        [PSCustomObject]@{ Name = 'picturesLibrary'; DisplayLabel = 'Pictures Library'; Risk = 'CAUTION'; Consequence = 'Apps needing broad access to your Pictures folder (Photos imports, some editors) may stop working' }
        [PSCustomObject]@{ Name = 'videosLibrary'; DisplayLabel = 'Videos Library'; Risk = 'CAUTION'; Consequence = 'Apps needing broad access to your Videos folder (Movies & TV imports, some editors) may stop working' }
        [PSCustomObject]@{ Name = 'musicLibrary'; DisplayLabel = 'Music Library'; Risk = 'CAUTION'; Consequence = 'Apps needing broad access to your Music folder (media players) may stop working' }
        [PSCustomObject]@{ Name = 'downloadsFolder'; DisplayLabel = 'Downloads Folder'; Risk = 'CAUTION'; Consequence = 'Apps needing broad access to your Downloads folder may stop working' }
        [PSCustomObject]@{ Name = 'broadFileSystemAccess'; DisplayLabel = 'File System (Broad Access)'; Risk = 'CAUTION'; Consequence = 'Apps needing full file-system access (some backup, sync, and antivirus tools) may stop working' }
        [PSCustomObject]@{ Name = 'graphicsCaptureProgrammatic'; DisplayLabel = 'Screen Capture (Apps)'; Risk = 'CAUTION'; Consequence = 'Xbox Game Bar, screen recording, and remote-support tools that capture your screen may stop working' }
        [PSCustomObject]@{ Name = 'graphicsCaptureWithoutBorder'; DisplayLabel = 'Screen Capture (No Border)'; Risk = 'CAUTION'; Consequence = 'Borderless screen-capture used by some recording/remote-support tools may stop working' }
    )
}

function Get-WtAppPermissionState {
    <#
    .SYNOPSIS
        Live state of one capability's global default: Applied only for a
        Value of exactly 'Deny'. A missing key, a missing value, and
        'Allow' all collapse to NotApplied - this catalog is not
        attempting Windows' own tri-state Settings UI.
    #>
    param(
        [Parameter(Mandatory)]
        [string]$Capability,

        [scriptblock]$GetPropertyAction = {
            param($p, $n)
            Get-WtRegistryProperty -Path $p -Name $n
        }
    )

    $path = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\$Capability"
    $current = Get-WtRegistryValue -Path $path -Name 'Value' -GetPropertyAction $GetPropertyAction
    return [PSCustomObject]@{ Applied = ($current.Present -and $current.Value -eq 'Deny') }
}
#endregion src/40-catalogs/app-permissions.ps1

#region src/40-catalogs/assistant-index.ps1
# The state-aware WinToolify tool index the assistant searches, suggests
# from and acts on, built stateless once per process and cached.
# Covered by: tests/AssistantIndex.Tests.ps1

function Get-WtAssistantNeverRunRows {
    <#
    .SYNOPSIS
        Action rows the model may only SUGGEST, never run, on top of the
        structural rules (Power rows, Inline rows, Delete* names): the
        cleanups that discard data with no undo entry.
    #>
    return [string[]]@('ClearPrintQueue', 'CleanComponentStore', 'WindowsDiskCleanup', 'DeleteOldRestorePoints')
}

function Get-WtAssistantCatalogText {
    <#
    .SYNOPSIS
        One catalog prose field in ONE requested language: the key's
        translated text (formatted with its Args property when present),
        else the entry's shipped literal, else empty. Needed because
        catalogs resolve DisplayLabel only in the active language.
    #>
    param(
        [Parameter(Mandatory)]$Entry,
        [Parameter(Mandatory)][string]$KeyProperty,
        [Parameter(Mandatory)][string]$TextProperty,
        [Parameter(Mandatory)][ValidateSet('EN', 'TR')][string]$Language
    )
    $props = @($Entry.PSObject.Properties.Name)
    if ($props -contains $KeyProperty -and $Entry.$KeyProperty) {
        $text = [string]$script:Translations[$Language][[string]$Entry.$KeyProperty]
        if ($text) {
            $argsProperty = $KeyProperty.Replace('Key', 'Args')
            if ($props -contains $argsProperty -and $null -ne $Entry.$argsProperty) {
                try { $text = $text -f @($Entry.$argsProperty) } catch { $null = $_ }
            }
            return $text
        }
    }
    if ($props -contains $TextProperty -and $Entry.$TextProperty) { return [string]$Entry.$TextProperty }
    return ''
}

function ConvertTo-WtAssistantSearchTokens {
    <#
    .SYNOPSIS
        Folded (Turkish letters -> ASCII, invariant lower) and split on
        anything that is not a-z/0-9. The class is ordinal in .NET regex,
        so tr-TR casing cannot reach it.
    #>
    param([AllowNull()][AllowEmptyString()][string]$Text)
    $folded = ConvertTo-WtAssistantSearchText -Text ([string]$Text)
    return [string[]]@([regex]::Split($folded, '[^a-z0-9]+') | Where-Object { $_.Length -ge 2 } | Select-Object -Unique)
}

function Remove-WtAssistantLabelPrefix {
    <#
    .SYNOPSIS
        PURE: strips a '<Name> - ' prefix from a catalog label whose id
        already carries the name (Packages); a label that IS the prefix,
        or does not start with it, comes back unchanged.
    #>
    param([AllowNull()][AllowEmptyString()][string]$Label, [AllowNull()][AllowEmptyString()][string]$Prefix)
    $text = [string]$Label
    $head = [string]$Prefix
    if ($head -and $text.Length -gt $head.Length -and $text.StartsWith($head, [System.StringComparison]::OrdinalIgnoreCase)) { return $text.Substring($head.Length) }
    return $text
}

function New-WtAssistantIndexEntry {
    param(
        [Parameter(Mandatory)][string]$Id,
        [Parameter(Mandatory)][ValidateSet('Toggle', 'Action', 'Info', 'Screen', 'Winget')][string]$Kind,
        [string]$SectionKey = '',
        [string]$Section = '',
        [AllowEmptyString()][string]$LabelEn = '',
        [AllowEmptyString()][string]$LabelTr = '',
        [AllowEmptyString()][string]$PathEn = '',
        [AllowEmptyString()][string]$PathTr = '',
        [AllowEmptyString()][string]$Risk = '',
        [AllowEmptyString()][string]$ConsequenceEn = '',
        [AllowEmptyString()][string]$ConsequenceTr = '',
        [bool]$Removable = $false,
        [bool]$Runnable = $false,
        [string]$Screen = '',
        [AllowNull()]$Item = $null,
        [AllowNull()]$Entry = $null,
        [AllowEmptyString()][string]$ExtraSearchText = '',
        [AllowEmptyString()][string]$DescriptionEn = '',
        [AllowEmptyString()][string]$DescriptionTr = '',
        [AllowEmptyString()][string]$Tags = '',
        [AllowEmptyString()][string]$Twin = ''
    )
    $haystack = ConvertTo-WtAssistantSearchText -Text (@($LabelEn, $LabelTr, $PathEn, $PathTr, $ConsequenceEn, $ConsequenceTr, $DescriptionEn, $DescriptionTr, $Id, $ExtraSearchText, $Tags) -join ' ')
    $labelText = ConvertTo-WtAssistantSearchText -Text (@($LabelEn, $LabelTr, $Id, $Tags, $ExtraSearchText) -join ' ')
    $descText = ConvertTo-WtAssistantSearchText -Text (@($ConsequenceEn, $ConsequenceTr, $DescriptionEn, $DescriptionTr) -join ' ')
    $pathText = ConvertTo-WtAssistantSearchText -Text (@($PathEn, $PathTr) -join ' ')
    return [PSCustomObject]@{
        Id = $Id; Kind = $Kind; SectionKey = $SectionKey; Section = $Section
        LabelEn = $LabelEn; LabelTr = $LabelTr; PathEn = $PathEn; PathTr = $PathTr
        Risk = $Risk; ConsequenceEn = $ConsequenceEn; ConsequenceTr = $ConsequenceTr
        DescriptionEn = $DescriptionEn; DescriptionTr = $DescriptionTr; Tags = $Tags; Twin = $Twin
        Removable = $Removable; Runnable = $Runnable; Screen = $Screen; Item = $Item; Entry = $Entry
        Haystack = $haystack
        Tokens = (ConvertTo-WtAssistantSearchTokens -Text $haystack)
        LabelTokens = (ConvertTo-WtAssistantSearchTokens -Text $labelText)
        DescTokens = (ConvertTo-WtAssistantSearchTokens -Text $descText)
        PathTokens = (ConvertTo-WtAssistantSearchTokens -Text $pathText)
    }
}

function Test-WtAssistantRowRunnable {
    <#
    .SYNOPSIS
        The assistant may run a Captured or Native row; never a Power
        row, an Inline row (it paints its own panel and reads the
        keyboard), a Delete* row, or one on the never-run list.
    #>
    param([Parameter(Mandatory)]$Row)
    $data = $Row.Data
    $name = [string]$Row.Name
    if ($name.StartsWith('Delete', [System.StringComparison]::Ordinal)) { return $false }
    foreach ($never in (Get-WtAssistantNeverRunRows)) {
        if ([string]::Equals($never, $name, [System.StringComparison]::Ordinal)) { return $false }
    }
    if ($null -eq $data) { return $false }
    if ($data.Power) { return $false }
    if ($data.Native -or $data.Captured) { return $true }
    return $false
}

function Get-WtAssistantTagArgs {
    <#
    .SYNOPSIS
        PURE: the splat for New-WtAssistantIndexEntry from the tag table's
        record for one id - empty strings when the id has none.
    #>
    param([Parameter(Mandatory)][AllowEmptyString()][string]$Id, [AllowNull()][hashtable]$Table = $null)
    $args = @{ DescriptionEn = ''; DescriptionTr = ''; Tags = '' }
    if ($null -eq $Table -or -not $Table.ContainsKey($Id)) { return $args }
    $record = $Table[$Id]
    if ($record.ContainsKey('En')) { $args.DescriptionEn = [string]$record.En }
    if ($record.ContainsKey('Tr')) { $args.DescriptionTr = [string]$record.Tr }
    if ($record.ContainsKey('Tags')) { $args.Tags = [string]$record.Tags }
    return $args
}

function Get-WtAssistantNavRows {
    <#
    .SYNOPSIS
        Action rows that live on navigation screens rather than the
        Actions/Information tables - the main menu's restore point,
        Profiles' export/import - as @{ Item; Section; PathKeys }. A
        missing screen builder (a partial dot-source) yields no rows
        rather than an error.
    #>
    $sources = @(
        @{ Builder = 'Get-WtMainMenuItems'; Section = 'MainMenu'; PathKeys = @('MainMenu') }
        @{ Builder = 'Get-WtBasicToolsItems'; Section = 'BasicTools'; PathKeys = @('MainMenu', 'BasicTools') }
        @{ Builder = 'Get-WtProfilesMenuItems'; Section = 'ConfigProfiles'; PathKeys = @('MainMenu', 'ConfigProfiles') }
    )
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($source in $sources) {
        if (-not (Get-Command -Name ([string]$source.Builder) -ErrorAction SilentlyContinue)) { continue }
        $items = @()
        try { $items = @(& ([string]$source.Builder)) } catch { $items = @() }
        foreach ($item in $items) {
            if ([string]$item.Kind -ne 'Action' -or $null -eq $item.Data) { continue }
            if ($item.Data.Exit) { continue }
            if (-not ($item.Data.Action -or $item.Data.Captured -or $item.Data.Native)) { continue }
            $rows.Add(@{ Item = $item; Section = [string]$source.Section; PathKeys = [string[]]@($source.PathKeys) })
        }
    }
    return $rows.ToArray()
}

function Reset-WtAssistantIndexCache { $script:WtAssistantIndexCache = $null; $script:WtAssistantSectionEnumCache = $null; $script:WtAssistantIdfCache = $null }

function Get-WtAssistantSearchSections {
    <#
    .SYNOPSIS
        The search tool's `section` enum: every apply-section key (the
        stateless per-app screen excluded), then the three kind filters.
        Cached per process since the registry asks for it on every dispatch.
    #>
    param([AllowNull()][array]$Sections = $null)
    if ($null -eq $Sections -and $null -ne $script:WtAssistantSectionEnumCache) { return [string[]]$script:WtAssistantSectionEnumCache }
    $catalog = $(if ($null -ne $Sections) { @($Sections) } else { @(Get-WtApplySectionCatalog) })
    $keys = New-Object System.Collections.Generic.List[string]
    foreach ($section in $catalog) {
        $key = [string]$section.Key
        if ([string]::Equals($key, 'PerAppPermissions', [System.StringComparison]::Ordinal)) { continue }
        if (-not $keys.Contains($key)) { $keys.Add($key) }
    }
    foreach ($kind in @('Tools', 'Screens', 'Winget')) { $keys.Add($kind) }
    $result = [string[]]$keys.ToArray()
    if ($null -eq $Sections) { $script:WtAssistantSectionEnumCache = $result }
    return $result
}

function Get-WtAssistantToolIndex {
    <#
    .SYNOPSIS
        Builds (or returns the cached) index; injecting a source or
        -NoCache bypasses the cache. Returns via the unary comma - assign
        bare. Winget rows are suggestion-only, never run by the assistant.
    #>
    param(
        [AllowNull()][array]$Sections = $null,
        [AllowNull()][array]$ActionGroups = $null,
        [AllowNull()][array]$InfoGroups = $null,
        [AllowNull()][array]$WingetCatalog = $null,
        [AllowNull()][array]$NavRows = $null,
        [switch]$NoCache
    )
    $injected = ($null -ne $Sections -or $null -ne $ActionGroups -or $null -ne $InfoGroups -or $null -ne $WingetCatalog -or $null -ne $NavRows)
    if (-not $injected -and -not $NoCache -and $null -ne $script:WtAssistantIndexCache) { return , $script:WtAssistantIndexCache }
    if ($null -eq $Sections) { $Sections = @(Get-WtApplySectionCatalog) }
    if ($null -eq $ActionGroups) { $ActionGroups = @(Get-WtActionToolGroups) }
    if ($null -eq $InfoGroups) { $InfoGroups = @(Get-WtInfoToolGroups) }
    if ($null -eq $WingetCatalog) { $WingetCatalog = @(Get-WtWingetStoreCatalog) }
    if ($null -eq $NavRows) { $NavRows = @(Get-WtAssistantNavRows) }
    $en = $script:Translations['EN']
    $tr = $script:Translations['TR']
    $tagTable = Get-WtAssistantSearchTagTable
    $twinTable = Get-WtAssistantTwinTable
    $index = New-Object System.Collections.Generic.List[object]

    foreach ($section in @($Sections)) {
        $key = [string]$section.Key
        if ($key -eq 'PerAppPermissions') { continue }
        $catalog = @()
        try { $catalog = @(& $section.GetCatalog) } catch { $catalog = @() }
        $stageOnly = [bool](($section.PSObject.Properties.Name -contains 'StageOnly') -and $section.StageOnly)
        foreach ($entry in $catalog) {
            $props = @($entry.PSObject.Properties.Name)
            $name = [string]$entry.Name
            $labelEn = Get-WtAssistantCatalogText -Entry $entry -KeyProperty 'LabelKey' -TextProperty 'DisplayLabel' -Language 'EN'
            $labelTr = Get-WtAssistantCatalogText -Entry $entry -KeyProperty 'LabelKey' -TextProperty 'DisplayLabel' -Language 'TR'
            if (-not $labelEn) { $labelEn = $name }
            if (-not $labelTr) { $labelTr = $labelEn }
            if ([string]::Equals($key, 'Packages', [System.StringComparison]::Ordinal)) {
                $labelEn = Remove-WtAssistantLabelPrefix -Label $labelEn -Prefix ($name + ' - ')
                $labelTr = Remove-WtAssistantLabelPrefix -Label $labelTr -Prefix ($name + ' - ')
            }
            if ([string]::Equals($key, 'DnsPreset', [System.StringComparison]::Ordinal)) {
                $dnsLabel = $name + ' DNS (' + [string]$entry.IPv4Primary + ', ' + [string]$entry.IPv4Secondary + ')'
                $labelEn = $dnsLabel
                $labelTr = $dnsLabel
            }
            $removable = $false
            if ($section.TurnOff) {
                $removable = $true
                if ($section.IsRemovable) { try { $removable = [bool](& $section.IsRemovable $entry) } catch { $removable = $false } }
            }
            $tagArgs = Get-WtAssistantTagArgs -Id ($key + ':' + $name) -Table $tagTable
            $twinId = $(if ($twinTable.ContainsKey($key + ':' + $name)) { [string]$twinTable[$key + ':' + $name] } else { '' })
            $index.Add((New-WtAssistantIndexEntry @tagArgs -Id ($key + ':' + $name) -Kind 'Toggle' -SectionKey $key -Section ([string]$section.TitleKey) `
                -LabelEn $labelEn -LabelTr $labelTr -PathEn ([string]$en[[string]$section.TitleKey]) -PathTr ([string]$tr[[string]$section.TitleKey]) `
                -Risk $(if ($props -contains 'Risk' -and $entry.Risk) { [string]$entry.Risk } else { '' }) `
                -ConsequenceEn (Get-WtAssistantCatalogText -Entry $entry -KeyProperty 'ConsequenceKey' -TextProperty 'Consequence' -Language 'EN') `
                -ConsequenceTr (Get-WtAssistantCatalogText -Entry $entry -KeyProperty 'ConsequenceKey' -TextProperty 'Consequence' -Language 'TR') `
                -Removable $removable -Runnable (-not $stageOnly) -Screen $(if ($stageOnly) { 'SystemSettings' } else { '' }) -Twin $twinId -Entry $entry))
        }
    }

    foreach ($pair in @(@{ Groups = $ActionGroups; Kind = 'Action'; RootKey = 'ActionTools' }, @{ Groups = $InfoGroups; Kind = 'Info'; RootKey = 'InformationTools' })) {
        foreach ($group in @($pair.Groups)) {
            $rows = @()
            try { $rows = @(& $group.GetRows) } catch { $rows = @() }
            foreach ($row in $rows) {
                $name = [string]$row.Name
                $tagArgs = Get-WtAssistantTagArgs -Id $name -Table $tagTable
                $index.Add((New-WtAssistantIndexEntry @tagArgs -Id $name -Kind $pair.Kind -Section ([string]$group.HeaderKey) `
                    -LabelEn ([string]$en[$name]) -LabelTr ([string]$tr[$name]) `
                    -PathEn ([string]$en[[string]$pair.RootKey] + ' > ' + [string]$en[[string]$group.HeaderKey]) `
                    -PathTr ([string]$tr[[string]$pair.RootKey] + ' > ' + [string]$tr[[string]$group.HeaderKey]) `
                    -Risk $(if ([string]$row.Risk) { [string]$row.Risk } elseif ([string]::Equals([string]$pair.Kind, 'Info', [System.StringComparison]::Ordinal)) { 'SAFE' } else { '' }) `
                    -Runnable (Test-WtAssistantRowRunnable -Row $row) -Item $row))
            }
        }
    }

    foreach ($nav in @($NavRows)) {
        $row = $nav.Item
        $name = [string]$row.Name
        $pathEn = @($nav.PathKeys | ForEach-Object { [string]$en[[string]$_] }) -join ' > '
        $pathTr = @($nav.PathKeys | ForEach-Object { [string]$tr[[string]$_] }) -join ' > '
        $tagArgs = Get-WtAssistantTagArgs -Id $name -Table $tagTable
        $index.Add((New-WtAssistantIndexEntry @tagArgs -Id $name -Kind 'Action' -Section ([string]$nav.Section) `
            -LabelEn ([string]$en[$name]) -LabelTr ([string]$tr[$name]) -PathEn $pathEn -PathTr $pathTr `
            -Risk ([string]$row.Risk) -Runnable (Test-WtAssistantRowRunnable -Row $row) -Item $row))
    }

    foreach ($screen in @(
        @{ Id = 'Screen:BasicTools'; Key = 'BasicTools'; Screen = 'BasicTools'; PathKeys = @('MainMenu') }
        @{ Id = 'Screen:ActionTools'; Key = 'ActionTools'; Screen = 'ActionTools'; PathKeys = @('MainMenu', 'BasicTools') }
        @{ Id = 'Screen:InfoTools'; Key = 'InformationTools'; Screen = 'InfoTools'; PathKeys = @('MainMenu', 'BasicTools') }
        @{ Id = 'Screen:Services'; Key = 'ServicesManagement'; Screen = 'Services'; PathKeys = @('MainMenu') }
        @{ Id = 'Screen:SystemSettings'; Key = 'SystemSettings'; Screen = 'SystemSettings'; PathKeys = @('MainMenu') }
        @{ Id = 'Screen:Privacy'; Key = 'PrivacySettings'; Screen = 'Privacy'; PathKeys = @('MainMenu') }
        @{ Id = 'Screen:PerApp'; Key = 'PerAppPermissions'; Screen = 'PerApp'; PathKeys = @('MainMenu', 'PrivacySettings', 'PrivacyAppPermissionsScreen') }
        @{ Id = 'Screen:Packages'; Key = 'AppsMenu'; Screen = 'Packages'; PathKeys = @('MainMenu') }
        @{ Id = 'Screen:WingetStore'; Key = 'WingetStore'; Screen = 'WingetStore'; PathKeys = @('MainMenu') }
        @{ Id = 'Screen:Language'; Key = 'Language'; Screen = 'Language'; PathKeys = @('MainMenu') }
        @{ Id = 'Screen:Undo'; Key = 'UndoLastChange'; Screen = 'Undo'; PathKeys = @('MainMenu') }
        @{ Id = 'Screen:Profiles'; Key = 'ConfigProfiles'; Screen = 'Profiles'; PathKeys = @('MainMenu') }
    )) {
        $tagArgs = Get-WtAssistantTagArgs -Id ([string]$screen.Id) -Table $tagTable
        $index.Add((New-WtAssistantIndexEntry @tagArgs -Id ([string]$screen.Id) -Kind 'Screen' -LabelEn ([string]$en[[string]$screen.Key]) -LabelTr ([string]$tr[[string]$screen.Key]) `
            -PathEn (@($screen.PathKeys | ForEach-Object { [string]$en[[string]$_] }) -join ' > ') `
            -PathTr (@($screen.PathKeys | ForEach-Object { [string]$tr[[string]$_] }) -join ' > ') -Screen ([string]$screen.Screen)))
    }

    $categoryKeys = @{}
    foreach ($category in @(Get-WtWingetStoreCategories)) { $categoryKeys[[string]$category.Key] = [string]$category.LabelKey }
    foreach ($package in @($WingetCatalog)) {
        $categoryKey = [string]$categoryKeys[[string]$package.Category]
        $index.Add((New-WtAssistantIndexEntry -Id ('Winget:' + [string]$package.Id) -Kind 'Winget' -Section ([string]$package.Category) `
            -LabelEn ([string]$package.Name) -LabelTr ([string]$package.Name) `
            -PathEn ([string]$en['WingetStore'] + ' > ' + [string]$en[$categoryKey]) -PathTr ([string]$tr['WingetStore'] + ' > ' + [string]$tr[$categoryKey]) `
            -Screen 'WingetStore' -ExtraSearchText ([string]$package.Tags)))
    }

    $built = $index.ToArray()
    if (-not $injected -and -not $NoCache) { $script:WtAssistantIndexCache = $built }
    return , $built
}

function Get-WtAssistantIndexEntry {
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Id,
        [AllowNull()][array]$Index = $null
    )
    $entries = if ($null -ne $Index) { @($Index) } else { Get-WtAssistantToolIndex }
    foreach ($entry in $entries) {
        if ([string]::Equals([string]$entry.Id, $Id, [System.StringComparison]::Ordinal)) { return $entry }
    }
    return $null
}

function Get-WtAssistantIndexLabel {
    param([Parameter(Mandatory)]$Entry)
    if ($script:Language -eq 'TR') { return [string]$Entry.LabelTr }
    return [string]$Entry.LabelEn
}

function Get-WtAssistantTokenHit {
    <#
    .SYNOPSIS
        2 = the word is a token; 1 = word and token share a 5+ char
        prefix in either direction (matches Turkish suffixes, e.g.
        "telemetriyi" finds "telemetri"); 0 = nothing. Ordinal only.
    #>
    param([AllowEmptyCollection()][string[]]$Tokens = @(), [Parameter(Mandatory)][string]$Word)
    $best = 0
    foreach ($token in @($Tokens)) {
        if ([string]::Equals($token, $Word, [System.StringComparison]::Ordinal)) { return 2 }
        if ($best -eq 0 -and $Word.Length -ge 5 -and $token.Length -ge 5) {
            if ($token.StartsWith($Word, [System.StringComparison]::Ordinal) -or $Word.StartsWith($token, [System.StringComparison]::Ordinal)) { $best = 1 }
        }
    }
    return $best
}

function Get-WtAssistantSearchStopWords {
    <#
    .SYNOPSIS
        Words a user types that name no entry - generic verbs and product
        words. They neither score nor count toward the two-word rule, so
        'telemetri kapat' is a one-word query about telemetry.
    #>
    return [string[]]@('kapat', 'kapatma', 'ac', 'acik', 'kapali', 'sil', 'silme', 'temizle', 'goster', 'ayar', 'ayari', 'ayarlari', 'ayarlar',
        'windows', 'microsoft', 'bilgisayar', 'bilgisayarim', 'pc', 'computer', 'disable', 'enable', 'turn', 'off', 'on', 'remove', 'delete', 'clean',
        'settings', 'setting', 'the', 'my', 'bir', 've', 'and', 'icin', 'for', 'nasil', 'how', 'to', 'ne', 'yapmaliyim', 'istiyorum', 'lutfen', 'please')
}

function Get-WtAssistantIndexIdf {
    <#
    .SYNOPSIS
        token -> inverse document frequency over the index, smoothed so
        every value is >= 1: ln((N + 1) / (df + 1)) + 1. Cached against
        the index ARRAY REFERENCE so an injected test index stays
        separate. Uses ordinal-comparer Hashtables, not bare @{}, so
        token keys never culture-fold on a tr-TR host.
    #>
    param([Parameter(Mandatory)][AllowEmptyCollection()][array]$Index)
    if ($null -ne $script:WtAssistantIdfCache -and [object]::ReferenceEquals($script:WtAssistantIdfCache.Ref, $Index)) { return $script:WtAssistantIdfCache.Table }
    $df = New-Object 'System.Collections.Hashtable' ([System.StringComparer]::Ordinal)
    foreach ($entry in @($Index)) {
        foreach ($token in @($entry.Tokens)) {
            if ($df.ContainsKey($token)) { $df[$token] = [int]$df[$token] + 1 } else { $df[$token] = 1 }
        }
    }
    $n = @($Index).Count
    $table = New-Object 'System.Collections.Hashtable' ([System.StringComparer]::Ordinal)
    foreach ($token in $df.Keys) { $table[$token] = [Math]::Log(($n + 1.0) / ([int]$df[$token] + 1.0)) + 1.0 }
    $script:WtAssistantIdfCache = @{ Ref = $Index; Table = $table }
    return $table
}

function Get-WtAssistantEntryScore {
    <#
    .SYNOPSIS
        PURE: one entry against the query words. Per word the best field
        hit wins - label/tag/id x2, consequence/description x1, menu path
        x0.5 - times the word's idf. Hits counts words that hit anywhere;
        ExactLabelHit says whether any word named the label exactly
        (the winget rule).
    #>
    param([Parameter(Mandatory)]$Entry, [AllowEmptyCollection()][string[]]$Words = @(), [Parameter(Mandatory)][hashtable]$Idf)
    $score = 0.0
    $hits = 0
    $exactLabel = $false
    foreach ($word in @($Words)) {
        $best = 0.0
        $labelHit = Get-WtAssistantTokenHit -Tokens ([string[]]@($Entry.LabelTokens)) -Word $word
        if ($labelHit -eq 2) { $exactLabel = $true }
        if ($labelHit -gt 0) { $best = [Math]::Max($best, $labelHit * 2.0) }
        $descHit = Get-WtAssistantTokenHit -Tokens ([string[]]@($Entry.DescTokens)) -Word $word
        if ($descHit -gt 0) { $best = [Math]::Max($best, $descHit * 1.0) }
        $pathHit = Get-WtAssistantTokenHit -Tokens ([string[]]@($Entry.PathTokens)) -Word $word
        if ($pathHit -gt 0) { $best = [Math]::Max($best, $pathHit * 0.5) }
        if ($best -le 0) { continue }
        $hits++
        $weight = 1.0
        if ($Idf.ContainsKey($word)) { $weight = [double]$Idf[$word] }
        $score += $best * $weight
    }
    return @{ Score = $score; Hits = $hits; ExactLabelHit = $exactLabel }
}

function Test-WtAssistantEntryInSection {
    <#
    .SYNOPSIS
        PURE: the section filter - a kind word (Tools / Screens / Winget) or a SectionKey, ordinal, case-insensitive.
    #>
    param([Parameter(Mandatory)]$Entry, [AllowEmptyString()][string]$Section)
    if (-not $Section) { return $true }
    $kind = [string]$Entry.Kind
    if ([string]::Equals($Section, 'Tools', [System.StringComparison]::OrdinalIgnoreCase)) { return ($kind -eq 'Action' -or $kind -eq 'Info') }
    if ([string]::Equals($Section, 'Screens', [System.StringComparison]::OrdinalIgnoreCase)) { return ($kind -eq 'Screen') }
    if ([string]::Equals($Section, 'Winget', [System.StringComparison]::OrdinalIgnoreCase)) { return ($kind -eq 'Winget') }
    return [string]::Equals([string]$Entry.SectionKey, $Section, [System.StringComparison]::OrdinalIgnoreCase)
}

function Find-WtAssistantEntries {
    <#
    .SYNOPSIS
        The ranked search. Effective words = query words minus stop words
        (all of them when nothing is left); an entry needs min(2,
        effective) hits, or 1 on a relaxed retry when nothing hits both
        (flagged Relaxed). Winget entries qualify only on an exact label
        hit. Order: score, then kind, then id - Sort-Object is not stable.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Query,
        [AllowNull()][AllowEmptyString()][string]$Section = '',
        [AllowNull()][array]$Index = $null
    )
    $entries = if ($null -ne $Index) { @($Index) } else { Get-WtAssistantToolIndex }
    $words = @(ConvertTo-WtAssistantSearchTokens -Text $Query)
    $empty = @{ Entries = @(); Relaxed = $false; MatchedWords = [string[]]@(); EffectiveWords = [string[]]@() }
    if ($words.Count -eq 0) { return $empty }
    $stop = @(Get-WtAssistantSearchStopWords)
    $effective = @(foreach ($word in $words) {
        $isStop = $false
        foreach ($s in $stop) { if ((Get-WtAssistantTokenHit -Tokens @($s) -Word $word) -gt 0) { $isStop = $true; break } }
        if (-not $isStop) { $word }
    })
    if ($effective.Count -eq 0) { $effective = $words }
    $idf = Get-WtAssistantIndexIdf -Index $entries
    $candidates = @($entries | Where-Object { Test-WtAssistantEntryInSection -Entry $_ -Section ([string]$Section) })
    $kindRank = { param($Kind) if ($Kind -eq 'Screen') { 1 } elseif ($Kind -eq 'Winget') { 2 } else { 0 } }
    $pass = { param([int]$Needed)
        $scored = New-Object System.Collections.Generic.List[object]
        foreach ($entry in $candidates) {
            $s = Get-WtAssistantEntryScore -Entry $entry -Words $effective -Idf $idf
            if ($s.Hits -lt $Needed) { continue }
            if ([string]$entry.Kind -eq 'Winget' -and -not $s.ExactLabelHit) { continue }
            $scored.Add([PSCustomObject]@{ Entry = $entry; Score = [double]$s.Score; Rank = [int](& $kindRank ([string]$entry.Kind)); Id = [string]$entry.Id })
        }
        return @($scored.ToArray() | Sort-Object -Property @{ Expression = { -[double]$_.Score } }, @{ Expression = { [int]$_.Rank } }, @{ Expression = { $_.Id } })
    }
    $needed = [Math]::Min(2, $effective.Count)
    $ranked = @(& $pass $needed)
    $relaxed = $false
    if ($ranked.Count -eq 0 -and $needed -gt 1) {
        $ranked = @(& $pass 1)
        $relaxed = ($ranked.Count -gt 0)
    }
    $matched = @(foreach ($word in $effective) {
        $hit = $false
        foreach ($r in $ranked) { if ((Get-WtAssistantEntryScore -Entry $r.Entry -Words @($word) -Idf $idf).Hits -gt 0) { $hit = $true; break } }
        if ($hit) { $word }
    })
    return @{ Entries = @($ranked | ForEach-Object { $_.Entry }); Relaxed = $relaxed; MatchedWords = [string[]]$matched; EffectiveWords = [string[]]$effective }
}

function Resolve-WtAssistantSuggestions {
    <#
    .SYNOPSIS
        Validates the ids the model suggested: unknown ids come back as
        Invalid (an error the model can correct), duplicates collapse,
        the list caps at 9 - the digit shortcuts end there - and twins
        collapse into the preferred side.
    #>
    param(
        [AllowEmptyCollection()][string[]]$Ids = @(),
        [AllowNull()][array]$Index = $null
    )
    $entries = if ($null -ne $Index) { @($Index) } else { Get-WtAssistantToolIndex }
    $byId = @{}
    foreach ($entry in $entries) { $byId[[string]$entry.Id] = $entry }
    $requested = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
    foreach ($id in @($Ids)) { [void]$requested.Add([string]$id) }
    $valid = New-Object System.Collections.Generic.List[object]
    $seen = New-Object 'System.Collections.Generic.HashSet[string]'
    $invalid = New-Object System.Collections.Generic.List[string]
    foreach ($id in @($Ids)) {
        $key = [string]$id
        if (-not $byId.ContainsKey($key)) { $invalid.Add($key); continue }
        $twin = [string]$byId[$key].Twin
        if ($twin -and $requested.Contains($twin)) { continue }
        if ($seen.Add($key) -and $valid.Count -lt 9) { $valid.Add($byId[$key]) }
    }
    return @{ Valid = @($valid.ToArray()); Invalid = [string[]]$invalid.ToArray() }
}

function Get-WtAssistantEntryState {
    <#
    .SYNOPSIS
        The live state of ONE toggle, read on demand through its section's
        GetState (Applied / NotApplied / NotPresent). Never at index build:
        a full pass costs 2.4-3.6 s and goes stale; 12 matched entries
        cost 46 ms.
    #>
    param(
        [Parameter(Mandatory)]$Entry,
        [AllowNull()][array]$Sections = $null
    )
    if ([string]$Entry.Kind -ne 'Toggle' -or $null -eq $Entry.Entry) { return '' }
    if ($null -eq $Sections) { $Sections = @(Get-WtApplySectionCatalog) }
    $section = $null
    foreach ($s in @($Sections)) { if ([string]$s.Key -eq [string]$Entry.SectionKey) { $section = $s; break } }
    if ($null -eq $section -or -not $section.GetState) { return '' }
    try { return [string](& $section.GetState $Entry.Entry) } catch { return 'Unknown' }
}

function ConvertTo-WtAssistantStateCode {
    <#
    .SYNOPSIS
        The live-state word (Applied/NotApplied/NotPresent/Unknown) as the
        row column's short code: on, off, n/a, ? or -.
    #>
    param([AllowNull()][AllowEmptyString()][string]$State)
    switch -CaseSensitive ([string]$State) {
        'Applied' { return 'on' }
        'NotApplied' { return 'off' }
        'NotPresent' { return 'n/a' }
        'Unknown' { return '?' }
    }
    return '-'
}

function ConvertTo-WtAssistantRiskCode {
    <#
    .SYNOPSIS
        The catalog Risk word (SAFE/CAUTION/ADVANCED) as its single-letter
        row code: S/C/A/-.
    #>
    param([AllowNull()][AllowEmptyString()][string]$Risk)
    switch -CaseSensitive ([string]$Risk) {
        'SAFE' { return 'S' }
        'CAUTION' { return 'C' }
        'ADVANCED' { return 'A' }
    }
    return '-'
}

function Get-WtAssistantEntryWhat {
    <#
    .SYNOPSIS
        The one free-text field a row may carry: the consequence, else the description, in the active language, cut at -Max.
    #>
    param([Parameter(Mandatory)]$Entry, [int]$Max = 120)
    $isTurkish = ($script:Language -eq 'TR')
    $text = [string]$(if ($isTurkish) { $Entry.ConsequenceTr } else { $Entry.ConsequenceEn })
    if (-not $text) { $text = [string]$(if ($isTurkish) { $Entry.DescriptionTr } else { $Entry.DescriptionEn }) }
    $text = $text.Trim()
    if ($Max -gt 1 -and $text.Length -gt $Max) { $text = $text.Substring(0, $Max - 1) + '~' }
    return $text
}

function ConvertTo-WtAssistantSearchRow {
    <#
    .SYNOPSIS
        search_wintoolify's row: id | label | state | risk, plus a 'what'
        column only when the caller asked for it (a narrow result or
        -Detail). The label is capped at 70 characters.
    #>
    param([Parameter(Mandatory)]$Entry, [AllowEmptyString()][string]$State = '', [AllowNull()][AllowEmptyString()][string]$What = '')
    $label = (Get-WtAssistantIndexLabel -Entry $Entry).Trim()
    if ($label.Length -gt 70) { $label = $label.Substring(0, 69) + '~' }
    $row = [ordered]@{ id = [string]$Entry.Id; label = $label; state = (ConvertTo-WtAssistantStateCode -State $State); risk = (ConvertTo-WtAssistantRiskCode -Risk ([string]$Entry.Risk)) }
    if ($What) { $row['what'] = [string]$What }
    return [PSCustomObject]$row
}

function Get-WtAssistantSearchFacetLine {
    <#
    .SYNOPSIS
        PURE: 'N (Section 12, Tools 3, ...) - narrow with section=' for the matches beyond the rows shown; '' when nothing is hidden. The caller's 'more' field name already supplies the word - the value never repeats it.
    #>
    param([AllowEmptyCollection()][array]$Entries = @(), [int]$Shown = 0)
    $all = @($Entries)
    if ($all.Count -le $Shown) { return '' }
    $counts = [ordered]@{}
    foreach ($entry in $all) {
        $kind = [string]$entry.Kind
        $bucket = $(if ($kind -eq 'Toggle') { [string]$entry.SectionKey } elseif ($kind -eq 'Screen') { 'Screens' } elseif ($kind -eq 'Winget') { 'Winget' } else { 'Tools' })
        if ($counts.Contains($bucket)) { $counts[$bucket] = [int]$counts[$bucket] + 1 } else { $counts[$bucket] = 1 }
    }
    $top = @($counts.Keys | Sort-Object -Property @{ Expression = { -[int]$counts[$_] } }, @{ Expression = { $_ } } | Select-Object -First 5 | ForEach-Object { [string]$_ + ' ' + [int]$counts[$_] })
    return [string]($all.Count - $Shown) + ' (' + ($top -join ', ') + ') - narrow with section='
}

function Get-WtAssistantFoldedHits {
    <#
    .SYNOPSIS
        PURE: collapses the pair onto the preferred entry at the better
        of the two ranks, remembering the fold so its what column can say
        '(twin: <id>)'. A dropped side whose twin did not match (a
        section filter, say) stays. Returns @{ Entries; Folded }.
    #>
    param([AllowEmptyCollection()][array]$Entries = @())
    $ids = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
    $byId = @{}
    foreach ($e in @($Entries)) { [void]$ids.Add([string]$e.Id); $byId[[string]$e.Id] = $e }
    $emitted = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
    $folded = @{}
    $kept = New-Object System.Collections.Generic.List[object]
    foreach ($e in @($Entries)) {
        $id = [string]$e.Id
        if ($emitted.Contains($id)) { continue }
        $twin = [string]$e.Twin
        if ($twin -and $ids.Contains($twin)) {
            $folded[$twin] = $id
            if (-not $emitted.Contains($twin)) { $kept.Add($byId[$twin]); [void]$emitted.Add($twin) }
            continue
        }
        $kept.Add($e)
        [void]$emitted.Add($id)
    }
    return @{ Entries = @($kept.ToArray()); Folded = $folded }
}

function Get-WtAssistantSearchResult {
    <#
    .SYNOPSIS
        search_wintoolify: up to -Take rows of id | label | state | risk.
        'what' is added for a narrow result or -Detail; 'more:' names
        remaining matches; a relaxed match says which words it honoured;
        an HKLM/HKCU twin pair collapses into the preferred row. Uses
        $rowLimit, not $take, since PS variable names are case-insensitive.
    #>
    param(
        [AllowNull()][AllowEmptyString()][string]$Query = '',
        [AllowNull()][AllowEmptyString()][string]$Section = '',
        [bool]$Detail = $false,
        [int]$Take = 8,
        [AllowNull()][array]$Index = $null,
        [AllowNull()][array]$Sections = $null
    )
    $found = Find-WtAssistantEntries -Query ([string]$Query) -Section ([string]$Section) -Index $Index
    $fold = Get-WtAssistantFoldedHits -Entries @($found.Entries)
    $hits = @($fold.Entries)
    $rowLimit = $(if ($Detail) { [Math]::Min(5, [Math]::Max(1, $Take)) } else { [Math]::Max(1, $Take) })
    $withWhat = ($Detail -or $hits.Count -le 3)
    $rows = New-Object System.Collections.Generic.List[object]
    $stateReads = 0
    foreach ($entry in $hits) {
        if ($rows.Count -ge $rowLimit -or $stateReads -ge 36) { break }
        $state = Get-WtAssistantEntryState -Entry $entry -Sections $Sections
        $stateReads++
        $what = ''
        if ($withWhat) {
            $twinNote = $(if ($fold.Folded.ContainsKey([string]$entry.Id)) { ' (twin: ' + [string]$fold.Folded[[string]$entry.Id] + ')' } else { '' })
            $what = ((Get-WtAssistantEntryWhat -Entry $entry -Max (120 - $twinNote.Length)) + $twinNote).Trim()
        }
        $rows.Add((ConvertTo-WtAssistantSearchRow -Entry $entry -State $state -What $what))
    }
    $result = [ordered]@{}
    if ($rows.Count -eq 0) { $result['rows'] = 'none' } else { $result['rows'] = @($rows.ToArray()) }
    $more = Get-WtAssistantSearchFacetLine -Entries $hits -Shown $rows.Count
    if ($more) { $result['more'] = $more }
    if ($found.Relaxed) { $result['hint'] = 'no entry matched all words; showing matches for: ' + (@($found.MatchedWords) -join ', ') }
    elseif ($rows.Count -eq 0) { $result['hint'] = 'try other words (a symptom or a setting name) or a section=' }
    return $result
}

function Get-WtAssistantWintoolifyStatus {
    <#
    .SYNOPSIS
        read_system topic=wintoolify_status: "N/M applied" per section,
        read on demand (2.4-3.6 s for the whole catalog - the tool trace
        row covers it).
    #>
    param(
        [AllowNull()][array]$Index = $null,
        [AllowNull()][array]$Sections = $null
    )
    $entries = if ($null -ne $Index) { @($Index) } else { Get-WtAssistantToolIndex }
    if ($null -eq $Sections) { $Sections = @(Get-WtApplySectionCatalog) }
    $bySection = [ordered]@{}
    foreach ($entry in @($entries | Where-Object { $_.Kind -eq 'Toggle' -and $_.Runnable })) {
        $key = [string]$entry.SectionKey
        if (-not $bySection.Contains($key)) { $bySection[$key] = @{ Title = [string](Get-Translation ([string]$entry.Section)); Applied = 0; Total = 0; NotPresent = 0 } }
        $state = Get-WtAssistantEntryState -Entry $entry -Sections $Sections
        $bySection[$key].Total++
        if ($state -eq 'Applied') { $bySection[$key].Applied++ }
        elseif ($state -eq 'NotPresent') { $bySection[$key].NotPresent++ }
    }
    $rows = New-Object System.Collections.Generic.List[object]
    $appliedTotal = 0
    $total = 0
    foreach ($key in $bySection.Keys) {
        $s = $bySection[$key]
        $appliedTotal += $s.Applied
        $total += $s.Total
        $rows.Add([PSCustomObject]@{ section = $key; title = $s.Title; applied = $s.Applied; total = $s.Total; not_present = $s.NotPresent })
    }
    return [PSCustomObject]@{ sections = @($rows.ToArray()); applied_total = $appliedTotal; total = $total }
}
#endregion src/40-catalogs/assistant-index.ps1

#region src/40-catalogs/assistant-registry.ps1
# The assistant's tool registry: one data record per tool, from which the
# OpenAI schemas and the dispatch table are both derived.
# Covered by: tests/AssistantRegistry.Tests.ps1

function New-WtAssistantToolRecord {
    <#
    .SYNOPSIS
        One registry record. Parameters are hashtables @{ Name; Type;
        Description; Param; Enum?; Default? }. MaskArgs masks string
        arguments before the handler sees them; PassContext adds
        -Context; Hint is appended when the result must be cut.
    #>
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string]$DescriptionKey,
        [Parameter(Mandatory)][string]$Handler,
        [ValidateSet('read', 'net')][string]$Tier = 'read',
        [AllowEmptyCollection()][array]$Parameters = @(),
        [AllowEmptyCollection()][string[]]$Required = @(),
        [switch]$SkipIpMask,
        [AllowEmptyCollection()][string[]]$MaskArgs = @(),
        [switch]$PassContext,
        [int]$MaxChars = 2500,
        [AllowEmptyString()][string]$Hint = ''
    )
    return @{
        Name = $Name; DescriptionKey = $DescriptionKey; Handler = $Handler; Tier = $Tier
        Parameters = @($Parameters); Required = [string[]]@($Required)
        SkipIpMask = [bool]$SkipIpMask; MaskArgs = [string[]]@($MaskArgs); PassContext = [bool]$PassContext; MaxChars = $MaxChars
        Hint = [string]$Hint
    }
}

function Get-WtAssistantReadTopics {
    <#
    .SYNOPSIS
        The twelve read_system topic names, in the fixed order the
        router and the unknown-topic hint both rely on.
    #>
    return [string[]]@('overview', 'errors', 'crashes', 'storage', 'network', 'network_tests', 'security', 'startup', 'services', 'processes', 'wintoolify_changes', 'wintoolify_status')
}

function Get-WtAssistantToolRegistry {
    <#
    .SYNOPSIS
        Every tool the model can call, as data. Read and net tiers only:
        the model never runs, applies or undoes anything.
    #>
    return @(
        (New-WtAssistantToolRecord -Name 'search_wintoolify' -DescriptionKey 'AsDescSearchWintoolify' -Handler 'Get-WtAssistantSearchResult' -Required @('query') -Hint 'narrow with section= or fewer, more specific words' -Parameters @(
            @{ Name = 'query'; Type = 'string'; Description = 'Keywords, Turkish or English.'; Param = 'Query' }
            @{ Name = 'section'; Type = 'string'; Description = 'Section key, or a kind: Tools, Screens, Winget.'; Param = 'Section'; Enum = @(Get-WtAssistantSearchSections) }
            @{ Name = 'detail'; Type = 'boolean'; Description = 'Add the what column to at most 5 rows.'; Param = 'Detail'; Default = $false }))
        (New-WtAssistantToolRecord -Name 'suggest_wintoolify' -DescriptionKey 'AsDescSuggestWintoolify' -Handler 'Invoke-WtAssistantSuggest' -PassContext -Required @('ids') -Parameters @(
            @{ Name = 'ids'; Type = 'array'; Description = 'Ids from search_wintoolify, best first, at most 9.'; Param = 'Ids' }))
        (New-WtAssistantToolRecord -Name 'read_system' -DescriptionKey 'AsDescReadSystem' -Handler 'Get-WtAssistantSystemRead' -Required @('topic') -Hint 'use filter= to narrow (name, hours or count)' -Parameters @(
            @{ Name = 'topic'; Type = 'string'; Description = 'What to read.'; Param = 'Topic'; Enum = @(Get-WtAssistantReadTopics) }
            @{ Name = 'filter'; Type = 'string'; Description = 'errors=hours, startup/services=name, processes/wintoolify_changes=count, crashes=dump file.'; Param = 'Filter' }))
        (New-WtAssistantToolRecord -Name 'web_search' -DescriptionKey 'AsDescWebSearch' -Handler 'Get-WtAssistantWebSearch' -Tier 'net' -SkipIpMask -MaskArgs @('query') -Required @('query') -Parameters @(
            @{ Name = 'query'; Type = 'string'; Description = 'Search words.'; Param = 'Query' }))
        (New-WtAssistantToolRecord -Name 'fetch_page' -DescriptionKey 'AsDescFetchPage' -Handler 'Get-WtAssistantFetchPage' -Tier 'net' -SkipIpMask -MaxChars 3900 -Required @('url') -Parameters @(
            @{ Name = 'url'; Type = 'string'; Description = 'A web_search result url.'; Param = 'Url' }
            @{ Name = 'offset'; Type = 'integer'; Description = 'Continue from this character (see omitted).'; Param = 'Offset'; Default = 0 }))
        (New-WtAssistantToolRecord -Name 'read_raw' -DescriptionKey 'AsDescReadRaw' -Handler 'Get-WtAssistantRawRead' -Required @('kind', 'path') -Parameters @(
            @{ Name = 'kind'; Type = 'string'; Description = 'registry or file.'; Param = 'Kind'; Enum = @('registry', 'file') }
            @{ Name = 'path'; Type = 'string'; Description = 'Registry path or absolute file path.'; Param = 'Path' }
            @{ Name = 'name'; Type = 'string'; Description = 'Value name; omit to list the key.'; Param = 'Name' }
            @{ Name = 'lines'; Type = 'integer'; Description = 'File lines to read (1-500).'; Param = 'Lines'; Default = 100 }))
        (New-WtAssistantToolRecord -Name 'save_note' -DescriptionKey 'AsDescSaveNote' -Handler 'Invoke-WtAssistantSaveNote' -PassContext -Required @('text') -Parameters @(
            @{ Name = 'text'; Type = 'string'; Description = 'One fact, max 200 characters.'; Param = 'Text' }))
    )
}

function Get-WtAssistantToolRecord {
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Name,
        [AllowNull()][array]$Registry = $null
    )
    $records = if ($null -ne $Registry) { @($Registry) } else { @(Get-WtAssistantToolRegistry) }
    foreach ($record in $records) {
        if ([string]::Equals([string]$record.Name, $Name, [System.StringComparison]::Ordinal)) { return $record }
    }
    return $null
}

function Test-WtAssistantToolDisabled {
    <#
    .SYNOPSIS
        PURE: whether a tool name is on the user's /araclar off-list.
        Ordinal - never -contains on names under tr-TR.
    #>
    param([Parameter(Mandatory)][AllowEmptyString()][string]$Name, [AllowNull()][AllowEmptyCollection()][string[]]$Disabled = @())
    foreach ($d in @($Disabled)) {
        if ([string]::Equals([string]$d, $Name, [System.StringComparison]::Ordinal)) { return $true }
    }
    return $false
}

function Get-WtAssistantDisabledTools {
    <#
    .SYNOPSIS
        PURE: the tools the model must NOT see - the user's /araclar
        off-list, filtered to names the registry knows.
    #>
    param([AllowNull()][hashtable]$Permissions = $null, [AllowNull()][array]$Registry = $null)
    $records = if ($null -ne $Registry) { @($Registry) } else { @(Get-WtAssistantToolRegistry) }
    $disabled = [string[]]@()
    if ($null -ne $Permissions -and $Permissions.ContainsKey('disabled')) { $disabled = [string[]]@($Permissions.disabled | ForEach-Object { [string]$_ } | Where-Object { $_ }) }
    $off = New-Object System.Collections.Generic.List[string]
    foreach ($record in $records) {
        $name = [string]$record.Name
        if (Test-WtAssistantToolDisabled -Name $name -Disabled $disabled) { $off.Add($name) }
    }
    return [string[]]$off.ToArray()
}

function Get-WtAssistantFunctionSchemas {
    <#
    .SYNOPSIS
        The OpenAI tool declarations, derived from the registry. The
        description comes from the active language's table. -Disabled
        names leave the list entirely: a tool the user switched off with
        /araclar is one the model never hears of.
    #>
    param([AllowNull()][array]$Registry = $null, [AllowNull()][AllowEmptyCollection()][string[]]$Disabled = @())
    $records = if ($null -ne $Registry) { @($Registry) } else { @(Get-WtAssistantToolRegistry) }
    return @(foreach ($record in $records) {
        if (Test-WtAssistantToolDisabled -Name ([string]$record.Name) -Disabled $Disabled) { continue }
        $properties = @{}
        foreach ($p in @($record.Parameters)) {
            $property = @{ type = [string]$p.Type; description = [string]$p.Description }
            if ([string]$p.Type -eq 'array') { $property['items'] = @{ type = 'string' } }
            if ($p.ContainsKey('Enum')) { $property['enum'] = @($p.Enum) }
            if ($p.ContainsKey('Default')) { $property['default'] = $p.Default }
            $properties[[string]$p.Name] = $property
        }
        New-WtAssistantFunctionSchema -Name ([string]$record.Name) -Description ([string](Get-Translation ([string]$record.DescriptionKey))) -Properties $properties -Required ([string[]]@($record.Required))
    })
}
#endregion src/40-catalogs/assistant-registry.ps1

