$script:WtDohSupportedCache = $null

function Test-WtManifestMayExport {
    <#
    .SYNOPSIS
        PURE over one file: $false only when the module manifest at
        ManifestPath exists and does not name CommandName at all - then
        Get-Command cannot find the command either, since command
        discovery reads exactly that export list. A missing or unreadable
        manifest says nothing, so $true: the caller still asks Get-Command.
    #>
    param(
        [Parameter(Mandatory)][string]$CommandName,
        [Parameter(Mandatory)][string]$ManifestPath
    )
    if (-not (Test-Path -LiteralPath $ManifestPath)) { return $true }
    try { $text = [System.IO.File]::ReadAllText($ManifestPath) } catch { return $true }
    return ($text.IndexOf($CommandName, [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
}

function Test-WtDohSupported {
    <#
    .SYNOPSIS
        Feature-detects native DoH client support via cmdlet presence, not
        a build-number gate: no documented minimum build exists (19628, the
        only one Microsoft ever published, is Insider-only). Checks the
        DnsClient manifest first for speed, then caches the answer per session.
    #>
    param(
        [scriptblock]$GetCommandAction = {
            $root = [string]$env:SystemRoot
            if ($root) {
                $manifest = Join-Path $root 'System32\WindowsPowerShell\v1.0\Modules\DnsClient\DnsClient.psd1'
                if (-not (Test-WtManifestMayExport -CommandName 'Add-DnsClientDohServerAddress' -ManifestPath $manifest)) { return $null }
            }
            Get-Command Add-DnsClientDohServerAddress -ErrorAction SilentlyContinue
        }
    )

    $useMemory = -not $PSBoundParameters.ContainsKey('GetCommandAction')
    if ($useMemory -and $null -ne $script:WtDohSupportedCache) { return [bool]$script:WtDohSupportedCache }
    $supported = [bool](& $GetCommandAction)
    if ($useMemory) { $script:WtDohSupportedCache = $supported }
    return $supported
}

function Get-WtDohServerAddressList {
    <#
    .SYNOPSIS
        The machine's registered DoH server entries, or an empty list on a
        build with no native DoH client: the cmdlet does not exist there,
        and a missing command throws CommandNotFoundException that no
        -ErrorAction can catch, so the presence probe must run first.
    #>
    param(
        [scriptblock]$GetCommandAction = {
            Get-Command Get-DnsClientDohServerAddress -ErrorAction SilentlyContinue
        },
        [scriptblock]$GetDohAction = {
            Get-DnsClientDohServerAddress
        }
    )

    if (-not (& $GetCommandAction)) { return @() }
    return @(& $GetDohAction)
}

function Get-WtDnsAdapterCaptureState {
    <#
    .SYNOPSIS
        Pre-change capture for every Up adapter: current IPv4/IPv6 server
        addresses (empty array = DHCP) and the full pre-existing DoH entry
        for any touched address, so undo can restore it. The add/modify
        split is computed here, before Apply runs, since Add- fails for an
        address already known.
    #>
    param(
        [Parameter(Mandatory)]
        [PSCustomObject]$Preset,

        [bool]$DohSupported = $false,

        [scriptblock]$GetAdaptersAction = {
            Get-NetAdapter | Where-Object Status -eq 'Up'
        },

        [scriptblock]$GetServerAddressAction = {
            param($InterfaceIndex, $AddressFamily)
            (Get-DnsClientServerAddress -InterfaceIndex $InterfaceIndex -AddressFamily $AddressFamily).ServerAddresses
        },

        [scriptblock]$GetDohAction = { Get-WtDohServerAddressList }
    )

    $touchedAddresses = @($Preset.IPv4Primary, $Preset.IPv4Secondary, $Preset.IPv6Primary, $Preset.IPv6Secondary)
    $allDohEntries = @(& $GetDohAction)
    $adapters = @(& $GetAdaptersAction)

    $items = foreach ($adapter in $adapters) {
        $previousIPv4 = @(& $GetServerAddressAction $adapter.InterfaceIndex 'IPv4')
        $previousIPv6 = @(& $GetServerAddressAction $adapter.InterfaceIndex 'IPv6')
        $previousDoh = @($allDohEntries | Where-Object { $touchedAddresses -contains $_.ServerAddress } | ForEach-Object {
            [PSCustomObject]@{
                Address            = $_.ServerAddress
                Template           = $_.DohTemplate
                AllowFallbackToUdp = $_.AllowFallbackToUdp
                AutoUpgrade        = $_.AutoUpgrade
            }
        })

        $previousDohAddresses = @($previousDoh | ForEach-Object { $_.Address })

        [PSCustomObject]@{
            ItemType           = 'DnsConfig'
            InterfaceIndex     = $adapter.InterfaceIndex
            PreviousIPv4       = $previousIPv4
            PreviousIPv6       = $previousIPv6
            PreviousDohEntries = $previousDoh
            AddedDohAddresses    = if ($DohSupported) { @($touchedAddresses | Where-Object { $previousDohAddresses -notcontains $_ }) } else { @() }
            ModifiedDohAddresses = if ($DohSupported) { $previousDohAddresses } else { @() }
        }
    }

    return @($items)
}
#endregion src/40-catalogs/dns-preset.ps1

#region src/40-catalogs/explorer-view.ps1
# Explorer view catalog.
# Covered by: tests/ExplorerViewCatalog.Tests.ps1

function Get-WtExplorerViewCatalog {
    <#
    .SYNOPSIS
        The seven File Explorer default-view tweaks as a RegistryChanges-
        shaped catalog, all HKCU DWORDs, sharing Get-WtRegistryEntryState /
        Invoke-WtApplyRegistryEntrySelection with no new code. Every entry
        needs an Explorer restart to become visible (RestartsExplorer).
    #>
    $advanced = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced'
    $explorer = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer'

    $entry = {
        param($name, $label, $risk, $consequence, $changes)
        [PSCustomObject]@{
            Name             = $name
            DisplayLabel     = $label
            Risk             = $risk
            Consequence      = $consequence
            RestartsExplorer = $true
            RegistryChanges  = @($changes)
        }
    }
    $dword = { param($p, $n, $v, $off) if ($null -eq $off) { [PSCustomObject]@{ Path = $p; Name = $n; RegType = 'DWord'; Value = $v; OffAction = 'Delete' } } else { [PSCustomObject]@{ Path = $p; Name = $n; RegType = 'DWord'; Value = $v; OffAction = 'Set'; OffValue = $off } } }

    return Resolve-WtCatalogText -KeyPrefix 'ExplorerView' -Catalog @(
        (& $entry 'ShowFileExtensions' 'Show file extensions' 'SAFE' $null @((& $dword $advanced 'HideFileExt' 0 1)))
        (& $entry 'ShowHiddenFiles' 'Show hidden files and folders' 'SAFE' $null @((& $dword $advanced 'Hidden' 1 2)))
        (& $entry 'OpenExplorerToThisPC' 'Open File Explorer to This PC' 'SAFE' $null @((& $dword $advanced 'LaunchTo' 1)))
        (& $entry 'UseCompactView' 'Use compact view (smaller row spacing)' 'SAFE' $null @((& $dword $advanced 'UseCompactMode' 1)))
        (& $entry 'ShowProtectedOsFiles' 'Show protected operating-system files' 'CAUTION' 'Exposes system files that Windows hides on purpose - deleting or moving them can break the install' @((& $dword $advanced 'ShowSuperHidden' 1 0)))
        (& $entry 'ShowFullPathInTitleBar' 'Show the full path in the title bar' 'SAFE' $null @((& $dword 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\CabinetState' 'FullPath' 1)))
        (& $entry 'HideRecentAndFrequent' 'Hide recent files and frequent folders in Quick Access' 'SAFE' $null @((& $dword $explorer 'ShowRecent' 0), (& $dword $explorer 'ShowFrequent' 0)))
    )
}
#endregion src/40-catalogs/explorer-view.ps1

#region src/40-catalogs/fast-startup.ps1
# Fast Startup catalog and state.
# Covered by: tests/FirewallFastStartup.Tests.ps1

# ---------------------------------------------------------------------------
# Power bundle - Fast Startup / hibernation guarded toggle
# ---------------------------------------------------------------------------

function Get-WtFastStartupCatalog {
    <#
    .SYNOPSIS
        The Fast Startup / hibernation toggle as a state-tracked catalog:
        a single CAUTION entry (powercfg /h off disables hibernation and
        removes Fast Startup, since it relies on hiberfil.sys). Turning it
        back on is the section's TurnOff (-Enable) or Restore-WtUndoEntry.
    #>
    return Resolve-WtCatalogText -KeyPrefix 'FastStartup' -Catalog @(
        [PSCustomObject]@{ Name = 'DisableFastStartup'; DisplayLabel = 'Disable hibernation and Fast Startup (powercfg /h off)'; Risk = 'CAUTION'; Consequence = 'Hibernate disappears from the power menu; hiberfil.sys is deleted; boots do a full kernel init' }
    )
}

function Get-WtFastStartupState {
    <#
    .SYNOPSIS
        Live-state check for the Get-WtFastStartupCatalog entry: Applied
        only when HibernateEnabled is present and equal to 0. Absent
        (never set) and non-zero both mean hibernation/Fast Startup are
        still on - Windows' own default is enabled.
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Entry,
        [scriptblock]$GetHibernateValueAction = { Get-WtRegistryValue -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Power' -Name 'HibernateEnabled' }
    )
    $current = & $GetHibernateValueAction
    $applied = [bool]($current.Present -and [int]$current.Value -eq 0)
    return [PSCustomObject]@{ Applied = $applied }
}
#endregion src/40-catalogs/fast-startup.ps1

#region src/40-catalogs/firewall.ps1
# Firewall catalog, state, GPO boolean conversion.
# Covered by: tests/FirewallFastStartup.Tests.ps1

# ---------------------------------------------------------------------------
# Network Privacy bundle - Windows Firewall guarded toggle
# ---------------------------------------------------------------------------

function Get-WtFirewallCatalog {
    <#
    .SYNOPSIS
        The Windows Firewall toggle as a state-tracked catalog: one
        entry per direction so live state, staging, profiles and undo
        all speak the same Name-based protocol. The UI offers only the
        direction opposite to the current state.
    #>
    return Resolve-WtCatalogText -KeyPrefix 'Firewall' -Catalog @(
        [PSCustomObject]@{ Name = 'EnableFirewall'; DisplayLabel = 'Windows Firewall: enable all profiles'; Risk = 'SAFE'; Consequence = $null; TargetEnabled = $true }
        [PSCustomObject]@{ Name = 'DisableFirewall'; DisplayLabel = 'Windows Firewall: disable all profiles'; Risk = 'ADVANCED'; Consequence = 'All three firewall profiles (Domain, Private, Public) stop filtering traffic until re-enabled'; TargetEnabled = $false }
    )
}

function Get-WtFirewallState {
    <#
    .SYNOPSIS
        Live-state check for a Get-WtFirewallCatalog entry: Applied is
        true only when every one of the three profiles already matches
        the entry's TargetEnabled (mirrors Get-WtGamingTweak-style state
        checks elsewhere - all-or-nothing, no partial "Applied").
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Entry,
        [scriptblock]$GetProfilesAction = { Get-NetFirewallProfile -Profile Domain, Private, Public }
    )
    $profiles = @(& $GetProfilesAction)
    if ($profiles.Count -eq 0) { return [PSCustomObject]@{ Applied = $false } }
    $mismatch = @($profiles | Where-Object { [bool]$_.Enabled -ne [bool]$Entry.TargetEnabled })
    return [PSCustomObject]@{ Applied = ($mismatch.Count -eq 0) }
}

function Get-WtFirewallRegistryState {
    <#
    .SYNOPSIS
        The firewall's on/off state straight from the registry, in a few
        milliseconds: @{ Enabled; Known }. Skips Get-NetFirewallProfile,
        which costs about a second on first use in a process (the
        NetSecurity import plus a CIM session). Known is false when a
        profile has no readable value, so the caller falls back to the
        cmdlet.
    #>
    param(
        [scriptblock]$GetPropertyAction = {
            param($p, $n)
            Get-WtRegistryProperty -Path $p -Name $n
        }
    )
    $enabledCount = 0
    foreach ($profile in 'Domain', 'Standard', 'Public') {
        $value = $null
        foreach ($path in @(
            ('HKLM:\SOFTWARE\Policies\Microsoft\WindowsFirewall\' + $profile + 'Profile')
            ('HKLM:\SYSTEM\CurrentControlSet\Services\SharedAccess\Parameters\FirewallPolicy\' + $profile + 'Profile')
        )) {
            $read = Get-WtRegistryValue -Path $path -Name 'EnableFirewall' -GetPropertyAction $GetPropertyAction
            if ($read.Present) { $value = $read.Value; break }
        }
        if ($null -eq $value) { return @{ Enabled = $false; Known = $false } }
        if ([int]$value -ne 0) { $enabledCount++ }
    }
    return @{ Enabled = ($enabledCount -eq 3); Known = $true }
}

function ConvertTo-WtGpoBoolean {
    <#
    .SYNOPSIS
        PURE: a [bool] as the enum name Set-NetFirewallProfile's -Enabled
        parameter accepts ('True'/'False'). A string, not a [GpoBoolean]
        literal: PowerShell cannot cast [bool] to that type directly, and
        the type resolves lazily via the NetSecurity module, so naming it
        here would break parsing on a host without it.
    #>
    param([Parameter(Mandatory)][bool]$Enabled)
    return [string]$Enabled
}
#endregion src/40-catalogs/firewall.ps1

#region src/40-catalogs/gaming.ps1
# Gaming tweak catalog and GPU scheduling support check.
# Covered by: tests/GamingTweaks.Tests.ps1

# ---------------------------------------------------------------------------
# Memory & Performance Tuning bundle - Gaming Tweaks
# ---------------------------------------------------------------------------

function Get-WtGamingTweakCatalog {
    <#
    .SYNOPSIS
        The three gaming toggles as a RegistryChanges-shaped catalog:
        disable Fullscreen Optimizations, enable hardware-accelerated GPU
        scheduling (restart required, WDDM 2.7+ - CAUTION), throttle
        background-window input to 50 Hz. HKCU values are written under
        Scope Machine like the AI toggles - an accepted cross-account-
        elevation risk. A few entries keep OffAction=Delete rather than
        Set: a matching OffValue would equal Value (breaking the
        off-differs-from-on invariant) or Windows already ships that
        default.
    #>
    return Resolve-WtCatalogText -KeyPrefix 'GamingTweak' -Catalog @(
        [PSCustomObject]@{
            Name            = 'DisableFullscreenOptimizations'
            DisplayLabel    = 'Disable Fullscreen Optimizations'
            Risk            = 'SAFE'
            Consequence     = $null
            RestartRequired = $false
            RegistryChanges = @(
                [PSCustomObject]@{ Path = 'HKCU:\System\GameConfigStore'; Name = 'GameDVR_FSEBehaviorMode'; RegType = 'DWord'; Value = 2; OffAction = 'Delete' }
                [PSCustomObject]@{ Path = 'HKCU:\System\GameConfigStore'; Name = 'GameDVR_FSEBehavior'; RegType = 'DWord'; Value = 2; OffAction = 'Delete' }
                [PSCustomObject]@{ Path = 'HKCU:\System\GameConfigStore'; Name = 'GameDVR_HonorUserFSEBehaviorMode'; RegType = 'DWord'; Value = 1; OffAction = 'Set'; OffValue = 0 }
                [PSCustomObject]@{ Path = 'HKCU:\System\GameConfigStore'; Name = 'GameDVR_DXGIHonorFSEWindowsCompatible'; RegType = 'DWord'; Value = 1; OffAction = 'Set'; OffValue = 0 }
                [PSCustomObject]@{ Path = 'HKCU:\System\GameConfigStore'; Name = 'GameDVR_EFSEFeatureFlags'; RegType = 'DWord'; Value = 0; OffAction = 'Delete' }
            )
        }
        [PSCustomObject]@{
            Name            = 'EnableGpuScheduling'
            DisplayLabel    = 'Enable hardware-accelerated GPU scheduling'
            Risk            = 'CAUTION'
            Consequence     = 'Takes effect after a restart; needs a WDDM 2.7+ driver - some older drivers perform worse with it on'
            RestartRequired = $true
            RegistryChanges = @(
                [PSCustomObject]@{ Path = 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers'; Name = 'HwSchMode'; RegType = 'DWord'; Value = 2; OffAction = 'Delete' }
            )
        }
        [PSCustomObject]@{
            Name            = 'ThrottleBackgroundInput'
            DisplayLabel    = 'Throttle background input to 50 Hz'
            Risk            = 'SAFE'
            Consequence     = $null
            RestartRequired = $false
            RegistryChanges = @(
                [PSCustomObject]@{ Path = 'HKCU:\Control Panel\Mouse'; Name = 'RawMouseThrottleEnabled'; RegType = 'DWord'; Value = 1; OffAction = 'Delete' }
                [PSCustomObject]@{ Path = 'HKCU:\Control Panel\Mouse'; Name = 'RawMouseThrottleDuration'; RegType = 'DWord'; Value = 20; OffAction = 'Delete' }
            )
        }
    )
}


function Test-WtGpuSchedulingSupported {
    <#
    .SYNOPSIS
        Hardware-accelerated GPU scheduling needs a WDDM 2.7+ driver
        (Sophia-Script's check): WddmVersion_Min under GraphicsDrivers\
        FeatureSetUsage reports the version x1000. Returns $false only when
        the value is present and below 2700; when it is absent the entry
        stays selectable (the driver simply may ignore HwSchMode).
    #>
    param(
        [scriptblock]$GetPropertyAction = {
            param($p, $n)
            Get-WtRegistryProperty -Path $p -Name $n
        }
    )

    $current = Get-WtRegistryValue -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers\FeatureSetUsage' -Name 'WddmVersion_Min' -GetPropertyAction $GetPropertyAction
    if ($current.Present -and [int]$current.Value -lt 2700) {
        return $false
    }
    return $true
}
#endregion src/40-catalogs/gaming.ps1

#region src/40-catalogs/hardening.ps1
# Extra Windows hardening rows as native registry entries.
# Covered by: tests/HardeningCatalog.Tests.ps1

function Test-WtIsWindows11 {
    <#
    .SYNOPSIS
        True on Windows 11 (build 22000 and later). Injectable so the OS
        filter can be exercised for both families from the tests.
    #>
    param([int]$Build = [System.Environment]::OSVersion.Version.Build)
    return ($Build -ge 22000)
}

