#region src/80-screens/apply.ps1
# Apply screen items, result lines/counts, Invoke-WtApplySelection, Invoke-WtApplyScreen.
# Covered by: tests/ApplyFlow.Tests.ps1, tests/Screens.Tests.ps1

function Test-WtEntryRemovable {
    <#
    .SYNOPSIS
        PURE: can this screen turn an applied entry back to its Windows
        default? Only when its section has a TurnOff delegate and (if the
        section defines IsRemovable) that delegate agrees for the entry.
    #>
    param(
        [AllowNull()][object]$Section,
        [Parameter(Mandatory)][PSCustomObject]$Entry
    )
    if ($null -eq $Section -or -not $Section.TurnOff) { return $false }
    if ($Section.IsRemovable) { return [bool](& $Section.IsRemovable $Entry) }
    return $true
}

function Get-WtApplyScreenItems {
    <#
    .SYNOPSIS
        PURE builder for an apply screen: turns catalog groups into
        Header/Info/Check(or Radio) rows plus a Meta map (Name ->
        SectionKey/Entry/Data) for the apply step. Delegates take the group
        as an argument, not a closure, since GetNewClosure breaks once built.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Groups,
        [array]$Sections = (Get-WtApplySectionCatalog)
    )
    $items = New-Object System.Collections.Generic.List[object]
    $meta = @{}
    foreach ($group in $Groups) {
        $sectionKey = [string]$group.SectionKey
        $section = $Sections | Where-Object Key -eq $sectionKey | Select-Object -First 1
        if ($group.HeaderKey) {
            $items.Add((New-WtListItem -Kind 'Header' -Name ('Header:' + $sectionKey) -Label (Get-Translation $group.HeaderKey)))
        }
        if ($group.InfoKey) {
            $items.Add((New-WtListItem -Kind 'Info' -Name ('Info:' + $sectionKey) -Label (Get-Translation $group.InfoKey)))
        }
        $kind = if ($group.Radio) { 'Radio' } else { 'Check' }
        $radioGroup = if ($group.Radio) { $sectionKey } else { '' }
        $lastSub = $null
        foreach ($entry in @(& $group.GetCatalog $group)) {
            if ($group.HeaderField -and ($entry.PSObject.Properties.Name -contains $group.HeaderField)) {
                $sub = [string]$entry.($group.HeaderField)
                if ($sub -and $sub -ne $lastSub) {
                    $items.Add((New-WtListItem -Kind 'Header' -Name ('Header:' + $sectionKey + ':' + $sub) -Label (Get-Translation $sub)))
                    $lastSub = $sub
                }
            }
            $state = & $group.GetEntryState $entry $group
            $applied = [bool]$state.Applied
            $available = if ($null -ne $state.Available) { [bool]$state.Available } else { $true }
            $stateLabel = if ($null -ne $state.StateLabel) { [string]$state.StateLabel }
                          elseif ($applied) { Get-Translation 'Applied' }
                          else { Get-Translation 'NotApplied' }
            $risk = if ($entry.PSObject.Properties.Name -contains 'Risk' -and $entry.Risk) { [string]$entry.Risk } else { '' }
            $removable = $applied -and (Test-WtEntryRemovable -Section $section -Entry $entry) -and $available
            $targets = @($(if ($entry.PSObject.Properties.Name -contains 'CycleTargets') { $entry.CycleTargets } else { @() }))
            $verbKey = $(if ($entry.PSObject.Properties.Name -contains 'PendingVerbKey') { [string]$entry.PendingVerbKey } else { '' })
            $items.Add((New-WtListItem -Kind $kind -Name $entry.Name -Label (Get-WtSelectorDisplayLabel -Entry $entry) `
                -Risk $risk -StateLabel $stateLabel -Selectable ($available -and (-not $applied -or $removable)) -Data $entry -Group $radioGroup `
                -Applied $applied -Removable $removable -CycleTargets $targets -PendingVerbKey $verbKey))
            $meta[[string]$entry.Name] = @{ SectionKey = $sectionKey; Entry = $entry; Data = $group.Data }
        }
    }
    return @{ Items = (Add-WtListGroupSpacers -Items $items.ToArray()); Meta = $meta }
}

function Get-WtApplyResultLines {
    <#
    .SYNOPSIS
        PURE formatter for the engine result: section title, then one line
        per row ("<label>: Applied" / "<label>: Not applied - <error>"). An
        Aborted section that already wrote rows before aborting prints those
        rows first, then the cancelled line, so the user sees what was written.
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Result,
        [array]$Sections = (Get-WtApplySectionCatalog)
    )
    $lines = New-Object System.Collections.Generic.List[string]
    if ($Result.Aborted -and @($Result.Sections).Count -eq 0) {
        $lines.Add((Get-Translation 'ActionCancelled'))
        return [string[]]$lines.ToArray()
    }
    $formatRow = {
        param($row)
        $isRemove = ($row.PSObject.Properties.Name -contains 'Direction') -and ([string]$row.Direction -eq 'Remove')
        $statusText = if ($isRemove) { if ($row.Applied) { Get-Translation 'Removed' } else { Get-Translation 'NotRemoved' } }
                      else { if ($row.Applied) { Get-Translation 'Applied' } else { Get-Translation 'NotApplied' } }
        if (-not $row.Applied -and $row.Error) { $statusText = "$statusText - $($row.Error)" }
        return '  ' + (Format-WtProfileResultLabel -Item $row.Item) + ': ' + $statusText
    }
    foreach ($sectionResult in @($Result.Sections)) {
        if ($sectionResult.Outcome -eq 'NothingToApply') { continue }
        $lines.Add([string](Get-Translation $sectionResult.TitleKey))
        switch ($sectionResult.Outcome) {
            'Aborted' {
                foreach ($row in @($sectionResult.Results)) { $lines.Add((& $formatRow $row)) }
                $lines.Add('  ' + (Get-Translation 'ActionCancelled'))
            }
            'Skipped' { $lines.Add('  ' + (Get-Translation 'ProfileImportStopped')) }
            default {
                foreach ($row in @($sectionResult.Results)) { $lines.Add((& $formatRow $row)) }
            }
        }
    }
    return [string[]]$lines.ToArray()
}

function Get-WtApplyResultCounts {
    <#
    .SYNOPSIS
        PURE: rows applied (Apply direction, Applied), removed (Remove
        direction, Applied) and failed (either direction, not Applied)
        across every section of an engine result.
    #>
    param([Parameter(Mandatory)][PSCustomObject]$Result)
    $applied = 0
    $removed = 0
    $failed = 0
    foreach ($sectionResult in @($Result.Sections)) {
        foreach ($row in @($sectionResult.Results)) {
            $isRemove = ($row.PSObject.Properties.Name -contains 'Direction') -and ([string]$row.Direction -eq 'Remove')
            if (-not $row.Applied) { $failed++ }
            elseif ($isRemove) { $removed++ }
            else { $applied++ }
        }
    }
    return @{ Applied = $applied; Removed = $removed; Failed = $failed }
}

function Invoke-WtApplySelection {
    <#
    .SYNOPSIS
        The apply flow of one screen, entirely inside the panel: marks ->
        gates -> summary with Enter-to-apply -> engine (in-panel progress)
        -> result lines -> Explorer-restart offer -> reboot note.
        Collaborators are injectable. Typing CONFIRM / ONAYLA / YES / EVET
        skips the summary step and applies immediately. The default
        -Engine/-OnSectionStart close over $progress/$Sections/$ShowMessage
        via dynamic scope, not GetNewClosure - codebase convention.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb,
        [Parameter(Mandatory)][AllowEmptyCollection()][System.Collections.Generic.HashSet[string]]$Selection,
        [Parameter(Mandatory)][AllowEmptyCollection()][hashtable]$Meta,
        [AllowEmptyCollection()][array]$Items = @(),
        [hashtable]$Cycle = @{},
        [array]$Sections = (Get-WtApplySectionCatalog),
        [scriptblock]$ReadAnswer = { param($Lines, $Prompt, $Risk) Read-WtPanelAnswer -Breadcrumb $script:WtPanelBreadcrumb -Lines $Lines -Prompt $Prompt -Risk $Risk },
        [scriptblock]$ShowMessage = { param($Lines, $Footer) Show-WtPanelMessage -Breadcrumb $script:WtPanelBreadcrumb -Lines $Lines -FooterText $Footer },
        [scriptblock]$Engine = {
            param($Plan)
            Invoke-WtCommitChangeSet -Plan $Plan -Sections $Sections `
                -OnSectionStart {
                    param($Key)
                    $section = $Sections | Where-Object Key -eq $Key | Select-Object -First 1
                    $title = if ($section) { Get-Translation $section.TitleKey } else { $Key }
                    $progress.Add(((Get-Translation 'CommitSectionStart') -f $title))
                    & $ShowMessage $progress.ToArray() (Get-Translation 'ApplyingFooter')
                }
        },
        [scriptblock]$RestartExplorer = { Invoke-WtRestartExplorer }
    )
    $script:WtPanelBreadcrumb = $Breadcrumb
    $records = @(ConvertTo-WtApplyRecords -Selection $Selection -Meta $Meta -Items $Items -Cycle $Cycle)
    if ($records.Count -eq 0) { return @{ Applied = $false } }

    $gated = Invoke-WtApplyGates -Records $records -Sections $Sections -ReadAnswer $ReadAnswer
    $plan = $gated.Plan
    $totalApply = 0
    $totalRemove = 0
    foreach ($s in @($plan.Sections)) { $totalApply += @($s.ApplyNames).Count; $totalRemove += @($s.RemoveNames).Count }
    $refusal = @(Get-WtGateRefusalLines -Dropped @($gated.Dropped))
    if (($totalApply + $totalRemove) -eq 0) {
        $nothing = New-Object System.Collections.Generic.List[string]
        foreach ($l in $refusal) { $nothing.Add($l) }
        if ($nothing.Count -gt 0) { $nothing.Add('') }
        $nothing.Add((Get-Translation 'ApplyNothingLeft'))
        $null = & $ReadAnswer $nothing.ToArray() (Get-Translation 'PressEnterContinue') 'CAUTION'
        return @{ Applied = $false }
    }

    if (-not $gated.TypedConfirmation -or $refusal.Count -gt 0) {
        $summary = New-Object System.Collections.Generic.List[string]
        foreach ($l in $refusal) { $summary.Add($l) }
        if ($refusal.Count -gt 0) { $summary.Add('') }
        $summary.Add((Get-Translation 'CommitSummaryTitle'))
        $summary.Add('')
        foreach ($s in @($plan.Sections)) { $summary.Add(('  {0}: {1}' -f (Get-Translation $s.TitleKey), (Format-WtDirectionCounts -ApplyCount @($s.ApplyNames).Count -RemoveCount @($s.RemoveNames).Count))) }
        if ($plan.HasExplorerRestart) { $summary.Add(''); $summary.Add((Get-Translation 'CommitExplorerNote')) }
        if (@($plan.RebootEntryNames).Count -gt 0) { $summary.Add(((Get-Translation 'RebootRequiredNote') -f (@($plan.RebootEntryNames) -join ', '))) }
        $answer = & $ReadAnswer $summary.ToArray() ((Get-Translation 'ApplyNowPrompt') -f (Format-WtDirectionCounts -ApplyCount $totalApply -RemoveCount $totalRemove)) ''
        if ($null -eq $answer -or ([string]$answer).Trim() -ne '') { return @{ Applied = $false } }
    }

    $progress = New-Object System.Collections.Generic.List[string]
    $result = & $Engine $plan

    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($l in @(Get-WtApplyResultLines -Result $result -Sections $Sections)) { $lines.Add($l) }
    if ($result.NeedsExplorerRestart) {
        $a = & $ReadAnswer $lines.ToArray() (Get-WtYesNoPrompt -Text (Get-Translation 'RestartExplorerPrompt')) ''
        if (Test-WtAffirmativeAnswer -Answer ([string]$a)) {
            $rs = & $RestartExplorer
            $lines.Add($(if ($rs -and $rs.Restarted) { Get-Translation 'RestartExplorerDone' } else { Get-Translation 'RestartExplorerFailed' }))
        }
        else { $lines.Add((Get-Translation 'RestartExplorerDeferred')) }
    }
    if (@($result.RebootEntryNames).Count -gt 0) { $lines.Add(((Get-Translation 'RebootRequiredNote') -f (@($result.RebootEntryNames) -join ', '))) }
    $counts = Get-WtApplyResultCounts -Result $result
    if (($counts.Applied + $counts.Removed + $counts.Failed) -gt 0) { $lines.Add(((Get-Translation 'ApplyDoneSummary') -f $counts.Applied, $counts.Removed, $counts.Failed)) }
    $applied = (@($result.Sections | Where-Object { $_.Outcome -eq 'Applied' }).Count -gt 0)
    if ($applied) { $lines.Add(''); $lines.Add((Get-Translation 'ApplySummaryDone')) }
    $null = & $ReadAnswer $lines.ToArray() (Get-Translation 'PressEnterContinue') ''
    return @{ Applied = $applied }
}

function Invoke-WtApplyScreen {
    <#
    .SYNOPSIS
        Shell shared by every "mark with Space, apply with Enter" screen:
        builds rows, runs the multi-select list, applies marks, rebuilds.
        -Groups/-ExtraItems take an array or a scriptblock re-resolved each
        rebuild; ExtraItems sit above the catalog (Link rows push a screen,
        Action rows run in console-output mode). A delegate's "return @()"
        binds $null in argument position, not an empty array, so $null here
        means "no extras". Returns
        @{ Nav = 'Back'|'Exit'|'Push'; Target; Char; HasMarks }.
    #>
    param(
        [Parameter(Mandatory)][string]$Breadcrumb,
        [Parameter(Mandatory)][AllowEmptyCollection()][object]$Groups,
        [AllowEmptyCollection()][object]$ExtraItems = @(),
        [string]$CounterKey = 'SettingsCount',
        [string]$FooterKey = 'ApplyFooter',
        [scriptblock]$OnHotkey,
        [hashtable]$CycleLabels = @{}
    )
    $cursor = -1
    while ($true) {
        Show-WtListLoading -Breadcrumb $Breadcrumb
        if ($Groups -is [scriptblock]) { $groupList = @(& $Groups) } else { $groupList = @($Groups) }
        if ($ExtraItems -is [scriptblock]) { $extraList = @(& $ExtraItems) }
        elseif ($null -eq $ExtraItems) { $extraList = @() }
        else { $extraList = @($ExtraItems) }
        $extraList = @($extraList | Where-Object { $null -ne $_ })
        $built = Get-WtApplyScreenItems -Groups $groupList
        $items = @($extraList) + @($built.Items)
        if ($items.Count -eq 0) { $items = @(New-WtListItem -Kind 'Info' -Name 'Empty' -Label (Get-Translation 'NoEntriesAvailable')) }
        $selection = New-Object 'System.Collections.Generic.HashSet[string]'
        $cycle = @{}
        $footer = Get-Translation $FooterKey
        $settingCount = @($built.Items | Where-Object { $_.Kind -eq 'Check' -or $_.Kind -eq 'Radio' }).Count
        $counter = (Get-Translation $CounterKey) -f $settingCount
        $rebuild = $false
        while (-not $rebuild) {
            $r = Invoke-WtListScreen -Breadcrumb $Breadcrumb -Items $items -MultiSelect $true -Selection $selection -FooterText $footer -CounterText $counter -InitialCursor $cursor -Cycle $cycle -CycleLabels $CycleLabels -Searchable $true
            $cursor = [int]$r.CursorIndex
            if ($r.Emit -eq 'Back') { return @{ Nav = 'Back'; Target = ''; Char = ''; HasMarks = $false } }
            if ($r.Emit -eq 'Quit') { return @{ Nav = 'Exit'; Target = ''; Char = ''; HasMarks = ($selection.Count -gt 0) } }
            if ($r.Emit -eq 'Global') {
                if ($OnHotkey -and (& $OnHotkey $r.Char)) { $rebuild = $true }
                continue
            }
            if ($r.Emit -ne 'Activate' -or -not $r.Item) { continue }
            $data = $r.Item.Data
            if ($r.Item.Kind -eq 'Link' -and $data -and $data.Screen) { return @{ Nav = 'Push'; Target = [string]$data.Screen; Char = ''; HasMarks = $false } }
            if ($r.Item.Kind -eq 'Action' -and $data -and $data.Action) {
                Invoke-WtCapturedAction -Title ([string]$r.Item.Label) -Breadcrumb $Breadcrumb -Action $data.Action
                continue
            }
            if ($selection.Count -eq 0) { $footer = Get-Translation 'MarkFirstHint'; continue }
            $null = Invoke-WtApplySelection -Breadcrumb $Breadcrumb -Selection $selection -Meta $built.Meta -Items $items -Cycle $cycle
            $rebuild = $true
        }
    }
}
#endregion src/80-screens/apply.ps1

#region src/80-screens/assistant-repl.ps1
# The assistant's plain-console REPL: pickers, slash commands, first-run
# wizard, and the loop. Every backend is an injectable seam.
# Covered by: tests/AssistantRepl.Tests.ps1

function Invoke-WtReplPick {
    <#
    .SYNOPSIS
        The REPL's numbered/arrow picker, kept under its old name and
        shape for the slash handlers and the wizard: delegates to
        Read-WtReplPick; -AllowText adds the "paste / type" row.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Title,
        [AllowEmptyCollection()][string[]]$Options = @(),
        [switch]$AllowText,
        [scriptblock]$ReadLine = { param($P) Read-WtReplLine -Prompt $P },
        [scriptblock]$ReadPick = { param($T, $O, $X) Read-WtReplPick -Title $T -Options $O -TextOption $X -ReadLine $ReadLine }
    )
    $textOption = $(if ($AllowText) { [string](Get-Translation 'AsPickTypeOption') } else { '' })
    $r = & $ReadPick $Title ([string[]]@($Options)) $textOption
    return @{ Index = [int]$r.Index; Text = [string]$r.Text }
}

function Invoke-WtReplChooseModel {
    <#
    .SYNOPSIS
        The /model picker. The list comes from the ACTIVE identity, not
        from AssistantEndpoint: in ChatGPT mode that is the curated
        catalogue, and the endpoint left in settings - which may be some
        other provider entirely - is never asked.
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Settings,
        [AllowNull()][AllowEmptyString()][string]$PlainApiKey = $null,
        [scriptblock]$GetModels = { param($E, $K) Get-WtLlmModelList -Endpoint $E -ApiKey $K },
        [scriptblock]$ReadLine = { param($P) Read-WtReplLine -Prompt $P }
    )
    $chatGptMode = Test-WtAssistantChatGptMode -AuthMode ([string]$Settings.AssistantAuthMode)
    if (-not $chatGptMode) { Write-WtReplLine -Text (Get-Translation 'AsLoadingModels') -Fg 'DarkGray' }
    $list = Get-WtAssistantModelChoices -Settings $Settings -PlainApiKey $PlainApiKey -GetModels $GetModels
    $models = [string[]]@()
    if ($list.Ok) { $models = [string[]]@($list.Models) } else { Write-WtReplLine -Text ([string]$list.ErrorText) -Fg 'Red' }
    if ([string]$list.HintKey) { Write-WtReplLine -Text (Get-Translation ([string]$list.HintKey)) -Fg 'DarkGray' }
    $pick = Invoke-WtReplPick -Title (Get-Translation 'AsSetModel') -Options $models -AllowText -ReadLine $ReadLine
    if ($pick.Index -gt 0) { return [string]$models[$pick.Index - 1] }
    return [string]$pick.Text
}

function Invoke-WtReplChooseServer {
    <#
    .SYNOPSIS
        Scan result -> endpoint + model, inline: pick a server, Ollama's
        list narrowed to tool-capable models, a single model taken as is,
        otherwise picked or typed. $null when the user gave up.
    #>
    param(
        [AllowEmptyCollection()][array]$Servers = @(),
        [scriptblock]$ReadLine = { param($P) Read-WtReplLine -Prompt $P },
        [scriptblock]$FilterOllama = { param($Models) Get-WtOllamaToolCapableModels -Models $Models }
    )
    $rows = @($Servers)
    if ($rows.Count -eq 0) { return $null }
    $names = @($rows | ForEach-Object { [string]$_.Provider + '  (' + [string]$_.Endpoint + ')' })
    $pick = Invoke-WtReplPick -Title (Get-Translation 'AsScanPickServer') -Options $names -ReadLine $ReadLine
    if ($pick.Index -lt 1) { return $null }
    $server = $rows[$pick.Index - 1]
    $models = [string[]]@($server.Models)
    if ([string]$server.Provider -eq 'Ollama') {
        Write-WtReplLine -Text (Get-Translation 'AsProbingTools') -Fg 'DarkGray'
        $models = [string[]]@(& $FilterOllama $models)
    }
    $model = ''
    if ($models.Count -eq 1) { $model = [string]$models[0] }
    else {
        $mp = Invoke-WtReplPick -Title (Get-Translation 'AsSetModel') -Options $models -AllowText -ReadLine $ReadLine
        $model = $(if ($mp.Index -gt 0) { [string]$models[$mp.Index - 1] } else { [string]$mp.Text })
    }
    if (-not $model) { return $null }
    return @{ Endpoint = [string]$server.Endpoint; Model = $model }
}

function Get-WtReplStatusLines {
    <#
    .SYNOPSIS
        The /status block. In ChatGPT mode the endpoint and key rows are
        replaced by the signed-in account: printing a stale endpoint and
        a key that nothing reads would describe an identity that is not
        the one answering.
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Settings,
        [Parameter(Mandatory)][hashtable]$Session,
        [AllowNull()][hashtable]$Permissions = $null,
        [AllowNull()][hashtable]$Auth = $null,
        [int]$NoteCount = 0
    )
    $where = Get-WtAssistantWhereTag -Settings $Settings
    $notSet = [string](Get-Translation 'AsNotSet')
    $endpoints = 0
    if ($null -ne $Permissions) { $endpoints = @($Permissions.endpoints).Count }
    $identity = [string[]]@(
        ((Get-Translation 'AsStatusEndpoint') -f $(if ([string]$Settings.AssistantEndpoint) { [string]$Settings.AssistantEndpoint } else { $notSet }), $where)
        ((Get-Translation 'AsStatusKey') -f $(if ([string]$Settings.AssistantApiKey) { '****' } else { $notSet }))
    )
    if (Test-WtAssistantChatGptMode -AuthMode ([string]$Settings.AssistantAuthMode)) {
        $account = Get-WtChatGptAccountStateLabel -Auth $Auth
        if (-not $account) { $account = $notSet }
        $identity = [string[]]@(((Get-Translation 'AsStatusChatGptAccount') -f $account))
    }
    return [string[]]@(
        $identity
        ((Get-Translation 'AsStatusModel') -f $(if ([string]$Settings.AssistantModel) { [string]$Settings.AssistantModel } else { $notSet }))
        ((Get-Translation 'AsStatusContext') -f (Get-WtReplContextPercent -Messages @($Session.Messages.ToArray()) -MaxChars $(if ([int]$Session.HistoryMaxChars -gt 0) { [int]$Session.HistoryMaxChars } else { 40000 })), $Session.Messages.Count)
        ((Get-Translation 'AsStatusPerms') -f $endpoints)
        ((Get-Translation 'AsStatusSampling') -f $(if ([string]$Settings.AssistantTemperature) { [string]$Settings.AssistantTemperature } else { $notSet }), $(if ([string]$Settings.AssistantMaxTokens) { [string]$Settings.AssistantMaxTokens } else { $notSet }))
        ((Get-Translation 'AsStatusNumCtx') -f $(if ([string]$Settings.AssistantNumCtx) { [string]$Settings.AssistantNumCtx } else { $notSet }))
        ((Get-Translation 'AsStatusProfile') -f $(if ($Session.ProfileEnabled) { Get-Translation 'AsOn' } else { Get-Translation 'AsOff' }))
        ((Get-Translation 'AsStatusNotes') -f $NoteCount)
        (Format-WtReplUsageLine -Usage $Session.LastUsage)
    )
}

function Get-WtReplTranscriptReportLines {
    param([Parameter(Mandatory)][hashtable]$Session)
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($entry in @($Session.Entries.ToArray())) {
        foreach ($row in (Get-WtReplEntryLines -Kind ([string]$entry.Kind) -Text ([string]$entry.Text))) { $lines.Add(((@($row) | ForEach-Object { [string]$_.T }) -join '')) }
    }
    foreach ($l in @(Get-WtReplSuggestionLines -Suggestions @($Session.Suggestions))) { $lines.Add($l) }
    return [string[]]$lines.ToArray()
}

function Write-WtReplPage {
    <#
    .SYNOPSIS
        A fresh assistant page: clear the console (viewport + scrollback)
        and print the banner + breadcrumb. Used on entry, after /yeni
        (= /temizle), /unut and when the REPL is re-entered from the menu.
    #>
    param()
    Clear-WtReplScreen
    Write-WtReplHeader
}

function Invoke-WtAssistantSlash {
    <#
    .SYNOPSIS
        One local command. Nothing here talks to the model. Returns what
        the loop must do next and the settings as saved. A confirmation
        rides back on the result's Notice field rather than being
        printed directly, since a command that starts a new session
        repaints the header and would erase a line printed here.
        Settings are re-read after every save rather than merged in
        memory, so the loop sees exactly what Save-WtSettings persisted.
        Disabled tools are both dropped from the model request and
        refused again at dispatch, in case a model still names one. The
        settings screen's Exit verdict is passed back through rather
        than swallowed, since its footer told the user to press the key
        that produced it.
    #>
    param(
        [Parameter(Mandatory)][string]$Command,
        [AllowNull()][AllowEmptyString()][string]$Argument = '',
        [Parameter(Mandatory)][hashtable]$Session,
        [Parameter(Mandatory)][PSCustomObject]$Settings,
        [scriptblock]$ReadLine = { param($P) Read-WtReplLine -Prompt $P },
        [scriptblock]$Scan = { Find-WtLocalLlmServers },
        [scriptblock]$GetModels = { param($E, $K) Get-WtLlmModelList -Endpoint $E -ApiKey $K },
        [scriptblock]$Test = { param($S) Invoke-WtAssistantConnectionTest -Settings $S },
        [scriptblock]$Save = { param($S) Save-WtSettings -Settings $S },
        [scriptblock]$ReadSettings = { Read-WtSettings },
        [scriptblock]$SaveReport = { param($Lines) Save-WtReport -Name 'assistant-chat' -Lines $Lines },
        [AllowNull()][hashtable]$Permissions = $null,
        [scriptblock]$SavePermissions = { param($P) Save-WtAssistantPermissions -Permissions $P },
        [scriptblock]$ReadPermissions = { Read-WtAssistantPermissions },
        [scriptblock]$Profile = { param($Force) if ($Force) { Get-WtAssistantMachineProfile -Kind 'Short' -Force } else { Get-WtAssistantMachineProfile -Kind 'Short' } },
        [scriptblock]$ReadNotes = { Read-WtAssistantNotes },
        [scriptblock]$RemoveNote = { param($I) Remove-WtAssistantNote -Index $I },
        [scriptblock]$ClearMemory = { Clear-WtAssistantMemory },
        [scriptblock]$Hop = { param($A) Invoke-WtReplHop -Action $A },
        [scriptblock]$OpenSettings = { Invoke-WtAssistantSettingsScreen },
        [scriptblock]$SetClipboard = { param($T) Set-Clipboard -Value $T }
    )
    $result = @{ Nav = 'None'; Settings = $Settings; NewSession = $false; Notice = ''; NoticeFg = 'DarkYellow' }
    $saveAndReload = { param($Patch)
        & $Save $Patch
        $result.Settings = & $ReadSettings
    }
    switch ($Command) {
        'new' { $result.NewSession = $true }
        'quit' { $result.Nav = 'Back' }
        'help' {
            foreach ($l in @(Get-WtReplHelpLines)) { Write-WtReplLine -Text $l }
            Write-WtReplLine -Text ''
            Write-WtReplLine -Text (Get-Translation 'AsReplHelpKeys1') -Fg 'DarkGray'
            Write-WtReplLine -Text (Get-Translation 'AsReplHelpKeys2') -Fg 'DarkGray'
        }
        'status' {
            $statusPerms = $Permissions
            if ($null -eq $statusPerms) { $statusPerms = & $ReadPermissions }
            foreach ($l in @(Get-WtReplStatusLines -Settings $Settings -Session $Session -Permissions $statusPerms -Auth (Read-WtChatGptAuth) -NoteCount @(& $ReadNotes).Count)) { Write-WtReplLine -Text $l }
        }
        'model' {
            $parts = @(([string]$Argument).Trim() -split '\s+' | Where-Object { $_ })
            $model = $(if ($parts.Count -ge 1) { [string]$parts[0] } else { '' })
            if (-not $model) {
                if (-not (Test-WtAssistantChatGptMode -AuthMode ([string]$Settings.AssistantAuthMode)) -and -not [string]$Settings.AssistantEndpoint) {
                    Write-WtReplLine -Text (Get-Translation 'AsReplNeedEndpoint') -Fg 'Red'; break
                }
                $model = Invoke-WtReplChooseModel -Settings $Settings -GetModels $GetModels -ReadLine $ReadLine
            }
            if ($model) {
                $patch = @{ AssistantModel = $model }
                if ($parts.Count -ge 2) {
                    $t = 0.0
                    if ([double]::TryParse([string]$parts[1], [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$t) -and $t -ge 0 -and $t -le 2) {
                        $patch['AssistantTemperature'] = [string]$parts[1]
                    }
                }
                if ($parts.Count -ge 3) {
                    $m = 0
                    if ([int]::TryParse([string]$parts[2], [ref]$m) -and $m -gt 0) {
                        $patch['AssistantMaxTokens'] = [string]$parts[2]
                    }
                }
                & $saveAndReload ([PSCustomObject]$patch)
                Write-WtReplLine -Text ((Get-Translation 'AsReplSaved') -f $model) -Fg 'DarkYellow'
            }
        }
        'endpoint' {
            if (Test-WtAssistantChatGptMode -AuthMode ([string]$Settings.AssistantAuthMode)) {
                Write-WtReplLine -Text (Get-Translation 'AsChatGptNotUsedInMode') -Fg 'DarkYellow'; break
            }
            $endpoint = ([string]$Argument).Trim()
            if (-not $endpoint) {
                $presets = @(Get-WtLlmPresets)
                $pick = Invoke-WtReplPick -Title (Get-Translation 'AsEndpointHint') -Options @($presets | ForEach-Object { [string]$_.Name + '  (' + [string]$_.Endpoint + ')' }) -AllowText -ReadLine $ReadLine
                $endpoint = $(if ($pick.Index -gt 0) { [string]$presets[$pick.Index - 1].Endpoint } else { [string]$pick.Text })
            }
            if ($endpoint -and ($endpoint.StartsWith('http://', [System.StringComparison]::OrdinalIgnoreCase) -or $endpoint.StartsWith('https://', [System.StringComparison]::OrdinalIgnoreCase))) {
                $script:WtAssistantPrivacyEndpoint = ''
                & $saveAndReload ([PSCustomObject]@{ AssistantEndpoint = $endpoint })
                Write-WtReplLine -Text ((Get-Translation 'AsReplSaved') -f $endpoint) -Fg 'DarkYellow'
            }
            elseif ($endpoint) { Write-WtReplLine -Text (Get-Translation 'AsEndpointHint') -Fg 'Red' }
        }
        'key' {
            if (Test-WtAssistantChatGptMode -AuthMode ([string]$Settings.AssistantAuthMode)) {
                Write-WtReplLine -Text (Get-Translation 'AsChatGptNotUsedInMode') -Fg 'DarkYellow'; break
            }
            Write-WtReplLine -Text (Get-Translation 'AsApiKeyHint')
            $r = Read-WtReplLine -Prompt ([string](Get-Translation 'AsSetApiKey') + ': ') -Secret
            if ([string]$r.Kind -eq 'Submit') {
                & $saveAndReload ([PSCustomObject]@{ AssistantApiKey = (Protect-WtAssistantSecret -PlainText (([string]$r.Text).Trim())) })
                Write-WtReplLine -Text (Get-Translation 'AsReplKeySaved') -Fg 'DarkYellow'
            }
        }
        'scan' {
            if (Test-WtAssistantChatGptMode -AuthMode ([string]$Settings.AssistantAuthMode)) {
                Write-WtReplLine -Text (Get-Translation 'AsChatGptNotUsedInMode') -Fg 'DarkYellow'; break
            }
            Write-WtReplLine -Text (Get-Translation 'AsScanning') -Fg 'DarkGray'
            $servers = @(& $Scan)
            if ($servers.Count -eq 0) {
                Write-WtReplLine -Text (Get-Translation 'AsScanNothing') -Fg 'Red'
                foreach ($h in @(Get-WtLlmLocalHints)) { Write-WtReplLine -Text $h -Fg 'DarkYellow' }
                break
            }
            $choice = Invoke-WtReplChooseServer -Servers $servers -ReadLine $ReadLine
            if ($null -ne $choice) {
                $script:WtAssistantPrivacyEndpoint = ''
                & $saveAndReload ([PSCustomObject]@{ AssistantEndpoint = [string]$choice.Endpoint; AssistantModel = [string]$choice.Model })
                Write-WtReplLine -Text ((Get-Translation 'AsAutoSelected') -f [string]$choice.Model, [string]$choice.Endpoint) -Fg 'DarkYellow'
            }
        }
        'test' {
            if (-not (Test-WtAssistantConfigured -Settings $Settings)) { Write-WtReplLine -Text (Get-Translation 'AsReplNeedEndpoint') -Fg 'Red'; break }
            Write-WtReplLine -Text (Get-Translation 'AsTesting') -Fg 'DarkGray'
            foreach ($l in @(& $Test $Settings)) { Write-WtReplLine -Text $l }
        }
        'perms' {
            $perms = $Permissions
            if ($null -eq $perms) { $perms = & $ReadPermissions }
            $endpointRows = @($perms.endpoints)
            if ($endpointRows.Count -eq 0) { Write-WtReplLine -Text (Get-Translation 'AsPermsEmpty') -Fg 'DarkYellow'; break }
            $options = @($endpointRows | ForEach-Object { (Get-Translation 'AsPermsEndpointRow') + '  ' + [string]$_.endpoint + '  (' + [string]$_.at + ')' })
            $pick = Invoke-WtReplPick -Title (Get-Translation 'AsPermsTitle') -Options $options -ReadLine $ReadLine
            if ($pick.Index -ge 1) {
                $e = $pick.Index - 1
                $keep = New-Object System.Collections.Generic.List[object]
                for ($i = 0; $i -lt $endpointRows.Count; $i++) { if ($i -ne $e) { $keep.Add($endpointRows[$i]) } }
                if ([string]::Equals([string]$script:WtAssistantPrivacyEndpoint, [string]$endpointRows[$e].endpoint, [System.StringComparison]::Ordinal)) { $script:WtAssistantPrivacyEndpoint = '' }
                $perms.endpoints = @($keep.ToArray())
                & $SavePermissions $perms
                Write-WtReplLine -Text (Get-Translation 'AsPermsRevoked') -Fg 'DarkYellow'
            }
        }
        'tools' {
            $perms = $Permissions
            if ($null -eq $perms) { $perms = & $ReadPermissions }
            $records = @(Get-WtAssistantToolRegistry)
            $off = [string[]]@(Get-WtAssistantDisabledTools -Permissions $perms -Registry $records)
            $options = @(foreach ($rec in $records) {
                $state = $(if (Test-WtAssistantToolDisabled -Name ([string]$rec.Name) -Disabled $off) { Get-Translation 'AsOff' } else { Get-Translation 'AsOn' })
                [string]$rec.Name + '  [' + [string]$rec.Tier + ']  ' + [string]$state
            })
            $pick = Invoke-WtReplPick -Title (Get-Translation 'AsToolsTitle') -Options $options -ReadLine $ReadLine
            if ($pick.Index -ge 1) {
                $rec = $records[$pick.Index - 1]
                $name = [string]$rec.Name
                $turningOn = (Test-WtAssistantToolDisabled -Name $name -Disabled $off)
                $without = { param($List) @(@($List) | ForEach-Object { [string]$_ } | Where-Object { $_ -and -not [string]::Equals($_, $name, [System.StringComparison]::Ordinal) }) }
                $disabled = & $without $(if ($perms.ContainsKey('disabled')) { $perms.disabled } else { @() })
                if (-not $turningOn) { $disabled += $name }
                $perms['disabled'] = @($disabled)
                & $SavePermissions $perms
                $state = [string](Get-Translation $(if ($turningOn) { 'AsOn' } else { 'AsOff' }))
                Write-WtReplLine -Text (((Get-Translation 'AsToolsToggled') -f $name, $state)) -Fg 'DarkYellow'
                Write-WtReplLine -Text ((Get-Translation 'AsToolsNextChat')) -Fg 'DarkGray'
            }
        }
        'forget' {
            Write-WtReplLine -Text (Get-Translation 'AsForgetWarning') -Fg 'DarkYellow'
            $r = & $ReadLine (Get-WtYesNoPrompt -Text (Get-Translation 'AsForgetPrompt'))
            if ([string]$r.Kind -eq 'Submit' -and (Test-WtAffirmativeAnswer -Answer ([string]$r.Text))) {
                $count = [int](& $ClearMemory)
                $script:WtAssistantPrivacyEndpoint = ''
                $result.NewSession = $true
                $result.Notice = [string]((Get-Translation 'AsForgotten') -f $count)
            }
        }
        'profile' {
            $word = ConvertTo-WtAssistantSearchText -Text (([string]$Argument).Trim())
            if ($word -eq 'off' -or $word -eq 'kapat') { $Session.ProfileEnabled = $false; Reset-WtAssistantSessionExtra -Chat $Session; Write-WtReplLine -Text ((Get-Translation 'AsProfileOff')) -Fg 'DarkYellow' }
            elseif ($word -eq 'on' -or $word -eq 'ac') { $Session.ProfileEnabled = $true; Reset-WtAssistantSessionExtra -Chat $Session; Write-WtReplLine -Text ((Get-Translation 'AsProfileOn')) -Fg 'DarkYellow' }
            elseif ($word -eq 'yenile' -or $word -eq 'refresh') {
                Write-WtReplLine -Text ((Get-Translation 'AsProfileBuilding')) -Fg 'DarkGray'
                $p = & $Profile $true
                Reset-WtAssistantSessionExtra -Chat $Session
                Write-WtReplLine -Text (((Get-Translation 'AsProfileRebuilt') -f ([string]$p.Json).Length)) -Fg 'DarkYellow'
            }
            else {
                $p = & $Profile $false
                $state = $(if ($Session.ProfileEnabled) { Get-Translation 'AsOn' } else { Get-Translation 'AsOff' })
                Write-WtReplLine -Text (((Get-Translation 'AsProfileStatus') -f $state, [string]$p.BuiltAt, ([string]$p.Json).Length))
                if ([string]$p.Json) { Write-WtReplLine -Text ([string]$p.Json) -Fg 'DarkGray' }
            }
        }
        'notes' {
            $notes = @(& $ReadNotes)
            if ($notes.Count -eq 0) { Write-WtReplLine -Text (Get-Translation 'AsNotesEmpty') -Fg 'DarkYellow'; break }
            $pick = Invoke-WtReplPick -Title (Get-Translation 'AsNotesTitle') -Options @($notes | ForEach-Object { [string]$_.text + '  (' + ([string]$_.at).Substring(0, [Math]::Min(10, ([string]$_.at).Length)) + ')' }) -ReadLine $ReadLine
            if ($pick.Index -ge 1 -and (& $RemoveNote ([int]$pick.Index))) { Reset-WtAssistantSessionExtra -Chat $Session; Write-WtReplLine -Text (Get-Translation 'AsNoteRemoved') -Fg 'DarkYellow' }
        }
        'save' {
            $path = [string](& $SaveReport ([string[]]@(Get-WtReplTranscriptReportLines -Session $Session)))
            Write-WtReplLine -Text ((Get-Translation 'ReportSaved') + ': ' + $path) -Fg 'DarkYellow'
        }
        'settings' {
            $before = [string]$Settings.AssistantEndpoint
            $hopOut = & $Hop $OpenSettings
            if ($null -ne $hopOut -and [string]$hopOut.Nav -eq 'Exit') { $result.Nav = 'Exit' }
            $result.Settings = & $ReadSettings
            $after = [string]$result.Settings.AssistantEndpoint
            if (-not [string]::Equals($before, $after, [System.StringComparison]::Ordinal)) { $script:WtAssistantPrivacyEndpoint = '' }
            $modelNow = [string]$result.Settings.AssistantModel
            if (-not $modelNow) { $modelNow = [string](Get-Translation 'AsNotSet') }
            if (-not $after) { $after = [string](Get-Translation 'AsNotSet') }
            Write-WtReplLine -Text ((Get-Translation 'AsReplSettingsBack') -f $modelNow, $after) -Fg 'DarkYellow'
        }
        'copy' {
            $n = 1
            $parsedN = 0
            if ([int]::TryParse(([string]$Argument).Trim(), [ref]$parsedN) -and $parsedN -ge 1) { $n = $parsedN }
            $answers = @($Session.Entries.ToArray() | Where-Object { [string]$_.Kind -eq 'Assistant' -and [string]$_.Text })
            if ($answers.Count -lt $n) { Write-WtReplLine -Text (Get-Translation 'AsReplNothingToCopy') -Fg 'DarkYellow'; break }
            $text = [string]$answers[$answers.Count - $n].Text
            $copied = $true
            try { & $SetClipboard $text } catch { $copied = $false }
            if ($copied) { Write-WtReplLine -Text ((Get-Translation 'AsReplCopied') -f $text.Length) -Fg 'DarkYellow' }
            else { Write-WtReplLine -Text (Get-Translation 'AsReplCopyFailed') -Fg 'Red' }
        }
        default { Write-WtReplLine -Text ((Get-Translation 'AsReplUnknownSlash') -f $Command) -Fg 'DarkYellow' }
    }
    return $result
}

function Invoke-WtAssistantReplWizard {
    <#
    .SYNOPSIS
        First run, inline: scan the local ports, list what answered,
        take a number or a pasted endpoint, ask for a key when the
        endpoint is remote (masked), pick the model, run the probe test,
        save. Nothing found and nothing pasted: say where keys and local
        servers come from and hand the prompt back.
    #>
    param(
        [scriptblock]$ReadLine = { param($P, $Secret) if ($Secret) { Read-WtReplLine -Prompt $P -Secret } else { Read-WtReplLine -Prompt $P } },
        [scriptblock]$Scan = { Find-WtLocalLlmServers },
        [scriptblock]$GetModels = { param($E, $K) Get-WtLlmModelList -Endpoint $E -ApiKey $K },
        [scriptblock]$Test = { param($S) Invoke-WtAssistantConnectionTest -Settings $S },
        [scriptblock]$Save = { param($S) Save-WtSettings -Settings $S },
        [scriptblock]$ProbeOllama = { param($M) Test-WtOllamaModelToolCapable -Model $M },
        [scriptblock]$FilterOllama = { param($Models) Get-WtOllamaToolCapableModels -Models $Models }
    )
    Write-WtReplLine -Text (Get-Translation 'AsWizardIntro') -Fg 'White'
    Write-WtReplLine -Text (Get-Translation 'AsScanning') -Fg 'DarkGray'
    $servers = @(& $Scan)
    $endpoint = ''
    $model = ''
    $apiKey = ''
    $isOllama = $false
    $names = @($servers | ForEach-Object { [string]$_.Provider + '  (' + [string]$_.Endpoint + ')' })
    if ($names.Count -eq 0) { Write-WtReplLine -Text (Get-Translation 'AsScanNothing') -Fg 'DarkYellow' }
    $pick = Invoke-WtReplPick -Title (Get-Translation 'AsWizardPickOrPaste') -Options $names -AllowText -ReadLine $ReadLine
    if ($pick.Index -ge 1) {
        $server = $servers[$pick.Index - 1]
        $endpoint = [string]$server.Endpoint
        $isOllama = ([string]$server.Provider -eq 'Ollama')
        $models = [string[]]@($server.Models)
        if ($isOllama) { Write-WtReplLine -Text (Get-Translation 'AsProbingTools') -Fg 'DarkGray'; $models = [string[]]@(& $FilterOllama $models) }
        if ($models.Count -eq 1) { $model = [string]$models[0] }
        else {
            $mp = Invoke-WtReplPick -Title (Get-Translation 'AsSetModel') -Options $models -AllowText -ReadLine $ReadLine
            $model = $(if ($mp.Index -gt 0) { [string]$models[$mp.Index - 1] } else { [string]$mp.Text })
        }
    }
    elseif ($pick.Text -and ($pick.Text.StartsWith('http://', [System.StringComparison]::OrdinalIgnoreCase) -or $pick.Text.StartsWith('https://', [System.StringComparison]::OrdinalIgnoreCase))) {
        $endpoint = [string]$pick.Text
        if (Test-WtAssistantRemoteEndpoint -Endpoint $endpoint) {
            Write-WtReplLine -Text (Get-Translation 'AsApiKeyHint')
            $k = & $ReadLine ([string](Get-Translation 'AsSetApiKey') + ': ') $true
            if ([string]$k.Kind -eq 'Submit') { $apiKey = ([string]$k.Text).Trim() }
        }
        $model = Invoke-WtReplChooseModel -GetModels $GetModels -ReadLine $ReadLine -PlainApiKey $apiKey `
            -Settings ([PSCustomObject]@{ AssistantEndpoint = $endpoint; AssistantApiKey = ''; AssistantAuthMode = '' })
    }
    if (-not ($endpoint -and $model)) {
        Write-WtReplLine -Text (Get-Translation 'AsWizardKeySources') -Fg 'DarkYellow'
        foreach ($h in @(Get-WtLlmLocalHints)) { Write-WtReplLine -Text $h -Fg 'DarkYellow' }
        Write-WtReplLine -Text (Get-Translation 'AsWizardLater') -Fg 'DarkYellow'
        return $null
    }
    if ($isOllama) {
        $verdict = [string](& $ProbeOllama $model)
        if ($verdict -eq 'NoTools') { Write-WtReplLine -Text (Get-Translation 'AsTestToolsMissing') -Fg 'Red'; return $null }
    }
    $settings = [PSCustomObject]@{ AssistantEndpoint = $endpoint; AssistantModel = $model; AssistantApiKey = (Protect-WtAssistantSecret -PlainText $apiKey) }
    Write-WtReplLine -Text (Get-Translation 'AsTesting') -Fg 'DarkGray'
    foreach ($l in @(& $Test $settings)) { Write-WtReplLine -Text $l }
    & $Save $settings
    $script:WtAssistantPrivacyEndpoint = ''
    Write-WtReplLine -Text ((Get-Translation 'AsAutoSelected') -f $model, $endpoint) -Fg 'DarkYellow'
    return $settings
}

function Invoke-WtAssistantScreen {
    <#
    .SYNOPSIS
        The assistant as a plain-console REPL: run the wizard if nothing
        is configured, then loop a line to the model, a lone number
        opening that suggestion, a /command running locally, and Esc x3
        on an empty line returning to the menu - replacing a Ctrl+C
        double-press since a child process can turn Ctrl+C back into a
        break signal. Entering from the menu always opens a fresh
        conversation, except a numbered suggestion that pushed another
        screen, which returns to the same conversation with its
        transcript tail reprinted. A resize repaints a fresh page at the
        new width, trading away scrollback; the loop variable is
        $nowValue, not $now, since a local $now would collide with the
        -Now parameter (case-insensitive). Returns @{ Nav; Target; Char;
        HasMarks } for Invoke-WtMainLoop.
    #>
    param(
        [scriptblock]$ReadLine = { param($P, $History, $StatusRows, $Draft) Read-WtReplLine -Prompt $P -History $History -StatusRows $StatusRows -Placeholder (Get-Translation 'AsReplPlaceholder') -EchoAsUser -AllowResize -InitialText $Draft },
        [scriptblock]$Send = { param($S, $Settings, $Text, $Keep) Invoke-WtAssistantSend -Chat $S -Settings $Settings -Text $Text -Breadcrumb (Get-Translation 'Assistant') -KeepSuggestions:([bool]$Keep) },
        [scriptblock]$Suggest = { param($S, $Index) Invoke-WtAssistantSuggestion -Chat $S -Index $Index -Breadcrumb (Get-Translation 'Assistant') },
        [scriptblock]$FollowUp = { param($S, $Settings, $Report) Invoke-WtAssistantSend -Chat $S -Settings $Settings -Text $Report -Breadcrumb (Get-Translation 'Assistant') -Harness },
        [scriptblock]$Slash = { param($C, $A, $S, $Settings) Invoke-WtAssistantSlash -Command $C -Argument $A -Session $S -Settings $Settings -Profile $Profile },
        [scriptblock]$Wizard = { Invoke-WtAssistantReplWizard },
        [scriptblock]$Header = { param($S, $Settings, $ResumedAt) Write-WtReplPage; Write-WtReplWelcome },
        [scriptblock]$Enter = { Enter-WtReplMode },
        [scriptblock]$Exit = { Exit-WtReplMode },
        [scriptblock]$Now = { Get-Date },
        [scriptblock]$Profile = { param($Force) if ($Force) { Get-WtAssistantMachineProfile -Kind 'Short' -Force -OnCold { Write-WtReplLine -Text ((Get-Translation 'AsProfileBuilding')) -Fg 'DarkGray' } } else { Get-WtAssistantMachineProfile -Kind 'Short' -OnCold { Write-WtReplLine -Text ((Get-Translation 'AsProfileBuilding')) -Fg 'DarkGray' } } },
        [scriptblock]$ReadPermissions = { Read-WtAssistantPermissions },
        [scriptblock]$ReadNotes = { Read-WtAssistantNotes }
    )
    $back = @{ Nav = 'Back'; Target = ''; Char = ''; HasMarks = $false }
    $leave = { param($Verdict) if ([string]$Verdict.Nav -ne 'Push') { $script:WtAssistantChat = $null }; return $Verdict }
    & $Enter
    try {
        $settings = Read-WtSettings
        $resumed = ($null -ne $script:WtAssistantChat)
        if (-not $resumed) { $script:WtAssistantChat = New-WtReplSession }
        $session = $script:WtAssistantChat
        & $Header $session $settings ''
        $built = $null
        try { $built = & $Profile $false } catch { $built = $null }
        if ($null -ne $built -and $built.Cold -and [string]$built.Json) {
            Write-WtReplLine -Text (((Get-Translation 'AsProfileBuilt') -f ([string]$built.Json).Length)) -Fg 'DarkGray'
        }
        if (-not (Test-WtAssistantConfigured -Settings $settings)) {
            $configured = & $Wizard
            if ($null -ne $configured) {
                $settings = Read-WtSettings; if (-not [string]$settings.AssistantEndpoint) { $settings = $configured }
                Write-WtReplLine -Text ((Get-Translation 'AsReplSettingsBack') -f [string]$settings.AssistantModel, [string]$settings.AssistantEndpoint) -Fg 'DarkYellow'
            }
        }
        $tailWrite = { param($Text, $Fg, $NoNewline) Write-WtReplLine -Text $Text -Fg $Fg }
        $width = (Get-WtConsoleSize).Width
        if ($resumed) { Write-WtReplTranscriptTail -Session $session -Count 400 -Width $width -Write $tailWrite }
        $permCount = 0
        try { $p = & $ReadPermissions; if ($null -ne $p) { $permCount = @($p.endpoints).Count } } catch { $permCount = 0 }
        $noteCount = 0
        try { $noteCount = @(& $ReadNotes).Count } catch { $noteCount = 0 }
        $draft = ''
        while ($true) {
            $configuredNow = Test-WtAssistantConfigured -Settings $settings
            $where = Get-WtAssistantWhereTag -Settings $settings
            Set-WtReplTitle -Text (Get-WtWindowTitle)
            $width = (Get-WtConsoleSize).Width
            $right = $(if ([int]$session.EscCount -gt 0 -and ([datetime](& $Now) - [datetime]$session.LastEsc).TotalSeconds -le 2) { [string]((Get-Translation 'AsReplEscHint') -f (3 - [int]$session.EscCount)) } else { Get-WtReplStatusRight })
            $left = $(if ($configuredNow) {
                Get-WtReplStatusLeft -Model ([string]$settings.AssistantModel) -WhereTag $where `
                    -Percent (Get-WtReplContextPercent -Messages @($session.Messages.ToArray()) -MaxChars $(if ([int]$session.HistoryMaxChars -gt 0) { [int]$session.HistoryMaxChars } else { 40000 })) `
                    -MessageCount $session.Messages.Count -NoteCount $noteCount -PermCount $permCount `
                    -Width $width -Reserve ([string]$right).Length
            }
            else { [string](Get-Translation 'AsReplNeedEndpoint') })
            $statusRows = @(, @(, (New-WtSeg -Text (Format-WtReplStatusLine -Left $left -Right $right -Width $width) -Fg $(if ($configuredNow) { 'DarkGray' } else { 'Yellow' }))))
            Close-WtReplToolBox
            $r = & $ReadLine '> ' ([string[]]@($session.History.ToArray())) $statusRows $draft
            $draft = ''
            $kind = [string]$r.Kind
            if ($kind -eq 'Eof') { return (& $leave $back) }
            if ($kind -eq 'Cancel') {
                $nowValue = [datetime](& $Now)
                if (($nowValue - [datetime]$session.LastEsc).TotalSeconds -le 2) { $session.EscCount = [int]$session.EscCount + 1 }
                else { $session.EscCount = 1 }
                $session.LastEsc = $nowValue
                if ([int]$session.EscCount -ge 3) { return (& $leave $back) }
                if (-not $script:WtReplLiveEnabled) { Write-WtReplLine -Text ((Get-Translation 'AsReplEscHint') -f (3 - [int]$session.EscCount)) -Fg 'DarkGray' }
                continue
            }
            $session.EscCount = 0
            if ($kind -eq 'Resize') {
                $draft = [string]$r.Text
                $width = (Get-WtConsoleSize).Width
                & $Header $session $settings ''
                Write-WtReplTranscriptTail -Session $session -Count 400 -Width $width -Write $tailWrite
                continue
            }
            if ($kind -eq 'CtrlC') { continue }
            $line = [string]$r.Text
            if (([string]$line).Trim()) { $session.History.Add($line) }
            $command = ConvertTo-WtReplCommand -Line $line -SuggestionCount (@($session.Suggestions).Count)
            switch ([string]$command.Kind) {
                'None' { }
                'Send' {
                    if (-not $configuredNow) { Write-WtReplLine -Text (Get-Translation 'AsReplNeedEndpoint') -Fg 'Red'; break }
                    & $Send $session $settings $line
                }
                'Suggest' {
                    $verdict = & $Suggest $session ([int]$command.Index)
                    if ($null -ne $verdict) { return (& $leave $verdict) }
                    $report = [string]$session.FollowUp
                    $session.FollowUp = ''
                    if ($report -and $configuredNow) { & $FollowUp $session $settings $report }
                }
                'Hint' { Write-WtReplLine -Text (Get-Translation 'AsReplQuitHint') -Fg 'DarkGray' }
                'Slash' {
                    $out = & $Slash ([string]$command.Command) ([string]$command.Argument) $session $settings
                    if ($null -ne $out.Settings) { $settings = $out.Settings }
                    if (@('new', 'forget', 'notes', 'perms') -contains [string]$command.Command) {
                        $permCount = 0
                        try { $p = & $ReadPermissions; if ($null -ne $p) { $permCount = @($p.endpoints).Count } } catch { $permCount = 0 }
                        $noteCount = 0
                        try { $noteCount = @(& $ReadNotes).Count } catch { $noteCount = 0 }
                    }
                    if ($out.NewSession) {
                        $wasProfileEnabled = $session.ProfileEnabled
                        $script:WtAssistantChat = New-WtReplSession
                        $script:WtAssistantChat.ProfileEnabled = $wasProfileEnabled
                        $session = $script:WtAssistantChat
                        & $Header $session $settings ''
                    }
                    if ([string]$out.Notice) { Write-WtReplLine -Text ([string]$out.Notice) -Fg ([string]$out.NoticeFg) }
                    if ([string]$out.Nav -eq 'Back') { return (& $leave $back) }
                    if ([string]$out.Nav -eq 'Exit') { return (& $leave @{ Nav = 'Exit'; Target = ''; Char = ''; HasMarks = $false }) }
                }
                'Unknown' {
                    $isDigit = (([string]$command.Text) -cmatch '^[0-9]{1,2}\z')
                    if ($isDigit) {
                        $digit = [int]$command.Text
                        if ($configuredNow) {
                            $cardRows = [string[]]@(for ($i = 0; $i -lt @($session.Suggestions).Count; $i++) { [string]($i + 1) + ' ' + [string](@($session.Suggestions)[$i].Label) })
                            $loose = Format-WtAssistantLooseNumberNote -Number $digit -Numbers $cardRows
                            Add-WtAssistantPendingNote -Chat $session -Text $loose
                            & $Send $session $settings $line ($cardRows.Count -gt 0)
                            $lastNote = $session.PendingNotes.Count - 1
                            if ($lastNote -ge 0 -and [string]::Equals([string]$session.PendingNotes[$lastNote], $loose, [System.StringComparison]::Ordinal)) { $session.PendingNotes.RemoveAt($lastNote) }
                        }
                        else { Write-WtReplLine -Text ((Get-Translation 'AsReplNoSuggestion') -f $digit) -Fg 'DarkYellow' }
                    }
                    else { Write-WtReplLine -Text ((Get-Translation 'AsReplUnknownSlash') -f [string]$command.Command) -Fg 'DarkYellow' }
                }
            }
        }
    }
    finally { & $Exit }
}
#endregion src/80-screens/assistant-repl.ps1

#region src/80-screens/assistant-settings.ps1
# The assistant settings screen: preset, endpoint, api key, model picker,
# local scan and the connection test.
# Covered by: tests/AssistantScreen.Tests.ps1

function Get-WtLlmPresets {
    <#
    .SYNOPSIS
        Known OpenAI-compatible endpoints. A preset only fills the
        endpoint field - key and model stay whatever they were.
    #>
    return @(
        [PSCustomObject]@{ Name = 'OpenAI'; Endpoint = 'https://api.openai.com/v1' }
        [PSCustomObject]@{ Name = 'OpenRouter'; Endpoint = 'https://openrouter.ai/api/v1' }
        [PSCustomObject]@{ Name = 'Groq'; Endpoint = 'https://api.groq.com/openai/v1' }
        [PSCustomObject]@{ Name = 'LM Studio'; Endpoint = 'http://127.0.0.1:1234/v1' }
        [PSCustomObject]@{ Name = 'Ollama'; Endpoint = 'http://127.0.0.1:11434/v1' }
        [PSCustomObject]@{ Name = 'llama.cpp'; Endpoint = 'http://127.0.0.1:8080/v1' }
    )
}

function Get-WtChatGptModelCatalog {
    <#
    .SYNOPSIS
        The models offered in ChatGPT mode. A hand-maintained list rather
        than a call: the subscription backend has no /models route. The
        ids are the ones documented for signing in with a ChatGPT
        account; gpt-5 and gpt-5-codex are NOT among them and the backend
        refuses them outright. Which of these a given plan actually
        allows is not documented, so all of them are offered, lighter
        first, and the type-it-yourself fallback and the connection test
        stay the real judges.
    #>
    return [string[]]@('gpt-5.6-terra', 'gpt-5.6-luna', 'gpt-5.3-codex-spark', 'gpt-5.6-sol', 'gpt-6-astra', 'gpt-5.5')
}

function Get-WtAssistantModelChoices {
    <#
    .SYNOPSIS
        The models to offer for the ACTIVE identity: the curated ChatGPT
        catalogue in ChatGPT mode - that backend has no /models route -
        and the endpoint's own list otherwise. One function so the
        settings screen and the REPL's /model can never disagree about
        which list belongs to which identity.
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Settings,
        [AllowNull()][AllowEmptyString()][string]$PlainApiKey = $null,
        [scriptblock]$GetModels = { param($E, $K) Get-WtLlmModelList -Endpoint $E -ApiKey $K }
    )
    if (Test-WtAssistantChatGptMode -AuthMode ([string]$Settings.AssistantAuthMode)) {
        return @{ Ok = $true; Models = [string[]]@(Get-WtChatGptModelCatalog); ErrorText = ''; HintKey = 'AsChatGptModelHint' }
    }
    $endpoint = [string]$Settings.AssistantEndpoint
    if (-not $endpoint) {
        return @{ Ok = $false; Models = [string[]]@(); ErrorText = [string](Get-Translation 'AsReplNeedEndpoint'); HintKey = '' }
    }
    $key = $(if ($null -ne $PlainApiKey) { [string]$PlainApiKey } else { [string](Unprotect-WtAssistantSecret -Blob ([string]$Settings.AssistantApiKey)) })
    $list = & $GetModels $endpoint $key
    return @{ Ok = [bool]$list.Ok; Models = [string[]]@($list.Models); ErrorText = [string]$list.ErrorText; HintKey = '' }
}

function Get-WtChatGptAccountStateLabel {
    <#
    .SYNOPSIS
        PURE: the account row's state column - "email - plan", the email
        alone when the plan is unknown, and nothing at all without an
        email, so a half-read session never renders a bare dash.
    #>
    param([AllowNull()][hashtable]$Auth)
    if ($null -eq $Auth) { return '' }
    $email = [string]$Auth.Email
    if (-not $email) { return '' }
    $plan = [string]$Auth.PlanType
    if (-not $plan) { return $email }
    return ([string](Get-Translation 'AsChatGptStateFormat') -f $email, $plan)
}

function Get-WtChatGptSignInWarningLines {
    <#
    .SYNOPSIS
        PURE: what stands behind the typed gate on the ChatGPT sign-in -
        that the risk of a restricted or closed account is the user's own
        and WinToolify carries none of it, that the API key row is the
        supported route, and the Codex disclosure. Pure so the wording
        can be tested without driving the screen; the consequence line
        itself is AsChatGptBanConsequence and the gate renders it in red.
    #>
    return [string[]]@(
        [string](Get-Translation 'AsChatGptBanLiability'),
        '',
        [string](Get-Translation 'AsChatGptBanAlternative'),
        '',
        [string](Get-Translation 'AsChatGptDisclosure')
    )
}

function Get-WtAssistantSettingsRows {
    <#
    .SYNOPSIS
        PURE: the eight settings rows with the live values in the state
        column. The key never shows itself - only '****' or "not set".
        In ChatGPT mode the rows that describe the other identity are
        marked Disabled and say why rather than disappearing: a row that
        vanishes reads as a missing feature, one that explains itself
        does not.
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Settings,
        [AllowNull()][hashtable]$Auth = $null
    )
    $notSet = [string](Get-Translation 'AsNotSet')
    $chatGpt = Test-WtAssistantChatGptMode -AuthMode ([string]$Settings.AssistantAuthMode)
    $unusedLabel = [string](Get-Translation 'AsChatGptNotUsedInMode')
    $endpoint = [string]$Settings.AssistantEndpoint
    if (-not $endpoint) { $endpoint = $notSet }
    $model = [string]$Settings.AssistantModel
    if (-not $model) { $model = $notSet }
    $keyState = $(if ([string]$Settings.AssistantApiKey) { '****' } else { $notSet })
    $numCtx = [string]$Settings.AssistantNumCtx
    if (-not $numCtx) { $numCtx = $notSet }
    $row = { param([string]$Name, [string]$Setting, [string]$Label, [string]$State, [bool]$Disabled)
        $shownState = $(if ($Disabled) { $unusedLabel } else { $State })
        return (New-WtListItem -Kind 'Action' -Name $Name -Label $Label -StateLabel $shownState -Data @{ Setting = $Setting; Disabled = $Disabled })
    }
    $accountLabel = [string](Get-Translation $(if ($chatGpt) { 'AsChatGptSignOut' } else { 'AsChatGptSignIn' }))
    $accountState = $(if ($chatGpt) { Get-WtChatGptAccountStateLabel -Auth $Auth } else { '' })
    return @(
        (& $row 'AsSetAuthMode' 'AuthMode' $accountLabel $accountState $false)
        (& $row 'AsSetPreset' 'Preset' ([string](Get-Translation 'AsSetPreset')) '' $chatGpt)
        (& $row 'AsSetEndpoint' 'Endpoint' ([string](Get-Translation 'AsSetEndpoint')) $endpoint $chatGpt)
        (& $row 'AsSetApiKey' 'ApiKey' ([string](Get-Translation 'AsSetApiKey')) $keyState $chatGpt)
        (& $row 'AsSetModel' 'Model' ([string](Get-Translation 'AsSetModel')) $model $false)
        (& $row 'AsScanLocal' 'Scan' ([string](Get-Translation 'AsScanLocal')) '' $chatGpt)
        (& $row 'AsTestConnection' 'Test' ([string](Get-Translation 'AsTestConnection')) '' $false)
        (& $row 'AsSetNumCtx' 'NumCtx' ([string](Get-Translation 'AsSetNumCtx')) $numCtx $chatGpt)
    )
}

function Invoke-WtAssistantPickFromList {
    <#
    .SYNOPSIS
        A numbered picker in the panel: options listed 1..N, the answer
        is a number; anything else (blank, out of range, letters) means
        "leave it". Used for presets, scanned servers and model lists.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb,
        [Parameter(Mandatory)][string]$Title,
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Options,
        [scriptblock]$ReadAnswer = { param($Lines, $Prompt) Read-WtPanelAnswer -Breadcrumb $Breadcrumb -Lines $Lines -Prompt $Prompt -Layout 'Compact' }
    )
    $options = @($Options)
    if ($options.Count -eq 0) { return '' }
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add($Title)
    for ($i = 0; $i -lt $options.Count; $i++) { $lines.Add(('  {0}) {1}' -f ($i + 1), [string]$options[$i])) }
    $answer = ([string](& $ReadAnswer ([string[]]$lines.ToArray()) (Get-Translation 'AsPickPrompt'))).Trim()
    $index = 0
    if (-not [int]::TryParse($answer, [ref]$index)) { return '' }
    if ($index -lt 1 -or $index -gt $options.Count) { return '' }
    return [string]$options[$index - 1]
}

function Invoke-WtAssistantChooseServer {
    <#
    .SYNOPSIS
        Turns a local scan into a saved endpoint+model: pick a server,
        then a model, then store both. Shared by the settings screen's
        Scan row and the chat startup 'Choose' branch, so a scan (up to
        8s) is offered rather than re-run. IndexOf returns -1 on a miss,
        and PS negative indices wrap from the end, so the miss is
        checked before indexing. The Ollama model list is force-wrapped
        in @() - unwrapped, a one-element result becomes a bare String
        and $models[0] returns its first CHARACTER, not the model name.
        Returns $true only when both were saved.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb,
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Servers
    )
    $servers = @($Servers)
    if ($servers.Count -eq 0) { return $false }
    $serverNames = @($servers | ForEach-Object { [string]$_.Provider + '  (' + [string]$_.Endpoint + ')' })
    $pickedServer = Invoke-WtAssistantPickFromList -Breadcrumb $Breadcrumb -Title (Get-Translation 'AsScanPickServer') -Options $serverNames
    $serverIndex = [array]::IndexOf($serverNames, $pickedServer)
    if ($serverIndex -lt 0) { return $false }
    $server = $servers[$serverIndex]
    $models = [string[]]@($server.Models)
    if ([string]$server.Provider -eq 'Ollama') {
        Show-WtPanelMessage -Breadcrumb $Breadcrumb -Lines @((Get-Translation 'AsProbingTools')) -FooterText '' | Out-Null
        $models = [string[]]@(Get-WtOllamaToolCapableModels -Models $models)
        Reset-WtFrameCache
    }
    $pickedModel = ''
    if (@($models).Count -eq 1) { $pickedModel = [string]$models[0] }
    else { $pickedModel = Invoke-WtAssistantPickFromList -Breadcrumb $Breadcrumb -Title (Get-Translation 'AsSetModel') -Options $models }
    if (-not $pickedModel) { return $false }
    Save-WtSettings -Settings ([PSCustomObject]@{ AssistantEndpoint = [string]$server.Endpoint; AssistantModel = $pickedModel })
    return $true
}

function Invoke-WtAssistantConnectionTest {
    <#
    .SYNOPSIS
        The full-agent gatekeeper: one small request WITH a probe tool.
        Reports reachability and - separately - whether the model
        actually answered with a tool call, because "the endpoint took
        tools" and "the model uses them" are different failures.
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Settings,
        [scriptblock]$Chat = { param($ArgTable) Invoke-WtAssistantChat -AuthMode ([string]$ArgTable.AuthMode) -Arguments $ArgTable }
    )
    $lines = New-Object System.Collections.Generic.List[string]
    $probeTool = @{ type = 'function'; 'function' = @{ name = 'probe_ping'; description = 'Connectivity probe. Call this tool once, with no arguments.'; parameters = @{ type = 'object'; properties = @{} } } }
    $result = & $Chat @{
        AuthMode = [string]$Settings.AssistantAuthMode
        Endpoint = [string]$Settings.AssistantEndpoint
        ApiKey = (Unprotect-WtAssistantSecret -Blob ([string]$Settings.AssistantApiKey))
        Model = [string]$Settings.AssistantModel
        Messages = @(@{ role = 'user'; content = 'Call the probe_ping tool now.' })
        Tools = @($probeTool); Stream = $false; TimeoutSec = 60
    }
    if (-not $result.Ok) {
        $lines.Add([string]$result.ErrorText)
        return [string[]]$lines.ToArray()
    }
    $lines.Add([string](Get-Translation 'AsTestReachable'))
    $called = @($result.ToolCalls) | Where-Object { [string]$_.Name -eq 'probe_ping' }
    if (@($called).Count -gt 0) { $lines.Add([string](Get-Translation 'AsTestToolsOk')) }
    else { $lines.Add([string](Get-Translation 'AsTestToolsMissing')) }
    return [string[]]$lines.ToArray()
}

function Invoke-WtAssistantSettingsScreen {
    <#
    .SYNOPSIS
        The settings list screen: each row opens its panel flow, saves
        and redraws with the new value. Left/Esc returns to the caller.
        A prompt answer of $null means cancelled (change nothing); '' is
        the documented way to clear a value - the two must be told apart
        before casting to [string], which collapses both to ''. IndexOf
        on a picked list returns -1 on a miss, and a negative PS array
        index wraps from the end, so the miss is checked before indexing.
    #>
    $breadcrumb = Get-WtBreadcrumb -Keys 'MainMenu', 'Assistant', 'AsSettingsTitle'
    while ($true) {
        $settings = Read-WtSettings
        $auth = Read-WtChatGptAuth
        $r = Invoke-WtListScreen -Breadcrumb $breadcrumb -Items @(Get-WtAssistantSettingsRows -Settings $settings -Auth $auth) `
            -MultiSelect $false -FooterText (Get-Translation 'NavFooter') -Layout 'Compact'
        if ($r.Emit -eq 'Back') { return @{ Nav = 'Back'; Target = ''; Char = ''; HasMarks = $false } }
        if ($r.Emit -eq 'Quit') { return @{ Nav = 'Exit'; Target = ''; Char = ''; HasMarks = $false } }
        if ($r.Emit -ne 'Activate' -or $null -eq $r.Item) { continue }
        if ([bool]$r.Item.Data.Disabled) { continue }
        switch ([string]$r.Item.Data.Setting) {
            'AuthMode' {
                if (Test-WtAssistantChatGptMode -AuthMode ([string]$settings.AssistantAuthMode)) {
                    Clear-WtChatGptAuth
                    $null = Read-WtPanelAnswer -Breadcrumb $breadcrumb -Lines @((Get-Translation 'AsChatGptSignedOut')) -Prompt (Get-Translation 'PressEnterContinue') -Layout 'Compact'
                    Reset-WtFrameCache
                    continue
                }
                $accepted = Confirm-WtDestructiveAction -Consequence (Get-Translation 'AsChatGptBanConsequence') `
                    -Lines (Get-WtChatGptSignInWarningLines) -Breadcrumb $breadcrumb
                Reset-WtFrameCache
                if (-not $accepted) { continue }
                Show-WtPanelMessage -Breadcrumb $breadcrumb -Lines @((Get-Translation 'AsChatGptDisclosure'), '', (Get-Translation 'AsChatGptWaiting')) -FooterText '' | Out-Null
                $signIn = Invoke-WtChatGptSignIn -ShouldCancel { Test-WtOAuthCancelKey }
                Reset-WtFrameCache
                $lines = New-Object System.Collections.Generic.List[string]
                if ($signIn.Ok) { $lines.Add(([string](Get-Translation 'AsChatGptSignedIn') -f [string]$signIn.Email)) }
                else {
                    if ([string]$signIn.ReasonKey) { $lines.Add([string](Get-Translation ([string]$signIn.ReasonKey))) }
                    if ([string]$signIn.ErrorText) { $lines.Add([string]$signIn.ErrorText) }
                    if ([bool]$signIn.BrowserFailed) {
                        $lines.Add([string](Get-Translation 'AsChatGptBrowserFailed'))
                        $lines.Add([string]$signIn.AuthorizeUri)
                    }
                }
                $null = Read-WtPanelAnswer -Breadcrumb $breadcrumb -Lines ([string[]]$lines.ToArray()) -Prompt (Get-Translation 'PressEnterContinue') -Layout 'Compact'
                Reset-WtFrameCache
            }
            'Preset' {
                $names = @((Get-WtLlmPresets) | ForEach-Object { [string]$_.Name + '  (' + [string]$_.Endpoint + ')' })
                $picked = Invoke-WtAssistantPickFromList -Breadcrumb $breadcrumb -Title (Get-Translation 'AsSetPreset') -Options $names
                $presetIndex = [array]::IndexOf($names, $picked)
                if ($presetIndex -ge 0) {
                    $preset = @(Get-WtLlmPresets)[$presetIndex]
                    Save-WtSettings -Settings ([PSCustomObject]@{ AssistantEndpoint = [string]$preset.Endpoint })
                }
            }
            'Endpoint' {
                $answer = ([string](Read-WtPanelAnswer -Breadcrumb $breadcrumb -Lines @((Get-Translation 'AsEndpointHint')) -Prompt (Get-Translation 'AsSetEndpoint') -Layout 'Compact')).Trim()
                if ($answer -and ($answer.StartsWith('http://', [System.StringComparison]::OrdinalIgnoreCase) -or $answer.StartsWith('https://', [System.StringComparison]::OrdinalIgnoreCase))) {
                    Save-WtSettings -Settings ([PSCustomObject]@{ AssistantEndpoint = $answer })
                }
            }
            'ApiKey' {
                $raw = Read-WtPanelAnswer -Breadcrumb $breadcrumb -Lines @((Get-Translation 'AsApiKeyHint')) -Prompt (Get-Translation 'AsSetApiKey') -Layout 'Compact' -Secret
                if ($null -ne $raw) {
                    Save-WtSettings -Settings ([PSCustomObject]@{ AssistantApiKey = (Protect-WtAssistantSecret -PlainText (([string]$raw).Trim())) })
                }
            }
            'NumCtx' {
                $raw = Read-WtPanelAnswer -Breadcrumb $breadcrumb -Lines @((Get-Translation 'AsNumCtxHint')) -Prompt (Get-Translation 'AsSetNumCtx') -Layout 'Compact'
                if ($null -ne $raw) {
                    $answer = ([string]$raw).Trim()
                    if ($answer -eq '') { Save-WtSettings -Settings ([PSCustomObject]@{ AssistantNumCtx = '' }) }
                    else {
                        $parsedCtx = ConvertTo-WtAssistantNumCtx -Text $answer
                        if ($parsedCtx -gt 0) { Save-WtSettings -Settings ([PSCustomObject]@{ AssistantNumCtx = [string]$parsedCtx }) }
                    }
                }
            }
            'Model' {
                $chatGptMode = Test-WtAssistantChatGptMode -AuthMode ([string]$settings.AssistantAuthMode)
                if (-not ($chatGptMode -or [string]$settings.AssistantEndpoint)) { continue }
                if (-not $chatGptMode) { Show-WtPanelMessage -Breadcrumb $breadcrumb -Lines @((Get-Translation 'AsLoadingModels')) -FooterText '' | Out-Null }
                $list = Get-WtAssistantModelChoices -Settings $settings
                Reset-WtFrameCache
                $picked = ''
                if ($list.Ok -and @($list.Models).Count -gt 0) {
                    $title = [string](Get-Translation 'AsSetModel')
                    if ([string]$list.HintKey) { $title = $title + ' - ' + [string](Get-Translation ([string]$list.HintKey)) }
                    $picked = Invoke-WtAssistantPickFromList -Breadcrumb $breadcrumb -Title $title -Options ([string[]]@($list.Models))
                }
                if (-not $picked) {
                    $picked = ([string](Read-WtPanelAnswer -Breadcrumb $breadcrumb -Lines @($(if ($list.Ok) { Get-Translation 'AsModelTypeHint' } else { [string]$list.ErrorText })) -Prompt (Get-Translation 'AsSetModel') -Layout 'Compact')).Trim()
                }
                if ($picked) { Save-WtSettings -Settings ([PSCustomObject]@{ AssistantModel = $picked }) }
            }
            'Scan' {
                Show-WtPanelMessage -Breadcrumb $breadcrumb -Lines @((Get-Translation 'AsScanning')) -FooterText '' | Out-Null
                $servers = @(Find-WtLocalLlmServers)
                Reset-WtFrameCache
                if (@($servers).Count -eq 0) {
                    $lines = @((Get-Translation 'AsScanNothing')) + @(Get-WtLlmLocalHints)
                    $null = Read-WtPanelAnswer -Breadcrumb $breadcrumb -Lines $lines -Prompt (Get-Translation 'PressEnterContinue') -Layout 'Compact'
                    Reset-WtFrameCache
                    continue
                }
                $null = Invoke-WtAssistantChooseServer -Breadcrumb $breadcrumb -Servers $servers
            }
            'Test' {
                if (-not ([string]$settings.AssistantEndpoint -and [string]$settings.AssistantModel)) { continue }
                Show-WtPanelMessage -Breadcrumb $breadcrumb -Lines @((Get-Translation 'AsTesting')) -FooterText '' | Out-Null
                $lines = @(Invoke-WtAssistantConnectionTest -Settings $settings)
                Reset-WtFrameCache
                $null = Read-WtPanelAnswer -Breadcrumb $breadcrumb -Lines $lines -Prompt (Get-Translation 'PressEnterContinue') -Layout 'Compact'
                Reset-WtFrameCache
            }
        }
        Reset-WtFrameCache
    }
}
#endregion src/80-screens/assistant-settings.ps1

#region src/80-screens/assistant.ps1
# The WinToolify Asistan chat screen: opening gate, the interactive loop,
# the send path and transcript saving.
# Covered by: tests/AssistantScreen.Tests.ps1

function Test-WtAssistantRemoteEndpoint {
    <#
    .SYNOPSIS
        Whether an endpoint leaves this machine. Loopback is decided by
        parsing the host as an IP address, not by string match, because
        Uri.DnsSafeHost expands IPv6 literals. Empty counts as local,
        unparsable as remote, so the privacy gate errs toward asking.
    #>
    param([AllowNull()][AllowEmptyString()][string]$Endpoint)
    if (-not $Endpoint) { return $false }
    $uri = $null
    try { $uri = [uri]$Endpoint } catch { return $true }
    if (-not $uri.IsAbsoluteUri) { return $true }
    if ([string]::Equals([string]$uri.Host, 'localhost', [System.StringComparison]::OrdinalIgnoreCase)) { return $false }
    $ip = $null
    if ([System.Net.IPAddress]::TryParse(([string]$uri.DnsSafeHost).Trim('[', ']'), [ref]$ip) -and [System.Net.IPAddress]::IsLoopback($ip)) { return $false }
    return $true
}

function ConvertTo-WtAssistantNumCtx {
    <#
    .SYNOPSIS
        PURE: the AssistantNumCtx setting (a string, '' = unset) as a
        positive integer, 0 for anything else, capped at 4,000,000 so the
        history-window arithmetic can never overflow Int32. Invariant
        parse - never a culture cast on user text.
    #>
    param([AllowNull()][AllowEmptyString()][string]$Text)
    $parsed = 0
    if ([int]::TryParse(([string]$Text).Trim(), [System.Globalization.NumberStyles]::Integer, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$parsed) -and $parsed -gt 0) { return [Math]::Min($parsed, 4000000) }
    return 0
}

function Get-WtAssistantHistoryMaxChars {
    <#
    .SYNOPSIS
        PURE: the history window in characters. Cloud endpoints and an
        unset num_ctx keep 40000; an Ollama endpoint with num_ctx gets
        max(12000, num_ctx*3 - prefixChars - 2000).
    #>
    param([int]$NumCtx = 0, [int]$PrefixChars = 0, [bool]$Ollama = $false)
    if (-not $Ollama -or $NumCtx -le 0) { return 40000 }
    return [int][Math]::Max(12000, ($NumCtx * 3) - $PrefixChars - 2000)
}

function Add-WtAssistantUsage {
    <#
    .SYNOPSIS
        Adds one round's usage to the turn total the screen keeps for
        /durum: the three counts are summed (every round re-sends the
        prefix, so the sum is what the provider bills), LastPromptTokens
        is the latest round's prompt (the context-warning measure).
    #>
    param([Parameter(Mandatory)][hashtable]$Total, [AllowNull()]$Usage)
    if ($null -eq $Usage) { return }
    $Total['PromptTokens'] = [int]$Total['PromptTokens'] + [int]$Usage.PromptTokens
    $Total['CompletionTokens'] = [int]$Total['CompletionTokens'] + [int]$Usage.CompletionTokens
    $Total['CachedTokens'] = [int]$Total['CachedTokens'] + [int]$Usage.CachedTokens
    $Total['LastPromptTokens'] = [int]$Usage.PromptTokens
    $Total['Rounds'] = [int]$Total['Rounds'] + 1
}

function Get-WtAssistantSystemPrompt {
    <#
    .SYNOPSIS
        system[0], STATIC: identity, scope, the suggest-only rule, the
        tool rules, the output format and the five slash names a user
        may ask about. No date, no language, no machine fact, no slash
        help table - those live in system[1] or on the screen, so this
        text is byte-identical across every request and a provider
        prefix cache can keep it. Under 2700 characters, pinned.
    #>
    return ('You are WinToolify Asistan, the assistant built into WinToolify, an open-source Windows optimization tool. ' +
        'If asked who you are or which model you are, say: WinToolify Asistan, running on the model configured under /ayarlar; never name a model vendor. ' +
        'Scope: Windows, this computer (hardware, drivers, software, services, startup, storage, network, security, performance, errors, updates), WinToolify itself and other technical questions. ' +
        'Decline anything else in one short sentence, without calling a tool. Greetings get one friendly sentence that offers help with this computer. ' +
        'You never run, apply, remove or undo anything and have no tool for it. For anything WinToolify can do, call search_wintoolify, then offer the fitting entries with suggest_wintoolify: ' +
        'the user types a number and WinToolify''s own confirmation takes over. Never say you started, applied or removed something, never ask the user to type CONFIRM or YES to you; point to the numbers instead ("type 1"). ' +
        'When no entry fits, explain the manual fix (steps or a command); when you are not sure of the facts, research with web_search and fetch_page and cite the sources by url. ' +
        'Tools: read the machine before diagnosing; follow each tool description; never repeat a call with the same or nearly the same words; never call a tool whose result you will not use; ' +
        'prefer the machine profile already in your context over a tool call for the same fact. ' +
        'Interpret every result in plain words for this computer - what it shows, what is normal and what is not, why it matters and what to do next; never paste raw lines. ' +
        'Lines starting with "(note:" or "(result of" at the top of a message come from WinToolify, not the user: what the user ran by number, or a number that matched nothing, and, after "(result of", its output, already on the user''s screen. ' +
        'If the user''s own words follow, answer those; if the message is only the report, explain it: what it found or changed, success or failure and the error if any, what it means, the next step. ' +
        'Never claim you did it; do not re-read that topic with read_system; the numbers on screen stay valid, call suggest_wintoolify only for a different next step. ' +
        'Format: you write for a terminal - short plain sentences, only "- " bullets (numbered lists exist only through suggest_wintoolify, never write your own), no headings or tables, **bold** only for one name or value, `backticks` for commands and file names. ' +
        'The user also has local commands starting with "/" (not tools, you cannot run them; /yardim lists them). If asked, name: /ayarlar (connection), /yeni (new chat), /profil, /notlar, /unut.')
}

function Get-WtAssistantSystemExtra {
    <#
    .SYNOPSIS
        system[1]: the per-session facts the static prompt must not
        carry - today's date, the reply language, the short anonymized
        profile, the saved notes. Built ONCE per session by
        Get-WtAssistantSessionExtra and re-sent byte for byte.
    #>
    param(
        [Parameter(Mandatory)][datetime]$Date,
        [Parameter(Mandatory)][string]$Language,
        [AllowNull()][AllowEmptyString()][string]$ProfileJson = '',
        [AllowNull()][AllowEmptyCollection()][array]$Notes = @(),
        [AllowNull()][hashtable]$Mask = $null
    )
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add('date: ' + $Date.ToString('yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture))
    $lines.Add('reply language: ' + $(if ($Language -eq 'TR') { 'Turkish' } else { 'English' }))
    if ($ProfileJson) { $lines.Add('machine profile (anonymized): ' + $ProfileJson) }
    $noteRows = @($Notes | Where-Object { $null -ne $_ -and [string]$_.text })
    if ($noteRows.Count -gt 0) {
        $lines.Add('notes the user asked you to remember:')
        foreach ($note in $noteRows) {
            $t = [string]$note.text
            if ($null -ne $Mask) { $t = Protect-WtAssistantText -Text $t -Mask $Mask }
            $lines.Add('- ' + $t)
        }
    }
    return ($lines.ToArray() -join "`n")
}

function Get-WtAssistantSessionExtra {
    <#
    .SYNOPSIS
        The frozen system[1]: built on first use from the seams, stored on
        the session, returned unchanged afterwards - so every request of
        a session carries the identical prefix. Reset-WtAssistantSessionExtra
        drops it (profile on/off/refresh, a note saved or deleted, an apply
        the user ran, a new chat).
    #>
    param(
        [Parameter(Mandatory)][hashtable]$Chat,
        [Parameter(Mandatory)][scriptblock]$GetProfile,
        [Parameter(Mandatory)][scriptblock]$GetNotes,
        [AllowNull()][hashtable]$Mask = $null,
        [datetime]$Date = (Get-Date),
        [string]$Language = $script:Language
    )
    if ($Chat.ContainsKey('SystemExtra') -and $null -ne $Chat.SystemExtra) { return [string]$Chat.SystemExtra }
    $profileJson = ''
    try { $profileJson = [string](& $GetProfile) } catch { $profileJson = '' }
    $notes = @()
    try { $notes = @(& $GetNotes) } catch { $notes = @() }
    $extra = Get-WtAssistantSystemExtra -Date $Date -Language $Language -ProfileJson $profileJson -Notes $notes -Mask $Mask
    $Chat.SystemExtra = $extra
    return $extra
}

function Reset-WtAssistantSessionExtra {
    <#
    .SYNOPSIS
        Drops the session's frozen system[1] so the next turn rebuilds it
        after the profile is toggled or refreshed, a note is saved or
        deleted, or a new chat.
    #>
    param([Parameter(Mandatory)][hashtable]$Chat)
    $Chat.SystemExtra = $null
}

function Get-WtAssistantPrivacyLines {
    <#
    .SYNOPSIS
        PURE: the consent text, one array of lines in the active
        language: where the data goes, a heading and four "- " items
        for WHAT goes there, what is masked first, the three tools that
        reach the internet on their own, and the closing guarantee.
        Blank lines separate the groups.
    #>
    param([Parameter(Mandatory)][AllowEmptyString()][string]$Endpoint)
    return [string[]]@(
        ((Get-Translation 'AsPrivacyLine1') -f $Endpoint)
        ''
        (Get-Translation 'AsPrivacyWhat')
        ('- ' + (Get-Translation 'AsPrivacyItem1'))
        ('- ' + (Get-Translation 'AsPrivacyItem2'))
        ('- ' + (Get-Translation 'AsPrivacyItem3'))
        ('- ' + (Get-Translation 'AsPrivacyItem4'))
        ''
        (Get-Translation 'AsPrivacyMasked')
        (Get-Translation 'AsPrivacyWeb')
        ''
        (Get-Translation 'AsPrivacyLine3')
    )
}

function Invoke-WtAssistantPrivacyGate {
    <#
    .SYNOPSIS
        Once per endpoint, persisted: where the data goes, what kind
        (anonymized), yes/no. A yes sticks for that endpoint, this
        session and every session after, once saved to permissions.json;
        a no asks again. Local endpoints never see this panel. Consent
        is stored keyed to the endpoint itself, not a bare flag, so
        switching endpoints through /ayarlar mid-chat cannot leak an
        earlier approval to a host the user never consented to.
    #>
    param(
        [Parameter(Mandatory)][PSCustomObject]$Settings,
        [Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb,
        [scriptblock]$ReadAnswer = { param($Lines, $Prompt) Read-WtReplAnswer -Lines $Lines -Prompt $Prompt -Risk 'CAUTION' -Choices @(@{ Label = [string](Get-Translation 'AnswerYes'); Letter = (Get-WtAnswerLetter -Kind 'Yes') }, @{ Label = [string](Get-Translation 'AnswerNo'); Letter = (Get-WtAnswerLetter -Kind 'No') }) },
        [scriptblock]$ReadPermissions = { Read-WtAssistantPermissions },
        [scriptblock]$SavePermissions = { param($P) Save-WtAssistantPermissions -Permissions $P }
    )
    $endpoint = Get-WtAssistantEffectiveEndpoint -Settings $Settings
    if (-not (Test-WtAssistantRemoteEndpoint -Endpoint $endpoint)) { return $true }
    if ($endpoint -and [string]::Equals([string]$script:WtAssistantPrivacyEndpoint, $endpoint, [System.StringComparison]::Ordinal)) { return $true }
    $perms = $null
    try { $perms = & $ReadPermissions } catch { $perms = $null }
    if ($null -ne $perms -and (Test-WtAssistantEndpointAllowed -Endpoint $endpoint -Permissions $perms)) { $script:WtAssistantPrivacyEndpoint = $endpoint; return $true }
    $lines = @(Get-WtAssistantPrivacyLines -Endpoint $endpoint)
    Close-WtReplToolBox
    $answer = & $ReadAnswer $lines (Get-WtYesNoPrompt -Text (Get-Translation 'AsPrivacyPrompt'))
    if (Test-WtAffirmativeAnswer -Answer ([string]$answer)) {
        $script:WtAssistantPrivacyEndpoint = $endpoint
        if ($null -eq $perms) { $perms = @{ v = 1; endpoints = @(); disabled = @() } }
        try { & $SavePermissions (Add-WtAssistantEndpointAllowed -Endpoint $endpoint -Permissions $perms) } catch { $null = $_ }
        return $true
    }
    return $false
}

function Set-WtAssistantSuggestions {
    <#
    .SYNOPSIS
        Stores the resolved suggestion entries on the chat state with
        the active language's label, path and What text, plus the tool
        index's Risk so the row can wear the Actions screen's badge. A
        new answer replaces the whole list.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$Chat,
        [AllowEmptyCollection()][array]$Entries = @()
    )
    $isTurkish = ($script:Language -eq 'TR')
    $Chat.Suggestions = @(foreach ($entry in @($Entries)) {
        @{
            Id    = [string]$entry.Id
            Label = [string]$(if ($isTurkish) { $entry.LabelTr } else { $entry.LabelEn })
            Path  = [string]$(if ($isTurkish) { $entry.PathTr } else { $entry.PathEn })
            Risk  = [string]$entry.Risk
            What  = (Get-WtAssistantEntryWhat -Entry $entry -Max 120)
            Entry = $entry
        }
    })
}

function Add-WtAssistantPendingNote {
    <#
    .SYNOPSIS
        Queues one digit-path run note on the chat; the next
        Invoke-WtAssistantSend prepends every queued note to the user's
        text and clears the queue.
    #>
    param([Parameter(Mandatory)][hashtable]$Chat, [Parameter(Mandatory)][AllowEmptyString()][string]$Text)
    if (-not $Text) { return }
    if (-not $Chat.ContainsKey('PendingNotes') -or $null -eq $Chat.PendingNotes) { $Chat.PendingNotes = New-Object System.Collections.Generic.List[string] }
    $Chat.PendingNotes.Add($Text)
}

function Invoke-WtAssistantSuggestion {
    <#
    .SYNOPSIS
        Digit 1-9. A Screen/Winget/stage-only-toggle entry pushes its
        screen or installs in place; a runnable Action/Info row runs
        through Invoke-WtAssistantToolRow; a non-runnable one runs
        through its own delegate and gates; a Toggle is confirmed with
        one Enter/Esc line and applied through WinToolify's own engine
        gates. Whatever ran leaves a transcript row and one pending note
        the next user message carries to the model. A run that finished
        in place with something to tell also fills $Chat.FollowUp with a
        report-turn body, sent immediately as a harness message so the
        model explains the outcome right away; a declined run or a
        pushed/painted screen leaves FollowUp alone since there is
        nothing honest to say yet.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$Chat,
        [Parameter(Mandatory)][int]$Index,
        [Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb,
        [scriptblock]$RunRow = { param($Entry, $Crumb) Invoke-WtAssistantToolRow -Entry $Entry -Breadcrumb $Crumb },
        [scriptblock]$RunInline = { param($Entry, $Crumb)
            Invoke-WtReplHop -Action {
                $data = $Entry.Item.Data
                $script:WtPanelBreadcrumb = $Crumb
                if ($data.Power) { Invoke-WtPowerAction -ConsequenceKey ([string]$data.ConsequenceKey) -Breadcrumb $Crumb -Action $data.Action }
                elseif ($data.Action) { & $data.Action | Out-Null }
            }
        },
        [scriptblock]$Confirm = { param($Entry)
            $answer = Read-WtReplAnswer -Lines (Get-WtAssistantDigitConfirmLines -Entry $Entry) -Prompt (Get-WtYesNoPrompt -Text (Get-Translation 'AsDigitApplyPrompt')) -Risk ([string]$Entry.Risk)
            return (Test-WtAffirmativeAnswer -Answer ([string]$answer))
        },
        [scriptblock]$Apply = { param($Ids, $Ctx) Invoke-WtAssistantApply -Ids $Ids -Context $Ctx },
        [scriptblock]$InstallWinget = { param($Entry, $Crumb)
            $id = [regex]::Replace([string]$Entry.Id, '^Winget:', '')
            $lines = @(((Get-Translation 'AsWingetInstallConfirm') -f [string]$Entry.LabelEn))
            $answer = Read-WtReplAnswer -Lines $lines -Prompt (Get-WtYesNoPrompt -Text (Get-Translation 'AsWingetInstallPrompt')) -Risk 'CAUTION'
            if (-not (Test-WtAffirmativeAnswer -Answer ([string]$answer))) { return @{ Ran = $false; Lines = [string[]]@() } }
            $state = @{ Marks = (New-Object 'System.Collections.Generic.List[string]'); Installed = @(); LastSummary = [string[]]@() }
            $null = Invoke-WtReplHop -Action {
                $script:WtPanelBreadcrumb = $Crumb
                $state.Marks.Add($id)
                Invoke-WtWingetStoreRun -State $state -Operation 'Install'
            }
            return @{ Ran = $true; Lines = [string[]]@($state.LastSummary | Where-Object { $null -ne $_ } | ForEach-Object { [string]$_ }) }
        }
    )
    $suggestions = @($Chat.Suggestions)
    if ($Index -lt 1 -or $Index -gt $suggestions.Count) { return $null }
    $pick = $suggestions[$Index - 1]
    $entry = $pick.Entry
    $kind = [string]$entry.Kind
    $mask = Get-WtAssistantMaskContext
    $note = { param($Outcome) Add-WtAssistantPendingNote -Chat $Chat -Text (Format-WtAssistantRunNote -Number $Index -Id ([string]$entry.Id) -Outcome $Outcome -Mask $mask) }
    $cardNumbers = [string[]]@(for ($i = 0; $i -lt $suggestions.Count; $i++) { [string]($i + 1) + ' ' + [string]$suggestions[$i].Label })
    $report = { param($Lines) $Chat.FollowUp = Format-WtAssistantRunReport -Number $Index -Label ([string]$pick.Label) -Lines ([string[]]@($Lines)) -Numbers $cardNumbers -Mask $mask }
    $stageOnlyToggle = ($kind -eq 'Toggle' -and -not $entry.Runnable -and [string]$entry.Screen)
    if ($kind -eq 'Screen' -or $stageOnlyToggle) {
        $script:WtWingetStoreInitialQuery = ''
        & $note 'opened its screen'
        return @{ Nav = 'Push'; Target = [string]$entry.Screen; Char = ''; HasMarks = $false }
    }
    if ($kind -eq 'Winget') {
        $install = & $InstallWinget $entry $Breadcrumb
        $installRan = $(if ($install -is [bool]) { [bool]$install } else { [bool]$install.Ran })
        if (-not $installRan) {
            Reset-WtFrameCache
            Add-WtChatEntry -State $Chat -Kind 'Info' -Text ((Get-Translation 'AsDeclinedTool') -f [string]$pick.Label)
            & $note 'declined'
            return $null
        }
        Reset-WtFrameCache
        foreach ($l in @(Format-WtReplToolRunLines -Label ([string]$pick.Label) -Status (Get-Translation 'AsToolRunOwnScreen'))) { Add-WtChatEntry -State $Chat -Kind 'Tool' -Text $l }
        & $note 'winget install ran on its own screen'
        $summary = [string[]]@()
        if (-not ($install -is [bool])) { $summary = [string[]]@($install.Lines | Where-Object { $null -ne $_ } | ForEach-Object { [string]$_ }) }
        if ($summary.Count -gt 0) { & $report $summary }
        return $null
    }
    if ($kind -eq 'Toggle') {
        if (-not (& $Confirm $entry)) {
            Reset-WtFrameCache
            Add-WtChatEntry -State $Chat -Kind 'Info' -Text ((Get-Translation 'AsDeclinedTool') -f [string]$pick.Label)
            & $note 'declined'
            return $null
        }
        $context = @{
            Mask = $mask; OnSuggest = { param($Valid) }; Breadcrumb = $Breadcrumb
            ReadAnswer = { param($Lines, $Prompt, $Risk) Read-WtReplAnswer -Lines $Lines -Prompt $Prompt -Risk $Risk }
            OnApplied = { param($Lines) foreach ($l in @($Lines)) { Add-WtChatEntry -State $Chat -Kind 'Tool' -Text ('    ' + [string]$script:WtGlyphs.Branch + ' ' + [string]$l) } }
        }
        $result = & $Apply ([string[]]@([string]$entry.Id)) $context
        Reset-WtFrameCache
        Reset-WtAssistantSessionExtra -Chat $Chat
        $outcome = 'applied'
        if (@($result.applied).Count -eq 0) {
            $firstError = ''
            if (@($result.failed).Count -gt 0) { $firstError = [string]$result.failed[0].error }
            if ($firstError) { $outcome = 'failed: ' + $firstError } else { $outcome = 'skipped (gate declined)' }
        }
        & $note $outcome
        if ($outcome -ne 'skipped (gate declined)') { & $report (Get-WtAssistantApplyReportLines -Result $result) }
        return $null
    }
    if ($entry.Runnable) {
        $run = & $RunRow $entry $Breadcrumb
        Reset-WtFrameCache
        $lines = [string[]]@($run.Lines | Where-Object { $null -ne $_ } | ForEach-Object { [string]$_ })
        if (-not $run.Ran) {
            foreach ($l in @(Format-WtReplToolRunLines -Label ([string]$pick.Label) -Status (Get-Translation 'AsToolRunRefused'))) { Add-WtChatEntry -State $Chat -Kind 'Tool' -Text ([string]$l) }
            & $note 'refused (not runnable from the chat)'
            return $null
        }
        foreach ($l in @(Format-WtReplToolRunLines -Label ([string]$pick.Label) -Status (Get-Translation 'AsToolRunDone') -Lines $lines -Max 0)) { Add-WtChatEntry -State $Chat -Kind 'Tool' -Text ([string]$l) }
        & $note ('ran (' + $lines.Count + ' output lines shown to the user)')
        & $report $lines
        return $null
    }
    & $RunInline $entry $Breadcrumb
    Reset-WtFrameCache
    foreach ($l in @(Format-WtReplToolRunLines -Label ([string]$pick.Label) -Status (Get-Translation 'AsToolRunOwnScreen'))) { Add-WtChatEntry -State $Chat -Kind 'Tool' -Text ([string]$l) }
    & $note 'opened its own screen'
    return $null
}

function Invoke-WtAssistantSend {
    <#
    .SYNOPSIS
        One user turn through the agent loop, printed as it happens: a
        spinner runs while the model thinks, the answer streams behind one
        bullet, and each tool call opens with "* name(args)" and closes
        with a branch line for time and size. -Harness (report-turn path):
        Text is WinToolify's own report of what the user ran by number, not
        something typed - it reaches the model as a user-role message with
        no transcript entry. The profile getter is passed as $profileSeam,
        not $GetProfile: that name collides with
        Get-WtAssistantSessionExtra's own -GetProfile parameter and would
        shadow into infinite self-recursion.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$Chat,
        [Parameter(Mandatory)][PSCustomObject]$Settings,
        [Parameter(Mandatory)][string]$Text,
        [Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb,
        [switch]$Harness,
        [switch]$KeepSuggestions,
        [scriptblock]$Turn = { param($ArgTable) Invoke-WtAssistantTurn @ArgTable },
        [scriptblock]$ReadAnswer = { param($Lines, $Prompt, $Risk, $Choices) Read-WtReplAnswer -Lines $Lines -Prompt $Prompt -Risk $Risk -Choices $Choices },
        [scriptblock]$OnDelta = { param($Piece) Hide-WtReplSpinner; Write-WtReplStream -Piece $Piece },
        [scriptblock]$OnReasoningDelta = { param($Piece) Update-WtReplSpinner -AddChars ([string]$Piece).Length },
        [scriptblock]$ShouldCancel = { Sync-WtReplResize | Out-Null; Update-WtReplSpinner; Test-WtReplCancelRequested },
        [scriptblock]$Write = (Get-WtReplDefaultWriter),
        [scriptblock]$GetProfile = { param($S) if ($S.ProfileEnabled) { [string](Get-WtAssistantMachineProfile -Kind 'Short' -OnCold { & $breakStream; Write-WtReplLine -Text ('  ' + (Get-Translation 'AsProfileBuilding')) -Fg 'DarkGray' }).Json } else { '' } },
        [scriptblock]$GetNotes = { @(Read-WtAssistantNotes) },
        [scriptblock]$ReadPermissions = { Read-WtAssistantPermissions }
    )
    if (-not (Invoke-WtAssistantPrivacyGate -Settings $Settings -Breadcrumb $Breadcrumb)) {
        Add-WtChatEntry -State $Chat -Kind 'Info' -Text (Get-Translation 'AsPrivacyDeclined')
        if ($Harness) { Add-WtAssistantPendingNote -Chat $Chat -Text $Text }
        return
    }
    if (-not $Harness) { Add-WtChatEntry -State $Chat -Kind 'User' -Text $Text -Silent }
    $sendText = $Text
    $notesSent = [string[]]@()
    if ($Chat.ContainsKey('PendingNotes') -and $null -ne $Chat.PendingNotes -and $Chat.PendingNotes.Count -gt 0) {
        $notesSent = [string[]]@($Chat.PendingNotes.ToArray())
        $sendText = ($notesSent -join "`n") + "`n" + $Text
        $Chat.PendingNotes.Clear()
    }
    $Chat.Busy = $true
    if (-not ($Harness -or $KeepSuggestions)) { $Chat.Suggestions = @() }
    $listBefore = $Chat.Suggestions
    Reset-WtReplStream
    $width = (Get-WtConsoleSize).Width
    $script:WtReplStream.Width = $width
    $apiKey = Unprotect-WtAssistantSecret -Blob ([string]$Settings.AssistantApiKey)
    $temperature = -1.0
    $parsedT = 0.0
    if ([double]::TryParse([string]$Settings.AssistantTemperature, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$parsedT) -and $parsedT -ge 0) {
        $temperature = $parsedT
    }
    $maxTokens = 0
    $parsedM = 0
    if ([int]::TryParse([string]$Settings.AssistantMaxTokens, [ref]$parsedM) -and $parsedM -gt 0) {
        $maxTokens = $parsedM
    }
    $isOllama = Test-WtLlmOllamaEndpoint -Endpoint (Get-WtAssistantEffectiveEndpoint -Settings $Settings)
    $numCtx = $(if ($isOllama) { ConvertTo-WtAssistantNumCtx -Text ([string]$Settings.AssistantNumCtx) } else { 0 })
    if ($null -eq $Chat.ClientCompat) { $Chat.ClientCompat = @{} }
    $turnUsage = @{ PromptTokens = 0; CompletionTokens = 0; CachedTokens = 0; LastPromptTokens = 0; Rounds = 0 }
    $mask = Get-WtAssistantMaskContext
    $context = @{
        Mask       = $mask
        OnSuggest  = { param($Valid) $validRows = @($Valid | Where-Object { $null -ne $_ }); if ($validRows.Count -gt 0) { Set-WtAssistantSuggestions -Chat $Chat -Entries $validRows } }
        Breadcrumb = $Breadcrumb
        ReadAnswer = $ReadAnswer
        OnApplied  = { param($Lines) & $breakStream; foreach ($l in @($Lines)) { Add-WtChatEntry -State $Chat -Kind 'Tool' -Text ('    ' + [string]$script:WtGlyphs.Branch + ' ' + [string]$l) } }
        OnNoteSaved = { param($T) Reset-WtAssistantSessionExtra -Chat $Chat; & $breakStream; Add-WtChatEntry -State $Chat -Kind 'Info' -Text ((Get-Translation 'AsNoteSaved') -f $T) }
    }
    if ($null -eq $Chat.Schemas) {
        $disabled = [string[]]@()
        try { $perms = & $ReadPermissions; $disabled = [string[]]@(Get-WtAssistantDisabledTools -Permissions $perms) } catch { $disabled = [string[]]@(Get-WtAssistantDisabledTools) }
        $Chat.Disabled = $disabled
        $Chat.Schemas = @(Get-WtAssistantFunctionSchemas -Disabled $disabled)
    }
    $context['Disabled'] = [string[]]@($Chat.Disabled)
    $schemas = $Chat.Schemas
    $systemPrompt = Get-WtAssistantSystemPrompt
    $maxRounds = 5
    $breakStream = { Complete-WtReplStream -Write $Write }
    $client = { param($Messages, $Round)
        $reply = Invoke-WtAssistantChat -AuthMode ([string]$Settings.AssistantAuthMode) -Arguments @{
            Endpoint    = [string]$Settings.AssistantEndpoint; ApiKey = $apiKey; Model = [string]$Settings.AssistantModel
            Messages    = $Messages; Tools = $schemas; ToolChoice = $(if ($Round -gt $maxRounds) { 'none' } else { '' })
            Stream      = $true; OnDelta = $OnDelta; OnReasoningDelta = $OnReasoningDelta; ShouldCancel = $ShouldCancel
            Temperature = $temperature; MaxTokens = $maxTokens; NumCtx = $numCtx; Compat = $Chat.ClientCompat
            SessionId   = [string]$Chat.SessionId; TimeoutSec = 180
        }
        if ($null -ne $reply) { Add-WtAssistantUsage -Total $turnUsage -Usage $reply.Usage }
        return $reply
    }
    $dispatch = { param($Name, $ArgsJson) Invoke-WtAssistantToolCall -Name $Name -ArgumentsJson $ArgsJson -Context $context }
    $onToolStart = { param($Name, $ArgsJson)
        & $breakStream
        Hide-WtReplSpinner
        Add-WtChatEntry -State $Chat -Kind 'Tool' -Text (Format-WtReplToolStart -Name $Name -ArgumentsJson $ArgsJson -Width ([int]$script:WtReplStream.Width))
        Show-WtReplSpinner -Label ((Get-Translation 'AsSpinTool') -f $Name)
    }
    $onToolDone = { param($Name, $Seconds, $Chars, $Ok)
        & $breakStream
        Hide-WtReplSpinner
        Add-WtChatEntry -State $Chat -Kind 'Tool' -Text (Format-WtReplToolResult -Seconds $Seconds -Chars $Chars -Ok $Ok)
        Show-WtReplSpinner -Label (Get-Translation 'AsSpinThinking')
    }
    $onRecovered = { param($Count) & $breakStream; Add-WtChatEntry -State $Chat -Kind 'Info' -Text ((Get-Translation 'AsReplRecovered') -f $Count) }
    try {
        Show-WtReplSpinner -Label (Get-Translation 'AsSpinThinking')
        $profileSeam = $GetProfile
        $systemExtra = Get-WtAssistantSessionExtra -Chat $Chat -GetProfile { & $profileSeam $Chat } -GetNotes $GetNotes -Mask $mask
        $prefixChars = 0
        if ($isOllama -and $numCtx -gt 0) {
            $prefixChars = ([string]$systemPrompt).Length + ([string]$systemExtra).Length + ([string](@($schemas) | ConvertTo-Json -Depth 10 -Compress)).Length
        }
        $historyMax = Get-WtAssistantHistoryMaxChars -NumCtx $numCtx -PrefixChars $prefixChars -Ollama $isOllama
        $Chat.HistoryMaxChars = $historyMax
        $result = & $Turn @{
            Conversation = @{ Messages = $Chat.Messages }; UserText = $sendText
            Client = $client; Dispatch = $dispatch; Schemas = $schemas; MaxRounds = $maxRounds
            HistoryMaxChars = $historyMax
            OnToolStart = $onToolStart; OnToolDone = $onToolDone; OnRecovered = $onRecovered
            SystemPrompt = $systemPrompt; SystemExtra = $systemExtra
        }
    }
    finally {
        Hide-WtReplSpinner
        $Chat.Busy = $false
        & $breakStream
        Close-WtReplToolBox -Write $Write
    }
    $Chat.LastUsage = $(if ([int]$turnUsage.Rounds -gt 0) { $turnUsage } else { $null })
    if ([int]$result.Dropped -gt 0) { Add-WtChatEntry -State $Chat -Kind 'Info' -Text (Get-Translation 'AsTrimmed') }
    $streamed = Get-WtReplStreamText -Kind 'Content'
    if (-not $result.Ok) {
        foreach ($n in $notesSent) { Add-WtAssistantPendingNote -Chat $Chat -Text $n }
        if ($Harness) { Add-WtAssistantPendingNote -Chat $Chat -Text $Text }
    }
    if ($result.Ok) {
        $answer = $(if ($streamed) { $streamed } else { [string]$result.FinalText })
        Add-WtChatEntry -State $Chat -Kind 'Assistant' -Text $answer -Silent
        $listChanged = -not [object]::ReferenceEquals($Chat.Suggestions, $listBefore)
        if ($listChanged -and @($Chat.Suggestions).Count -gt 0 -and $script:WtReplMode) { Write-WtReplSuggestions -Suggestions @($Chat.Suggestions) -Write $Write }
        if ($numCtx -gt 0 -and [int]$turnUsage.LastPromptTokens -gt (0.8 * $numCtx)) {
            Add-WtChatEntry -State $Chat -Kind 'Info' -Text ((Get-Translation 'AsCtxWarning') -f [int]$turnUsage.LastPromptTokens, $numCtx)
        }
    }
    elseif ($result.Cancelled) {
        $partial = [string]$result.FinalText
        if (-not $partial) { $partial = $streamed }
        Add-WtChatEntry -State $Chat -Kind 'Info' -Text ((Get-Translation 'AsCancelled') + $(if ($partial) { ' ' + $partial } else { '' }))
    }
    else { Add-WtChatEntry -State $Chat -Kind 'Error' -Text ([string]$result.ErrorText) }
}
#endregion src/80-screens/assistant.ps1

