#region src/80-screens/list-items.ps1
# New-WtListItem and group spacers.
# Covered by: tests/Screens.Tests.ps1, tests/MenuTree.Tests.ps1

function New-WtListItem {
    <#
    .SYNOPSIS
        The one constructor for list rows, so every screen builder emits
        the shape Get-WtListRowSegments / Update-WtListState expect. Desc
        drives the description band under the cursor's row (empty shows
        nothing); RiskTag prints the "[CAUTION]"-style tag while Risk
        still drives the row's colour even when the tag is off.
        CycleTargets turns Space from a two-state toggle into a walk
        through those targets and back to unmarked. Header, Info and
        Spacer rows are never focusable; Applied means the live state
        already matches the target, Removable means it may also be
        marked back to the Windows default.
    #>
    param(
        [Parameter(Mandatory)][ValidateSet('Link', 'Action', 'Check', 'Radio', 'Header', 'Info', 'Spacer', 'Rule')][string]$Kind,
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][AllowEmptyString()][string]$Label,
        [string]$Risk = $null,
        [string]$StateLabel = '',
        [string]$PendingVerbKey = '',
        [string]$Desc = '',
        [bool]$Selectable = $true,
        [object]$Data = $null,
        [string]$Group = '',
        [bool]$Applied = $false,
        [bool]$Removable = $false,
        [bool]$RiskTag = $true,
        [AllowEmptyCollection()][string[]]$CycleTargets = @()
    )
    if (@('Header', 'Info', 'Spacer', 'Rule') -contains $Kind) { $Selectable = $false }
    return [PSCustomObject]@{
        Kind       = $Kind
        Name       = $Name
        Label      = $Label
        Risk       = $Risk
        StateLabel = $StateLabel
        PendingVerbKey = $PendingVerbKey
        Desc       = $Desc
        Selectable = $Selectable
        Data       = $Data
        Group      = $Group
        Applied      = $Applied
        Removable    = $Removable
        RiskTag      = $RiskTag
        CycleTargets = [string[]]@($CycleTargets)
    }
}

function Add-WtListGroupSpacers {
    <#
    .SYNOPSIS
        PURE: returns the list with one blank Spacer row in front of
        every Header that is not already the first row of the list, so
        long screens breathe between their groups instead of running
        together. Adjacent headers (a group header immediately followed
        by its first sub-header) get no spacer between them - the pair
        reads as one heading.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Items
    )
    $out = New-Object System.Collections.Generic.List[object]
    $n = 0
    for ($i = 0; $i -lt $Items.Count; $i++) {
        $item = $Items[$i]
        if ($item.Kind -eq 'Header' -and $i -gt 0 -and $Items[$i - 1].Kind -ne 'Header') {
            $n++
            $out.Add((New-WtListItem -Kind 'Spacer' -Name ('Spacer:' + $n) -Label ''))
        }
        $out.Add($item)
    }
    return $out.ToArray()
}
#endregion src/80-screens/list-items.ps1

#region src/80-screens/main.ps1
# Invoke-WtScreenByKey, Confirm-WtExit, Invoke-WtMainLoop, Get-WtMainScreenFrame, Show-Menu.
# Covered by: tests/Guard.Tests.ps1, tests/Screens.Tests.ps1

function Invoke-WtScreenByKey {
    <#
    .SYNOPSIS
        The screen registry: one switch from a screen key to the function
        that runs it. Every Data.Screen value emitted by any item builder
        must have a case here; an unmapped key falls through to the
        placeholder screen.
    #>
    param([Parameter(Mandatory)][string]$Key)
    switch ($Key) {
        'Main' { return Invoke-WtMainScreen }
        'BasicTools' { return Invoke-WtBasicToolsScreen }
        'ActionTools' { return Invoke-WtActionToolsScreen }
        'InfoTools' { return Invoke-WtInfoToolsScreen }
        'SystemSettings' { return Invoke-WtSystemSettingsScreen }
        'Services' { return Invoke-WtServicesScreen }
        'Privacy' { return Invoke-WtPrivacyMenuScreen }
        'PrivacyTelemetry' { return Invoke-WtPrivacyGroupScreen -Key 'PrivacyTelemetry' }
        'PrivacyAppPermissions' { return Invoke-WtPrivacyGroupScreen -Key 'PrivacyAppPermissions' }
        'PrivacyAi' { return Invoke-WtPrivacyGroupScreen -Key 'PrivacyAi' }
        'PrivacySearchUi' { return Invoke-WtPrivacyGroupScreen -Key 'PrivacySearchUi' }
        'PrivacyEdge' { return Invoke-WtPrivacyGroupScreen -Key 'PrivacyEdge' }
        'PrivacyOffice' { return Invoke-WtPrivacyGroupScreen -Key 'PrivacyOffice' }
        'PrivacyUpdate' { return Invoke-WtPrivacyGroupScreen -Key 'PrivacyUpdate' }
        'PerApp' { return Invoke-WtPerAppScreen }
        'Packages' { return Invoke-WtPackagesScreen }
        'WingetStore' { return Invoke-WtWingetStoreScreen }
        'Assistant' { return Invoke-WtAssistantScreen }
        'Language' { return Invoke-WtLanguageScreen }
        'Undo' { return Invoke-WtUndoScreen }
        'Profiles' { return Invoke-WtProfilesScreen }
        default { return Invoke-WtPlaceholderScreen -Key $Key }
    }
}

function Confirm-WtExit {
    <#
    .SYNOPSIS
        Exit gate: nothing marked -> leave at once. Marks on the current
        screen would be lost -> ask in the panel (Enter leaves, anything
        else stays, exhausted input leaves).
    #>
    param(
        [bool]$HasMarks = $false,
        [scriptblock]$ReadAnswer = { param($Lines, $Prompt) Read-WtPanelAnswer -Breadcrumb (Get-Translation 'Exit') -Lines $Lines -Prompt $Prompt -Risk 'CAUTION' }
    )
    if (-not $HasMarks) { return $true }
    $answer = & $ReadAnswer @((Get-Translation 'MarksWillBeLost')) (Get-Translation 'ExitConfirmPrompt')
    if ($null -eq $answer) { return $true }
    return (([string]$answer).Trim() -eq '')
}

function Show-WtScreenError {
    <#
    .SYNOPSIS
        What the navigation loop does with an exception a screen let
        escape: log it, make sure the REPL no longer owns the console (a
        throw out of Enter-WtReplMode itself never reaches the assistant
        screen's own cleanup, so this is a second safety net), and say
        so in a panel - which screen, the message, where the log is, and
        that the previous screen comes back. Nothing here may throw; the
        panel itself is guarded.
    #>
    param(
        [Parameter(Mandatory)][string]$Key,
        [Parameter(Mandatory)]$ErrorRecord,
        [scriptblock]$Log = { param($R, $C) Write-WtErrorLog -ErrorRecord $R -Context $C },
        [scriptblock]$ReadAnswer = { param($Lines, $Prompt) Read-WtPanelAnswer -Breadcrumb (Get-Translation 'MainMenu') -Lines $Lines -Prompt $Prompt -Risk 'CAUTION' -Layout 'Compact' }
    )
    $logPath = ''
    try { $logPath = [string](& $Log $ErrorRecord ('Screen: ' + $Key)) } catch { $logPath = '' }
    try { if ($script:WtReplMode) { Exit-WtReplMode } } catch { $null = $_ }
    Reset-WtFrameCache
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add(((Get-Translation 'ErrScreenFailed') -f $Key))
    foreach ($l in @(Get-WtErrorSummaryLines -ErrorRecord $ErrorRecord)) { $lines.Add('  ' + [string]$l) }
    if ($logPath) { $lines.Add(''); $lines.Add(((Get-Translation 'ErrLogSaved') -f $logPath)) }
    $lines.Add('')
    $lines.Add((Get-Translation 'ErrReturning'))
    try { $null = & $ReadAnswer $lines.ToArray() (Get-Translation 'PressEnterContinue') } catch { $null = $_ }
    Reset-WtFrameCache
}

function Show-WtFatalError {
    <#
    .SYNOPSIS
        The entry point's last word when an exception escapes even the
        navigation loop: log it, leave the alternate buffer so the text
        lands where the user can read it, print what happened and where
        the log is, and - on an interactive console - wait for Enter.
        The finally that follows may Stop-Process the spawned console;
        without this wait the window closed with the error still in it.
    #>
    param(
        [Parameter(Mandatory)]$ErrorRecord,
        [scriptblock]$Log = { param($R, $C) Write-WtErrorLog -ErrorRecord $R -Context $C },
        [scriptblock]$Write = { param($Text, $Fg) Write-Host -ForegroundColor ([ConsoleColor]$Fg) ([string]$Text) },
        [scriptblock]$WaitEnter = { $null = Read-Host },
        [scriptblock]$IsInteractive = { -not [Console]::IsInputRedirected }
    )
    $logPath = ''
    try { $logPath = [string](& $Log $ErrorRecord 'Main') } catch { $logPath = '' }
    try { if ($script:WtReplMode) { Exit-WtReplMode } } catch { $null = $_ }
    try { Restore-WtTui } catch { $null = $_ }
    try {
        & $Write '' 'Gray'
        & $Write (Get-Translation 'ErrFatal') 'Red'
        foreach ($l in @(Get-WtErrorSummaryLines -ErrorRecord $ErrorRecord)) { & $Write ('  ' + [string]$l) 'Red' }
        if ($logPath) { & $Write ('  ' + ((Get-Translation 'ErrLogSaved') -f $logPath)) 'Gray' }
        $interactive = $false
        try { $interactive = [bool](& $IsInteractive) } catch { $interactive = $false }
        if ($interactive) {
            & $Write (Get-Translation 'ErrPressEnterClose') 'Yellow'
            try { & $WaitEnter } catch { $null = $_ }
        }
    }
    catch { $null = $_ }
}

function Invoke-WtMainLoop {
    <#
    .SYNOPSIS
        The navigation stack machine: Push adds a child, Back pops (or
        stays at the root, so no run of Esc closes the app), Exit asks
        Confirm-WtExit. Returns rather than exiting, so the dot-source
        guard and Guard.Tests' no-exit rule hold. A screen that throws
        is contained here - logged, shown, and popped as if it had said
        Back - rather than reaching the entry point's finally, whose
        Stop-Process would take the window and error text with it. The
        root screen gets one retry; throwing twice ends the loop, the
        only way to leave a menu that cannot paint at all. The verdict
        is read defensively ($result -is [hashtable]) since a bridged
        legacy screen can leak raw Read-Host output into its return value.
    #>
    param(
        [AllowEmptyCollection()][string[]]$InitialScreens = @('Main'),
        [scriptblock]$OnScreenError = { param($Key, $Record) Show-WtScreenError -Key $Key -ErrorRecord $Record }
    )
    $stack = New-Object System.Collections.Generic.List[string]
    foreach ($screen in @($InitialScreens)) { if ($screen) { $stack.Add([string]$screen) } }
    if ($stack.Count -eq 0) { $stack.Add('Main') }
    $rootFailures = 0
    while ($stack.Count -gt 0) {
        $key = [string]$stack[$stack.Count - 1]
        $result = $null
        $failed = $false
        try { $result = Invoke-WtScreenByKey -Key $key }
        catch {
            $failed = $true
            try { & $OnScreenError $key $_ } catch { $null = $_ }
        }
        if ($failed) {
            if ($stack.Count -gt 1) { $stack.RemoveAt($stack.Count - 1); continue }
            $rootFailures++
            if ($rootFailures -ge 2) { return }
            continue
        }
        $rootFailures = 0
        $hasMarks = [bool](($result -is [hashtable]) -and $result.ContainsKey('HasMarks') -and $result.HasMarks)
        switch ([string]$result.Nav) {
            'Push' { $stack.Add([string]$result.Target) }
            'Back' {
                if ($stack.Count -gt 1) { $stack.RemoveAt($stack.Count - 1) }
                elseif ($script:WtInputExhausted) { return }
            }
            'Exit' { if (Confirm-WtExit -HasMarks $hasMarks) { return } }
            default { if ($stack.Count -gt 1) { $stack.RemoveAt($stack.Count - 1) } else { return } }
        }
    }
}

function Get-WtMainScreenFrame {
    <#
    .SYNOPSIS
        One static frame of the main screen (no input) - what Show-Menu
        prints. Resolves glyphs itself so it also works before
        Initialize-WtTui has run (dot-sourced / tests). The cursor
        starts on the first row that can take it, not row 0, which is
        the title rule and would leave the description band blank.
    #>
    param(
        [Parameter(Mandatory)][int]$Width,
        [Parameter(Mandatory)][int]$Height
    )
    $glyphs = $script:WtGlyphs
    if ($null -eq $glyphs) { $glyphs = Get-WtGlyphSet -Unicode (Test-WtUnicodeGlyphSupport) }
    $items = Get-WtMainMenuItems
    $state = @{ CursorIndex = (Get-WtValidListCursor -Items $items); WindowStart = 0; Selection = (New-Object 'System.Collections.Generic.HashSet[string]') }
    return Get-WtFrameRows -Breadcrumb (Get-Translation 'MainMenu') -Items $items -State $state -Width $Width -Height $Height `
        -Glyphs $glyphs -FooterText (Get-Translation 'MainFooter') -ShowBanner $true -Layout 'Compact' -DescriptionRows 2
}

function Show-Menu {
    <#
    .SYNOPSIS
        Renders one static frame of the main screen (no input, no loop).
        The name is pinned by Guard.Tests; the interactive loop is
        Invoke-WtMainLoop.
    #>
    $width = 100
    $height = 40
    try {
        $size = $Host.UI.RawUI.WindowSize
        if ($size.Width -gt 0 -and $size.Height -gt 0) { $width = $size.Width; $height = $size.Height }
    }
    catch { $null = $_ }
    Write-WtFrame -FrameLines (Get-WtMainScreenFrame -Width $width -Height $height) -Width $width
}
#endregion src/80-screens/main.ps1

#region src/80-screens/nav.ps1
# Main menu and basic tools items, Invoke-WtNavScreen, placeholder/main/basic screens, breadcrumbs.
# Covered by: tests/MenuTree.Tests.ps1, tests/Screens.Tests.ps1

function Get-WtMainMenuItems {
    <#
    .SYNOPSIS
        The main menu rows, in order, under their titled rules, with the
        assistant's own block near the end and Exit last. A Rule, Info or
        Spacer row never takes a number or the cursor. Every row that does
        carries a Desc, shown in the description band between the rows
        and the navigation guide. Pure - labels resolve through the
        active language.
    #>
    $rows = @(
        New-WtListItem -Kind 'Rule' -Name 'MainToolsRule' -Label (Get-Translation 'MainToolsRule')
        New-WtListItem -Kind 'Link' -Name 'BasicTools' -Label (Get-Translation 'BasicTools') -Desc (Get-Translation 'MainDescBasicTools') -Data @{ Screen = 'BasicTools' }
        New-WtListItem -Kind 'Link' -Name 'Services' -Label (Get-Translation 'ServicesManagement') -Desc (Get-Translation 'MainDescServices') -Data @{ Screen = 'Services' }
        New-WtListItem -Kind 'Link' -Name 'SystemSettings' -Label (Get-Translation 'SystemSettings') -Desc (Get-Translation 'MainDescSystemSettings') -Data @{ Screen = 'SystemSettings' }
        New-WtListItem -Kind 'Link' -Name 'Privacy' -Label (Get-Translation 'PrivacySettings') -Desc (Get-Translation 'MainDescPrivacy') -Data @{ Screen = 'Privacy' }
        New-WtListItem -Kind 'Link' -Name 'Packages' -Label (Get-Translation 'AppsMenu') -Desc (Get-Translation 'MainDescPackages') -Data @{ Screen = 'Packages' }
        New-WtListItem -Kind 'Link' -Name 'WingetStore' -Label (Get-Translation 'WingetStore') -Desc (Get-Translation 'MainDescWingetStore') -Data @{ Screen = 'WingetStore' }
        New-WtListItem -Kind 'Link' -Name 'Language' -Label (Get-Translation 'Language') -Desc (Get-Translation 'MainDescLanguage') -Data @{ Screen = 'Language' }
        New-WtListItem -Kind 'Action' -Name 'CreateRestorePoint' -Label (Get-Translation 'CreateRestorePoint') -Desc (Get-Translation 'MainDescCreateRestorePoint') -Data @{ Action = { Invoke-WtCreateRestorePointAction } }
        New-WtListItem -Kind 'Link' -Name 'Undo' -Label (Get-Translation 'UndoLastChange') -Desc (Get-Translation 'MainDescUndo') -Data @{ Screen = 'Undo' }
        New-WtListItem -Kind 'Link' -Name 'Profiles' -Label (Get-Translation 'ConfigProfiles') -Desc (Get-Translation 'MainDescProfiles') -Data @{ Screen = 'Profiles' }
    )
    return @($rows) + @(
        New-WtListItem -Kind 'Spacer' -Name 'MainAssistantSpacer' -Label ''
        New-WtListItem -Kind 'Rule' -Name 'MainAssistantRule' -Label (Get-Translation 'Assistant')
        New-WtListItem -Kind 'Link' -Name 'Assistant' -Label (Get-Translation 'MainAssistantRow') -Desc (Get-Translation 'MainDescAssistant') -Data @{ Screen = 'Assistant' }
        New-WtListItem -Kind 'Spacer' -Name 'MainExitSpacer' -Label ''
        New-WtListItem -Kind 'Action' -Name 'Exit' -Label (Get-Translation 'Exit') -Desc (Get-Translation 'MainDescExit') -Data @{ Exit = $true }
    )
}

function Get-WtBasicToolsItems {
    <#
    .SYNOPSIS
        Basic Tools: the pair of sub-menus, Action Tools and Information
        Tools. Pure.
    #>
    return @(
        New-WtListItem -Kind 'Link' -Name 'ActionTools' -Label (Get-Translation 'ActionTools') -Data @{ Screen = 'ActionTools' }
        New-WtListItem -Kind 'Link' -Name 'InfoTools' -Label (Get-Translation 'InformationTools') -Data @{ Screen = 'InfoTools' }
    )
}

function Invoke-WtNavScreen {
    <#
    .SYNOPSIS
        A navigation screen: Link rows push a child screen, Action rows
        run inline and keep the screen open, Exit rows / Q ask to leave.
        Returns @{ Nav = 'Push'|'Back'|'Exit'; Target; Char; HasMarks } for
        Invoke-WtMainLoop. Stray pipeline output from an inline action is
        piped to Out-Null so it cannot leak into the nav verdict, and
        pending input is cleared after a row runs so queued keystrokes
        cannot re-activate it.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb,
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Items,
        [string]$FooterText = '',
        [bool]$ShowBanner = $false,
        [bool]$RememberCursor = $false,
        [bool]$RootMenu = $false,
        [bool]$Searchable = $false,
        [int]$DescriptionRows = 0
    )
    if (-not $FooterText) { $FooterText = Get-Translation 'NavFooter' }
    $cursor = if ($RememberCursor) { Get-WtMainMenuCursor -Items $Items } else { -1 }
    $footerOnce = ''
    while ($true) {
        $footer = $(if ($footerOnce) { $footerOnce } else { $FooterText })
        $footerOnce = ''
        $r = Invoke-WtListScreen -Breadcrumb $Breadcrumb -Items $Items -MultiSelect $false -FooterText $footer -ShowBanner $ShowBanner -InitialCursor $cursor -Layout 'Compact' -Searchable $Searchable -DescriptionRows $DescriptionRows
        $cursor = [int]$r.CursorIndex
        if ($RememberCursor) { Set-WtMainMenuCursor -Items $Items -Index $cursor }
        if ($r.Emit -eq 'Back') {
            if ($RootMenu -and -not $script:WtInputExhausted) { $footerOnce = [string](Get-Translation 'MainEscHint'); continue }
            return @{ Nav = 'Back'; Target = ''; Char = ''; HasMarks = $false }
        }
        if ($r.Emit -eq 'Quit') { return @{ Nav = 'Exit'; Target = ''; Char = ''; HasMarks = $false } }
        if ($r.Emit -eq 'Activate' -and $r.Item -and $r.Item.Data) {
            $data = $r.Item.Data
            if ($data.Exit) { return @{ Nav = 'Exit'; Target = ''; Char = ''; HasMarks = $false } }
            if ($data.Screen) { return @{ Nav = 'Push'; Target = [string]$data.Screen; Char = ''; HasMarks = $false } }
            if ($data.Native) {
                Invoke-WtCapturedNativeAction -FilePath ([string]$data.FilePath) -Arguments ([string]$data.Arguments) `
                    -Title ([string]$data.Title) -Breadcrumb $Breadcrumb -Encoding $data.Encoding
                Reset-WtFrameCache
            }
            elseif ($data.Action) {
                if ($data.Captured) { Invoke-WtCapturedAction -Title ([string]$data.Title) -Breadcrumb $Breadcrumb -Action $data.Action -Encoding $data.Encoding }
                elseif ($data.Power) { Invoke-WtPowerAction -ConsequenceKey ([string]$data.ConsequenceKey) -Breadcrumb $Breadcrumb -Action $data.Action }
                else { $script:WtPanelBreadcrumb = $Breadcrumb; & $data.Action | Out-Null }
                Reset-WtFrameCache
            }
            if ($data.Native -or $data.Action) { $null = Clear-WtPendingInput }
        }
    }
}


function Invoke-WtPlaceholderScreen {
    <#
    .SYNOPSIS
        Keeps the navigation loop runnable while category screens are
        still being built: shows which screen was requested and returns
        to the parent.
    #>
    param([Parameter(Mandatory)][string]$Key)
    $script:WtPanelBreadcrumb = $Key
    Wait-WtEnter -Lines @((Get-Translation 'ScreenNotReady'))
    return @{ Nav = 'Back'; Target = ''; Char = ''; HasMarks = $false }
}

function Invoke-WtMainScreen {
    return Invoke-WtNavScreen -Breadcrumb (Get-Translation 'MainMenu') -Items (Get-WtMainMenuItems) -FooterText (Get-Translation 'MainFooter') -ShowBanner $true -RememberCursor $true -RootMenu $true -DescriptionRows 2
}

function Invoke-WtBasicToolsScreen {
    return Invoke-WtNavScreen -Breadcrumb (Get-WtBreadcrumb -Keys 'MainMenu', 'BasicTools') -Items (Get-WtBasicToolsItems)
}

function Get-WtBreadcrumb {
    <#
    .SYNOPSIS
        "Main Menu > Category > Screen" from translation keys, with an
        optional literal suffix (e.g. a capability's display label).
    #>
    param(
        [Parameter(Mandatory)][string[]]$Keys,
        [string]$Suffix = ''
    )
    $parts = @($Keys | ForEach-Object { [string](Get-Translation $_) })
    if ($Suffix) { $parts += $Suffix }
    return ($parts -join ' > ')
}
#endregion src/80-screens/nav.ps1

#region src/80-screens/output.ps1
# Output tail, native encoding, output screen, captured actions, savable reports.
# Covered by: tests/Screens.Tests.ps1

function Get-WtOutputTail {
    <#
    .SYNOPSIS
        PURE: the last Count lines, for the live progress panel. A
        running command's newest output is the interesting end, and
        Show-WtPanelMessage paints from the top with no scrolling, so
        the caller hands it a tail that fits instead of the whole log.
    #>
    param(
        [AllowEmptyCollection()][string[]]$Lines = @(),
        [Parameter(Mandatory)][int]$Count
    )
    $all = @($Lines)
    $take = [Math]::Max(1, $Count)
    if ($all.Count -le $take) { return $all }
    return @($all[($all.Count - $take)..($all.Count - 1)])
}

function Get-WtNativeOutputEncoding {
    <#
    .SYNOPSIS
        The encoding a captured native command's stdout must be decoded
        with: the console's REAL OEM code page, not what chcp reports.
        Nothing decoded anything while output went straight to the
        console, so this never mattered before; captured, a Turkish
        machine's ipconfig writes cp857 and decoding it as UTF-8 turns
        "Yerel Ag Baglantisi" into mojibake. Legacy console tools
        (ipconfig, systeminfo, chkdsk, netstat, sfc) write OEM bytes even
        when the console itself is on UTF-8; tools that really emit
        UTF-8 (winget and friends) get an explicit -Encoding from their
        caller instead of being guessed at here.
    #>
    param(
        [int]$OemCodePage = [System.Globalization.CultureInfo]::CurrentCulture.TextInfo.OEMCodePage
    )
    try { return [System.Text.Encoding]::GetEncoding($OemCodePage) }
    catch { $null = $_ }
    return [Console]::OutputEncoding
}

function Show-WtOutputScreen {
    <#
    .SYNOPSIS
        A command's output inside the box: scrollable, read-only, and
        never a bare console page. Nothing in the list is focusable, so
        Update-WtListState's cursorless branch scrolls the window with
        the arrows / PgUp / PgDn / Home / End, and Enter or Esc closes.
        Wide rows are cut with '~' rather than wrapped, so table output
        keeps its columns. -Hotkeys are extra letters the screen hands
        back instead of closing; anything else closes and returns ''.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb,
        [AllowEmptyCollection()][string[]]$Lines = @(),
        [string]$FooterText = '',
        [AllowEmptyCollection()][string[]]$Hotkeys = @()
    )
    $text = @($Lines)
    if ($text.Count -eq 0) { $text = @((Get-Translation 'OutputEmpty')) }
    if (-not $FooterText) { $FooterText = Get-Translation 'OutputFooter' }
    $script:WtPanelBreadcrumb = $Breadcrumb
    $items = @(Get-WtPanelItems -Lines $text)
    $pressed = ''
    while ($true) {
        $r = Invoke-WtListScreen -Breadcrumb $Breadcrumb -Items $items -FooterText $FooterText
        if ($r.Emit -eq 'Global') {
            $char = [string]$r.Char
            if (@($Hotkeys) -contains $char) { $pressed = $char; break }
            continue
        }
        break
    }
    Reset-WtFrameCache
    return $pressed
}

function Invoke-WtCapturedAction {
    <#
    .SYNOPSIS
        Runs an action with every output stream captured and rendered
        INSIDE the box, repainting at most every RefreshMs so a long
        sfc /scannow still visibly progresses; the same output then opens
        in a scrollable Show-WtOutputScreen when the command finishes.
        *>&1 merges every stream into one pipeline, so the action must
        NOT call Read-Host - ask for input in the panel before calling
        this. There is no cancel key while the command runs, matching
        the old console mode: reading the keyboard mid-pipeline would
        need a second runspace, and killing a half-finished sfc/DISM is
        worse than letting it end. Around each repaint, the console's
        encoding is swapped back to the UI encoding and then back to the
        native one, so a box-drawing glyph is never painted under a
        foreign code page.
    #>
    param(
        [Parameter(Mandatory)][scriptblock]$Action,
        [string]$Title = '',
        [string]$Breadcrumb = '',
        [scriptblock]$ShowProgress = {
            param($Lines, $Footer)
            $size = Get-WtConsoleSize
            $view = [Math]::Max(1, $size.Height - (Get-WtFrameChromeHeight -Width $size.Width))
            Show-WtPanelMessage -Breadcrumb $script:WtPanelBreadcrumb -Lines (Get-WtOutputTail -Lines $Lines -Count $view) -FooterText $Footer | Out-Null
        },
        [scriptblock]$ShowResult = { param($Lines) Show-WtOutputScreen -Breadcrumb $script:WtPanelBreadcrumb -Lines $Lines },
        [int]$RefreshMs = 120,
        [AllowNull()][System.Text.Encoding]$Encoding = $null,
        [bool]$UseNativeEncoding = $true
    )
    $script:WtPanelBreadcrumb = $(if ($Breadcrumb) { $Breadcrumb } elseif ($Title) { $Title } else { '' })
    $lines = New-Object System.Collections.Generic.List[string]
    $watch = [System.Diagnostics.Stopwatch]::StartNew()
    $lastPaint = [long]-1000
    $footer = { (Get-Translation 'OutputRunning') -f (Format-WtElapsed -Seconds ([int]$watch.Elapsed.TotalSeconds)) }
    & $ShowProgress @() (& $footer)

    $uiEncoding = $null
    $nativeEncoding = $null
    if ($UseNativeEncoding) {
        try {
            $uiEncoding = [Console]::OutputEncoding
            $nativeEncoding = if ($Encoding) { $Encoding } else { Get-WtNativeOutputEncoding }
            if ($nativeEncoding.CodePage -ne $uiEncoding.CodePage) { [Console]::OutputEncoding = $nativeEncoding }
            else { $uiEncoding = $null }
        }
        catch { $uiEncoding = $null }
    }
    $paint = {
        param($Rows, $Foot)
        if ($uiEncoding) { try { [Console]::OutputEncoding = $uiEncoding } catch { $null = $_ } }
        & $ShowProgress $Rows $Foot
        if ($uiEncoding) { try { [Console]::OutputEncoding = $nativeEncoding } catch { $null = $_ } }
    }
    try {
        & $Action *>&1 | ForEach-Object {
            foreach ($line in (ConvertTo-WtOutputLines -InputObject $_)) { $lines.Add([string]$line) }
            if (($watch.ElapsedMilliseconds - $lastPaint) -ge $RefreshMs) {
                $lastPaint = $watch.ElapsedMilliseconds
                & $paint $lines.ToArray() (& $footer)
            }
        }
    }
    catch { $lines.Add([string]$_.Exception.Message) }
    finally {
        if ($uiEncoding) { try { [Console]::OutputEncoding = $uiEncoding } catch { $null = $_ } }
    }
    $watch.Stop()
    $null = Clear-WtPendingInput
    & $ShowResult $lines.ToArray()
}

function Invoke-WtStreamedProcess {
    <#
    .SYNOPSIS
        Runs one native tool as a child process, draining both pipes
        asynchronously into $State and calling OnTick on a TIMER, then
        returns its exit code. Repaint must be timer- not output-driven:
        sfc goes silent for minutes mid-phase, which would otherwise
        read as a hang. stderr is drained in the SAME loop, never after,
        or a tool that fills its error pipe blocks forever waiting for a
        reader. Decoding rides StandardOutputEncoding on the child, not
        [Console]::OutputEncoding; -Encoding $null means the OEM page
        (sfc needs UTF-16, winget UTF-8). Each tick reasserts the Ctrl+C
        guard and window lock, since the child shares this console and
        can turn Ctrl+C back into a break signal for everyone on it.
    #>
    param(
        [Parameter(Mandatory)][string]$FilePath,
        [string]$Arguments = '',
        [Parameter(Mandatory)][hashtable]$State,
        [Parameter(Mandatory)][scriptblock]$OnTick,
        [AllowNull()][System.Text.Encoding]$Encoding = $null,
        [int]$RefreshMs = 120,
        [scriptblock]$StartProcess = { param($StartInfo) [System.Diagnostics.Process]::Start($StartInfo) }
    )
    $startInfo = New-Object System.Diagnostics.ProcessStartInfo
    $startInfo.FileName = $FilePath
    $startInfo.Arguments = $Arguments
    $startInfo.UseShellExecute = $false
    $startInfo.RedirectStandardOutput = $true
    $startInfo.RedirectStandardError = $true
    $startInfo.CreateNoWindow = $true
    $startInfo.StandardOutputEncoding = $(if ($Encoding) { $Encoding } else { Get-WtNativeOutputEncoding })
    $startInfo.StandardErrorEncoding = $startInfo.StandardOutputEncoding

    $process = $null
    try { $process = & $StartProcess $startInfo }
    catch {
        $State.Lines.Add([string]$_.Exception.Message)
        return -1
    }
    if ($null -eq $process) { return -1 }

    $watch = [System.Diagnostics.Stopwatch]::StartNew()
    $outBuffer = New-Object char[] 4096
    $errBuffer = New-Object char[] 4096
    $outRead = $process.StandardOutput.ReadAsync($outBuffer, 0, $outBuffer.Length)
    $errRead = $process.StandardError.ReadAsync($errBuffer, 0, $errBuffer.Length)
    $lastPaint = [long]-1000
    while ($outRead -or $errRead) {
        $moved = $false
        if ($outRead -and $outRead.IsCompleted) {
            $count = [int]$outRead.Result
            if ($count -le 0) { $outRead = $null }
            else {
                Add-WtNativeOutputChunk -State $State -Chunk ([string]::new($outBuffer, 0, $count))
                $outRead = $process.StandardOutput.ReadAsync($outBuffer, 0, $outBuffer.Length)
            }
            $moved = $true
        }
        if ($errRead -and $errRead.IsCompleted) {
            $count = [int]$errRead.Result
            if ($count -le 0) { $errRead = $null }
            else {
                Add-WtNativeOutputChunk -State $State -Chunk ([string]::new($errBuffer, 0, $count))
                $errRead = $process.StandardError.ReadAsync($errBuffer, 0, $errBuffer.Length)
            }
            $moved = $true
        }
        if (-not $moved) { Start-Sleep -Milliseconds 25 }
        if (($watch.ElapsedMilliseconds - $lastPaint) -ge $RefreshMs) {
            $lastPaint = $watch.ElapsedMilliseconds
            $null = Assert-WtTuiCtrlCInput
            $null = Assert-WtWindowMaximized
            & $OnTick
        }
    }
    $process.WaitForExit()
    $exit = [int]$process.ExitCode
    $process.Dispose()
    $watch.Stop()
    return $exit
}

function Invoke-WtCapturedNativeAction {
    <#
    .SYNOPSIS
        The captured-output panel for a long native tool (sfc, DISM):
        runs Invoke-WtStreamedProcess (shared with the winget batch
        runner) so the panel repaints on a TIMER instead of only when a
        line happens to arrive, and ends in the same scrollable
        Show-WtOutputScreen every other captured action ends in. Like
        Invoke-WtCapturedAction there is no cancel key - killing a
        half-finished sfc or DISM is worse than letting it end.
    #>
    param(
        [Parameter(Mandatory)][string]$FilePath,
        [string]$Arguments = '',
        [string]$Title = '',
        [string]$Breadcrumb = '',
        [AllowNull()][System.Text.Encoding]$Encoding = $null,
        [scriptblock]$ShowProgress = {
            param($Lines, $Footer)
            $size = Get-WtConsoleSize
            $view = [Math]::Max(1, $size.Height - (Get-WtFrameChromeHeight -Width $size.Width))
            Show-WtPanelMessage -Breadcrumb $script:WtPanelBreadcrumb -Lines (Get-WtOutputTail -Lines $Lines -Count $view) -FooterText $Footer | Out-Null
        },
        [scriptblock]$ShowResult = { param($Lines) Show-WtOutputScreen -Breadcrumb $script:WtPanelBreadcrumb -Lines $Lines },
        [int]$RefreshMs = 120,
        [scriptblock]$StartProcess = { param($StartInfo) [System.Diagnostics.Process]::Start($StartInfo) }
    )
    $script:WtPanelBreadcrumb = $(if ($Breadcrumb) { $Breadcrumb } elseif ($Title) { $Title } else { '' })
    $state = New-WtNativeOutputState
    $watch = [System.Diagnostics.Stopwatch]::StartNew()
    $footer = { (Get-Translation 'OutputRunning') -f (Format-WtElapsed -Seconds ([int]$watch.Elapsed.TotalSeconds)) }
    $paint = {
        $view = @($state.Lines.ToArray())
        if ([string]$state.Current -ne '') { $view += [string]$state.Current }
        & $ShowProgress $view (& $footer)
    }
    & $paint

    $null = Invoke-WtStreamedProcess -FilePath $FilePath -Arguments $Arguments -State $state `
        -OnTick $paint -Encoding $Encoding -RefreshMs $RefreshMs -StartProcess $StartProcess

    if ([string]$state.Current -ne '') { $state.Lines.Add([string]$state.Current) }
    $watch.Stop()
    $null = Clear-WtPendingInput
    & $ShowResult $state.Lines.ToArray()
}


function Show-WtSavableReport {
    <#
    .SYNOPSIS
        A report in the scrollable box, with "S" on the footer to write
        it to a file. The save confirmation is appended to the same
        report and the screen reopens, so the user sees where it went
        without losing the report.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb,
        [AllowEmptyCollection()][string[]]$Lines = @(),
        [Parameter(Mandatory)][string]$ReportName,
        [scriptblock]$SaveAction = { param($Name, $Rows) Save-WtReport -Name $Name -Lines $Rows },
        [scriptblock]$ShowResult = { param($Crumb, $Rows, $Footer) Show-WtOutputScreen -Breadcrumb $Crumb -Lines $Rows -FooterText $Footer -Hotkeys @('s') }
    )
    $rows = @($Lines)
    $footer = (Get-Translation 'OutputFooter') + ' - ' + (Get-Translation 'OutputSaveHint')
    while ($true) {
        $key = [string](& $ShowResult $Breadcrumb $rows $footer)
        if ($key -ne 's') { break }
        $saved = & $SaveAction $ReportName $rows
        $rows = @($rows) + @('', ('{0}: {1}' -f (Get-Translation 'ReportSaved'), $saved))
        $footer = Get-Translation 'OutputFooter'
    }
}
#endregion src/80-screens/output.ps1

#region src/80-screens/packages.ps1
# Packages screen (show-all toggle).
# Covered by: tests/Screens.Tests.ps1

$script:WtShowAllPackages = $false

function Get-WtPackagesGroups {
    <#
    .SYNOPSIS
        The Apps screen's single group: installed packages only by
        default, everything with the H toggle, and automatically
        everything when fewer than 10 are installed so the screen never
        falls below the design floor. Live state is computed once and
        cached in Data with the catalog, since re-localizing every row
        and probing Get-AppxPackage -AllUsers are both too slow to
        repeat per row; a RemovalMethod='WinGet' row is invisible to
        Get-AppxPackage and routes through Get-WtPackageLiveInstalled
        instead. Every row is tagged PendingVerbKey='WillRemove' so
        marking an installed app for removal never displays as "Will
        apply".
    #>
    param(
        [bool]$ShowAll = $script:WtShowAllPackages,
        [scriptblock]$GetState,
        [scriptblock]$GetSnapshot = { Get-WtInstalledPackageSnapshot }
    )
    $catalog = @(Get-WtPackageCatalog)
    $states = @{}
    if ($GetState) {
        foreach ($e in $catalog) { $states[$e.Name] = & $GetState $e.Name }
    }
    else {
        $states = Get-WtPackageStatesFromSnapshot -Catalog $catalog -Snapshot @(& $GetSnapshot)
    }
    $installedCount = @($states.Values | Where-Object { $_.Installed }).Count
    $effectiveShowAll = ($ShowAll -or $installedCount -lt 10)
    return @{
        SectionKey = 'Packages'; HeaderKey = $null; HeaderField = 'Group'
        Data = @{ States = $states; ShowAll = $effectiveShowAll; Catalog = $catalog }
        GetCatalog = {
            param($g)
            $all = @($g.Data.Catalog | ForEach-Object { $_ | Add-Member -NotePropertyName 'PendingVerbKey' -NotePropertyValue 'WillRemove' -Force -PassThru })
            if ($g.Data.ShowAll) { return $all }
            return @($all | Where-Object { $g.Data.States[$_.Name].Installed })
        }
        GetEntryState = {
            param($e, $g)
            $s = $g.Data.States[$e.Name]
            $label = if ($s.Installed) { Get-Translation 'StateInstalled' } else { Get-Translation 'StateRemoved' }
            @{ Applied = $false; Available = [bool]$s.Installed; StateLabel = $label }
        }
    }
}

function Invoke-WtPackagesScreen {
    <#
    .SYNOPSIS
        Apps: the package catalog under its group sub-headers, with H
        toggling between "installed only" and the whole catalog.
        -Groups and -ExtraItems are scriptblocks, not arrays, so the
        rebuild Invoke-WtApplyScreen runs after OnHotkey returns $true
        re-reads $script:WtShowAllPackages instead of freezing the rows
        and hint at their first-build values.
    #>
    $toggle = {
        param($Char)
        if ($Char -eq 'h') { $script:WtShowAllPackages = -not $script:WtShowAllPackages; return $true }
        return $false
    }
    $hint = {
        $hintKey = if ($script:WtShowAllPackages) { 'PackagesToggleHintAll' } else { 'PackagesToggleHint' }
        @((New-WtListItem -Kind 'Info' -Name 'HideHint' -Label (Get-Translation $hintKey)))
    }
    $crumb = Get-WtBreadcrumb -Keys 'MainMenu', 'AppsMenu'
    return Invoke-WtApplyScreen -Breadcrumb $crumb -Groups { @((Get-WtPackagesGroups)) } -ExtraItems $hint `
        -CounterKey 'PackagesCount' -OnHotkey $toggle
}
#endregion src/80-screens/packages.ps1

#region src/80-screens/per-app.ps1
# Per-app permission screen.
# Covered by: tests/PerAppPermission.Tests.ps1

function Get-WtRegistryEntryLiveState {
    <#
    .SYNOPSIS
        The common GetEntryState for registry-backed catalogs
        (Telemetry, Explorer View, Gaming, ...): Applied from the live
        registry, always available.
    #>
    param([Parameter(Mandatory)][PSCustomObject]$Entry)
    $state = Get-WtRegistryEntryState -Entry $Entry
    return @{ Applied = [bool]$state.Applied; Available = $true }
}

function Invoke-WtApplyPerAppPermissionGroups {
    <#
    .SYNOPSIS
        Commit-side adapter for PerAppPermissions: groups staged
        "<capability>|<package family name>" names by capability and runs
        the guarded apply once per group (one undo entry each), aggregating
        results; the first Aborted group stops the rest, like sections do.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Names,
        [Parameter(Mandatory)][string]$Sid,
        [ValidateSet('Deny', 'Allow')][string]$Value = 'Deny',
        [scriptblock]$ApplyAction = {
            param($Capability, $Sid, [string[]]$Names, $Value)
            $action = if ($Value -eq 'Allow') { 'Revert Per-App Permission' } else { 'Apply Per-App Permission' }
            Invoke-WtApplyPerAppPermissionSelection -Capability $Capability -Sid $Sid -SelectedNames $Names -Value $Value -ActionName $action
        }
    )
    $groups = [ordered]@{}
    foreach ($n in $Names) {
        $idx = $n.IndexOf('|')
        if ($idx -lt 1 -or $idx -ge ($n.Length - 1)) { continue }
        $cap = $n.Substring(0, $idx)
        $app = $n.Substring($idx + 1)
        if (-not $groups.Contains($cap)) { $groups[$cap] = New-Object System.Collections.Generic.List[string] }
        $groups[$cap].Add($app)
    }
    $results = New-Object System.Collections.Generic.List[object]
    $aborted = $false
    foreach ($cap in @($groups.Keys)) {
        $r = & $ApplyAction $cap $Sid ([string[]]$groups[$cap].ToArray()) $Value
        if ($r -and $r.Aborted) { $aborted = $true; break }
        if ($r) { foreach ($x in @($r.Results)) { $results.Add($x) } }
    }
    return [PSCustomObject]@{ Aborted = $aborted; Results = $results.ToArray() }
}

function Get-WtFirewallOfferEntry {
    <#
    .SYNOPSIS
        The single firewall catalog entry worth offering: the direction
        opposite to the live state (enabled -> offer Disable, ADVANCED;
        disabled -> offer Enable, SAFE).
    #>
    param(
        [Parameter(Mandatory)][bool]$CurrentlyEnabled,
        [array]$Catalog = (Get-WtFirewallCatalog)
    )
    $target = if ($CurrentlyEnabled) { 'DisableFirewall' } else { 'EnableFirewall' }
    return ($Catalog | Where-Object Name -eq $target | Select-Object -First 1)
}

# --- settings screens (mark with Space, apply with Enter) -----------------

function Invoke-WtPerAppScreen {
    <#
    .SYNOPSIS
        One screen, two panes: pick a capability, then the apps it needs
        (check rows); stages each as "<capability>|<package family name>".
        Re-enumerated every rebuild, not cached, so a repeat Enter sees
        post-apply state instead of re-recording the same undo.
    #>
    $crumb = Get-WtBreadcrumb -Keys 'MainMenu', 'PrivacySettings', 'PerAppPermissions'
    $sid = Get-WtConsoleUserSid
    if (-not $sid) {
        $script:WtPanelBreadcrumb = $crumb
        Wait-WtEnter -Lines @((Get-Translation 'CouldNotDetermineAccount'))
        return @{ Nav = 'Back'; Target = ''; Char = ''; HasMarks = $false }
    }
    $capabilities = @(Get-WtAppPermissionCatalog)
    $capItems = @($capabilities | ForEach-Object { New-WtListItem -Kind 'Radio' -Name $_.Name -Label (Get-WtSelectorDisplayLabel -Entry $_) -Data $_ })
    $capSelection = New-Object 'System.Collections.Generic.HashSet[string]'
    while ($true) {
        $r = Invoke-WtListScreen -Breadcrumb $crumb -Items $capItems -MultiSelect $false -Selection $capSelection -FooterText (Get-Translation 'NavFooter')
        if ($r.Emit -eq 'Back' -or $r.Emit -eq 'Quit') { return @{ Nav = 'Back'; Target = ''; Char = ''; HasMarks = $false } }
        if ($r.Emit -ne 'Activate' -or -not $r.Item) { continue }
        $capability = $r.Item.Data
        $apps = @(Get-WtAppsForCapability -Capability $capability.Name -Sid $sid)
        if ($apps.Count -eq 0) {
            $script:WtPanelBreadcrumb = [string]$r.Item.Label
            Wait-WtEnter -Lines @((Get-Translation 'NoAppsRequestedCapability'))
            continue
        }
        $capName = [string]$capability.Name
        $capLabel = [string]$r.Item.Label
        $group = @{
            SectionKey = 'PerAppPermissions'; HeaderKey = $null
            Data = @{ Capability = $capName; Sid = $sid; CapLabel = $capLabel }
            GetCatalog = {
                param($g)
                @(Get-WtAppsForCapability -Capability $g.Data.Capability -Sid $g.Data.Sid | ForEach-Object {
                    [PSCustomObject]@{
                        Name         = ('{0}|{1}' -f $g.Data.Capability, $_.Name)
                        DisplayLabel = ('{0}: {1}' -f $g.Data.CapLabel, $_.DisplayLabel)
                        Risk         = 'SAFE'
                        Consequence  = $null
                        Selectable   = [bool]$_.Selectable
                    }
                })
            }
            GetEntryState = { param($e, $g) @{ Applied = (-not $e.Selectable); Available = $true } }
        }
        $inner = Invoke-WtApplyScreen -Breadcrumb (Get-WtBreadcrumb -Keys 'MainMenu', 'PrivacySettings', 'PerAppPermissions' -Suffix $capLabel) -Groups @($group)
        if ($inner.Nav -eq 'Exit') { return $inner }
    }
}
#endregion src/80-screens/per-app.ps1

#region src/80-screens/privacy.ps1
# Privacy menu and group screens.
# Covered by: tests/MenuTree.Tests.ps1

function Get-WtPrivacyScreenCatalog {
    <#
    .SYNOPSIS
        The seven Privacy screens: which existing sections each one hosts
        (first, with their own headers) and which hardening groups follow.
        Security has no screen of its own - after the OS filter its group
        falls below the ten-setting floor, so it rides under its own
        header on the Windows Update screen; its profile section stays
        separate.
    #>
    return @(
        @{ Key = 'PrivacyTelemetry'; TitleKey = 'PrivacyTelemetryScreen'; ExistingSections = [string[]]@('Telemetry', 'ActivityAdvertising')
           HardeningGroups = @(@{ Group = 'PrivacyTelemetry'; Section = 'HardeningPrivacy'; HeaderKey = 'HardeningMoreSettings' }) }
        @{ Key = 'PrivacyAppPermissions'; TitleKey = 'PrivacyAppPermissionsScreen'; ExistingSections = [string[]]@('CapabilityDefaults')
           HardeningGroups = @(@{ Group = 'AppPermissions'; Section = 'HardeningAppPermissions'; HeaderKey = 'HardeningMoreSettings' }) }
        @{ Key = 'PrivacyAi'; TitleKey = 'PrivacyAiScreen'; ExistingSections = [string[]]@('AiPrivacy')
           HardeningGroups = @(@{ Group = 'Ai'; Section = 'HardeningAi'; HeaderKey = 'HardeningMoreSettings' }) }
        @{ Key = 'PrivacySearchUi'; TitleKey = 'PrivacySearchUiScreen'; ExistingSections = [string[]]@('SearchSuggestions')
           HardeningGroups = @(@{ Group = 'SearchUi'; Section = 'HardeningSearchUi'; HeaderKey = 'HardeningMoreSettings' }) }
        @{ Key = 'PrivacyEdge'; TitleKey = 'PrivacyEdgeScreen'; ExistingSections = [string[]]@()
           HardeningGroups = @(@{ Group = 'Edge'; Section = 'HardeningEdge'; HeaderKey = $null }) }
        @{ Key = 'PrivacyOffice'; TitleKey = 'PrivacyOfficeScreen'; ExistingSections = [string[]]@()
           HardeningGroups = @(@{ Group = 'Office'; Section = 'HardeningOffice'; HeaderKey = $null }) }
        @{ Key = 'PrivacyUpdate'; TitleKey = 'PrivacyUpdateScreen'; ExistingSections = [string[]]@()
           HardeningGroups = @(
               @{ Group = 'Update'; Section = 'HardeningUpdate'; HeaderKey = $null }
               @{ Group = 'Security'; Section = 'HardeningSecurity'; HeaderKey = 'PrivacySecuritySection' }
           ) }
    )
}

function Get-WtPrivacyMenuItems {
    <#
    .SYNOPSIS
        The Privacy menu - one link per screen, in catalog order. Pure.
    #>
    return @(foreach ($s in @(Get-WtPrivacyScreenCatalog)) {
        New-WtListItem -Kind 'Link' -Name $s.Key -Label (Get-Translation $s.TitleKey) -Data @{ Screen = $s.Key }
    })
}

function Get-WtPrivacyGroups {
    <#
    .SYNOPSIS
        Apply groups for one Privacy screen: each existing section as its
        own headed group, then one group per hardening group with Category
        sub-headers. Every hardening catalog is resolved once here and
        carried in Data, since Get-WtHardeningCatalog re-parses the row
        table on every call.
    #>
    param(
        [Parameter(Mandatory)][string]$Key,
        [bool]$IsWindows11 = (Test-WtIsWindows11),
        [array]$Sections = (Get-WtApplySectionCatalog)
    )
    $screen = @(Get-WtPrivacyScreenCatalog) | Where-Object { $_.Key -eq $Key } | Select-Object -First 1
    if (-not $screen) { throw "Unknown privacy screen '$Key'" }
    $groups = New-Object System.Collections.Generic.List[object]
    foreach ($sectionKey in @($screen.ExistingSections)) {
        $section = $Sections | Where-Object { $_.Key -eq $sectionKey } | Select-Object -First 1
        if (-not $section) { continue }
        $groups.Add(@{
            SectionKey    = $sectionKey
            HeaderKey     = $section.TitleKey
            Data          = @{ Section = $section }
            GetCatalog    = { param($g) @(& $g.Data.Section.GetCatalog) }
            GetEntryState = { param($e, $g) @{ Applied = ((& $g.Data.Section.GetState $e) -eq 'Applied'); Available = $true } }
        })
    }
    foreach ($hardening in @($screen.HardeningGroups)) {
        $groups.Add(@{
            SectionKey    = $hardening.Section
            HeaderKey     = $hardening.HeaderKey
            HeaderField   = 'Category'
            Data          = @{ Catalog = @(Get-WtHardeningCatalog -Group $hardening.Group -IsWindows11 $IsWindows11) }
            GetCatalog    = { param($g) $g.Data.Catalog }
            GetEntryState = { param($e, $g) Get-WtRegistryEntryLiveState -Entry $e }
        })
    }
    return $groups.ToArray()
}

function Get-WtPrivacyExtraItems {
    <#
    .SYNOPSIS
        Rows above the catalog rows of a Privacy screen - only App
        Permissions has one: the link to the per-app permission screen.
    #>
    param([Parameter(Mandatory)][string]$Key)
    if ($Key -eq 'PrivacyAppPermissions') {
        return @(New-WtListItem -Kind 'Link' -Name 'PerAppLink' -Label (Get-Translation 'PerAppPermissions') -Data @{ Screen = 'PerApp' })
    }
    return @()
}

function Invoke-WtPrivacyMenuScreen {
    return Invoke-WtNavScreen -Breadcrumb (Get-WtBreadcrumb -Keys 'MainMenu', 'PrivacySettings') -Items (Get-WtPrivacyMenuItems)
}

function Invoke-WtPrivacyGroupScreen {
    param([Parameter(Mandatory)][string]$Key)
    $screen = @(Get-WtPrivacyScreenCatalog) | Where-Object { $_.Key -eq $Key } | Select-Object -First 1
    if (-not $screen) { throw "Unknown privacy screen '$Key'" }
    $crumb = Get-WtBreadcrumb -Keys 'MainMenu', 'PrivacySettings', $screen.TitleKey
    return Invoke-WtApplyScreen -Breadcrumb $crumb -Groups (Get-WtPrivacyGroups -Key $Key) -ExtraItems (Get-WtPrivacyExtraItems -Key $Key)
}
#endregion src/80-screens/privacy.ps1

#region src/80-screens/profiles.ps1
# Profiles menu screen.
# Covered by: tests/ConfigProfile.Tests.ps1

function Get-WtProfilesMenuItems {
    <#
    .SYNOPSIS
        PURE: Export / Import as inline actions - both flows draw their
        own panels (prompts, progress and results all inside the box).
    #>
    return @(
        New-WtListItem -Kind 'Action' -Name 'ExportProfile' -Label (Get-Translation 'ExportProfile') -Data @{ Action = { Show-WtProfileExport } }
        New-WtListItem -Kind 'Action' -Name 'ImportProfile' -Label (Get-Translation 'ImportProfile') -Data @{ Action = { Show-WtProfileImport } }
    )
}

function Invoke-WtProfilesScreen {
    return Invoke-WtNavScreen -Breadcrumb (Get-WtBreadcrumb -Keys 'MainMenu', 'ConfigProfiles') -Items (Get-WtProfilesMenuItems)
}

function Test-WtProfileRebootNeeded {
    <#
    .SYNOPSIS
        PURE: does any applied profile-import row map to a catalog entry
        flagged RestartRequired (today: the gaming GPU-scheduling row)?
        Ensures the profile-import path prints the same reboot note the
        normal apply path does.
    #>
    param([Parameter(Mandatory)][AllowEmptyCollection()][array]$Sections)
    foreach ($section in $Sections) {
        if ($section.Outcome -ne 'Applied') { continue }
        foreach ($row in @($section.Results)) {
            if (-not $row.Applied) { continue }
            $entryName = if ($row.Item.PSObject.Properties.Name -contains 'CatalogEntry') { [string]$row.Item.CatalogEntry } else { [string]$row.Item.Name }
            $entry = @($section.Catalog) | Where-Object Name -eq $entryName | Select-Object -First 1
            if ($entry -and ($entry.PSObject.Properties.Name -contains 'RestartRequired') -and $entry.RestartRequired) { return $true }
        }
    }
    return $false
}
#endregion src/80-screens/profiles.ps1

#region src/80-screens/services.ps1
# Services screen and start-type cycling.
# Covered by: tests/Screens.Tests.ps1

function Format-WtServiceStateLabel {
    <#
    .SYNOPSIS
        PURE: "Status/StartType" for the Services screen with both words
        localized (SvcStatus.<Status> / SvcStart.<StartType>); an unknown
        word is shown as-is.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Status,
        [Parameter(Mandatory)][AllowEmptyString()][string]$StartType
    )
    $st = Get-Translation ('SvcStatus.' + $Status); if (-not $st) { $st = $Status }
    $sm = Get-Translation ('SvcStart.' + $StartType); if (-not $sm) { $sm = $StartType }
    return '{0}/{1}' -f $st, $sm
}

function Get-WtServiceCycleTargets {
    <#
    .SYNOPSIS
        PURE: the order Space walks a Services row through. Disabled
        first - it is what the screen has always done and what a single
        press should still mean - then the two ways back on.
    #>
    return [string[]]@('Disabled', 'Manual', 'Automatic')
}

function Get-WtServiceCycleLabels {
    <#
    .SYNOPSIS
        Target -> the word the row shows after "->", reusing the same
        SvcStart.* strings the live state column already prints, so
        "Calisiyor/Otomatik" and "-> Otomatik" never disagree.
    #>
    $labels = @{}
    foreach ($target in (Get-WtServiceCycleTargets)) {
        $text = Get-Translation ('SvcStart.' + $target)
        $labels[$target] = $(if ($text) { [string]$text } else { $target })
    }
    return $labels
}

function Invoke-WtServicesScreen {
    <#
    .SYNOPSIS
        The Services screen, where Space cycles a row through its start
        types instead of only disabling it. One Get-Service per build feeds
        a name index: enumerating per row cost a quarter second on entry,
        and a Where-Object per row another 200 ms. GetCatalog refreshes the
        snapshot before GetEntryState reads it, so an applied start type
        shows live on the rebuild that follows.
    #>
    $group = @{
        SectionKey = 'Services'; HeaderKey = $null
        Data = @{ Services = @(); ByName = @{} }
        GetCatalog = {
            param($g)
            $g.Data.Services = @(Get-Service -ErrorAction SilentlyContinue)
            $byName = @{}
            foreach ($svc in $g.Data.Services) { $byName[[string]$svc.Name] = $svc }
            $g.Data.ByName = $byName
            $targets = Get-WtServiceCycleTargets
            return @(Get-WtServiceCatalog | ForEach-Object { $_ | Add-Member -NotePropertyName 'CycleTargets' -NotePropertyValue $targets -Force -PassThru })
        }
        GetEntryState = {
            param($e, $g)
            $hit = $null
            if ($e.IsPerUser) {
                $prefix = [string]$e.Name + '_*'
                foreach ($svc in $g.Data.Services) { if ([string]$svc.Name -like $prefix) { $hit = $svc; break } }
            }
            elseif ($g.Data.ByName.ContainsKey([string]$e.Name)) { $hit = $g.Data.ByName[[string]$e.Name] }
            $s = Get-WtServiceState -Name $e.Name -IsPerUser $e.IsPerUser -GetServiceAction { if ($null -ne $hit) { @($hit) } else { @() } }
            $label = if ($s.Present) { Format-WtServiceStateLabel -Status ([string]$s.Status) -StartType ([string]$s.StartType) } else { Get-Translation 'StateNotPresent' }
            @{ Applied = $false; Available = [bool]$s.Present; StateLabel = $label }
        }
    }
    return Invoke-WtApplyScreen -Breadcrumb (Get-WtBreadcrumb -Keys 'MainMenu', 'ServicesManagement') -Groups @($group) `
        -FooterKey 'ServicesFooter' -CycleLabels (Get-WtServiceCycleLabels)
}
#endregion src/80-screens/services.ps1

#region src/80-screens/system-settings.ps1
# System settings screen.
# Covered by: tests/MenuTree.Tests.ps1

function Get-WtSystemSettingsGroups {
    <#
    .SYNOPSIS
        Basic Tools > System Settings: the eight persistent-setting
        sections on one screen, in apply order. Live-environment flags
        (GPU scheduling support, firewall state, DoH support) are carried
        in each group's Data so the delegates read them through the group
        argument, not a closure.
    #>
    param(
        [bool]$GpuSupported = (Test-WtGpuSchedulingSupported),
        [hashtable]$FirewallState = (Get-WtFirewallLiveState),
        [bool]$DohSupported = (Test-WtDohSupported)
    )
    $registryState = { param($e, $g) Get-WtRegistryEntryLiveState -Entry $e }
    $blankState = { param($e, $g) @{ Applied = $false; Available = $true; StateLabel = '' } }
    return @(
        @{ SectionKey = 'PowerPlan'; HeaderKey = 'GroupPowerPerformance'
           GetCatalog = { param($g) Get-WtPowerPlanCatalog }
           GetEntryState = { param($e, $g) $s = Get-WtPowerPlanState -Entry $e; @{ Applied = [bool]$s.Applied; Available = $true } } }
        @{ SectionKey = 'GamingTweaks'; HeaderKey = 'GroupGaming'; Data = @{ GpuSupported = $GpuSupported }
           GetCatalog = { param($g) Get-WtGamingTweakCatalog }
           GetEntryState = {
               param($e, $g)
               if ($e.Name -eq 'EnableGpuScheduling' -and -not $g.Data.GpuSupported) { return @{ Applied = $false; Available = $false; StateLabel = (Get-Translation 'NotSupportedWddm') } }
               Get-WtRegistryEntryLiveState -Entry $e
           } }
        @{ SectionKey = 'FastStartup'; HeaderKey = 'GroupStartup'
           GetCatalog = { param($g) Get-WtFastStartupCatalog }
           GetEntryState = { param($e, $g) $s = Get-WtFastStartupState -Entry $e; @{ Applied = [bool]$s.Applied; Available = $true } } }
        @{ SectionKey = 'Firewall'; HeaderKey = 'GroupFirewall'; Data = @{ FirewallEnabled = [bool]$FirewallState.Enabled; FirewallKnown = [bool]$FirewallState.Known }
           GetCatalog = { param($g) if ($g.Data.FirewallKnown) { @(Get-WtFirewallOfferEntry -CurrentlyEnabled $g.Data.FirewallEnabled) } else { @() } }
           GetEntryState = { param($e, $g) @{ Applied = $false; Available = $true; StateLabel = $(if ($g.Data.FirewallEnabled) { Get-Translation 'FirewallCurrentlyOn' } else { Get-Translation 'FirewallCurrentlyOff' }) } } }
        @{ SectionKey = 'ContextMenu'; HeaderKey = 'GroupContextMenu'
           GetCatalog = { param($g) Get-WtContextMenuCatalog }
           GetEntryState = { param($e, $g) $s = Get-WtShellEntryState -Entry $e; @{ Applied = [bool]$s.Applied; Available = $true } } }
        @{ SectionKey = 'ExplorerView'; HeaderKey = 'GroupExplorerView'
           GetCatalog = { param($g) Get-WtExplorerViewCatalog }
           GetEntryState = $registryState }
        @{ SectionKey = 'DnsPreset'; HeaderKey = 'GroupDns'; Radio = $true; InfoKey = $(if ($DohSupported) { 'DohSupportedInfo' } else { 'DohNotSupportedDisclosure' })
           GetCatalog = { param($g) @(Get-WtDnsPresetCatalog | ForEach-Object { [PSCustomObject]@{ Name = $_.Name; DisplayLabel = ('{0}  ({1}, {2})' -f $_.Name, $_.IPv4Primary, $_.IPv4Secondary); Risk = 'CAUTION'; Consequence = $null } }) }
           GetEntryState = $blankState }
        @{ SectionKey = 'Blocklist'; HeaderKey = 'GroupBlocklist'
           GetCatalog = { param($g) Get-WtBlocklistTierCatalog }
           GetEntryState = $blankState }
    )
}

function Get-WtFirewallLiveState {
    <#
    .SYNOPSIS
        @{ Enabled; Known }. The registry is asked first (milliseconds);
        only when it has no answer does the NetSecurity cmdlet run (about
        a second cold). Known is false when neither can say (no module,
        no admin), and the screen then offers no firewall row.
    #>
    param(
        [scriptblock]$GetPropertyAction,
        [scriptblock]$GetProfilesAction
    )
    $registryArgs = @{}
    if ($GetPropertyAction) { $registryArgs['GetPropertyAction'] = $GetPropertyAction }
    $fromRegistry = Get-WtFirewallRegistryState @registryArgs
    if ($fromRegistry.Known) { return @{ Enabled = [bool]$fromRegistry.Enabled; Known = $true } }
    try {
        $enableEntry = @(Get-WtFirewallCatalog) | Where-Object Name -eq 'EnableFirewall' | Select-Object -First 1
        $stateArgs = @{}
        if ($GetProfilesAction) { $stateArgs['GetProfilesAction'] = $GetProfilesAction }
        return @{ Enabled = [bool](Get-WtFirewallState -Entry $enableEntry @stateArgs).Applied; Known = $true }
    }
    catch { return @{ Enabled = $false; Known = $false } }
}

function Invoke-WtSystemSettingsScreen {
    <#
    .SYNOPSIS
        Passes Groups as a scriptblock, not an evaluated array, since the
        firewall row's live probe must be re-taken on every rebuild - an
        evaluated array freezes that probe at screen entry.
    #>
    return Invoke-WtApplyScreen -Breadcrumb (Get-WtBreadcrumb -Keys 'MainMenu', 'SystemSettings') -Groups { Get-WtSystemSettingsGroups }
}
#endregion src/80-screens/system-settings.ps1

#region src/80-screens/tool-rows.ps1
# Tool screen items (header + rows + spacers) and the apply-gate helpers.
# The row constructors and the row tables live in 40-catalogs/tool-rows.ps1.
# Covered by: tests/ToolScreenStructure.Tests.ps1

function Get-WtToolScreenItems {
    <#
    .SYNOPSIS
        PURE: turns a group descriptor list into the rows a tool screen
        shows - one Header row per group, then that group's rows, with a
        blank line between groups. A group whose delegate returns nothing
        is skipped entirely, header included.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Groups
    )
    $items = New-Object System.Collections.Generic.List[object]
    foreach ($group in $Groups) {
        $rows = @(& $group.GetRows)
        if ($rows.Count -eq 0) { continue }
        $items.Add((New-WtListItem -Kind 'Header' -Name ('Header:' + $group.HeaderKey) -Label (Get-Translation $group.HeaderKey)))
        foreach ($row in $rows) { $items.Add($row) }
    }
    return Add-WtListGroupSpacers -Items $items.ToArray()
}

# --- apply-gate helpers ---------------------------------------------------------
#endregion src/80-screens/tool-rows.ps1

#region src/80-screens/undo.ps1
# Undo screen.
# Covered by: tests/Screens.Tests.ps1

function Get-WtRecordConsequence {
    param(
        [Parameter(Mandatory)][PSCustomObject]$Record,
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Sections
    )
    $section = $Sections | Where-Object Key -eq $Record.SectionKey | Select-Object -First 1
    if (-not $section -or -not $section.GetCatalog) { return '' }
    try {
        $entry = @(& $section.GetCatalog) | Where-Object Name -eq $Record.EntryName | Select-Object -First 1
        if ($entry -and ($entry.PSObject.Properties.Name -contains 'Consequence') -and $entry.Consequence) { return [string]$entry.Consequence }
    }
    catch { $null = $_ }
    return ''
}

# --- Undo / Profiles / Language screens ------------------------------------------

function Get-WtUndoScreenItems {
    <#
    .SYNOPSIS
        PURE: one Action row per undo entry (newest first), carrying the
        entry path; a single Info row when nothing is left to undo.
        Entries finished with - restored, or retired because another
        action wiped their state - are hidden here (Test-WtUndoEntryClosed)
        though the file stays on disk.
    #>
    param([AllowEmptyCollection()][array]$Entries = @(Get-WtUndoEntries))
    $pending = @(@($Entries) | Where-Object { -not (Test-WtUndoEntryClosed -Entry $_) })
    if ($pending.Count -eq 0) { return @(New-WtListItem -Kind 'Info' -Name 'UndoEmpty' -Label (Get-Translation 'UndoMenuEmpty')) }
    return @(foreach ($e in $pending) {
        New-WtListItem -Kind 'Action' -Name ([string]$e.Path) -Label (Format-WtUndoEntryLabel -Entry $e) -Data @{ EntryPath = [string]$e.Path; Action = [string]$e.Action; Entry = $e }
    })
}

$script:WtUndoLabelMemo = @{}

function Get-WtUndoCatalogLabel {
    <#
    .SYNOPSIS
        The localized catalog label behind one undo-record item - the
        text the user picked on the apply screen - or '' when no catalog
        knows it. A service is looked up by its template name (the
        per-user services carry a LUID suffix in Name), a package by
        name, others by CatalogEntry; first hit wins, a throwing catalog
        is skipped. Results are memoized per language and item, since a
        catalog can cost ~100ms to build and one record can hold a dozen
        items.
    #>
    param(
        [Parameter(Mandatory)][object]$Item,
        [AllowEmptyCollection()][array]$Sections = @(Get-WtApplySectionCatalog)
    )
    $names = @($Item.PSObject.Properties.Name)
    $type = [string]$Item.ItemType
    $only = @()
    $lookup = ''
    if ($type -eq 'Service') {
        $only = @('Services')
        $lookup = $(if (($names -contains 'Template') -and $Item.Template) { [string]$Item.Template } else { [string]$Item.Name })
    }
    elseif ($type -eq 'Package') {
        $only = @('Packages')
        $lookup = [string]$Item.Name
    }
    elseif (($names -contains 'CatalogEntry') -and $Item.CatalogEntry) {
        $lookup = [string]$Item.CatalogEntry
    }
    if (-not $lookup) { return '' }
    if ($null -eq $script:WtUndoLabelMemo) { $script:WtUndoLabelMemo = @{} }
    $memoKey = [string]$script:Language + '|' + $(if ($only.Count -gt 0) { $only[0] } else { 'Catalog' }) + '|' + $lookup
    if ($script:WtUndoLabelMemo.ContainsKey($memoKey)) { return [string]$script:WtUndoLabelMemo[$memoKey] }
    $label = ''
    foreach ($section in @($Sections)) {
        if ($null -eq $section) { continue }
        $key = [string]$section.Key
        if ($only.Count -gt 0) { if ($only -notcontains $key) { continue } }
        elseif ($key -eq 'Services' -or $key -eq 'Packages') { continue }
        if (-not $section.GetCatalog) { continue }
        $rows = @()
        try { $rows = @(& $section.GetCatalog) } catch { $rows = @() }
        foreach ($row in $rows) {
            if ($null -eq $row) { continue }
            if (-not [string]::Equals([string]$row.Name, $lookup, [System.StringComparison]::Ordinal)) { continue }
            if (($row.PSObject.Properties.Name -contains 'DisplayLabel') -and $row.DisplayLabel) { $label = [string]$row.DisplayLabel }
            break
        }
        if ($label) { break }
    }
    $script:WtUndoLabelMemo[$memoKey] = $label
    return $label
}

function Confirm-WtUndoRestore {
    <#
    .SYNOPSIS
        The undo confirm panel: the record's detail lines as a read-only
        compact box, Enter restores, Esc (and Q) cancel, any other key is
        ignored and the box stays. A read-only list, rather than a typed
        answer, lets a long record scroll with the arrow keys. Long lines
        are wrapped to the box; short ones keep their indent.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Breadcrumb,
        [AllowEmptyCollection()][string[]]$Lines = @()
    )
    $width = Get-WtPanelInnerWidth -Width ([int](Get-WtConsoleSize).Width)
    $rows = New-Object System.Collections.Generic.List[string]
    foreach ($line in @($Lines)) {
        $pieces = @(ConvertTo-WtPanelLines -Lines @([string]$line) -Width $width -Risk 'CAUTION')
        if ($pieces.Count -le 1) { $rows.Add([string]$line) } else { foreach ($p in $pieces) { $rows.Add($p) } }
    }
    $items = @(Get-WtPanelItems -Lines $rows.ToArray() -Risk 'CAUTION')
    try {
        while ($true) {
            $r = Invoke-WtListScreen -Breadcrumb $Breadcrumb -Items $items -FooterText (Get-Translation 'UndoConfirmFooter') -Layout 'Compact'
            if ($r.Emit -eq 'Activate') { return $true }
            if ($r.Emit -eq 'Global') { continue }
            return $false
        }
    }
    finally { Reset-WtFrameCache }
}

function Invoke-WtUndoScreen {
    <#
    .SYNOPSIS
        Undo as a list screen: Enter on an entry opens the confirm panel
        (what the record changed, Enter = restore, Esc = cancel), restores
        through Restore-WtUndoEntry and shows per-item outcomes in the
        panel, each named the way the confirm panel named it. Two
        registry values of one catalog entry that both came back
        collapse into one "label: outcome" line, matching how the
        confirm panel listed them; a value with a different outcome
        keeps its own line.
    #>
    $crumb = Get-WtBreadcrumb -Keys 'MainMenu', 'UndoLastChange'
    $cursor = -1
    $resolve = { param($Item) Get-WtUndoCatalogLabel -Item $Item }
    while ($true) {
        $items = @(Get-WtUndoScreenItems)
        $r = Invoke-WtListScreen -Breadcrumb $crumb -Items $items -FooterText (Get-Translation 'UndoFooter') -InitialCursor $cursor -Layout 'Compact'
        $cursor = [int]$r.CursorIndex
        if ($r.Emit -eq 'Back') { return @{ Nav = 'Back'; Target = ''; Char = ''; HasMarks = $false } }
        if ($r.Emit -eq 'Quit') { return @{ Nav = 'Exit'; Target = ''; Char = ''; HasMarks = $false } }
        if ($r.Emit -ne 'Activate' -or -not $r.Item -or $r.Item.Kind -ne 'Action') { continue }
        Show-WtListLoading -Breadcrumb $crumb
        $detail = @(Get-WtUndoEntryDetailLines -Entry $r.Item.Data.Entry -CatalogLabel $resolve)
        if (-not (Confirm-WtUndoRestore -Breadcrumb $crumb -Lines $detail)) { continue }
        $results = @(Restore-WtUndoEntry -EntryPath $r.Item.Data.EntryPath)
        $lines = New-Object System.Collections.Generic.List[string]
        $lines.Add(((Get-Translation 'UndoMenuResultsHeader') -f $r.Item.Data.Action))
        $listed = New-Object -TypeName 'System.Collections.Generic.HashSet[string]' -ArgumentList ([System.StringComparer]::Ordinal)
        foreach ($res in $results) {
            $label = switch ($res.Outcome) { 'Restored' { Get-Translation 'UndoResultRestored' } 'NotRestorable' { Get-Translation 'UndoResultNotRestorable' } default { Get-Translation 'UndoResultFailed' } }
            $name = $(if (($res.PSObject.Properties.Name -contains 'Item') -and $res.Item) { Get-WtUndoItemLabel -Item $res.Item -CatalogLabel $resolve } else { [string]$res.Name })
            $line = '  ' + $name + ': ' + $label
            if (-not $listed.Add($line)) { continue }
            $lines.Add($line)
        }
        $null = Read-WtPanelAnswer -Breadcrumb $crumb -Lines $lines.ToArray() -Prompt (Get-Translation 'PressEnterContinue') -Layout 'Compact'
    }
}
#endregion src/80-screens/undo.ps1

#region src/80-screens/winget-store.ps1
# The winget store screen: the winget gate, tab projections and the loop.
# Covered by: tests/WingetStoreScreen.Tests.ps1

function Get-WtWingetStoreLabels {
    <#
    .SYNOPSIS
        Every user-visible label the store frame needs, resolved through
        the active language in one place so the composers stay pure.
    #>
    $categories = @{}
    foreach ($c in (Get-WtWingetStoreCategories)) { $categories[[string]$c.Key] = Get-Translation ([string]$c.LabelKey) }
    return @{
        Categories = $categories
        Tabs       = @{
            Store     = Get-Translation 'WsTabStore'
            Installed = Get-Translation 'WsTabInstalled'
        }
        Headers    = @{
            Name      = Get-Translation 'WsColName'
            Id        = Get-Translation 'WsColId'
            Version   = Get-Translation 'WsColVersion'
            Available = Get-Translation 'WsColAvailable'
        }
    }
}

function Test-WtWingetStoreGate {
    <#
    .SYNOPSIS
        Whether the store may open. winget present -> yes. Absent -> a
        panel explains why (Windows 10 / LTSC often ships without App
        Installer) and ASKS. Never a silent install: the rest of this
        tool asks before it reaches the network, and so does this.
        Returns [bool]; $false means go back to the menu. If the user
        agrees but the install itself fails, that failure is shown
        before returning $false, since a silent return would read as
        the keypress having done nothing. Both panels are injected, the
        failure notice through its own -ReadFailure: it is a different
        panel from the question, and a caller (a test, or any host with
        no console) that replaced only the question would still have hit
        the real console here.
    #>
    param(
        [bool]$HasWinget = $true,
        [scriptblock]$ReadAnswer = {
            param($Lines, $Prompt)
            Read-WtPanelAnswer -Breadcrumb (Get-Translation 'WsMissingTitle') -Lines $Lines -Prompt $Prompt -Risk 'CAUTION'
        },
        [scriptblock]$ReadFailure = {
            $null = Read-WtPanelAnswer -Breadcrumb (Get-Translation 'WsMissingTitle') `
                -Lines @((Get-Translation 'WsMissingFailed')) -Prompt (Get-Translation 'PressEnterContinue') -Layout 'Compact'
        },
        [scriptblock]$Install = {
            $null = Test-WingetInstalled
            [bool](Get-Command winget -ErrorAction SilentlyContinue)
        }
    )
    if ($HasWinget) { return $true }
    $answer = & $ReadAnswer @((Get-Translation 'WsMissingLines')) (Get-Translation 'WsMissingPrompt')
    if (-not (Test-WtAffirmativeAnswer -Answer ([string]$answer))) { return $false }
    $ok = [bool](& $Install)
    if (-not $ok) {
        $null = & $ReadFailure
        Reset-WtFrameCache
    }
    return $ok
}

function Get-WtWingetStoreTabRows {
    <#
    .SYNOPSIS
        The rows the table composer draws for the page on screen: the
        installed tab, or the store page showing winget results. The store
        page's CATALOG is a grid, not a table, so it projects to nothing.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$State
    )
    if ([string]$State.Tab -eq 'Installed') {
        return , @(Select-WtWingetStoreApps -Apps @($State.Installed) -Query ([string]$State.InstalledQuery))
    }
    if ([string]$State.Tab -eq 'Store' -and [string]$State.Mode -eq 'Results') { return , @($State.Results) }
    return @()
}

function Invoke-WtWingetStoreScreen {
    <#
    .SYNOPSIS
        The store's interactive loop: frame -> key batch -> reducer
        until the reducer emits Back, returning @{ Nav; Target; Char;
        HasMarks } for Invoke-WtMainLoop; everything testable lives in
        Update-WtStoreState / Get-WtStoreFrameRows / Invoke-WtWingetBatch.
        A bare pipeline call unwraps empty/single results, so callers
        wrap in @() - except a source already returning "return , $list",
        which must be assigned bare or @() re-wraps the whole list into
        one element. An unlabeled 'break' in a switch nested in a
        foreach exits only the switch, so the stop condition rides a
        variable checked after it.
    #>
    $back = @{ Nav = 'Back'; Target = ''; Char = ''; HasMarks = $false }
    if (-not (Test-WtWingetStoreGate -HasWinget ([bool](Get-Command winget -ErrorAction SilentlyContinue)))) {
        Reset-WtFrameCache
        return $back
    }

    $labels = Get-WtWingetStoreLabels
    $breadcrumb = Get-WtBreadcrumb -Keys 'MainMenu', 'WingetStore'
    $apps = @(Get-WtWingetStoreCatalog)
    $categoryKeys = @((Get-WtWingetStoreCategories).Key)
    $state = New-WtStoreState -Query ([string]$script:WtWingetStoreInitialQuery)
    $script:WtWingetStoreInitialQuery = ''
    $converter = { param($Key, $KeyChar) ConvertTo-WtGridKeyToken -Key $Key -KeyChar $KeyChar }
    $waiting = { param([string]$Text)
        Show-WtPanelMessage -Breadcrumb (Get-Translation 'WingetStore') -Lines @($Text) -FooterText '' | Out-Null
    }
    $reloadInstalled = {
        & $waiting (Get-Translation 'WsLoadingInstalled')
        $state.Installed = @(Get-WtWingetInstalledPackages)
        Reset-WtFrameCache
    }

    & $reloadInstalled

    $gridKey = ''
    $gridRows = @()
    while ($true) {
        $size = Get-WtConsoleSize
        $installedIds = [string[]]@(foreach ($installedPkg in @($state.Installed)) { [string]$installedPkg.Id })
        $onStore = ([string]$state.Tab -eq 'Store')
        $isResults = ($onStore -and [string]$state.Mode -eq 'Results')
        $isCatalog = ($onStore -and -not $isResults)
        $visible = @(Select-WtWingetStoreApps -Apps $apps -Query $(if ($isCatalog) { [string]$state.Query } else { '' }))
        $geo = Get-WtGridGeometry -Inner ([Math]::Max(20, $size.Width - 1) - 4)
        $nextGridKey = [string]$isCatalog + '|' + [string]$state.Query + '|' + [string]$geo.ColumnCount + '|' + [string]$visible.Count
        if ($nextGridKey -ne $gridKey) {
            $gridRows = Get-WtStoreGridRows -Apps $visible -CategoryKeys $categoryKeys -CellsPerRow $geo.ColumnCount `
                -CategoryLabels $labels.Categories
            $gridKey = $nextGridKey
        }
        $tableRows = Get-WtWingetStoreTabRows -State $state
        $chromeLayout = 'Table'
        if ($isCatalog) { $chromeLayout = 'Grid' }
        elseif ($isResults) { $chromeLayout = 'Results' }
        $viewHeight = [Math]::Max(1, $size.Height - (Get-WtStoreChromeHeight -Layout $chromeLayout -Width $size.Width))

        $navRows = @()
        if ($isCatalog) { $navRows = $gridRows }
        else { $navRows = Get-WtStoreListRows -Rows $tableRows }
        $state.Cursor = Get-WtStoreValidCursor -Rows $navRows -Cursor $state.Cursor
        $state.WindowStart = Get-WtViewportWindow -ItemCount (Get-WtGridRowCount -Rows $navRows) `
            -CursorIndex ([int]$state.Cursor.Row) -ViewHeight $viewHeight -WindowStart ([int]$state.WindowStart)

        $onInstalled = ([string]$state.Tab -eq 'Installed')
        $installedFiltered = ($onInstalled -and ([string]$state.InstalledQuery).Trim() -ne '')
        $footer = switch ([string]$state.Focus) {
            'Input' { if ($onInstalled) { Get-Translation 'WsFooterInputInstalled' } else { Get-Translation 'WsFooterInput' } }
            default {
                if ($onInstalled) { Get-Translation 'WsFooterInstalled' }
                elseif ($isResults) { Get-Translation 'WsFooterResults' }
                else { Get-Translation 'WsFooterStore' }
            }
        }
        if ($state.Hint) { $footer = [string]$state.Hint }
        $counter = if ($state.Marks.Count -gt 0) { (Get-Translation 'WsMarked') -f $state.Marks.Count } else { '' }
        $searchCount = (Get-Translation 'WsCountApps') -f $(if ($onInstalled) { @($state.Installed).Count } else { $apps.Count })
        if ($onStore -and ([string]$state.Query).Trim() -ne '') {
            $matchCount = if ($isResults) { @($state.Results).Count } else { $visible.Count }
            $searchCount += ' - ' + ((Get-Translation 'WsCountMatches') -f $matchCount)
        }
        elseif ($installedFiltered) {
            $searchCount += ' - ' + ((Get-Translation 'WsCountMatches') -f @($tableRows).Count)
        }

        if ($isCatalog) {
            $frame = Get-WtStoreFrameRows -State $state -Rows $gridRows -Width $size.Width -Height $size.Height `
                -Glyphs $script:WtGlyphs -Breadcrumb $breadcrumb -TabLabels $labels.Tabs `
                -FooterText $footer -CounterText $counter -SearchCountText $searchCount -InstalledIds $installedIds
        }
        else {
            $empty = if ($isResults -or $installedFiltered) { Get-Translation 'WsEmptySearch' } else { Get-Translation 'WsEmptyInstalled' }
            $heading = if ($isResults) { (Get-Translation 'WsResultsHeading') -f [string]$state.Query } else { '' }
            $frame = Get-WtStoreTableRows -State $state -Rows $tableRows -Width $size.Width -Height $size.Height `
                -Glyphs $script:WtGlyphs -Breadcrumb $breadcrumb -Headers $labels.Headers -TabLabels $labels.Tabs `
                -FooterText $footer -CounterText $counter -SearchCountText $searchCount `
                -HeadingText $heading -EmptyText $empty
        }
        Write-WtFrame -FrameLines $frame -Width $size.Width -Height $size.Height

        foreach ($token in (Read-WtInputBatch -Converter $converter)) {
            $r = Update-WtStoreState -State $state -Token $token -Rows $navRows `
                -ViewHeight $viewHeight -InstalledIds $installedIds
            $state = $r.State
            $stop = $false
            switch ($r.Emit) {
                'Back' { Reset-WtFrameCache; return $back }
                'Refused' { $state.Hint = Get-Translation 'WsHintInstalled' }
                'Refresh' {
                    Clear-WtWingetCache
                    if ([string]$state.Mode -eq 'Results') {
                        if ([string]$state.Query) {
                            & $waiting ((Get-Translation 'WsSearching') -f [string]$state.Query)
                            $state.Results = @(Get-WtWingetSearchResults -Query ([string]$state.Query))
                            Reset-WtFrameCache
                        }
                    }
                    else { & $reloadInstalled }
                    $stop = $true
                }
                'Search' {
                    if ([string]$state.Mode -eq 'Results') {
                        & $waiting ((Get-Translation 'WsSearching') -f [string]$state.Query)
                        $state.Results = @(Get-WtWingetSearchResults -Query ([string]$state.Query))
                        Reset-WtFrameCache
                    }
                    $stop = $true
                }
                'Install'   { Invoke-WtWingetStoreRun -State $state -Operation 'Install'; $stop = $true }
                'Upgrade'   { Invoke-WtWingetStoreRun -State $state -Operation 'Upgrade'; $stop = $true }
                'Uninstall' {
                    if (Confirm-WtWingetUninstall -Ids ([string[]]@($state.Marks))) {
                        Invoke-WtWingetStoreRun -State $state -Operation 'Uninstall'
                    }
                    else { Reset-WtFrameCache }
                    $stop = $true
                }
            }
            if ($stop) { break }
        }
    }
}

function Confirm-WtWingetUninstall {
    <#
    .SYNOPSIS
        The typed-word gate in front of a bulk uninstall, naming every
        package it is about to remove. Returns [bool]; $false means do
        nothing at all. Uninstall is the only irreversible, hence the
        only gated, operation on this screen - install and upgrade only
        add software. The ids are listed, not counted, since "3
        packages will be removed" is not something anyone can check,
        and a mark can outlive the screen that set it.
    #>
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Ids,
        [scriptblock]$Confirm = {
            param($Consequence, $Lines)
            Confirm-WtDestructiveAction -Consequence $Consequence -Lines $Lines -Breadcrumb (Get-Translation 'WingetStore')
        }
    )
    $ids = @($Ids)
    if ($ids.Count -eq 0) { return $false }
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($id in $ids) { $lines.Add('  - ' + [string]$id) }
    $consequence = (Get-Translation 'WsUninstallConsequence') -f $ids.Count
    return [bool](& $Confirm $consequence ([string[]]$lines.ToArray()))
}

function Invoke-WtWingetStoreRun {
    <#
    .SYNOPSIS
        Runs the marked packages through Invoke-WtWingetBatch with the
        live output panel attached, prints the summary, then clears the
        marks and re-reads the installed list. A partial output line is
        committed before the next package's header so it can't merge
        into that line. A user-scope package can't be touched from this
        elevated session (0x8A15007D); that case retries via a scheduled
        task at medium integrity, tailing its output since it can't be
        streamed, with a start failure returned as $null rather than an
        invented exit code. LastSummary on State lets the assistant's
        digit path report the result without opening this screen.
    #>
    param(
        [Parameter(Mandatory)][hashtable]$State,
        [Parameter(Mandatory)][ValidateSet('Install', 'Upgrade', 'Uninstall')][string]$Operation
    )
    $ids = [string[]]@($State.Marks)
    if ($ids.Count -eq 0) { return }
    $script:WtPanelBreadcrumb = Get-Translation 'WingetStore'
    $output = New-WtNativeOutputState
    $header = ''
    $paint = {
        $size = Get-WtConsoleSize
        $view = [Math]::Max(1, $size.Height - (Get-WtFrameChromeHeight -Width $size.Width))
        $lines = @($output.Lines.ToArray())
        if ([string]$output.Current -ne '') { $lines += [string]$output.Current }
        Show-WtPanelMessage -Breadcrumb $script:WtPanelBreadcrumb `
            -Lines (Get-WtOutputTail -Lines $lines -Count $view) -FooterText $header | Out-Null
    }
    $runOne = {
        param($Id, $Arguments, $Index, $Total)
        $header = (Get-Translation 'WsRunning') -f $Index, $Total, $Id
        if ([string]$output.Current -ne '') {
            $output.Lines.Add([string]$output.Current)
            $output.Current = ''
            $output.Column = 0
        }
        $output.Lines.Add('')
        $output.Lines.Add('> winget ' + ($Arguments -join ' '))
        & $paint
        Invoke-WtStreamedProcess -FilePath 'winget.exe' `
            -Arguments (ConvertTo-WtNativeArgumentLine -Arguments $Arguments) `
            -State $output -OnTick $paint -Encoding ([System.Text.Encoding]::UTF8)
    }
    $runOneAsUser = {
        param($Id, $Arguments, $Index, $Total)
        if ([string]$output.Current -ne '') {
            $output.Lines.Add([string]$output.Current)
            $output.Current = ''
            $output.Column = 0
        }
        $output.Lines.Add('')
        $output.Lines.Add((Get-Translation 'WsRetryAsUser'))
        $output.Lines.Add('> winget ' + ($Arguments -join ' '))
        & $paint
        $tailMark = $output.Lines.Count
        $replaceTail = {
            param($TailLines)
            while ($output.Lines.Count -gt $tailMark) { $output.Lines.RemoveAt($output.Lines.Count - 1) }
            foreach ($tailLine in @($TailLines)) { $output.Lines.Add([string]$tailLine) }
        }
        $asUser = Invoke-WtProcessAsInteractiveUser -FilePath 'winget.exe' -Arguments ([string[]]@($Arguments)) `
            -OnOutput { param($TailLines) & $replaceTail $TailLines; & $paint }
        & $replaceTail $asUser.Lines
        if (-not $asUser.Ran) {
            $output.Lines.Add((Get-Translation (Get-WtRetryReasonKey -Reason ([string]$asUser.Reason))))
            & $paint
            return $null
        }
        & $paint
        return $asUser.ExitCode
    }
    $results = @(Invoke-WtWingetBatch -Ids $ids -Operation $Operation -RunOne $runOne -RunOneAsUser $runOneAsUser)
    if ([string]$output.Current -ne '') {
        $output.Lines.Add([string]$output.Current)
        $output.Current = ''
        $output.Column = 0
    }
    $summaryLines = [string[]]@(Get-WtWingetSummaryLines -Results $results -Operation $Operation)
    foreach ($line in $summaryLines) { $output.Lines.Add($line) }
    $State.LastSummary = $summaryLines

    $State.Marks.Clear()
    Show-WtPanelMessage -Breadcrumb $script:WtPanelBreadcrumb `
        -Lines @((Get-Translation 'WsLoadingInstalled')) -FooterText '' | Out-Null
    $State.Installed = @(Get-WtWingetInstalledPackages)
    Show-WtOutputScreen -Breadcrumb $script:WtPanelBreadcrumb -Lines $output.Lines.ToArray()
    Reset-WtFrameCache
}
#endregion src/80-screens/winget-store.ps1

#region src/90-main/10-elevation.ps1
# Relaunch elevated when not an administrator (guarded by Test-WtIsMainInvocation).
# The child is handed the script TEXT, never the path: "& 'file.ps1'" is a script
# load, so it inherits every block a load can hit - a policy pinned by group
# policy (which -ExecutionPolicy Bypass cannot override), a drive the elevated
# account cannot see, a Mark of the Web. Any of those kills the new window
# before the fatal-error screen exists, which reads as "it opened and closed
# instantly". [scriptblock]::Create is not a load, so it survives all three and
# both branches end up the same shape. Constrained Language mode blocks it too;
# nothing here can help there.
# The Mark of the Web comes off first, while the non-elevated process still holds
# the path the user owns - the elevated child runs from text and has no
# $PSCommandPath of its own to unmark.